INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利息", "is_correct": true, "explanation": "正确：lì xī 是“利息”，指借贷或存款中除本金外多付或多收的钱。"}, {"text": "窒息", "is_correct": false, "explanation": "声母混淆：zhì xī 与 lì xī 只有第一个字声母不同（zh／l），声调相同，意思是呼吸受阻、气不通。"}, {"text": "气息", "is_correct": false, "explanation": "声母混淆：qì xī 与 lì xī 只有第一个字声母不同（q／l），声调相同，意思是呼吸时的气，也指气味或气氛。"}, {"text": "离析", "is_correct": false, "explanation": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}], "explanations": {"利息": "正确：lì xī 是“利息”，指借贷或存款中除本金外多付或多收的钱。", "窒息": "声母混淆：zhì xī 与 lì xī 只有第一个字声母不同（zh／l），声调相同，意思是呼吸受阻、气不通。", "气息": "声母混淆：qì xī 与 lì xī 只有第一个字声母不同（q／l），声调相同，意思是呼吸时的气，也指气味或气氛。", "离析": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}, "sentence_index": null, "correct_answer": "利息"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身材，与贷款买车无关。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量是声音的大小，与贷款买车无关。"}, {"text": "利息", "is_correct": true, "explanation": "正确：利息太高，不想贷款，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，与“利息太高了，他不想贷款”没有关系，句中说的是利息的高低。"}], "explanations": {"身高": "语义：身高是人的身材，与贷款买车无关。", "音量": "语义：音量是声音的大小，与贷款买车无关。", "利息": "正确：利息太高，不想贷款，符合句意。", "年龄": "语义：年龄是人的岁数，与“利息太高了，他不想贷款”没有关系，句中说的是利息的高低。"}, "sentence_index": 6, "correct_answer": "利息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房客每个月要交一笔利息。", "explanation": "这里应该用〈租金〉。租金是租房的费用，利息是借钱多付的钱，租房不说利息。"}, {"text": "她靠教钢琴的利息养活全家。", "explanation": "这里应该用〈收入〉。利息指存款或借贷多付的钱，教课的报酬不叫利息。"}, {"text": "这笔钱的利息很硬。", "explanation": "这里应该用〈多〉或〈少〉。利息是数量，要说利息很多或很少，不能用形容物体质地的词来说它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我要付银行一张利息。", "corrected_sentence": "这个月我要付银行一笔利息。", "error_description": "量词错误：“利息”是一笔钱，量词应用“笔”，不能用“张”。正确说法是“一笔利息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每年都要还贷款利息们。", "corrected_sentence": "我每年都要还贷款利息。", "error_description": "“利息”是抽象名词，不能加“们”表示复数。应说“还贷款利息”，不说“还贷款利息们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离任", "is_correct": true, "explanation": "离任：离开所任职务，与“到任”相对"}, {"text": "出国", "is_correct": false, "explanation": "出国：前往国外，与“到任”没有反义关系"}, {"text": "结婚", "is_correct": false, "explanation": "结婚：缔结婚姻关系，与“到任”没有反义关系"}, {"text": "散步", "is_correct": false, "explanation": "散步：随意走动，与“到任”没有反义关系"}], "correct_answer": "离任", "explanations": {"离任": "离任：离开所任职务，与“到任”相对", "出国": "出国：前往国外，与“到任”没有反义关系", "结婚": "结婚：缔结婚姻关系，与“到任”没有反义关系", "散步": "散步：随意走动，与“到任”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离任", "is_correct": true, "explanation": "离任：离开所任职务，与“到任”相对"}, {"text": "下棋", "is_correct": false, "explanation": "下棋：进行棋类游戏，与“到任”没有反义关系"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：用声音演唱曲调，与“到任”没有反义关系"}, {"text": "出差", "is_correct": false, "explanation": "出差：因公外出办事，与“到任”没有反义关系"}], "correct_answer": "离任", "explanations": {"离任": "离任：离开所任职务，与“到任”相对", "下棋": "下棋：进行棋类游戏，与“到任”没有反义关系", "唱歌": "唱歌：用声音演唱曲调，与“到任”没有反义关系", "出差": "出差：因公外出办事，与“到任”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到任是到了新的工作地方，开始做事。", "primary_collocate": null, "pronunciation": "dào rèn", "ipa": "tɑʊ̯⁵¹ ɻən⁵¹", "syllable_count": 2, "sentences": [{"text": "新来的经理今天到任。", "target_word": "到任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一到任，就问同事公司的情况。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说我下个月一号到任。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚到任，什么都不太熟。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新主任到任后，开了第一次会。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们的新校长是哪天到任的？", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到任的第一天，来得特别早。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们等着新队长到任。", "target_word": "到任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张医生去年到任，大家都喜欢他。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新老师到任了，我们很高兴。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "到任了", "label": "体标"}], "register": "书面", "sense_fingerprint": "到了新的工作地方并开始做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离职", "is_correct": false, "explanation": "语义：“离职”指离开工作岗位，与“新来的”矛盾"}, {"text": "到任", "is_correct": true, "explanation": "到任：到了新的工作地方开始做事，与“新来的经理今天”相符"}, {"text": "退伍", "is_correct": false, "explanation": "搭配：“退伍”指军人离开部队，经理不能退伍"}, {"text": "下岗", "is_correct": false, "explanation": "语义：“下岗”指失去工作岗位，与“新来的”矛盾"}], "explanations": {"离职": "语义：“离职”指离开工作岗位，与“新来的”矛盾", "到任": "到任：到了新的工作地方开始做事，与“新来的经理今天”相符", "退伍": "搭配：“退伍”指军人离开部队，经理不能退伍", "下岗": "语义：“下岗”指失去工作岗位，与“新来的”矛盾"}, "sentence_index": 0, "correct_answer": "到任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新同学一早就来宿舍到任。", "explanation": "这里应该用〈报到〉。到任只用于就任工作岗位，新同学登记入住要说报到"}, {"text": "嘉宾们陆续到任。", "explanation": "这里应该用〈到场〉。到任指就任工作岗位，嘉宾入场要说到场"}, {"text": "游客已经到任了。", "explanation": "这里应该用〈入住〉。到任不用于游客，住进酒店要说入住"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请假", "is_correct": false, "explanation": "语义：“请假”指暂时离开岗位，与“来得特别早”矛盾"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与“来得特别早”矛盾"}, {"text": "到任", "is_correct": true, "explanation": "到任：到了新的工作地方开始做事，与“第一天”和“来得特别早”相符"}, {"text": "离职", "is_correct": false, "explanation": "语义：“离职”指离开工作岗位，与“来得特别早”矛盾"}], "explanations": {"请假": "语义：“请假”指暂时离开岗位，与“来得特别早”矛盾", "迟到": "语义：“迟到”与“来得特别早”矛盾", "到任": "到任：到了新的工作地方开始做事，与“第一天”和“来得特别早”相符", "离职": "语义：“离职”指离开工作岗位，与“来得特别早”矛盾"}, "sentence_index": 6, "correct_answer": "到任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几位客人刚才到任。", "explanation": "这里应该用〈到访〉。到任用于就任工作岗位，客人来访要说到访"}, {"text": "航班已经到任。", "explanation": "这里应该用〈抵达〉。到任只用于人员就职，航班到达目的地要说抵达"}, {"text": "选手们准时到任。", "explanation": "这里应该用〈入场〉。到任表示就任工作岗位，选手进入比赛场地要说入场"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来的副总下个月到任过。", "corrected_sentence": "新来的副总下个月到任。", "error_description": "错误形式：下个月到任过；正确形式：下个月到任。“过”表示曾经发生的动作，“下个月”指将来，两者不能搭配", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "李主任去年在到任了。", "corrected_sentence": "李主任去年到任了。", "error_description": "错误形式：去年在到任了；正确形式：去年到任了。“在”表示动作正在进行，但“去年”指已经发生的事，“到任”是一次性完成的动作，不能加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
