INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离任", "is_correct": true, "explanation": "离任：离开所任职务，与“到任”相对"}, {"text": "出差", "is_correct": false, "explanation": "出差：因公外出办事，与“到任”没有反义关系"}, {"text": "开会", "is_correct": false, "explanation": "开会：集中讨论事务，与“到任”没有反义关系"}, {"text": "下班", "is_correct": false, "explanation": "下班：结束一天的工作，与“到任”没有反义关系"}], "correct_answer": "离任", "explanations": {"离任": "离任：离开所任职务，与“到任”相对", "出差": "出差：因公外出办事，与“到任”没有反义关系", "开会": "开会：集中讨论事务，与“到任”没有反义关系", "下班": "下班：结束一天的工作，与“到任”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "官员或职员到达任职的地方开始工作。", "primary_collocate": null, "pronunciation": "dào rèn", "ipa": "tɑʊ̯⁵¹ ɻən⁵¹", "syllable_count": 2, "sentences": [{"text": "新校长昨天已经到任了。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王经理下周一到任。", "target_word": "到任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新市长到任后，先去看了老人。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚到任，就开始工作了。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的大使什么时候到任？", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的副局长下周到任，大家都在准备欢迎会。", "target_word": "到任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新局长到任那天，大家都去欢迎他。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到任以后，办公室变得很干净。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的新院长到任了。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说新书记明天上午到任。", "target_word": "到任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "到任了", "label": "体标"}], "register": "书面", "sense_fingerprint": "官员或职员抵达任职地点并开始工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：“退休”指不再工作，与“新校长”矛盾，刚上任不可能昨天就退休"}, {"text": "到任", "is_correct": true, "explanation": "到任：官员到达任职地点开始工作，与“新校长昨天已经”相符"}, {"text": "离任", "is_correct": false, "explanation": "语义：“离任”指离开所任职务，与“新”矛盾，新校长不会昨天已经离任"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”用于学生，不能说校长毕业"}], "explanations": {"退休": "语义：“退休”指不再工作，与“新校长”矛盾，刚上任不可能昨天就退休", "到任": "到任：官员到达任职地点开始工作，与“新校长昨天已经”相符", "离任": "语义：“离任”指离开所任职务，与“新”矛盾，新校长不会昨天已经离任", "毕业": "搭配：“毕业”用于学生，不能说校长毕业"}, "sentence_index": 0, "correct_answer": "到任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新生今天下午来学校到任。", "explanation": "这里应该用〈报到〉。到任只用于官员或职员就任职务，新生办理入学手续要说报到"}, {"text": "观众七点准时到任。", "explanation": "这里应该用〈到场〉。到任指官员或职员就任，观众入场要说到场"}, {"text": "游客下午就到任了。", "explanation": "这里应该用〈入住〉。到任不用于游客，住进酒店要说入住"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离开", "is_correct": false, "explanation": "语义：“离开”与句中“大家都去欢迎他”矛盾"}, {"text": "到任", "is_correct": true, "explanation": "到任：官员到达任职地点开始工作，与“欢迎他”相符"}, {"text": "辞行", "is_correct": false, "explanation": "语义：“辞行”指临走前告别，与“欢迎”的场合矛盾"}, {"text": "退位", "is_correct": false, "explanation": "搭配：“退位”用于君主或元首，不能用于局长"}], "explanations": {"离开": "语义：“离开”与句中“大家都去欢迎他”矛盾", "到任": "到任：官员到达任职地点开始工作，与“欢迎他”相符", "辞行": "语义：“辞行”指临走前告别，与“欢迎”的场合矛盾", "退位": "搭配：“退位”用于君主或元首，不能用于局长"}, "sentence_index": 6, "correct_answer": "到任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来宾十点到任。", "explanation": "这里应该用〈到访〉。到任用于就任职务，来宾来访要说到访"}, {"text": "货车早上六点到任。", "explanation": "这里应该用〈抵达〉。到任只用于人员就职，货车到达目的地要说抵达"}, {"text": "同学们准时到任了。", "explanation": "这里应该用〈出席〉。到任表示就任职务，同学参加活动要说出席"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新校长上个月已经在到任了。", "corrected_sentence": "新校长上个月已经到任了。", "error_description": "错误形式：在到任了；正确形式：到任了。“在”不能加在“到任”前面，多出的“在”让句子不通顺，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新书记下周一到任过。", "corrected_sentence": "新书记下周一到任。", "error_description": "错误形式：下周一到任过；正确形式：下周一到任。“过”表示曾经发生的动作，“下周一”指将来，两者不能搭配", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
