INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98291, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "剪是用剪刀把东西弄开或弄断。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "我想把这张纸剪成两半。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明正在剪指甲。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布太长，你帮我剪一下。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把长头发剪短了。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈剪下一朵花，放在桌子上。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这根线剪断。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐坐在椅子上，让理发师剪头发。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她低着头，认真地剪着一块布。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，爷爷在院子里剪树枝。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新衣服上有一根长线头，请你剪一下。", "target_word": "剪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剪了", "label": "体标"}, {"form": "剪过", "label": "体标"}, {"form": "剪着", "label": "体标"}, {"form": "剪剪", "label": "重叠"}, {"form": "剪刀", "label": "复合"}, {"form": "剪纸", "label": "复合"}], "register": "中性", "sense_fingerprint": "用剪刀把东西弄开或弄断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98291, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剪", "is_correct": true, "explanation": "正确。剪是用剪刀把东西弄开或弄断，读 jiǎn（第三声）。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是“尖锐”。"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是“看见”。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn 与 jiǎn 声母不同（q / j），意思是“浅”。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo 与 jiǎn 韵母不同（iao / ian），意思是“脚”。"}], "explanations": {"剪": "正确。剪是用剪刀把东西弄开或弄断，读 jiǎn（第三声）。", "尖": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是“尖锐”。", "见": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是“看见”。", "浅": "qiǎn 与 jiǎn 声母不同（q / j），意思是“浅”。", "脚": "jiǎo 与 jiǎn 韵母不同（iao / ian），意思是“脚”。"}, "sentence_index": null, "correct_answer": "剪"}, "level_3": {"options": [{"text": "剪", "is_correct": true, "explanation": "正确。“剪成两半”是用剪刀把纸分开，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧纸会烧成灰，不会把纸分成两半。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写成两半”不成立，“写”不能使纸分开。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是咽下液体的动作，不能使纸分开。"}], "explanations": {"剪": "正确。“剪成两半”是用剪刀把纸分开，符合句意。", "烧": "语义：烧纸会烧成灰，不会把纸分成两半。", "写": "搭配：“写成两半”不成立，“写”不能使纸分开。", "喝": "语义：喝是咽下液体的动作，不能使纸分开。"}, "sentence_index": 0, "correct_answer": "剪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈剪了一块西瓜，分给大家吃。", "explanation": "近义混淆：这里应该用〈切〉。切用于西瓜等食物，剪用于纸、布、绳线，不说“剪西瓜”。"}, {"text": "爸爸剪倒了院子里的大树。", "explanation": "近义混淆：这里应该用〈砍〉。大树要用斧头等砍倒，剪刀只用于细软的东西。"}, {"text": "他用剪刀把木板剪断了，准备做个书架。", "explanation": "近义混淆：这里应该用〈锯〉。锯用于木板、木头等硬物，剪刀只剪纸、布、绳线等软物，不能剪断木板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98291, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剪", "is_correct": true, "explanation": "正确。剪是用剪刀把东西弄开或弄断，读 jiǎn（第三声）。"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是“件”。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是“房间”。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn 与 jiǎn 声母不同（x / j），意思是“危险”。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo 与 jiǎn 韵母不同（iao / ian），意思是“角落”。"}], "explanations": {"剪": "正确。剪是用剪刀把东西弄开或弄断，读 jiǎn（第三声）。", "件": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是“件”。", "间": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是“房间”。", "险": "xiǎn 与 jiǎn 声母不同（x / j），意思是“危险”。", "角": "jiǎo 与 jiǎn 韵母不同（iao / ian），意思是“角落”。"}, "sentence_index": null, "correct_answer": "剪"}, "level_3": {"options": [{"text": "剪", "is_correct": true, "explanation": "正确。“剪头发”就是用剪刀把头发剪短，是理发师的工作。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物送进嘴里咽下，头发不能吃。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”用于搬动较重的东西，不说“搬头发”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发出歌声，与理发无关，“唱头发”不成立。"}], "explanations": {"剪": "正确。“剪头发”就是用剪刀把头发剪短，是理发师的工作。", "吃": "语义：吃是把食物送进嘴里咽下，头发不能吃。", "搬": "搭配：“搬”用于搬动较重的东西，不说“搬头发”。", "唱": "语义：唱是发出歌声，与理发无关，“唱头发”不成立。"}, "sentence_index": 6, "correct_answer": "剪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支铅笔钝了，请你帮我剪一下。", "explanation": "近义混淆：这里应该用〈削〉。削用于铅笔、水果等去皮或削尖，剪刀不能用来削铅笔。"}, {"text": "他拿剪刀把玻璃剪了个洞，好伸手开窗。", "explanation": "搭配错误：这里应该用〈砸〉。玻璃又硬又脆，剪刀剪不开。"}, {"text": "下课了，老师让我把黑板上的字剪掉。", "explanation": "近义混淆：这里应该用〈擦〉。黑板上的字要用板擦擦掉，剪只用于纸、布、头发等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把绳子剪了断。", "corrected_sentence": "她把绳子剪断了。", "error_description": "补语位置错误：“剪断”是动补结构，“断”要紧跟“剪”，“了”放在句末；应说“她把绳子剪断了”，“剪了断”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天理发师把我的刘海剪短着。", "corrected_sentence": "昨天理发师把我的刘海剪短了。", "error_description": "体标误用：“剪短”是动补结构，表示已完成的结果，要用“了”。“着”表示动作在持续，不能跟在结果补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
