INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "副总统是国家里排在总统后面的第二位大官。", "primary_collocate": null, "pronunciation": "fù zǒng tǒng", "ipa": "fu˥˩ tsʊŋ˨˩ tʰʊŋ˨˩", "syllable_count": 3, "sentences": [{"text": "这位副总统的职位在国家里排第二。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个国家当了四年副总统。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统的位置仅次于总统。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位副总统常常在电视上讲话。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统和副总统一起参加了晚会。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的副总统住在华盛顿。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想当副总统，可是没有成功。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统今天要坐飞机去北京。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，新副总统很年轻。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位副总统有两个孩子。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位副总统", "label": "量词"}, {"form": "副總統", "label": "繁体"}, {"form": "副总统候选人", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家里排在总统之后的第二位官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副总统", "is_correct": true, "explanation": "正确：副总统是国家里排在总统之后的官员，与「职位在国家里排第二」相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是教职人员，不是国家职位，不可能在国家里排第二。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军是比赛名次，不是国家职位，不能在国家里排第二。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：「大爷」是口语称呼，与「职位」「国家里排第二」的正式语域不合。"}], "explanations": {"副总统": "正确：副总统是国家里排在总统之后的官员，与「职位在国家里排第二」相符。", "老师": "语义：老师是教职人员，不是国家职位，不可能在国家里排第二。", "冠军": "语义：冠军是比赛名次，不是国家职位，不能在国家里排第二。", "大爷": "语域：「大爷」是口语称呼，与「职位」「国家里排第二」的正式语域不合。"}, "sentence_index": 0, "correct_answer": "副总统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "副总统负责城市的交通管理。", "explanation": "这里应该用〈副市长〉。副市长管理城市事务，副总统是国家的副职，不管城市交通。"}, {"text": "副总统每天帮经理整理文件。", "explanation": "这里应该用〈秘书〉。副总统是国家职位，不是个人的文书助理。"}, {"text": "副总统每天在学校给学生上数学课。", "explanation": "这里应该用〈老师〉。副总统是国家职位，不负责给学生上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副总统", "is_correct": true, "explanation": "正确：「想当副总统」指想担任这个国家职务，与句意相符。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：「妈妈」是母亲的身份，与句中的「我哥哥」身份冲突。"}, {"text": "高个子", "is_correct": false, "explanation": "体貌：「高个子」描述身材，不是可以「想当」的身份。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：「女儿」是子女的身份，与句中的「我哥哥」身份冲突。"}], "explanations": {"副总统": "正确：「想当副总统」指想担任这个国家职务，与句意相符。", "妈妈": "语义：「妈妈」是母亲的身份，与句中的「我哥哥」身份冲突。", "高个子": "体貌：「高个子」描述身材，不是可以「想当」的身份。", "女儿": "语义：「女儿」是子女的身份，与句中的「我哥哥」身份冲突。"}, "sentence_index": 6, "correct_answer": "副总统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "副总统每天检查车间。", "explanation": "这里应该用〈副厂长〉。副厂长管理工厂，副总统是国家职务，不能指工厂里的副职。"}, {"text": "副总统是一国之首，拥有最高权力。", "explanation": "这里应该用〈总统〉。副总统排在总统之后，不是一国之首，也没有最高权力；一国之首、拥有最高权力的是总统。"}, {"text": "副总统负责办公室的日常事务。", "explanation": "这里应该用〈副主任〉。副总统是国家职位，不负责机关办公室的日常事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她当了一只副总统。", "corrected_sentence": "她当了一位副总统。", "error_description": "「副总统」指人，量词应用「位」，不应用「只」（「只」多用于动物）。错误形式：一只副总统；正确形式：一位副总统。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被选副总统。", "corrected_sentence": "他被选为副总统。", "error_description": "「选」后接职务要用「选为」，应说「被选为副总统」；「被选副总统」漏了「为」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
