INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助总统工作、总统缺位时可代行其职务的官员。", "primary_collocate": null, "pronunciation": "fù zǒng tǒng", "ipa": "fu˥˩ tsʊŋ˨˩ tʰʊŋ˨˩", "syllable_count": 3, "sentences": [{"text": "总统生病时，副总统可以代行职务。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统每天都要帮总统处理工作。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统不在国内，副总统主持了会议。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的副总统明天宣誓就职。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位副总统以前是一位律师。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统缺位时，副总统要接任。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统将代表总统出席开幕式。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统的办公室离总统的很近。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们选她当副总统，帮总统做事。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副总统昨天接见了外国客人。", "target_word": "副总统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位副总统", "label": "量词"}, {"form": "副總統", "label": "繁体"}, {"form": "副总统候选人", "label": "复合"}], "register": "正式", "sense_fingerprint": "协助总统并可代行总统职务的官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副总统", "is_correct": true, "explanation": "正确：副总统在总统生病时代行其职务，与句意相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是医护人员，不担任国家职务，不能代行总统的职务。"}, {"text": "老大", "is_correct": false, "explanation": "语域：「老大」是口语说法，与「代行职务」这类正式语域不合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不担任国家官职，不能代行总统的职务。"}], "explanations": {"副总统": "正确：副总统在总统生病时代行其职务，与句意相符。", "医生": "语义：医生是医护人员，不担任国家职务，不能代行总统的职务。", "老大": "语域：「老大」是口语说法，与「代行职务」这类正式语域不合。", "厨师": "语义：厨师不担任国家官职，不能代行总统的职务。"}, "sentence_index": 0, "correct_answer": "副总统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的副总统每天帮我整理文件。", "explanation": "这里应该用〈助手〉。副总统是国家的副职官员，不是个人的助理，不能说「我的副总统」。"}, {"text": "我们公司的副总统每天开会。", "explanation": "这里应该用〈副总裁〉。副总统只指国家的副职，公司的副职要说副总裁。"}, {"text": "副总统每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。副总统是协助总统的国家官员，不负责给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副总统", "is_correct": true, "explanation": "正确：副总统是代表总统出席活动的官员，与句意相符。"}, {"text": "记者", "is_correct": false, "explanation": "语义：记者是新闻工作者，不能代表总统出席开幕式。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：「哥们」是口语，与「代表总统」「出席开幕式」的正式语域不合。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不担任国家职务，不能代表总统出席开幕式。"}], "explanations": {"副总统": "正确：副总统是代表总统出席活动的官员，与句意相符。", "记者": "语义：记者是新闻工作者，不能代表总统出席开幕式。", "哥们": "语域：「哥们」是口语，与「代表总统」「出席开幕式」的正式语域不合。", "学生": "语义：学生不担任国家职务，不能代表总统出席开幕式。"}, "sentence_index": 6, "correct_answer": "副总统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "副总统每天早上在校门口迎接学生。", "explanation": "这里应该用〈副校长〉。副总统指国家的副职官员，学校的副职要说副校长。"}, {"text": "副总统负责每天收作业。", "explanation": "这里应该用〈副班长〉。副总统是国家职务，不负责班级的日常事务。"}, {"text": "副总统是政府首脑，负责领导内阁。", "explanation": "这里应该用〈首相〉。副总统是总统的副职，不是政府首脑，也不领导内阁；领导内阁的是首相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们选出了一只副总统。", "corrected_sentence": "他们选出了一位副总统。", "error_description": "量词误用：副总统指人，量词应用「位」，不用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前当过副总统过。", "corrected_sentence": "他以前当过副总统。", "error_description": "重复用“过”：“过”只用一次，紧接动词表示经历，应说“当过副总统”，不说“当过副总统过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "半数是一个总数里的一半。", "primary_collocate": null, "pronunciation": "bàn shù", "ipa": "pan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "全班四十人，半数是男生，其余都是女生。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的队伍有半数来自北方。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次聚会，半数的同学带了礼物。", "target_word": "半数", "complexity_tier": "T3", "furigana": "Zhè cì jù huì，bàn shù de tóng xué dài le lǐ wù。", "sentence_source": "generated"}, {"text": "超过半数的老师今天没来学校。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的鱼死了半数。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家半数的房间都空着。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半数人同意，我们就可以开始。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动，半数的票已经卖完了。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里半数的东西都在打折。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨以后，半数的路都不能走了。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半数以上", "label": "复合"}, {"form": "半数以下", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个总数里的一半", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半数", "is_correct": true, "explanation": "bàn shù（第四声）指总数的一半，是正确答案。"}, {"text": "办事", "is_correct": false, "explanation": "bàn shì 与 bàn shù 只在第二个音节的韵母不同（ì 与 u），意思是办理事务，不是一半的数量。"}, {"text": "半熟", "is_correct": false, "explanation": "bàn shú（第二声）与 bàn shù（第四声）只差第二个音节的声调，意思是半生半熟，如“半熟鸡蛋”。"}, {"text": "半速", "is_correct": false, "explanation": "bàn sù 与 bàn shù 只差第二个音节的声母（s 与 sh），意思是一半的速度，如“半速播放”。"}], "explanations": {"半数": "bàn shù（第四声）指总数的一半，是正确答案。", "办事": "bàn shì 与 bàn shù 只在第二个音节的韵母不同（ì 与 u），意思是办理事务，不是一半的数量。", "半熟": "bàn shú（第二声）与 bàn shù（第四声）只差第二个音节的声调，意思是半生半熟，如“半熟鸡蛋”。", "半速": "bàn sù 与 bàn shù 只差第二个音节的声母（s 与 sh），意思是一半的速度，如“半速播放”。"}, "sentence_index": null, "correct_answer": "半数"}, "level_3": {"options": [{"text": "半数", "is_correct": true, "explanation": "半数：总数的一半，与“全班四十人”的总数相合，指其中一半是男生。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不属于“全班四十人”这一群学生，与句子的所指不符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“教室”不能作“是男生”的主语，搭配不通。"}, {"text": "男生", "is_correct": false, "explanation": "语义：“男生”不能与后面的“是女生”的对照同时成立，句子讲不通。"}], "explanations": {"半数": "半数：总数的一半，与“全班四十人”的总数相合，指其中一半是男生。", "老师": "语义：老师不属于“全班四十人”这一群学生，与句子的所指不符。", "教室": "搭配：“教室”不能作“是男生”的主语，搭配不通。", "男生": "语义：“男生”不能与后面的“是女生”的对照同时成立，句子讲不通。"}, "sentence_index": 0, "correct_answer": "半数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块饼的半数被我吃了。", "explanation": "这里应该用〈一半〉。半数指由许多个体组成的总数的一半，一块饼是整体，切开吃要用一半。"}, {"text": "这杯牛奶的半数被弟弟喝了。", "explanation": "这里应该用〈一半〉。半数指由许多个体组成的总数的一半，一杯牛奶不能按个数计算，要用一半。"}, {"text": "他半数时间在图书馆。", "explanation": "这里应该用〈多半〉。半数用于可以计数的人或事物，时间不能按个数计算，要用多半或一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半数", "is_correct": true, "explanation": "半数：总数的一半，修饰“人”，表示有一半的人同意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有意志，不能表示同意，与“同意”的主体不符。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“同意”需要有意志的人作主语，“窗户”不能充当这个主语。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不能说“同意”，与句子所要表达的意思不相容。"}], "explanations": {"半数": "半数：总数的一半，修饰“人”，表示有一半的人同意。", "桌子": "语义：桌子没有意志，不能表示同意，与“同意”的主体不符。", "窗户": "配价：“同意”需要有意志的人作主语，“窗户”不能充当这个主语。", "书本": "语义：书本不能说“同意”，与句子所要表达的意思不相容。"}, "sentence_index": 6, "correct_answer": "半数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在路上走了半数。", "explanation": "这里应该用〈半小时〉。半数指一个总数中的一半，用于人或事物的数量，不能用来表示时间长短。"}, {"text": "这件衣服打半数。", "explanation": "这里应该用〈半价〉。半数是数量的一半，不表示价格的折扣，应说“打半价”。"}, {"text": "他在国外住了半数。", "explanation": "这里应该用〈半年〉。半数用于可以计数的人或事物，表示住的时间长短要用时间词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校的一个半数老师住在城里。", "corrected_sentence": "我们学校的半数老师住在城里。", "error_description": "“半数”前不能加数量词“一个”。错误在于多加了“一个”，应说“我们学校的半数老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子的人半数会说普通话的一个。", "corrected_sentence": "这个村子的人半数会说普通话。", "error_description": "句末多加了“的一个”，与“半数”的用法冲突：半数本身就表示数量，不能再接“一个”。正确形式是“这个村子的人半数会说普通话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总数的一半。", "primary_collocate": null, "pronunciation": "bàn shù", "ipa": "pan˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "教室里的学生，半数是女生。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，半数同学得了九十分。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司半数员工今天去外地开会。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班半数人喜欢踢足球。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票时，半数以上的人说同意。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这箱苹果有半数已经坏了。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次调查中，半数人把工资存进了银行。", "target_word": "半数", "complexity_tier": "T3", "furigana": "Zhè cì diào chá zhōng，bàn shù rén bǎ gōng zī cún jìn le yín háng。", "sentence_source": "generated"}, {"text": "来参加会议的人不到半数。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上半数的书是我妹妹的。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市半数家庭都有汽车。", "target_word": "半数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半数以上", "label": "复合"}, {"form": "半数以下", "label": "复合"}], "register": "中性", "sense_fingerprint": "总数的一半，多指人或事物的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半数", "is_correct": true, "explanation": "bàn shù（第四声）指总数的一半，是正确答案。"}, {"text": "办事", "is_correct": false, "explanation": "bàn shì 与 bàn shù 只在第二个音节的韵母不同（ì 与 u），意思是办理事务，不是一半的数量。"}, {"text": "半熟", "is_correct": false, "explanation": "bàn shú（第二声）与 bàn shù（第四声）只差第二个音节的声调，意思是半生半熟，如“半熟鸡蛋”。"}, {"text": "半速", "is_correct": false, "explanation": "bàn sù 与 bàn shù 只差第二个音节的声母（s 与 sh），意思是一半的速度，如“半速播放”。"}], "explanations": {"半数": "bàn shù（第四声）指总数的一半，是正确答案。", "办事": "bàn shì 与 bàn shù 只在第二个音节的韵母不同（ì 与 u），意思是办理事务，不是一半的数量。", "半熟": "bàn shú（第二声）与 bàn shù（第四声）只差第二个音节的声调，意思是半生半熟，如“半熟鸡蛋”。", "半速": "bàn sù 与 bàn shù 只差第二个音节的声母（s 与 sh），意思是一半的速度，如“半速播放”。"}, "sentence_index": null, "correct_answer": "半数"}, "level_3": {"options": [{"text": "半数", "is_correct": true, "explanation": "半数：总数的一半，与“学生”的数量相合，表示一半学生是女生。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不是学生，与“教室里的学生”所指的对象不符。"}, {"text": "男生", "is_correct": false, "explanation": "语义：“男生”与后面的“是女生”直接矛盾，无法作这里的主语。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“教室”不能作“是女生”的主语，两者搭配不通。"}], "explanations": {"半数": "半数：总数的一半，与“学生”的数量相合，表示一半学生是女生。", "老师": "语义：老师不是学生，与“教室里的学生”所指的对象不符。", "男生": "语义：“男生”与后面的“是女生”直接矛盾，无法作这里的主语。", "教室": "搭配：“教室”不能作“是女生”的主语，两者搭配不通。"}, "sentence_index": 0, "correct_answer": "半数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的半数被我吃掉了。", "explanation": "这里应该用〈一半〉。半数指由许多个体组成的总数的一半，一个西瓜是整体，切开吃要用一半。"}, {"text": "这瓶水的半数被我喝了。", "explanation": "这里应该用〈一半〉。半数用于可以计数的人或事物，一瓶水不能按个数计算，要用一半。"}, {"text": "我半数时间在图书馆。", "explanation": "这里应该用〈多半〉。半数用于可以计数的人或事物，时间不能按个数计算，要用多半或一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半数", "is_correct": true, "explanation": "半数：总数的一半，修饰“人”，说明一半的人把工资存进了银行。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不是人，不能作“把……存进了银行”这个动作的主体。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是人，不能作“把……存进了银行”这个动作的主体。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“银行”已经是“存进了”的终点，不能再作主语，搭配不通。"}], "explanations": {"半数": "半数：总数的一半，修饰“人”，说明一半的人把工资存进了银行。", "工资": "语义：工资不是人，不能作“把……存进了银行”这个动作的主体。", "钥匙": "语义：钥匙不是人，不能作“把……存进了银行”这个动作的主体。", "银行": "搭配：“银行”已经是“存进了”的终点，不能再作主语，搭配不通。"}, "sentence_index": 6, "correct_answer": "半数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在图书馆待了半数。", "explanation": "这里应该用〈半天〉。半数指一个总数中的一半，用于人或事物的数量，不能用来表示时间的长短。"}, {"text": "这件衣服打了半数的折。", "explanation": "这里应该用〈五折〉。半数指总数中的一半，用于可以计数的人或事物；折扣是比例，不能说“半数的折”。"}, {"text": "他在国外住了半数。", "explanation": "这里应该用〈半年〉。半数用于可以计数的人或事物，表示住的时间长短要用“半年”之类的时间词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班半数个同学爱看书。", "corrected_sentence": "我们班半数同学爱看书。", "error_description": "“半数”后面不能加量词“个”。错误形式是“半数个同学”，正确形式是“半数同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校一个半数教师都住在附近。", "corrected_sentence": "这所学校半数教师都住在附近。", "error_description": "“半数”前不能加数量词“一个”。错误在于在“半数”前多加了“一个”，应直接说“半数教师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
