INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98303, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受害是被别人弄伤或弄坏，吃了亏。", "primary_collocate": null, "pronunciation": "shòu hài", "ipa": "ʂou̯⁵¹ xai̯⁵¹", "syllable_count": 2, "sentences": [{"text": "老人被骗子骗了钱，成了受害的人。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多顾客买了假货，受害不少。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信了坏人的话，结果自己受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人老受害，坏人却没事，真不公平。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李借钱给朋友，朋友跑了，他受害最大。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居在网上买东西被骗，也受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人乱说话，一个无辜的同学就受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不听我的话，以后受害的是你自己。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司骗了很多人，大家都受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很后悔，因为他的错，朋友也受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受害了", "label": "体标（了）"}, {"form": "受害者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "被他人伤害而吃亏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98303, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受害", "is_correct": true, "explanation": "正确：“受害”指遭受伤害、吃亏，与“被骗子骗了钱”相符。"}, {"text": "得利", "is_correct": false, "explanation": "语义：“得利”指获得好处，与“被骗了钱”的结果正相反。"}, {"text": "获奖", "is_correct": false, "explanation": "语义：“获奖”指得到奖励，与“被骗子骗了钱”的遭遇毫不相关。"}, {"text": "施害", "is_correct": false, "explanation": "语义：“施害”指伤害别人，老人被骗了钱，是被伤害的一方，不是施害的人。"}], "explanations": {"受害": "正确：“受害”指遭受伤害、吃亏，与“被骗子骗了钱”相符。", "得利": "语义：“得利”指获得好处，与“被骗了钱”的结果正相反。", "获奖": "语义：“获奖”指得到奖励，与“被骗子骗了钱”的遭遇毫不相关。", "施害": "语义：“施害”指伤害别人，老人被骗了钱，是被伤害的一方，不是施害的人。"}, "sentence_index": 0, "correct_answer": "受害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革后，大多数人都受害，生活变得更好了。", "explanation": "这里应该用〈受益〉。“受害”指吃亏、遭伤害，与“生活变得更好”的结果相矛盾。"}, {"text": "老人退休后终于能受害了，过上了安稳的日子。", "explanation": "这里应该用〈享福〉。“受害”指遭受伤害、吃亏，与“过上了安稳的日子”正好相反。"}, {"text": "他在比赛中受害，所以得分很高。", "explanation": "这里应该用〈占优〉。“受害”指吃亏、遭伤害，与“得分很高”的结果相矛盾，因果也说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受害", "is_correct": true, "explanation": "正确：“受害”指遭受伤害，与“有人乱说话”导致的后果相符。"}, {"text": "发财", "is_correct": false, "explanation": "语义：“发财”指获得大量财富，与“乱说话”导致的伤害结果正相反。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“有人乱说话”的因果关系说不通。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”需带受事宾语，“同学就批评了”缺少对象，且与“无辜”的角色冲突。"}], "explanations": {"受害": "正确：“受害”指遭受伤害，与“有人乱说话”导致的后果相符。", "发财": "语义：“发财”指获得大量财富，与“乱说话”导致的伤害结果正相反。", "结婚": "语义：“结婚”与“有人乱说话”的因果关系说不通。", "批评": "配价：“批评”需带受事宾语，“同学就批评了”缺少对象，且与“无辜”的角色冲突。"}, "sentence_index": 6, "correct_answer": "受害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很受害，躲过了那场事故。", "explanation": "这里应该用〈幸运〉。“受害”指遭受伤害，与“躲过了那场事故”的庆幸语境不合。"}, {"text": "他这次考试得了第一，真是受害了。", "explanation": "这里应该用〈获益〉。“受害”指吃亏、遭伤害，与“得了第一”的好结果相反。"}, {"text": "我们队受害了，比分领先很多。", "explanation": "这里应该用〈获胜〉。“受害”指遭受伤害，不能用来描述比赛的胜利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多老人在这次诈骗中成了受害了。", "corrected_sentence": "很多老人在这次诈骗中成了受害者。", "error_description": "“成了”后应接名词“受害者”，不能接动词形式“受害了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次骗局中，老年人受害了最重。", "corrected_sentence": "这次骗局中，老年人受害最重。", "error_description": "“受害”后面接“最重”这样的程度说明时，不能加“了”，应说“老年人受害最重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遭受损害或伤害。", "primary_collocate": null, "pronunciation": "shòu hài", "ipa": "ʂou̯⁵¹ xai̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这次大水来得很急，农民受害很重。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水被工厂弄脏，鱼都受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，沿海的村子受害最大。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让这一带的庄稼受害不少。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震中受害的家庭得到了帮助。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪使很多果树受害。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气不好，孩子的身体也会受害。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火烧了山，山上的动物受害了。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受害的居民正在等着政府的帮助。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次洪水中，南方三个城市受害最严重。", "target_word": "受害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受害了", "label": "体标（了）"}, {"form": "受害者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "遭受灾害或环境带来的损害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受害", "is_correct": true, "explanation": "正确：“受害”指遭受损害，与“大水来得很急”的灾害语境相符。"}, {"text": "受益", "is_correct": false, "explanation": "语义：“受益”指得到好处，与“大水来得很急”的灾害语境正相反。"}, {"text": "丰收", "is_correct": false, "explanation": "语义：“丰收”指收成好，与“大水来得很急”的灾害语境矛盾。"}, {"text": "建设", "is_correct": false, "explanation": "配价：“建设”是及物动词，需带宾语（建设家园），“农民建设很重”缺少对象，句子不通。"}], "explanations": {"受害": "正确：“受害”指遭受损害，与“大水来得很急”的灾害语境相符。", "受益": "语义：“受益”指得到好处，与“大水来得很急”的灾害语境正相反。", "丰收": "语义：“丰收”指收成好，与“大水来得很急”的灾害语境矛盾。", "建设": "配价：“建设”是及物动词，需带宾语（建设家园），“农民建设很重”缺少对象，句子不通。"}, "sentence_index": 0, "correct_answer": "受害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风调雨顺让这一带的庄稼受害不少。", "explanation": "这里应该用〈获益〉。“受害”指遭受损害，与“风调雨顺”的好结果矛盾。"}, {"text": "下了一场及时雨，庄稼都受害了，长得特别好。", "explanation": "这里应该用〈受益〉。“受害”指遭受损害，与“及时雨”“长得特别好”相矛盾。"}, {"text": "今年的粮食产量大大受害了，农民都很高兴。", "explanation": "这里应该用〈增产〉。“受害”指遭受损害，不能描述产量增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受害", "is_correct": true, "explanation": "正确：“受害”指遭受损害，与“空气不好”的因果关系相符。"}, {"text": "好转", "is_correct": false, "explanation": "语义：“好转”指变好，与“空气不好”的因果关系正相反。"}, {"text": "旅行", "is_correct": false, "explanation": "搭配：“身体”不能作“旅行”的主语，“身体也会旅行”搭配不当。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”的主语须是人，“孩子的身体也会散步”不合常理。"}], "explanations": {"受害": "正确：“受害”指遭受损害，与“空气不好”的因果关系相符。", "好转": "语义：“好转”指变好，与“空气不好”的因果关系正相反。", "旅行": "搭配：“身体”不能作“旅行”的主语，“身体也会旅行”搭配不当。", "散步": "搭配：“散步”的主语须是人，“孩子的身体也会散步”不合常理。"}, "sentence_index": 6, "correct_answer": "受害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次洪水中，我们村离河很远，一点也没受害，大家都受害了。", "explanation": "这里应该用〈放心〉。“受害”指遭受损害，前面说没受损，后面又说受害，前后矛盾。"}, {"text": "春天雨水很多，这片树林受害得越来越绿了。", "explanation": "这里应该用〈长〉。“受害”指遭受损害，不能描述树林越来越绿。"}, {"text": "这块地的产量很高，年年受害。", "explanation": "这里应该用〈丰产〉。“受害”指遭受损害，与“产量很高”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场暴雨让不少村民受害者了。", "corrected_sentence": "这场暴雨让不少村民受害了。", "error_description": "“受害者”是名词，不能直接加“了”，这里应该说“受害了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次台风过后，很多果树被受害了。", "corrected_sentence": "这次台风过后，很多果树受害了。", "error_description": "“受害”本身已表示遭受伤害，不能再加“被”，应说“很多果树受害了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98307, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "左派", "is_correct": true, "explanation": "正确。“左派”指政治上较激进的一派，与“右派”（偏保守）相对。"}, {"text": "学生", "is_correct": false, "explanation": "无关：“学生”指求学的人，不是政治派别，与“右派”没有反义关系。"}, {"text": "农民", "is_correct": false, "explanation": "无关：“农民”指从事农业的人，与“右派”没有反义关系。"}, {"text": "工人", "is_correct": false, "explanation": "无关：“工人”指从事体力劳动的人，与“右派”没有反义关系。"}], "correct_answer": "左派", "explanations": {"左派": "正确。“左派”指政治上较激进的一派，与“右派”（偏保守）相对。", "学生": "无关：“学生”指求学的人，不是政治派别，与“右派”没有反义关系。", "农民": "无关：“农民”指从事农业的人，与“右派”没有反义关系。", "工人": "无关：“工人”指从事体力劳动的人，与“右派”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
