INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "右派是一个团体里，想法比较保守的那一部分人。", "primary_collocate": null, "pronunciation": "yòu pài", "ipa": "joʊ˥˩ pʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "党内的右派不同意改变计划。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "委员会里的右派想保持老办法。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "会上，右派和左派吵了起来。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个党派内部有右派，总是反对新想法。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "议会里的右派希望慢慢改，不想太快。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "协会里的右派主要是老会员，他们不喜欢新东西。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "理事会里的右派觉得不用改规定。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "董事会里的右派坚持旧方法，老板没有改。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "这个党派里右派比较少。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "委员们中的右派说，先看看再决定。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "右派分子", "label": "复合"}], "register": "中性", "sense_fingerprint": "团体内部想法偏保守的一部分人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右派", "is_correct": true, "explanation": "正确。“右派”指团体内想法较保守的一部分人，与“党内的……不同意改变计划”相符。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“党内的”不能修饰“猫”，句中指的是党内的一类人。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：小孩子不属于党内的派别，与“党内”的语境冲突。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外来的旅行者，不会是党内的一派。"}], "explanations": {"右派": "正确。“右派”指团体内想法较保守的一部分人，与“党内的……不同意改变计划”相符。", "猫": "搭配：“党内的”不能修饰“猫”，句中指的是党内的一类人。", "小孩子": "语义：小孩子不属于党内的派别，与“党内”的语境冲突。", "游客": "语义：游客是外来的旅行者，不会是党内的一派。"}, "sentence_index": 0, "correct_answer": "右派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "党内的右派主张快速改革。", "explanation": "这里应该用〈左派〉。右派指偏保守的一部分人，主张快速改革的是左派。"}, {"text": "会上坐着一只右派。", "explanation": "这里应该用〈个〉。右派指人，量词用“个”，“只”多用于动物。"}, {"text": "他坐在会议室的右派。", "explanation": "这里应该用〈右边〉。右派指团体中偏保守的人，不能表示方位，表示位置要用〈右边〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右派", "is_correct": true, "explanation": "正确。“右派”指团体内想法较保守的人，与“理事会里的……觉得不用改规定”相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能是理事会的成员，与“理事会里的”语境冲突。"}, {"text": "小鸟", "is_correct": false, "explanation": "搭配：“理事会里的”不能修饰“小鸟”，与“觉得”的主语不搭。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不是人，不能“觉得”，与句子语境冲突。"}], "explanations": {"右派": "正确。“右派”指团体内想法较保守的人，与“理事会里的……觉得不用改规定”相符。", "植物": "语义：植物不能是理事会的成员，与“理事会里的”语境冲突。", "小鸟": "搭配：“理事会里的”不能修饰“小鸟”，与“觉得”的主语不搭。", "白菜": "语义：白菜不是人，不能“觉得”，与句子语境冲突。"}, "sentence_index": 6, "correct_answer": "右派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "右派的委员希望马上改革。", "explanation": "这里应该用〈激进派〉。右派偏保守，希望马上改革的是激进派。"}, {"text": "会上来了一条右派。", "explanation": "这里应该用〈个〉。右派指人，应该用量词“个”，“条”用于细长的东西。"}, {"text": "车子向右派。", "explanation": "这里应该用〈右转〉。“右派”表示团体中的人，不能表示方向，表示向右行驶应说〈右转〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
