INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治上较保守的派别或人士。", "primary_collocate": null, "pronunciation": "yòu pài", "ipa": "joʊ˥˩ pʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的右派反对提高税率。", "target_word": "右派", "complexity_tier": "T3", "furigana": "yòu pài", "sentence_source": "generated"}, {"text": "报纸说，右派赢得了选举。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "右派在政治上比较保守。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府里的右派一直反对改革。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是有名的右派，常上电视讲话。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "右派支持传统，不想马上改革。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举前，右派的支持者很多。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一直是右派。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "右派的领导人今天发表了讲话。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人不喜欢右派的看法。", "target_word": "右派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "右派分子", "label": "复合"}], "register": "中性", "sense_fingerprint": "政治上偏保守的派别或人士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右派", "is_correct": true, "explanation": "正确。“右派”指政治上较保守的派别或人士，与“反对提高税率”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人或团体，不能“反对”提高税率。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与“反对提高税率”的语境冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“这个国家的”不能修饰“窗户”，窗户也不会“反对”。"}], "explanations": {"右派": "正确。“右派”指政治上较保守的派别或人士，与“反对提高税率”相符。", "石头": "语义：石头不是人或团体，不能“反对”提高税率。", "蛋糕": "语义：蛋糕是食物，与“反对提高税率”的语境冲突。", "窗户": "搭配：“这个国家的”不能修饰“窗户”，窗户也不会“反对”。"}, "sentence_index": 0, "correct_answer": "右派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府里的右派主张快速改革。", "explanation": "这里应该用〈左派〉。右派指政治上较保守的一方，主张快速改革的是左派。"}, {"text": "政府里来了一块右派。", "explanation": "这里应该用〈个〉。右派指人，量词用“个”，“块”用于块状的东西。"}, {"text": "他用右派拿着杯子。", "explanation": "这里应该用〈右手〉。“右派”表示团体中的人，不能表示手，表示用右边的手应说〈右手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右派", "is_correct": true, "explanation": "正确。“右派”指保守派别，其支持者多，与“选举前，……的支持者很多”相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能拥有支持者，与“选举”的语境冲突。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”不能与“支持者”搭配，句子语义不通。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是人或派别，不会有“支持者”，与选举语境冲突。"}], "explanations": {"右派": "正确。“右派”指保守派别，其支持者多，与“选举前，……的支持者很多”相符。", "河流": "语义：河流不能拥有支持者，与“选举”的语境冲突。", "椅子": "搭配：“椅子”不能与“支持者”搭配，句子语义不通。", "树叶": "语义：树叶不是人或派别，不会有“支持者”，与选举语境冲突。"}, "sentence_index": 6, "correct_answer": "右派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书放在桌子的右派。", "explanation": "这里应该用〈右侧〉。右派指政治上较保守的一方人士，不能表示位置，“桌子的右边”应说〈右侧〉。"}, {"text": "电视上来了一条右派，讲了很久。", "explanation": "这里应该用〈个〉。右派指人，应该用量词“个”，“条”用于细长的东西。"}, {"text": "车子向右派。", "explanation": "这里应该用〈右转〉。“右派”表示团体中的人，不能表示方向，表示向右行驶应说〈右转〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有一只右派反对提高税率。", "corrected_sentence": "这个国家有一个右派反对提高税率。", "error_description": "量词错误：“右派”指人，应该用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只有名的右派，常上电视讲话。", "corrected_sentence": "他是一个有名的右派，常上电视讲话。", "error_description": "量词错误：“右派”指人，应该用量词“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
