INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外网是一个单位以外、大家都可以上的网。", "primary_collocate": null, "pronunciation": "wài wǎng", "ipa": "waɪ̯˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司里有内网，也有外网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在学校图书馆连上了外网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，上课时不能用外网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的外网很慢，视频打不开。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的电脑坏了，现在上不了外网。", "target_word": "外网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先连外网，再下载文件。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间没有外网，只有内网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在公司用不了外网聊天。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，外网的密码是多少？", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在家的时候，我只用外网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外网地址", "label": "复合"}, {"form": "外网访问", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位以外大家都能上的网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外网", "is_correct": true, "explanation": "正确：外网与内网相对，指单位以外的公共网络。"}, {"text": "外国", "is_correct": false, "explanation": "语义：外国是国家，与“内网”并列说不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是场所，不是网络，与“内网”并列不合。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是网络，不能与“内网”并列。"}], "explanations": {"外网": "正确：外网与内网相对，指单位以外的公共网络。", "外国": "语义：外国是国家，与“内网”并列说不通。", "学校": "语义：学校是场所，不是网络，与“内网”并列不合。", "苹果": "语义：苹果是水果，不是网络，不能与“内网”并列。"}, "sentence_index": 0, "correct_answer": "外网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的外网新增了很多图片，同学们都很喜欢。", "explanation": "这里应该用〈网站〉。新增图片的是网站，外网指网络，不能说“外网新增了图片”。"}, {"text": "他在一家外网公司工作，负责做软件。", "explanation": "这里应该用〈互联网〉。“互联网公司”是固定说法，外网只指单位以外的网络，不修饰公司。"}, {"text": "我们公司的外网只让员工使用，外人上不去。", "explanation": "这里应该用〈内网〉。外网指单位以外、大家都可以上的网；只让员工用、外人上不去的是内网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外网", "is_correct": true, "explanation": "正确：外网指单位以外的公共网络，这个房间没有它。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是网络，与“内网”不并列。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是网络，无法和“内网”并列。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭是食物，不是网络，不能与“只有内网”形成对比。"}], "explanations": {"外网": "正确：外网指单位以外的公共网络，这个房间没有它。", "感冒": "语义：感冒是疾病，不是网络，与“内网”不并列。", "天气": "语义：天气不是网络，无法和“内网”并列。", "米饭": "语义：米饭是食物，不是网络，不能与“只有内网”形成对比。"}, "sentence_index": 6, "correct_answer": "外网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这个外网发给了朋友。", "explanation": "这里应该用〈网址〉。能发给朋友的是网址，外网是网络，不能“发”。"}, {"text": "电脑要用外网连到路由器上。", "explanation": "这里应该用〈网线〉。外网是网络，不是线，无法用来连接路由器。"}, {"text": "我们中午点了一个外网，很快就送到了。", "explanation": "这里应该用〈外卖〉。外网是网络，不是食物，不能点，也不能“送到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的外网了坏。", "corrected_sentence": "这个房间的外网坏了。", "error_description": "语序错误：“坏了”的“了”应紧跟“坏”；说成“了坏”不对，应说“外网坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这里有一座外网，谁都能上。", "corrected_sentence": "我们这里有一个外网，谁都能上。", "error_description": "量词错误：“座”用于山、楼等大型物体，外网不能用“座”来数，应说“一个外网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
