INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机构内部网络之外的公共互联网。", "primary_collocate": null, "pronunciation": "wài wǎng", "ipa": "waɪ̯˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司的电脑不能直接连外网。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在办公室里，我们用外网查资料。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用外网下载一个软件。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑只能上内网，不能上外网。", "target_word": "外网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的外网速度很快。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的内网和外网是分开的。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在家里可以用外网看新闻。", "target_word": "外网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作时不要随便把资料传到外网上。", "target_word": "外网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天上不了外网，网络出问题了。", "target_word": "外网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统要先连接外网才能更新。", "target_word": "外网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外网地址", "label": "复合"}, {"form": "外网访问", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位内部网络以外的公共互联网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外网", "is_correct": true, "explanation": "正确：外网指单位以外的公共互联网，“连外网”即接入它。"}, {"text": "外国", "is_correct": false, "explanation": "语义：外国是国家，不是网络，无法用“连”接入。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不是可以连接的网络。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“连”后接网络或设备，不说“连感情”。"}], "explanations": {"外网": "正确：外网指单位以外的公共互联网，“连外网”即接入它。", "外国": "语义：外国是国家，不是网络，无法用“连”接入。", "时间": "语义：时间是抽象概念，不是可以连接的网络。", "感情": "搭配：“连”后接网络或设备，不说“连感情”。"}, "sentence_index": 0, "correct_answer": "外网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都在外网上班，工作很忙。", "explanation": "这里应该用〈公司〉。外网是网络，不是地点，不能在它“上班”。"}, {"text": "我的外网做得很漂亮，很多人喜欢点进来看。", "explanation": "这里应该用〈网站〉。外网是网络，不是网页；网页做得漂亮要说“网站”。"}, {"text": "他在外网留过学，回国后找到了好工作。", "explanation": "这里应该用〈外国〉。“留学”要去外国学习，外网是网络，不能说“在外网留学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外网", "is_correct": true, "explanation": "正确：“用外网看新闻”指通过单位以外的公共网络上网。"}, {"text": "感冒", "is_correct": false, "explanation": "配价：“用”后要接工具或途径，“感冒”不能用来看新闻。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是看新闻的途径。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能用来看新闻，句子说不通。"}], "explanations": {"外网": "正确：“用外网看新闻”指通过单位以外的公共网络上网。", "感冒": "配价：“用”后要接工具或途径，“感冒”不能用来看新闻。", "天气": "语义：天气是气象状况，不是看新闻的途径。", "垃圾": "语义：垃圾不能用来看新闻，句子说不通。"}, "sentence_index": 6, "correct_answer": "外网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个外网可以直接打开，不用输入密码。", "explanation": "这里应该用〈网址〉。能直接打开的是网页地址，外网是网络，不能“打开”。"}, {"text": "请把外网插到路由器上，然后就能用了。", "explanation": "这里应该用〈网线〉。外网是网络，不是线，无法插到路由器上。"}, {"text": "我每天都要花一个小时学习外网，很辛苦。", "explanation": "这里应该用〈外语〉。学习的是语言，外网是网络，不能说“学习外网”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台外网的速度很快，下载文件很方便。", "corrected_sentence": "这个外网的速度很快，下载文件很方便。", "error_description": "量词错误：“外网”是网络，不能用“台”（用于机器、设备）来数，应说“这个外网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的电脑刚上连外网，就收到了新邮件。", "corrected_sentence": "我的电脑刚连上外网，就收到了新邮件。", "error_description": "语序错误：结果补语“上”应紧跟动词，说“连上外网”；“上连外网”的顺序是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”指钱财少，与“多金”（钱财很多）意思相反。"}, {"text": "勤奋", "is_correct": false, "explanation": "“勤奋”形容努力，与“多金”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“多金”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“多金”没有反义关系。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”指钱财少，与“多金”（钱财很多）意思相反。", "勤奋": "“勤奋”形容努力，与“多金”没有反义关系。", "高兴": "“高兴”形容心情，与“多金”没有反义关系。", "安静": "“安静”形容声音或环境，与“多金”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”指钱财少，与“多金”（钱财很多）意思相反。"}, {"text": "诚实", "is_correct": false, "explanation": "“诚实”形容品德，与“多金”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度或气氛，与“多金”没有反义关系。"}, {"text": "年轻", "is_correct": false, "explanation": "“年轻”形容年龄，与“多金”没有反义关系。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”指钱财少，与“多金”（钱财很多）意思相反。", "诚实": "“诚实”形容品德，与“多金”没有反义关系。", "严肃": "“严肃”形容态度或气氛，与“多金”没有反义关系。", "年轻": "“年轻”形容年龄，与“多金”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人非常有钱。", "primary_collocate": null, "pronunciation": "duō jīn", "ipa": "tuɔ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "这个多金的老人把钱都送给了学校。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他非常多金，想买什么就买什么。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男朋友既帅气又多金。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多金的先生请大家吃了一顿大餐。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不多金，可是我很快乐。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪轻轻就多金，让人羡慕。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司的老板多金又大方。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢多金的男人，觉得这样才有安全感。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家里多金，从小不用担心钱。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上说，帅气又多金的人很受欢迎。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容人非常有钱，想买什么就买什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吝啬", "is_correct": false, "explanation": "语义：“吝啬”的人不会把钱都送人，与“把钱都送给了学校”矛盾。"}, {"text": "多金", "is_correct": true, "explanation": "形容人非常有钱，与“把钱都送给了学校”的慷慨相符。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”与“老人”相矛盾，“年轻的老人”不能成立，句意不通。"}, {"text": "富饶", "is_correct": false, "explanation": "搭配：“富饶”多形容地区、土地，不用来形容老人。"}], "explanations": {"吝啬": "语义：“吝啬”的人不会把钱都送人，与“把钱都送给了学校”矛盾。", "多金": "形容人非常有钱，与“把钱都送给了学校”的慷慨相符。", "年轻": "语义：“年轻”与“老人”相矛盾，“年轻的老人”不能成立，句意不通。", "富饶": "搭配：“富饶”多形容地区、土地，不用来形容老人。"}, "sentence_index": 0, "correct_answer": "多金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子的生活很多金。", "explanation": "这里应该用〈富裕〉。多金只形容人的钱财多，村子的生活要说富裕。"}, {"text": "这笔存款很多金。", "explanation": "这里应该说〈数额大〉。“多金”只形容人的钱财多，存款的数额多要说“数额大”。"}, {"text": "这位老人的精神世界很多金。", "explanation": "这里应该用〈富有〉。“多金”只形容人的钱财多，不能用来形容精神世界；〈富有〉可指精神上的丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小气", "is_correct": false, "explanation": "语义：“小气”与后半句“大方”的性格相反，不能并列。"}, {"text": "富庶", "is_correct": false, "explanation": "搭配：“富庶”多形容地区、土地，不用来形容公司老板。"}, {"text": "多金", "is_correct": true, "explanation": "形容人钱财很多，与“又大方”并列，符合句意。"}, {"text": "冷酷", "is_correct": false, "explanation": "语义：“冷酷”与“大方”的性格相反，不能并列。"}], "explanations": {"小气": "语义：“小气”与后半句“大方”的性格相反，不能并列。", "富庶": "搭配：“富庶”多形容地区、土地，不用来形容公司老板。", "多金": "形容人钱财很多，与“又大方”并列，符合句意。", "冷酷": "语义：“冷酷”与“大方”的性格相反，不能并列。"}, "sentence_index": 6, "correct_answer": "多金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的经济很多金。", "explanation": "这里应该用〈宽裕〉。“多金”只形容人的钱财多，公司的经济状况要说“宽裕”。"}, {"text": "我家的狗很多金。", "explanation": "这里应该用〈名贵〉。“多金”只形容人的钱财多，狗这类动物的贵重要说“名贵”。"}, {"text": "这台电脑很多金，运行速度很快。", "explanation": "这里应该用〈性能好〉。“多金”只形容人的钱财多，电脑的性能要说“性能好”，不能说多金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位多金地阿姨捐了很多钱给医院。", "corrected_sentence": "这位多金的阿姨捐了很多钱给医院。", "error_description": "错误形式：“多金地阿姨”；正确形式：“多金的阿姨”。“多金”修饰名词“阿姨”时要用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的邻居很多金地，每天开着新车上班。", "corrected_sentence": "我的邻居很多金，每天开着新车上班。", "error_description": "错误形式：“很多金地”。“地”只用于修饰后面的动词，“多金”作谓语时后面不能加“地”；正确形式是去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”指钱财少，与“多金”（钱财很多）意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌，与“多金”的钱财含义没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑，与“多金”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“多金”没有反义关系。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”指钱财少，与“多金”（钱财很多）意思相反。", "漂亮": "“漂亮”形容外貌，与“多金”的钱财含义没有反义关系。", "聪明": "“聪明”形容头脑，与“多金”没有反义关系。", "安静": "“安静”形容声音或环境，与“多金”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穷", "is_correct": true, "explanation": "“穷”指钱财少，与“多金”（钱财很多）意思相反。"}, {"text": "勤奋", "is_correct": false, "explanation": "“勤奋”形容努力，与“多金”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“多金”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度或气氛，与“多金”没有反义关系。"}], "correct_answer": "穷", "explanations": {"穷": "“穷”指钱财少，与“多金”（钱财很多）意思相反。", "勤奋": "“勤奋”形容努力，与“多金”没有反义关系。", "高兴": "“高兴”形容心情，与“多金”没有反义关系。", "严肃": "“严肃”形容态度或气氛，与“多金”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "钱财很多。", "primary_collocate": null, "pronunciation": "duō jīn", "ipa": "tuɔ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "他又帅又多金，很多女孩都喜欢他。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友开公司，年轻又多金。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找一个温柔又多金的男朋友。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位多金的老板买了三辆新车。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出身好，是个多金的富二代。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但多金，而且对人很好。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多金的人不一定快乐。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个多金的年轻人住在大房子里。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了一个多金的医生。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着好车，住大房子，真是多金。", "target_word": "多金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容人钱财很多，常与又帅又多金连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丑", "is_correct": false, "explanation": "语义：“丑”与前面的“帅”意思相反，“又帅又丑”前后矛盾。"}, {"text": "多金", "is_correct": true, "explanation": "形容人钱财很多，与“又帅”并列使用，是口语中的常见说法。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气、环境，不能用来形容人，“又帅又潮湿”不通。"}, {"text": "富饶", "is_correct": false, "explanation": "搭配：“富饶”多用来形容土地、地区的物产丰富，不用来形容人。"}], "explanations": {"丑": "语义：“丑”与前面的“帅”意思相反，“又帅又丑”前后矛盾。", "多金": "形容人钱财很多，与“又帅”并列使用，是口语中的常见说法。", "潮湿": "搭配：“潮湿”形容天气、环境，不能用来形容人，“又帅又潮湿”不通。", "富饶": "搭配：“富饶”多用来形容土地、地区的物产丰富，不用来形容人。"}, "sentence_index": 0, "correct_answer": "多金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市很多金。", "explanation": "这里应该用〈富裕〉。多金只形容人的钱财多，不说城市；〈富裕〉可以用于城市、地区的经济状况。"}, {"text": "这间房子很多金。", "explanation": "这里应该用〈豪华〉或〈昂贵〉。“多金”只形容人的钱财多，房屋这类物品要说价值高，不能用“多金”。"}, {"text": "他的内心很多金，从不在乎钱。", "explanation": "这里应该用〈富有〉。“多金”指钱财多，不能用来形容内心；〈富有〉可指精神上的丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多形容空气、土地，不用来形容人。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐的人不一定快乐”前后矛盾，不合句意。"}, {"text": "多金", "is_correct": true, "explanation": "形容人钱财很多，与“不一定快乐”组成一般性的判断，符合句意。"}, {"text": "贫瘠", "is_correct": false, "explanation": "搭配：“贫瘠”多形容土地，不能用来形容人。"}], "explanations": {"干燥": "搭配：“干燥”多形容空气、土地，不用来形容人。", "快乐": "语义：“快乐的人不一定快乐”前后矛盾，不合句意。", "多金": "形容人钱财很多，与“不一定快乐”组成一般性的判断，符合句意。", "贫瘠": "搭配：“贫瘠”多形容土地，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "多金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些年农民的生活越来越多金。", "explanation": "这里应该用〈富足〉。“多金”只形容人的钱财多，生活的充裕程度要说“富足”。"}, {"text": "我家的狗很多金。", "explanation": "这里应该用〈名贵〉。“多金”只形容人的钱财多，狗这类动物的贵重要说“名贵”。"}, {"text": "这辆汽车很多金，开起来很快。", "explanation": "这里应该用〈性能好〉。“多金”只形容人的钱财多，汽车的性能要说“性能好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位多金地叔叔常常请大家吃饭。", "corrected_sentence": "那位多金的叔叔常常请大家吃饭。", "error_description": "错误形式：“多金地叔叔”；正确形式：“多金的叔叔”。“多金”修饰名词“叔叔”时要用“的”，“地”用于修饰动词，不能用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位邻居很多金地，每年都去国外旅游。", "corrected_sentence": "那位邻居很多金，每年都去国外旅游。", "error_description": "错误形式：“很多金地”。“地”只用于修饰后面的动词，“多金”作谓语时后面不能加“地”；正确形式是去掉“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
