INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专家系统是一种电脑程序，像一位很会解决问题的专家一样回答问题。", "primary_collocate": null, "pronunciation": "zhuān jiā xì tǒng", "ipa": "ʈʂwan˥ tɕja˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "我在电脑上问专家系统一个问题。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专家系统像医生一样回答问题。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校买了一套专家系统，帮学生选课。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家系统很快就告诉我答案。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电脑里有一个专家系统。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专家系统会告诉你怎么做菜。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以问专家系统，它像老师一样耐心。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用专家系统查资料。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专家系统很聪明，什么问题都能回答。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家系统是电脑程序，不是真的人。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "專家系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像专家一样回答问题的电脑程序，普通人可以向它提问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空调", "is_correct": false, "explanation": "搭配：“在电脑上”后面应接能被提问的程序或网站，“空调”不搭配。"}, {"text": "专家系统", "is_correct": true, "explanation": "正确：专家系统是能像专家一样回答问题的电脑程序，正好可以在电脑上提问。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能回答问题，不是“问”的对象。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“问”需要能作答的对象，石头不能作答。"}], "explanations": {"空调": "搭配：“在电脑上”后面应接能被提问的程序或网站，“空调”不搭配。", "专家系统": "正确：专家系统是能像专家一样回答问题的电脑程序，正好可以在电脑上提问。", "冰箱": "语义：冰箱不能回答问题，不是“问”的对象。", "石头": "配价：“问”需要能作答的对象，石头不能作答。"}, "sentence_index": 0, "correct_answer": "专家系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专家系统给我打了一针。", "explanation": "这里应该用〈护士〉。专家系统只是软件，不能给人打针，打针要由护士来做。"}, {"text": "专家系统给我端来了一杯茶。", "explanation": "这里应该用〈机器人〉。专家系统只是软件，不能端茶，端东西要用机器人。"}, {"text": "这个专家系统很快就来我家修好了空调。", "explanation": "这里应该用〈维修人员〉。专家系统是软件，不能上门修理空调，上门修东西要找真正的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不能回答问题，不是“问”的对象。"}, {"text": "专家系统", "is_correct": true, "explanation": "正确：专家系统能回答问题，“它像老师一样耐心”指它的回答方式。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会回答问题，“它像老师一样耐心”也不成立。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“问”需要能作答的对象，书包不具备。"}], "explanations": {"空气": "语义：空气不能回答问题，不是“问”的对象。", "专家系统": "正确：专家系统能回答问题，“它像老师一样耐心”指它的回答方式。", "小猫": "语义：小猫不会回答问题，“它像老师一样耐心”也不成立。", "书包": "配价：“问”需要能作答的对象，书包不具备。"}, "sentence_index": 6, "correct_answer": "专家系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家系统昨天发烧，去医院看病了。", "explanation": "这里应该用〈病人〉。专家系统是电脑程序，不会生病，也不能去医院。"}, {"text": "专家系统在花园里跑来跑去。", "explanation": "这里应该用〈小狗〉。专家系统是软件，不能在花园里跑。"}, {"text": "我把专家系统放进冰箱里冻起来了。", "explanation": "这里应该用〈水果〉。专家系统是电脑程序，不是能放进冰箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在电脑里装了一只专家系统，可以随时提问。", "corrected_sentence": "我在电脑里装了一套专家系统，可以随时提问。", "error_description": "量词错误：“一只”应改为“一套”。“只”多用于动物，专家系统是成套的软件，应用量词“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个专家系统们很有用，什么问题都能帮我解答。", "corrected_sentence": "这个专家系统很有用，什么问题都能帮我解答。", "error_description": "词缀错误：“专家系统”是软件，不能加复数词尾“们”，应说“这个专家系统”，不说“这个专家系统们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
