INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "模拟专家知识和经验，用于解决特定领域问题的计算机程序。", "primary_collocate": null, "pronunciation": "zhuān jiā xì tǒng", "ipa": "ʈʂwan˥ tɕja˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "医院用专家系统帮医生判断病情。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专家系统储存了很多医学知识。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家系统能模仿专家，回答特定领域的问题。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一个专家系统，帮客人选择保险。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家系统里有很多规则，可以一步一步推理。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的专家系统能找出机器的问题。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专家系统的知识来自很多有经验的医生。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在研究法律方面的专家系统。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用专家系统，知道什么时候给田浇水。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家系统不会自己学习，只会用已有的知识。", "target_word": "专家系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "專家系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "保存专家知识和规则、能在特定领域推理解决问题的计算机程序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来储存食物，不能判断病情。"}, {"text": "专家系统", "is_correct": true, "explanation": "正确：专家系统是模拟专家知识、帮助判断问题的程序，符合“帮医生判断病情”。"}, {"text": "红茶", "is_correct": false, "explanation": "语义：红茶是饮料，无法帮医生判断病情。"}, {"text": "病人", "is_correct": false, "explanation": "配价：“病人”是被判断的对象，不能充当“用”的工具。"}], "explanations": {"冰箱": "语义：冰箱用来储存食物，不能判断病情。", "专家系统": "正确：专家系统是模拟专家知识、帮助判断问题的程序，符合“帮医生判断病情”。", "红茶": "语义：红茶是饮料，无法帮医生判断病情。", "病人": "配价：“病人”是被判断的对象，不能充当“用”的工具。"}, "sentence_index": 0, "correct_answer": "专家系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个专家系统是我的小狗，放学后总陪我去公园散步。", "explanation": "这里应该用〈宠物〉的意思（会陪人散步的动物）。专家系统是软件，不是动物，不能当宠物陪我散步。"}, {"text": "我想买一个专家系统陪孩子玩。", "explanation": "这里应该用〈机器人〉。专家系统只是软件，没有实体，不能陪孩子玩；陪玩要用机器人。"}, {"text": "专家系统给我做了手术。", "explanation": "这里应该用〈医生〉。专家系统不能动手做手术，“做手术”的主体应是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具没有知识，不能说知识来自医生。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会有来自医生的专业知识。"}, {"text": "专家系统", "is_correct": true, "explanation": "正确：专家系统的知识来自专家和医生的经验，符合句意。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯只是照明用具，不可能有来自医生的知识。"}], "explanations": {"玩具": "语义：玩具没有知识，不能说知识来自医生。", "小狗": "语义：小狗是动物，不会有来自医生的专业知识。", "专家系统": "正确：专家系统的知识来自专家和医生的经验，符合句意。", "台灯": "语义：台灯只是照明用具，不可能有来自医生的知识。"}, "sentence_index": 6, "correct_answer": "专家系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家系统在厨房里给我们做了晚饭。", "explanation": "这里应该用〈厨师〉。专家系统是计算机程序，不能动手做饭。"}, {"text": "我坐专家系统去上班。", "explanation": "这里应该用〈公共汽车〉。专家系统是软件，不是交通工具，不能坐。"}, {"text": "下雨了，我打开专家系统挡雨。", "explanation": "这里应该用〈雨伞〉。专家系统是计算机程序，不能用来挡雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们医院买了一只专家系统，帮医生判断病情。", "corrected_sentence": "我们医院买了一套专家系统，帮医生判断病情。", "error_description": "量词错误：“一只”应改为“一套”。“只”多用于动物，专家系统是成套的软件，量词应用“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个专家系统们能帮医生判断病情，很有用。", "corrected_sentence": "这个专家系统能帮医生判断病情，很有用。", "error_description": "词缀错误：“专家系统”是软件，不能加复数词尾“们”，应说“这个专家系统”，不说“这个专家系统们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吻合", "is_correct": true, "explanation": "与“对不上”构成反义：指两个物件合得上、相合。"}, {"text": "咬", "is_correct": false, "explanation": "与“对不上”无反义关系：咬指用牙齿夹住，与物件是否合得上无关。"}, {"text": "跳", "is_correct": false, "explanation": "与“对不上”无反义关系：跳指向上移动，与是否合得上无关。"}, {"text": "写", "is_correct": false, "explanation": "与“对不上”无反义关系：写指写字，与此句意无关。"}], "correct_answer": "吻合", "explanations": {"吻合": "与“对不上”构成反义：指两个物件合得上、相合。", "咬": "与“对不上”无反义关系：咬指用牙齿夹住，与物件是否合得上无关。", "跳": "与“对不上”无反义关系：跳指向上移动，与是否合得上无关。", "写": "与“对不上”无反义关系：写指写字，与此句意无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吻合", "is_correct": true, "explanation": "与“对不上”构成反义：指两个物件合得上、相合。"}, {"text": "撕", "is_correct": false, "explanation": "与“对不上”无反义关系：撕指用力分开，与物件是否合得上无关。"}, {"text": "扔", "is_correct": false, "explanation": "与“对不上”无反义关系：扔指抛出，与此义无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“对不上”无反义关系：睡觉指休息，与物件是否合得上无关。"}], "correct_answer": "吻合", "explanations": {"吻合": "与“对不上”构成反义：指两个物件合得上、相合。", "撕": "与“对不上”无反义关系：撕指用力分开，与物件是否合得上无关。", "扔": "与“对不上”无反义关系：扔指抛出，与此义无关。", "睡觉": "与“对不上”无反义关系：睡觉指休息，与物件是否合得上无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对不上是两样东西放在一起，不一样，合不到一起。", "primary_collocate": null, "pronunciation": "duì bu shàng", "ipa": "tweɪ̯˥˩ pu ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个螺丝和孔对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两块拼图的边怎么也对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙和锁对不上，门打不开。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机壳和手机的孔对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两节水管的接口对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新盖子和旧瓶子对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个插头和插座对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门框和门板对不上，关不紧。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个齿轮的齿对不上，机器不转。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的板和钉子的位置对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对得上", "label": "可能补语肯定式"}], "register": "口语", "sense_fingerprint": "两个具体物件的形状、位置合不到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，螺丝和孔不会哭。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求可食用的宾语，螺丝不能被吃。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说”要求能说话的人作主语，螺丝和孔不能说话。"}, {"text": "对不上", "is_correct": true, "explanation": "正确：“对不上”指两个物件合不到一起，与句意相符。"}], "explanations": {"哭": "语义：“哭”指流泪，螺丝和孔不会哭。", "吃": "配价：“吃”要求可食用的宾语，螺丝不能被吃。", "说": "搭配：“说”要求能说话的人作主语，螺丝和孔不能说话。", "对不上": "正确：“对不上”指两个物件合不到一起，与句意相符。"}, "sentence_index": 0, "correct_answer": "对不上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一大堆作业，我一晚上实在对不上。", "explanation": "这里应该用〈应付〉。对不上表示两者合不到一起，不能表示能否完成事情，这里要用应付。"}, {"text": "我起得太晚，实在对不上早上的火车。", "explanation": "这里应该用〈赶不上〉。对不上表示两者合不到一起，不能表示来不及搭乘车次，这里要用赶不上。"}, {"text": "我不小心碰坏了你的手机，真对不上。", "explanation": "这里应该用〈对不起〉。对不上指两者合不到一起，向别人道歉要用对不起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑", "is_correct": false, "explanation": "语义：“笑”的主体须是人，插头和插座不会笑。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指闭眼休息，与插头和插座无关。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”要求有施事和受事，如喂人、喂动物，不能只说插头和插座喂。"}, {"text": "对不上", "is_correct": true, "explanation": "正确：“对不上”指插头与插座合不到一起，符合句意。"}], "explanations": {"笑": "语义：“笑”的主体须是人，插头和插座不会笑。", "睡": "语义：“睡”指闭眼休息，与插头和插座无关。", "喂": "配价：“喂”要求有施事和受事，如喂人、喂动物，不能只说插头和插座喂。", "对不上": "正确：“对不上”指插头与插座合不到一起，符合句意。"}, "sentence_index": 6, "correct_answer": "对不上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这么优秀，我实在对不上他。", "explanation": "这里应该用〈配不上〉。对不上表示两者合不到一起，不能表示与人的条件不相称，这里要用配不上。"}, {"text": "他跑得太快，我怎么也对不上他。", "explanation": "这里应该用〈跟不上〉。对不上表示两者合不到一起，不能表示速度赶不上别人，这里要用跟不上。"}, {"text": "这么大的洪水，这道堤坝实在对不上。", "explanation": "这里应该用〈抵挡〉。对不上表示两者合不到一起，不能表示抵御、经受住冲击，这里要用抵挡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把这个螺母和螺丝对不上。", "corrected_sentence": "这个螺母和螺丝对不上。", "error_description": "错误：「对不上」是不及物动词，不能用于「把」字句。应去掉「把」，说「这个螺母和螺丝对不上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "插头和插座对不上很，灯不亮。", "corrected_sentence": "插头和插座对不上，灯不亮。", "error_description": "错误：「很」是程度副词，不能放在动词「对不上」后面。应去掉「很」，说「对不上，灯不亮」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吻合", "is_correct": true, "explanation": "与“对不上”构成反义：指两者一致、相合。"}, {"text": "送", "is_correct": false, "explanation": "与“对不上”无反义关系：送指传递，与两者是否一致无关。"}, {"text": "唱", "is_correct": false, "explanation": "与“对不上”无反义关系：唱指发出歌声，与此句意无关。"}, {"text": "修理", "is_correct": false, "explanation": "与“对不上”无反义关系：修理指修复，不是一致与否的对立面。"}], "correct_answer": "吻合", "explanations": {"吻合": "与“对不上”构成反义：指两者一致、相合。", "送": "与“对不上”无反义关系：送指传递，与两者是否一致无关。", "唱": "与“对不上”无反义关系：唱指发出歌声，与此句意无关。", "修理": "与“对不上”无反义关系：修理指修复，不是一致与否的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吻合", "is_correct": true, "explanation": "与“对不上”构成反义：指两者一致、相合。"}, {"text": "进入", "is_correct": false, "explanation": "与“对不上”无反义关系：进入指从外到内，与是否一致无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与“对不上”无反义关系：游泳指在水中活动，与此义无关。"}, {"text": "种", "is_correct": false, "explanation": "与“对不上”无反义关系：种指栽种，与两者是否一致无关。"}], "correct_answer": "吻合", "explanations": {"吻合": "与“对不上”构成反义：指两者一致、相合。", "进入": "与“对不上”无反义关系：进入指从外到内，与是否一致无关。", "游泳": "与“对不上”无反义关系：游泳指在水中活动，与此义无关。", "种": "与“对不上”无反义关系：种指栽种，与两者是否一致无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两者不吻合，不一致。", "primary_collocate": null, "pronunciation": "duì bu shàng", "ipa": "tweɪ̯˥˩ pu ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他说的时间和我记的对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两份账目的数字对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他的话前后对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的口供和监控录像对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的名字和身份证上的对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的路线和实际的路对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的收入和支出怎么也对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讲的故事前后对不上，大家都不信。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的说法完全对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里的数据和表格里的对不上。", "target_word": "对不上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对得上", "label": "可能补语肯定式"}], "register": "口语", "sense_fingerprint": "说法、数字、信息等两者不一致，对不起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "配价：“喝”要求可饮用的宾语，“我记的”不能被喝。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与记录的时间不相容。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”指争吵或发出噪声，不能接在“我记的”之后。"}, {"text": "对不上", "is_correct": true, "explanation": "正确：“对不上”表示两者不一致，与句意相符。"}], "explanations": {"喝": "配价：“喝”要求可饮用的宾语，“我记的”不能被喝。", "跑": "语义：“跑”指快速移动，与记录的时间不相容。", "吵": "搭配：“吵”指争吵或发出噪声，不能接在“我记的”之后。", "对不上": "正确：“对不上”表示两者不一致，与句意相符。"}, "sentence_index": 0, "correct_answer": "对不上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我来晚了，真对不上，请大家原谅。", "explanation": "这里应该用〈对不起〉。对不上表示两者不一致，向别人道歉要用对不起。"}, {"text": "比赛一开始，我就对不上前面的选手，只能落在最后。", "explanation": "这里应该用〈跟不上〉。对不上表示两者不一致，不能表示赶不上别人的速度，这里要用跟不上。"}, {"text": "这么多工作，我一个人实在对不上。", "explanation": "这里应该用〈应付〉。对不上表示两者不一致，不能表示能否处理、应付事情，这里要用应付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，收入和支出不能唱。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”指事情终止，不能说收支之间的不一致。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”指没有按时到达，不用于收入和支出。"}, {"text": "对不上", "is_correct": true, "explanation": "正确：“对不上”表示收支两者不一致，符合句意。"}], "explanations": {"唱": "语义：“唱”指发出歌声，收入和支出不能唱。", "结束": "语义：“结束”指事情终止，不能说收支之间的不一致。", "迟到": "搭配：“迟到”指没有按时到达，不用于收入和支出。", "对不上": "正确：“对不上”表示收支两者不一致，符合句意。"}, "sentence_index": 6, "correct_answer": "对不上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的球技很高，我怎么练也对不上他。", "explanation": "这里应该用〈比不上〉。对不上表示两者不一致，不能表示与别人相比差距很大，这里要用比不上。"}, {"text": "我们的兵力实在对不上敌人，只能撤退。", "explanation": "这里应该用〈对抗〉。对不上表示两者不一致，不能表示与敌人较量、抵抗，这里要用对抗。"}, {"text": "他这么努力，一定对不上父母的养育之恩。", "explanation": "这里应该用〈对得起〉（不辜负）。对不上表示两者不一致，不能表示有没有辜负别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把两份账单的金额对不上。", "corrected_sentence": "两份账单的金额对不上。", "error_description": "错误：「对不上」是不及物动词，不能用于「把」字句。应去掉「把」，说「两份账单的金额对不上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "账单上的金额和发票对不上很。", "corrected_sentence": "账单上的金额和发票对不上。", "error_description": "错误：「很」是程度副词，不能放在动词「对不上」后面。应去掉「很」，说「对不上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
