INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对谈是两个人面对面地说话，谈一件事。", "primary_collocate": null, "pronunciation": "duì tán", "ipa": "twei˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "两位作家在电视里对谈，聊了一个小时。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚八点，校长和学生代表要对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐在桌子两边对谈了很久。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者请两位老师就教育问题对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手想和老板对谈一次。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社安排两位画家对谈，读者很喜欢。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我和老师对谈到很晚。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对谈过一次，但是没有结果。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下周，两位教授将在图书馆对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人让两个人坐近一点，开始对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对谈了", "label": "完成体（了）"}, {"form": "对谈过", "label": "经历体（过）"}, {"form": "对谈着", "label": "持续体（着）"}], "register": "书面", "sense_fingerprint": "两人面对面谈论某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对谈", "is_correct": true, "explanation": "对谈：双方面对面交谈，与“聊了一个小时”的句意相符。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架带有争执意味，与后半句“聊了一个小时”的平和氛围相矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是独自表演，不是两人交谈，与“聊”不合。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“在电视里写”搭配不通，“写”也不是两位作家共同进行的交谈动作。"}], "explanations": {"对谈": "对谈：双方面对面交谈，与“聊了一个小时”的句意相符。", "吵架": "语义：吵架带有争执意味，与后半句“聊了一个小时”的平和氛围相矛盾。", "唱": "语义：唱是独自表演，不是两人交谈，与“聊”不合。", "写": "搭配：“在电视里写”搭配不通，“写”也不是两位作家共同进行的交谈动作。"}, "sentence_index": 0, "correct_answer": "对谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者对谈了两位老师，问了他们很多问题。", "explanation": "这里应该用〈采访〉。采访是记者提问、对方回答；对谈指双方平等地交谈，不能用于记者提问。"}, {"text": "我周末去医院对谈生病的朋友。", "explanation": "这里应该用〈看望〉。看望是去探望对方；对谈指双方面对面交谈，不能用于探望生病的人。"}, {"text": "他一个人对谈，讲了很久。", "explanation": "这里应该用〈独白〉。对谈需要两人面对面交谈，一个人讲话应说独白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对谈", "is_correct": true, "explanation": "对谈：双方面对面交谈，与“昨天我和老师……到很晚”的句意相符。"}, {"text": "独白", "is_correct": false, "explanation": "语义：独白只有一人说话，与“我和老师”双方共同交谈的句意不合。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”要带宾语（如活动），“昨天我和老师举办到很晚”意思不完整。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆是独自出神，与“我和老师”互动的语境相矛盾。"}], "explanations": {"对谈": "对谈：双方面对面交谈，与“昨天我和老师……到很晚”的句意相符。", "独白": "语义：独白只有一人说话，与“我和老师”双方共同交谈的句意不合。", "举办": "配价：“举办”要带宾语（如活动），“昨天我和老师举办到很晚”意思不完整。", "发呆": "语义：发呆是独自出神，与“我和老师”互动的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "对谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在北京，她在上海，两个人每天晚上用手机对谈。", "explanation": "这里应该用〈通话〉。对谈指双方面对面交谈，两地用手机说话应说“通话”。"}, {"text": "两国军队在边境对谈了一个月，互相开了炮。", "explanation": "这里应该用〈交火〉。对谈是双方平和地交谈，不表示军队互相开炮。"}, {"text": "他在台上对谈了一首新歌，大家都很喜欢。", "explanation": "这里应该用〈唱〉。对谈是双方面对面交谈，不能用于唱歌；唱歌应说“唱了一首新歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位老师教育问题对谈了很久。", "corrected_sentence": "两位老师就教育问题对谈了很久。", "error_description": "错误：缺少介词“就”。“对谈”的话题要用“就……”引出，放在“对谈”前面，应说“两位老师就教育问题对谈了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们对谈的很愉快。", "corrected_sentence": "他们对谈得很愉快。", "error_description": "补语标记错误：动词后带程度补语须用“得”，应说“对谈得很愉快”，不能用“的”说“对谈的很愉快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
