INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方面对面交谈。", "primary_collocate": null, "pronunciation": "duì tán", "ipa": "twei˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "两家公司的老板今天上午对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老作家和年轻作家对谈，谈的是写作。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台请医生和听众对谈，讲怎么睡好觉。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约好周末在茶馆对谈。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位音乐家对谈着，旁边的人都安静地听。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长和市民对谈，认真听大家的意见。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想和那位导演对谈一下。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位球星对谈了半个小时，笑声不断。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在咖啡馆对谈，大家聊得很开心。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长坐下来对谈，一起想办法。", "target_word": "对谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对谈了", "label": "完成体（了）"}, {"form": "对谈过", "label": "经历体（过）"}, {"form": "对谈着", "label": "持续体（着）"}], "register": "书面", "sense_fingerprint": "双方当面交谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对谈", "is_correct": true, "explanation": "对谈：双方当面交谈，与“两家公司的老板今天上午”开会的语境相符。"}, {"text": "独唱", "is_correct": false, "explanation": "语义：独唱是一个人演唱，与“两家公司的老板”这种多方的情境不合。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”要带宾语（如活动），“两家公司的老板今天上午举办”意思不完整。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，不能作谓语，“老板今天上午桌子”不成句。"}], "explanations": {"对谈": "对谈：双方当面交谈，与“两家公司的老板今天上午”开会的语境相符。", "独唱": "语义：独唱是一个人演唱，与“两家公司的老板”这种多方的情境不合。", "举办": "配价：“举办”要带宾语（如活动），“两家公司的老板今天上午举办”意思不完整。", "桌子": "词性：“桌子”是名词，不能作谓语，“老板今天上午桌子”不成句。"}, "sentence_index": 0, "correct_answer": "对谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们昨天在茶馆对谈，输了很多钱。", "explanation": "这里应该用〈打牌〉。对谈指双方面对面交谈，不是娱乐活动；“输了很多钱”说的是打牌。"}, {"text": "他一个人在茶馆对谈，等了很久。", "explanation": "这里误用了〈对谈〉。对谈只能指双方面对面交谈，句中只有一个人，应删去“对谈”，只说“一个人在茶馆等了很久”。"}, {"text": "记者在茶馆对谈了老板，问了很多问题。", "explanation": "这里应该用〈采访〉。记者提问、对方回答是采访；对谈指双方平等交谈，不用于记者提问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对谈", "is_correct": true, "explanation": "对谈：双方当面交谈，与“她很想和那位导演……一下”的句意相符。"}, {"text": "独白", "is_correct": false, "explanation": "语义：独白是一人自说，与“和那位导演”的双方关系不合。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆是独自出神，与“和那位导演”的交往语境矛盾。"}, {"text": "名字", "is_correct": false, "explanation": "词性：“名字”是名词，不能带“一下”作动词用。"}], "explanations": {"对谈": "对谈：双方当面交谈，与“她很想和那位导演……一下”的句意相符。", "独白": "语义：独白是一人自说，与“和那位导演”的双方关系不合。", "发呆": "语义：发呆是独自出神，与“和那位导演”的交往语境矛盾。", "名字": "词性：“名字”是名词，不能带“一下”作动词用。"}, "sentence_index": 6, "correct_answer": "对谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师和家长坐下来对谈，互相骂了起来。", "explanation": "这里应该用〈争吵〉。对谈是平和地交谈，不表示互相谩骂。"}, {"text": "老师在台上对谈了一首歌，孩子们都很喜欢。", "explanation": "这里应该用〈唱〉。对谈是双方面对面交谈，不能用于唱歌；唱歌应说“唱了一首歌”。"}, {"text": "他一个人对谈了三年，终于出版了一本小说。", "explanation": "这里应该用〈写作〉。对谈指双方面对面交谈，一个人不能对谈，应说“写作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和他对谈的很开心。", "corrected_sentence": "我和他对谈得很开心。", "error_description": "补语标记错误：动词后带程度补语须用“得”，应说“对谈得很开心”，不能用“的”说“对谈的很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们举行了一只对谈。", "corrected_sentence": "他们举行了一场对谈。", "error_description": "量词错误：“对谈”指一次交谈活动，量词应用“场”，不用“只”。正确说法是“他们举行了一场对谈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
