INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小学生是在小学里读书的孩子。", "primary_collocate": null, "pronunciation": "xiǎo xué shēng", "ipa": "ɕiɑʊ̯˨˩˦ ɕɥɛ˧˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "这个小学生每天走路上学。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小学生要早点睡觉。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟是一个小学生。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些小学生在操场上玩儿。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小学生的书包看起来很重。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位小学生帮老人拿了东西。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这名小学生画了一张画。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我女儿以前是小学生，现在上中学了。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生坐在教室里听故事。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校门口有很多小学生。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "小学生们", "label": "复数"}, {"form": "小學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在小学里读书的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小学生", "is_correct": true, "explanation": "正确：小学生是在小学读书的孩子，会每天上学。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会走路上学，句子说不通。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会上学，句子说不通。"}, {"text": "小学", "is_correct": false, "explanation": "搭配：“上学”的主语应是学生，学校不能走路上学。"}], "explanations": {"小学生": "正确：小学生是在小学读书的孩子，会每天上学。", "石头": "语义：石头不会走路上学，句子说不通。", "小狗": "语义：小狗不会上学，句子说不通。", "小学": "搭配：“上学”的主语应是学生，学校不能走路上学。"}, "sentence_index": 0, "correct_answer": "小学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们大学有很多小学生。", "explanation": "这里应该用〈大学生〉。小学生指小学里读书的孩子，大学里的学生应说“大学生”。"}, {"text": "幼儿园里有很多小学生在玩。", "explanation": "这里应该用〈儿童〉。幼儿园的孩子不是小学生，小学生指在小学读书的学生。"}, {"text": "她每天准时上班，是公司的一名小学生。", "explanation": "这里应该用〈职员〉。小学生是在小学读书的孩子，每天上班的人应说“职员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小学生", "is_correct": true, "explanation": "正确：小学生是小学里的孩子，可以画画。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会画画，句子说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能拿笔画画，句子说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能画画，句子说不通。"}], "explanations": {"小学生": "正确：小学生是小学里的孩子，可以画画。", "小猫": "语义：小猫不会画画，句子说不通。", "汽车": "语义：汽车不能拿笔画画，句子说不通。", "椅子": "语义：椅子不能画画，句子说不通。"}, "sentence_index": 6, "correct_answer": "小学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所中学里有很多小学生，每天都很忙。", "explanation": "这里应该用〈中学生〉。小学生只指小学里的学生，中学里要说“中学生”。"}, {"text": "她在学校里教数学，是一位小学生。", "explanation": "这里应该用〈老师〉。在学校教书的是老师，小学生是在小学读书的孩子。"}, {"text": "这所小学生很大，有很多教室。", "explanation": "这里应该用〈小学〉。“小学”是学校，“小学生”是学生，学校不能说“小学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小学生每天写作业。", "corrected_sentence": "这个小学生每天写作业。", "error_description": "量词错误：“小学生”指人，应用“个”或“名”，不能用“只”（只用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口站着几个小学生们。", "corrected_sentence": "门口站着几个小学生。", "error_description": "复数标记错误：“几个”已表示数量，“小学生”后不能再加“们”，应说“几个小学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
