INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在小学读书的学生。", "primary_collocate": null, "pronunciation": "xiǎo xué shēng", "ipa": "ɕiɑʊ̯˨˩˦ ɕɥɛ˧˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "小学生放学后先做作业。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她教过很多小学生。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是写给小学生看的。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥是小学生的时候很喜欢踢球。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生不应该玩太长时间手机。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群小学生排着队走进了学校。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车上有几个小学生。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家书店有很多适合小学生的书。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都是六年级的小学生。", "target_word": "小学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着小学生去公园玩。", "target_word": "小学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "小学生们", "label": "复数"}, {"form": "小學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在小学读书的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小学生", "is_correct": true, "explanation": "正确：小学生是在小学读书的学生，会放学。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会放学做作业，句子说不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司不会放学，句子说不通。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“放学”只用于学生，不说“病人放学”。"}], "explanations": {"小学生": "正确：小学生是在小学读书的学生，会放学。", "小狗": "语义：小狗不会放学做作业，句子说不通。", "公司": "语义：公司不会放学，句子说不通。", "病人": "搭配：“放学”只用于学生，不说“病人放学”。"}, "sentence_index": 0, "correct_answer": "小学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在大学里读书，是一名小学生。", "explanation": "这里应该用〈大学生〉。正在大学读书的是大学生，小学生只指在小学读书的学生。"}, {"text": "这个幼儿园有三十个小学生。", "explanation": "这里应该用〈幼儿〉。小学生指小学里读书的学生，幼儿园的孩子要说“幼儿”。"}, {"text": "他是一名小学生，每天在工厂里干活。", "explanation": "这里应该用〈工人〉。小学生是在小学读书的学生，在工厂干活的是工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小学生", "is_correct": true, "explanation": "正确：小学生是在小学读书的学生，可以坐公共汽车。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不可能在公共汽车上，句子说不通。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“公共汽车上”与“宿舍”不搭，宿舍是住所。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是建筑，不可能在公共汽车上。"}], "explanations": {"小学生": "正确：小学生是在小学读书的学生，可以坐公共汽车。", "城市": "语义：城市不可能在公共汽车上，句子说不通。", "宿舍": "搭配：“公共汽车上”与“宿舍”不搭，宿舍是住所。", "医院": "语义：医院是建筑，不可能在公共汽车上。"}, "sentence_index": 6, "correct_answer": "小学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所中学有三千个小学生。", "explanation": "这里应该用〈中学生〉。小学生只指小学里读书的学生，中学里要说“中学生”。"}, {"text": "他刚上完小学，现在是一名小学生。", "explanation": "这里应该用〈中学生〉。他已上完小学，现在读中学，应说“中学生”；小学生只指在小学读书的学生。"}, {"text": "这所小学生有很大的操场。", "explanation": "这里应该用〈小学〉。“小学”是学校，学校不能说“小学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班来了一只小学生，他很活泼。", "corrected_sentence": "我们班来了一名小学生，他很活泼。", "error_description": "量词错误：“小学生”指人，应用“名”，不能用“只”（只用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学以后，几个小学生们在街上玩。", "corrected_sentence": "放学以后，几个小学生在街上玩。", "error_description": "复数标记错误：“几个”已表示数量，“小学生”后不能再加“们”，应说“几个小学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
