INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98344, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问时间的说法，问几时。", "primary_collocate": null, "pronunciation": "jǐ diǎn", "ipa": "tɕi˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "你明天早上几点起床？", "target_word": "几点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们学校几点上课？", "target_word": "几点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电影几点开始，你知道吗？", "target_word": "几点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天晚上你几点睡觉的？", "target_word": "几点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们几点在门口见面？", "target_word": "几点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机几点到北京，你知道吗？", "target_word": "几点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你平时几点吃晚饭？", "target_word": "几点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店几点关门？", "target_word": "几点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天的会议几点开始？", "target_word": "几点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你昨天几点到家的？", "target_word": "几点", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "几点钟", "label": "复合"}, {"form": "幾點", "label": "繁体"}], "register": "口语", "sense_fingerprint": "询问某件事发生在几时，问事情的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几点", "is_correct": true, "explanation": "几点 jǐ diǎn：询问某件事发生在几时。"}, {"text": "九点", "is_correct": false, "explanation": "jiǔ 与 jǐ 韵母不同（jiǔ 为 iou），意思是九点钟。"}, {"text": "起点", "is_correct": false, "explanation": "qǐ 与 jǐ 声母不同（q 对 j），声调相同，意思是出发的地方。"}, {"text": "几天", "is_correct": false, "explanation": "第二音节 tiān 与 diǎn 声母不同（t 对 d），声调也不同，意思是若干天。"}, {"text": "基点", "is_correct": false, "explanation": "第一音节 jī 为第一声，与 jǐ 的声调不同，意思是基础的要点。"}], "explanations": {"几点": "几点 jǐ diǎn：询问某件事发生在几时。", "九点": "jiǔ 与 jǐ 韵母不同（jiǔ 为 iou），意思是九点钟。", "起点": "qǐ 与 jǐ 声母不同（q 对 j），声调相同，意思是出发的地方。", "几天": "第二音节 tiān 与 diǎn 声母不同（t 对 d），声调也不同，意思是若干天。", "基点": "第一音节 jī 为第一声，与 jǐ 的声调不同，意思是基础的要点。"}, "sentence_index": null, "correct_answer": "几点"}, "level_3": {"options": [{"text": "几点", "is_correct": true, "explanation": "正确：问某件事在几时发生，填入后句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，这句问的是起床的时间，不是起床的人。"}, {"text": "哪儿", "is_correct": false, "explanation": "搭配：“起床”不带处所宾语，不能说“哪儿起床”。"}, {"text": "多久", "is_correct": false, "explanation": "语义：“多久”问时长，不问具体的钟点。"}], "explanations": {"几点": "正确：问某件事在几时发生，填入后句意通顺。", "谁": "语义：“谁”问人，这句问的是起床的时间，不是起床的人。", "哪儿": "搭配：“起床”不带处所宾语，不能说“哪儿起床”。", "多久": "语义：“多久”问时长，不问具体的钟点。"}, "sentence_index": 0, "correct_answer": "几点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在北京住了几点？", "explanation": "这里应该用〈多久〉。几点问的是钟点，问停留了多长时间要用多久。"}, {"text": "你住在几点？", "explanation": "这里应该用〈哪儿〉。几点只问时刻，问居住的地方要用哪儿。"}, {"text": "我们班有几点学生。", "explanation": "这里应该用〈几个〉。几点只用于问时刻，问人数要用几个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98344, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "几点", "is_correct": true, "explanation": "几点 jǐ diǎn：询问某件事发生在几时。"}, {"text": "七点", "is_correct": false, "explanation": "qī 与 jǐ 声母不同（q 对 j），且声调改为第一声，意思是七点钟。"}, {"text": "极点", "is_correct": false, "explanation": "第一音节 jí 为第二声，与 jǐ 的声调不同，意思是程度的最高点。"}, {"text": "起点", "is_correct": false, "explanation": "qǐ 与 jǐ 声母不同（q 对 j），声调相同，意思是出发的地方。"}, {"text": "基点", "is_correct": false, "explanation": "第一音节 jī 为第一声，与 jǐ 的声调不同，意思是基础的要点。"}], "explanations": {"几点": "几点 jǐ diǎn：询问某件事发生在几时。", "七点": "qī 与 jǐ 声母不同（q 对 j），且声调改为第一声，意思是七点钟。", "极点": "第一音节 jí 为第二声，与 jǐ 的声调不同，意思是程度的最高点。", "起点": "qǐ 与 jǐ 声母不同（q 对 j），声调相同，意思是出发的地方。", "基点": "第一音节 jī 为第一声，与 jǐ 的声调不同，意思是基础的要点。"}, "sentence_index": null, "correct_answer": "几点"}, "level_3": {"options": [{"text": "几点", "is_correct": true, "explanation": "正确：问吃晚饭的时间，填入后句意通顺。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：“什么”不能直接修饰“吃晚饭”，这句要问钟点，不能用“什么”。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”用于在几样东西中选择，不问时刻。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，这句问的是吃晚饭的时间。"}], "explanations": {"几点": "正确：问吃晚饭的时间，填入后句意通顺。", "什么": "搭配：“什么”不能直接修饰“吃晚饭”，这句要问钟点，不能用“什么”。", "哪个": "语义：“哪个”用于在几样东西中选择，不问时刻。", "为什么": "语义：“为什么”问原因，这句问的是吃晚饭的时间。"}, "sentence_index": 6, "correct_answer": "几点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你去过几点北京？", "explanation": "这里应该用〈几次〉。几点问时刻，问去过的次数要用几次。"}, {"text": "这本书卖了几点钱？", "explanation": "这里应该用〈多少〉。几点问时刻，问价钱要用多少钱。"}, {"text": "我今年几点了？", "explanation": "这里应该用〈几岁〉。几点问时刻，问年龄要用几岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.