INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "忍是心里难受或生气，可是不说也不做。", "primary_collocate": null, "pronunciation": "rěn", "ipa": "ʐən˨˩˦", "syllable_count": 1, "sentences": [{"text": "他很生气，但是忍着没有说话。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说错了，我只好忍一忍。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里难受，一直忍着没哭。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿了我的东西，我忍了。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里很委屈，但是忍着没有跟老板说。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学说了难听的话，他忍下去了。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很生气，可是为了朋友忍住了。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我已经忍了很久了。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忍着火气，没有跟客人吵架。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小事就忍一下，别吵架了。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忍着", "label": "体标"}, {"form": "忍了", "label": "体标"}, {"form": "忍忍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "心里生气或难受，但克制自己，不说话也不行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忍", "is_correct": true, "explanation": "忍（rěn）：心里难受或生气，却不说也不做，压在心里。"}, {"text": "人", "is_correct": false, "explanation": "rén（第二声）与 rěn（第三声）声调不同，意思是人。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是认识、承认。"}, {"text": "很", "is_correct": false, "explanation": "hěn 与 rěn 声母不同（h 与 r），意思是很。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。"}], "explanations": {"忍": "忍（rěn）：心里难受或生气，却不说也不做，压在心里。", "人": "rén（第二声）与 rěn（第三声）声调不同，意思是人。", "认": "rèn（第四声）与 rěn（第三声）声调不同，意思是认识、承认。", "很": "hěn 与 rěn 声母不同（h 与 r），意思是很。", "任": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。"}, "sentence_index": null, "correct_answer": "忍"}, "level_3": {"options": [{"text": "忍", "is_correct": true, "explanation": "正确：“忍着”表示压住情绪、不说话，符合“很生气，却没有说话”。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”就是说话，与“没有说话”矛盾。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”是争执、发出声音，与“没有说话”矛盾。"}, {"text": "发", "is_correct": false, "explanation": "搭配：“发”要带“火”或“脾气”等宾语，不能单独这样接“着”和“没有说话”。"}], "explanations": {"忍": "正确：“忍着”表示压住情绪、不说话，符合“很生气，却没有说话”。", "骂": "语义：“骂”就是说话，与“没有说话”矛盾。", "吵": "语义：“吵”是争执、发出声音，与“没有说话”矛盾。", "发": "搭配：“发”要带“火”或“脾气”等宾语，不能单独这样接“着”和“没有说话”。"}, "sentence_index": 0, "correct_answer": "忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里难受，就忍着大声哭出来。", "explanation": "这里应该用〈忍不住〉。“忍”是压住情绪、不表现出来，这里说“大声哭出来”，是把情绪表现出来，与“忍”的意思相反。"}, {"text": "他心里很委屈，却把情绪忍给大家看。", "explanation": "这里应该用〈流露〉。“忍”是压住情绪、不表现出来，这里说“忍给大家看”，实际是把情绪表现出来，与“忍”的意思相反。"}, {"text": "老板骂了他，他就忍着把桌子砸了。", "explanation": "这里应该用〈发火〉。“忍”不能接“砸桌子”这类发泄的动作，与“不做”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忍", "is_correct": true, "explanation": "忍（rěn）：心里难受或生气，却不说也不做，压在心里。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。"}, {"text": "仁", "is_correct": false, "explanation": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。"}, {"text": "韧", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是柔韧。"}, {"text": "审", "is_correct": false, "explanation": "shěn 与 rěn 声母不同（sh 与 r），意思是审查、审判。"}], "explanations": {"忍": "忍（rěn）：心里难受或生气，却不说也不做，压在心里。", "任": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。", "仁": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。", "韧": "rèn（第四声）与 rěn（第三声）声调不同，意思是柔韧。", "审": "shěn 与 rěn 声母不同（sh 与 r），意思是审查、审判。"}, "sentence_index": null, "correct_answer": "忍"}, "level_3": {"options": [{"text": "忍", "is_correct": true, "explanation": "正确：“忍住”表示克制住情绪，符合“为了朋友”的语境。"}, {"text": "抓", "is_correct": false, "explanation": "语义：“抓住”是用手握住，与“为了朋友”而克制情绪的语境不合。"}, {"text": "挤", "is_correct": false, "explanation": "语义：“挤住”是挤压或拥挤，与“很生气，却为了朋友克制”不合。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬住”的对象是东西或嘴，不能用来指克制情绪。"}], "explanations": {"忍": "正确：“忍住”表示克制住情绪，符合“为了朋友”的语境。", "抓": "语义：“抓住”是用手握住，与“为了朋友”而克制情绪的语境不合。", "挤": "语义：“挤住”是挤压或拥挤，与“很生气，却为了朋友克制”不合。", "咬": "搭配：“咬住”的对象是东西或嘴，不能用来指克制情绪。"}, "sentence_index": 6, "correct_answer": "忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈一直忍着，对我大声吼了一顿。", "explanation": "这里应该用〈发火〉或〈训斥〉。“忍”表示不表现出来，这里说“大声吼了一顿”，是表现出来的动作，与“忍”矛盾。"}, {"text": "他对新工作很满意，却一直忍着。", "explanation": "这里应该用〈高兴〉或〈满足〉。“忍”是把痛苦、委屈或不满压在心里，这里的情绪是愉快，不是痛苦或不满，两者意思不符。"}, {"text": "孩子得了第一名，妈妈忍着，笑得合不拢嘴。", "explanation": "这里应该用〈高兴〉或〈欢喜〉。“忍”是把痛苦或不满压在心里，这里说“笑得合不拢嘴”，是高兴地表现出来，与“忍”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很生气，但是忍起来没有骂他。", "corrected_sentence": "我很生气，但是忍着没有骂他。", "error_description": "补语错误：“忍”后应接“着”或“住”表示克制，不能接趋向补语“起来”。正确说法是“忍着没有骂他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她心里难受，却忍起来没哭。", "corrected_sentence": "她心里难受，却忍住没哭。", "error_description": "补语错误：表示克制要用结果补语“住”，“忍”后不能接趋向补语“起来”。正确说法是“忍住没哭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
