INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把痛苦或不满压在心里，不表现出来。", "primary_collocate": null, "pronunciation": "rěn", "ipa": "ʐən˨˩˦", "syllable_count": 1, "sentences": [{"text": "他忍着痛，笑着对大家说没事。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈累了一天，什么也没说，只是忍着。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里很不高兴，却一直忍着，脸上还在笑。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腿很疼，但他一直忍着没有叫出来。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔疼了，忍着眼泪没哭。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作很不满，可是一直忍着。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问疼不疼，她忍了一下说不疼。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，他忍住难过，没让人看出来。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把委屈忍了很多年，从来不说。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙疼得厉害，她还是忍着去上班。", "target_word": "忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忍着", "label": "体标"}, {"form": "忍了", "label": "体标"}, {"form": "忍忍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把痛苦、不满或难过压在心里，不让别人看出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忍", "is_correct": true, "explanation": "忍（rěn）：把痛苦或不满压在心里，不表现出来。"}, {"text": "仁", "is_correct": false, "explanation": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。"}, {"text": "任", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。"}, {"text": "审", "is_correct": false, "explanation": "shěn 与 rěn 声母不同（sh 与 r），意思是审查、审判。"}, {"text": "人", "is_correct": false, "explanation": "rén（第二声）与 rěn（第三声）声调不同，意思是人。"}], "explanations": {"忍": "忍（rěn）：把痛苦或不满压在心里，不表现出来。", "仁": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。", "任": "rèn（第四声）与 rěn（第三声）声调不同，意思是任务、任何。", "审": "shěn 与 rěn 声母不同（sh 与 r），意思是审查、审判。", "人": "rén（第二声）与 rěn（第三声）声调不同，意思是人。"}, "sentence_index": null, "correct_answer": "忍"}, "level_3": {"options": [{"text": "忍", "is_correct": true, "explanation": "正确：“忍着痛”表示克制疼痛、不表现出来，与“笑着说没事”一致。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭着痛”就是哭出来，与后面“笑着说没事”矛盾。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊着痛”是大声表现疼痛，与“笑着说没事”矛盾。"}, {"text": "闹", "is_correct": false, "explanation": "搭配：“闹”指吵闹，不能用来带“痛”作状态，“闹着痛”不这样说。"}], "explanations": {"忍": "正确：“忍着痛”表示克制疼痛、不表现出来，与“笑着说没事”一致。", "哭": "语义：“哭着痛”就是哭出来，与后面“笑着说没事”矛盾。", "喊": "语义：“喊着痛”是大声表现疼痛，与“笑着说没事”矛盾。", "闹": "搭配：“闹”指吵闹，不能用来带“痛”作状态，“闹着痛”不这样说。"}, "sentence_index": 0, "correct_answer": "忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他忍着高兴，蹦起来跟大家一起庆祝。", "explanation": "这里应该用〈兴奋〉或〈欢喜〉。“忍”只用于痛苦、委屈或不满，这里是高兴的情绪，两者意思不符。"}, {"text": "他忍着，对大家开心地笑起来。", "explanation": "这里应该用〈欢笑〉。“忍”是把痛苦或不满压在心里、不表现出来，这里说“开心地笑起来”，是把快乐表现出来，与“忍”的意思相反。"}, {"text": "他很痛，就忍着把痛苦全写在脸上。", "explanation": "这里应该用〈流露〉。“忍”是压住痛苦、不表现出来，这里说“痛苦全写在脸上”，是表现出来，与“忍”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忍", "is_correct": true, "explanation": "忍（rěn）：把痛苦或不满压在心里，不表现出来。"}, {"text": "认", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是认识、承认。"}, {"text": "很", "is_correct": false, "explanation": "hěn 与 rěn 声母不同（h 与 r），意思是很。"}, {"text": "仁", "is_correct": false, "explanation": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。"}, {"text": "韧", "is_correct": false, "explanation": "rèn（第四声）与 rěn（第三声）声调不同，意思是柔韧。"}], "explanations": {"忍": "忍（rěn）：把痛苦或不满压在心里，不表现出来。", "认": "rèn（第四声）与 rěn（第三声）声调不同，意思是认识、承认。", "很": "hěn 与 rěn 声母不同（h 与 r），意思是很。", "仁": "rén（第二声）与 rěn（第三声）声调不同，意思是仁爱。", "韧": "rèn（第四声）与 rěn（第三声）声调不同，意思是柔韧。"}, "sentence_index": null, "correct_answer": "忍"}, "level_3": {"options": [{"text": "忍", "is_correct": true, "explanation": "正确：“忍了一下”表示克制疼痛、不表现出来，然后才说不疼。"}, {"text": "抬", "is_correct": false, "explanation": "语义：“抬”是举起东西，与“说不疼”没有关系。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳了一下”是跃起、蹦一下，与医生问话后“说不疼”没有关系。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔了一下”是抛出东西，与医生问疼不疼、她回答“说不疼”没有关系。"}], "explanations": {"忍": "正确：“忍了一下”表示克制疼痛、不表现出来，然后才说不疼。", "抬": "语义：“抬”是举起东西，与“说不疼”没有关系。", "跳": "语义：“跳了一下”是跃起、蹦一下，与医生问话后“说不疼”没有关系。", "扔": "语义：“扔了一下”是抛出东西，与医生问疼不疼、她回答“说不疼”没有关系。"}, "sentence_index": 6, "correct_answer": "忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他评上了先进，却忍着，把奖状拿给全村人看。", "explanation": "这里应该用〈炫耀〉。“忍”是压住不表现出来，这里说“拿给全村人看”，是主动表现出来，与“忍”矛盾。"}, {"text": "这个月他工资涨了，他却一直忍着，很得意。", "explanation": "这里应该用〈自豪〉。“忍”是把痛苦或不满压在心里，这里的情绪是愉快，不是痛苦或不满，两者意思不符。"}, {"text": "牙疼得厉害，她却大声地忍着哭出来。", "explanation": "这里应该用〈痛哭〉。“忍”是把痛苦压在心里、不表现出来，这里说“大声地哭出来”，是把痛苦表现出来，与“忍”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他疼得厉害，还是忍了着没有叫。", "corrected_sentence": "他疼得厉害，还是忍着没有叫。", "error_description": "体标错误：“忍着”表示持续的克制，“着”之前不能再加“了”。正确说法是“忍着没有叫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些委屈，他被忍了好多年。", "corrected_sentence": "这些委屈，他忍了好多年。", "error_description": "“被”字句使“他”成为被忍受的对象，而“委屈”才是他所忍受的内容，句意不通；应说“这些委屈，他忍了好多年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情景是某个时候你看到的样子和发生的事。", "primary_collocate": null, "pronunciation": "qíng jǐng", "ipa": "tɕʰiŋ˧˥ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我还记得第一次见面时的情景。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这个情景，大家都笑了。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片让他想起了小时候的情景。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个情景我一辈子也忘不了。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩雪的情景真让人开心。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我讲了当时的情景。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，车站里的情景很热闹。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有一个很感人的情景。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着眼前的情景，一句话也说不出来。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回家后，我对妈妈说了路上的情景。", "target_word": "情景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个情景", "label": "量词（个）"}, {"form": "一幕情景", "label": "量词（幕）"}, {"form": "情景剧", "label": "复合词"}, {"form": "情景对话", "label": "复合词"}], "register": "中性", "sense_fingerprint": "某时所见所发生的景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能指见面时的情形。"}, {"text": "情景", "is_correct": true, "explanation": "正确：指第一次见面时看到的情形，与“记得”搭配。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”是语言规则，见面时看不到“语法”。"}, {"text": "典籍", "is_correct": false, "explanation": "语义：“典籍”指古代重要的书，不能指第一次见面时看到的情形。"}], "explanations": {"价格": "语义：“价格”指钱数，不能指见面时的情形。", "情景": "正确：指第一次见面时看到的情形，与“记得”搭配。", "语法": "语义：“语法”是语言规则，见面时看不到“语法”。", "典籍": "语义：“典籍”指古代重要的书，不能指第一次见面时看到的情形。"}, "sentence_index": 0, "correct_answer": "情景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们收到了一份重要的情景，需要马上处理。", "explanation": "这里应该用〈情报〉。情报指消息、资料，“情景”指看到的景象，不能“收到一份”。"}, {"text": "他一进门就带着好情景，大家都很开心。", "explanation": "这里应该用〈情绪〉。情绪指心里的状态，“情景”是景象，不能“带着”。"}, {"text": "老师一脸情景，大家都不敢说话。", "explanation": "这里应该用〈表情〉。“一脸”后接面部神色，“情景”指场面，不能说“一脸情景”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车票", "is_correct": false, "explanation": "语义：“车票”是乘车的凭证，不指车站里的情形，不能“很热闹”。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不能用来形容座位。"}, {"text": "情景", "is_correct": true, "explanation": "正确：指车站里下雨天的情形，与“热闹”相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能指车站里的情形。"}], "explanations": {"车票": "语义：“车票”是乘车的凭证，不指车站里的情形，不能“很热闹”。", "座位": "搭配：“热闹”形容场面，不能用来形容座位。", "情景": "正确：指车站里下雨天的情形，与“热闹”相符。", "课本": "语义：“课本”是书，不能指车站里的情形。"}, "sentence_index": 6, "correct_answer": "情景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个情景很聪明，大家都很佩服。", "explanation": "这里应该用〈人〉。“聪明”形容人的智力，“情景”指景象，不能用来形容它。"}, {"text": "这顿饭的情景很辣，大家吃得很满意。", "explanation": "这里应该用〈味道〉。“辣”形容味道，“情景”指景象，不能用来形容味道。"}, {"text": "她拿起一个情景，仔细看了看。", "explanation": "这里应该用〈照片〉。“拿起”的是实物，“情景”是看到的景象，不能拿起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想起了那天的一条情景。", "corrected_sentence": "我想起了那天的一幕情景。", "error_description": "错误：量词“条”。“情景”应用量词“幕”（或“个”）计量，“条”用于路、河等细长事物。正确：“一幕情景”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影里，老人在海边散步地情景很动人。", "corrected_sentence": "这部电影里，老人在海边散步的情景很动人。", "error_description": "错误：修饰语的标记。名词前的修饰成分应用“的”连接，应为“散步的情景”，不能用“地”（“地”用于动词前的状语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
