INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "或门是电路里的一种开关，几个入口里只要有一个有电，就会通电。", "primary_collocate": null, "pronunciation": "huò mén", "ipa": "xwo˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "或门有两个入口，只要一个有电就通电。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电路里有一个或门。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个或门。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个入口都没电，或门就不通电。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把灯接在或门上。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要有一个入口有电，或门就让灯亮。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个或门有三个入口。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "或门坏了，灯怎么也不亮。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找一找电路图里的或门。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用两个开关做了一个或门。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个或门", "label": "量词"}, {"form": "或非门", "label": "复合"}], "register": "专业", "sense_fingerprint": "电路中的开关，任一入口有电就通电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "或门", "is_correct": true, "explanation": "正确：或门有两个入口，只要一个有电就通电，与句意相符。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡不是开关电路元件，没有可以分别输入电的两个入口。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是空间，不会因为一个入口有电就通电，与电路语境不合。"}, {"text": "喷泉", "is_correct": false, "explanation": "语义：喷泉是景观设施，不是电路元件，没有可以分别输入电的两个入口，与句意不合。"}], "explanations": {"或门": "正确：或门有两个入口，只要一个有电就通电，与句意相符。", "灯泡": "语义：灯泡不是开关电路元件，没有可以分别输入电的两个入口。", "厨房": "语义：厨房是空间，不会因为一个入口有电就通电，与电路语境不合。", "喷泉": "语义：喷泉是景观设施，不是电路元件，没有可以分别输入电的两个入口，与句意不合。"}, "sentence_index": 0, "correct_answer": "或门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "或门要求两个入口都有电，才会通电。", "explanation": "这里应该用〈与门〉。或门只要一个入口有电就通电；要求两个入口都有电才通电的是与门。"}, {"text": "只有两个入口都没电，或门才会通电。", "explanation": "这里应该用〈或非门〉。或门只要一个入口有电就通电，不会只在都没电时才通电；这种情况是或非门。"}, {"text": "或门只有两个入口都有电时才不通电。", "explanation": "这里应该用〈与非门〉。或门两个入口都有电时就通电；「都有电时才不通电」是与非门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或门", "is_correct": true, "explanation": "正确：或门是电路元件，「有三个入口」与句意相符。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不是电路元件，不会有输入电的「入口」。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：「入口」多用于建筑、电路等，不搭配「月亮」。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不是电路元件，没有输入电的入口，与电路语境不合。"}], "explanations": {"或门": "正确：或门是电路元件，「有三个入口」与句意相符。", "西瓜": "语义：西瓜不是电路元件，不会有输入电的「入口」。", "月亮": "搭配：「入口」多用于建筑、电路等，不搭配「月亮」。", "花瓶": "语义：花瓶不是电路元件，没有输入电的入口，与电路语境不合。"}, "sentence_index": 6, "correct_answer": "或门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "或门的输出总是与输入正好相反。", "explanation": "这里应该用〈非门〉。非门的输出与输入相反；或门只要有一个入口有电就通电，输出不会总与输入相反。"}, {"text": "或门的两个入口电压不同时才通电。", "explanation": "这里应该用〈异或门〉。异或门要求两个入口不同时才通电；或门两个入口都有电时也通电。"}, {"text": "只要有一个入口有电，或门就不通电。", "explanation": "这里应该用〈或非门〉。或门只要有一个入口有电就通电；有一个入口有电就不通电的是或非门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在电路里装了一棵或门。", "corrected_sentence": "我们在电路里装了一个或门。", "error_description": "量词错误：「或门」是电路元件，量词应用「个」。「棵」多用于树木，与电路元件搭配明显不当。错误形式：一棵或门；正确形式：一个或门。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学了也或门。", "corrected_sentence": "我们学了或门。", "error_description": "「也」是副词，应放在动词前，不能放在名词「或门」前。「学了也或门」中多出的「也」位置错误，应说「我们学了或门」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
