INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "逻辑电路的一种，只要有一个输入为真，输出就为真。", "primary_collocate": null, "pronunciation": "huò mén", "ipa": "xwo˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "或门的两个输入只要有一个是真，输出就是真。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输入都是假，或门的输出也是假。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计算机课上，我们学了或门。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "或门和与门是两种常见的逻辑电路。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "或门的输入是一真一假，输出是什么？", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表写的是或门的输出。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逻辑电路中，或门只有一个输出。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出或门的符号。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "或门的输出只取决于输入中是否存在真。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用或门可以做一个简单的报警器。", "target_word": "或门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个或门", "label": "量词"}, {"form": "或非门", "label": "复合"}], "register": "专业", "sense_fingerprint": "逻辑电路，任一输入为真则输出为真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "或门", "is_correct": true, "explanation": "正确：或门的输入只要有一个为真，输出就为真，与句意相符。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯不是逻辑电路元件，没有可以取真值的输入，与「输入为真」不合。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是逻辑电路元件，没有可以取真值的输入，与句意不合。"}, {"text": "真理", "is_correct": false, "explanation": "语义：真理是抽象概念，不是逻辑电路元件，不能有「输入」。"}], "explanations": {"或门": "正确：或门的输入只要有一个为真，输出就为真，与句意相符。", "电灯": "语义：电灯不是逻辑电路元件，没有可以取真值的输入，与「输入为真」不合。", "饺子": "语义：饺子是食物，不是逻辑电路元件，没有可以取真值的输入，与句意不合。", "真理": "语义：真理是抽象概念，不是逻辑电路元件，不能有「输入」。"}, "sentence_index": 0, "correct_answer": "或门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "或门的两个输入都是真，输出才是真。", "explanation": "这里应该用〈与门〉。与门要求两个输入都为真，输出才为真；或门只要一个为真输出就为真。"}, {"text": "或门的输出与输入相反。", "explanation": "这里应该用〈非门〉。非门的输出与输入相反；或门的输出在有真输入时为真，不与输入相反。"}, {"text": "或门的两个输入不同时，输出才是真。", "explanation": "这里应该用〈异或门〉。异或门要求两个输入不同时输出才为真；或门两个输入都为真时输出也为真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或门", "is_correct": true, "explanation": "正确：或门是逻辑电路的元件，「只有一个输出」与句意相符。"}, {"text": "诗", "is_correct": false, "explanation": "语义：诗是文学作品，不是逻辑电路的元件，不能在逻辑电路中有输出。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是电路元件，与「逻辑电路中」的语境不合。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：「大爷」是口语称呼，与「逻辑电路中」的专业语域不合。"}], "explanations": {"或门": "正确：或门是逻辑电路的元件，「只有一个输出」与句意相符。", "诗": "语义：诗是文学作品，不是逻辑电路的元件，不能在逻辑电路中有输出。", "月亮": "语义：月亮不是电路元件，与「逻辑电路中」的语境不合。", "大爷": "语域：「大爷」是口语称呼，与「逻辑电路中」的专业语域不合。"}, "sentence_index": 6, "correct_answer": "或门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "或门的两个输入都是真时，输出为假。", "explanation": "这里应该用〈与非门〉。或门两个输入都为真时输出也为真，不会输出为假；输入都为真时输出为假的是与非门。"}, {"text": "或门的两个输入都是假时，输出为真。", "explanation": "这里应该用〈或非门〉。或门两个输入都为假时输出为假；输出为真的是或非门。"}, {"text": "只要有一个输入是假，或门的输出就是假。", "explanation": "这里应该用〈与门〉。与门只要有一个输入为假，输出就为假；或门只要有一个输入为真，输出就为真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "逻辑电路中，我们画了一棵或门。", "corrected_sentence": "逻辑电路中，我们画了一个或门。", "error_description": "量词错误：「或门」是逻辑电路元件，量词应用「个」。「棵」多用于树木，与电路元件搭配明显不当。错误形式：一棵或门；正确形式：一个或门。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师画了也或门的符号。", "corrected_sentence": "老师画了或门的符号。", "error_description": "「也」是副词，应放在动词前，不能放在名词「或门」前。「画了也或门的符号」中多出的「也」位置错误，应说「老师画了或门的符号」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
