INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手工是用手做出来的东西，或者用手做东西的事。", "primary_collocate": null, "pronunciation": "shǒu gōng", "ipa": "ʂoʊ˨˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这个小礼物是我自己做的手工。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上做手工，用纸做小花。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹喜欢做手工，家里有很多她做的小动物。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们周末在家做一件手工。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾是奶奶的手工，又软又暖和。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的都是当地人做的手工。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送我的手工是一只用布做的小猫。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做手工的时候，不喜欢别人和我说话。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园明天要做手工，孩子要带剪刀和纸。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些手工很可爱，都是学生们自己做的。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "手工艺", "label": "复合"}, {"form": "手工品", "label": "复合"}], "register": "中性", "sense_fingerprint": "亲手做出的小物件或做这类东西的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼节", "is_correct": false, "explanation": "语义：礼节指待人接物的规矩，不是做出来的东西。"}, {"text": "手工", "is_correct": true, "explanation": "手工：用手做出来的东西，与“我自己做的”搭配。"}, {"text": "手段", "is_correct": false, "explanation": "搭配：“手段”是方法，不是能被做出来的物品。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是身体的活动，不能是送出去的小礼物。"}], "explanations": {"礼节": "语义：礼节指待人接物的规矩，不是做出来的东西。", "手工": "手工：用手做出来的东西，与“我自己做的”搭配。", "手段": "搭配：“手段”是方法，不是能被做出来的物品。", "呼吸": "语义：呼吸是身体的活动，不能是送出去的小礼物。"}, "sentence_index": 0, "correct_answer": "手工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做菜的手工很好，大家都爱吃。", "explanation": "这里应该用〈手艺〉。手工指用手做出来的东西或做东西的活动，做菜的本领要说手艺。"}, {"text": "老师让我们周末在家做一台手工。", "explanation": "这里应该用〈件〉。手工作品用“件”计量，“台”用于机器、仪器。"}, {"text": "老师让我们周末在家手工写作文。", "explanation": "这里应该用〈手写〉。手工指做出东西或做东西的活动，写字要说手写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩笑", "is_correct": false, "explanation": "语义：玩笑是逗人笑的话，不是能送的小猫。"}, {"text": "思路", "is_correct": false, "explanation": "搭配：“送”不能与“思路”搭配，思路也不是布做的东西。"}, {"text": "手工", "is_correct": true, "explanation": "手工：用手做出来的东西，可以送人，也可以是布做的小猫。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：习惯是行为方式，不是能送出去的东西。"}], "explanations": {"玩笑": "语义：玩笑是逗人笑的话，不是能送的小猫。", "思路": "搭配：“送”不能与“思路”搭配，思路也不是布做的东西。", "手工": "手工：用手做出来的东西，可以送人，也可以是布做的小猫。", "习惯": "语义：习惯是行为方式，不是能送出去的东西。"}, "sentence_index": 6, "correct_answer": "手工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的手工受伤了，不能弹钢琴。", "explanation": "这里应该用〈手指〉。手工指用手做出来的东西，身体部位要说手指。"}, {"text": "他做菜的手工很好，饭馆的客人都爱吃。", "explanation": "这里应该用〈手艺〉。手工指用手做出来的东西，做菜的本领要说手艺。"}, {"text": "他用手工和朋友交流，两人都很开心。", "explanation": "这里应该用〈手语〉。手工指用手做东西，用手比画交流要说手语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈送了我一台手工，是一只布做的小猫。", "corrected_sentence": "妈妈送了我一件手工，是一只布做的小猫。", "error_description": "“台”用于机器、仪器等，手工作品应用“件”。应说“一件手工”，不说“一台手工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做了过手工。", "corrected_sentence": "妈妈做过手工。", "error_description": "“过”表示曾经有过某种经历，用了“过”就不能再加“了”，应说“做过手工”；“做了过手工”同时使用了两个动态助词，是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手艺", "is_correct": false, "explanation": "与“手工”没有反义关系，手艺指手上的技能本领。"}, {"text": "工人", "is_correct": false, "explanation": "与“手工”没有反义关系，工人指做工的人。"}, {"text": "机器", "is_correct": true, "explanation": "机器：靠机械动力完成制作，与“靠人手”的手工相对。"}, {"text": "材料", "is_correct": false, "explanation": "与“手工”没有反义关系，材料指做东西用的原料。"}], "correct_answer": "机器", "explanations": {"手艺": "与“手工”没有反义关系，手艺指手上的技能本领。", "工人": "与“手工”没有反义关系，工人指做工的人。", "机器": "机器：靠机械动力完成制作，与“靠人手”的手工相对。", "材料": "与“手工”没有反义关系，材料指做东西用的原料。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用手进行的制作，不是靠机器。", "primary_collocate": null, "pronunciation": "shǒu gōng", "ipa": "ʂoʊ˨˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这件衣服是手工做的，不是机器做的。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工做一双鞋要用好几天。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面包全靠手工，所以每天只做一百个。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的人用手工做纸，已经做了几百年。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工做的东西一般比机器做的贵。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为是手工，每个杯子都有一点不一样。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢手工做的东西，觉得它有温度。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶要用手工来做，机器做不好。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工比机器慢，可是做得很细。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用手工做了一张椅子，没有用一个钉子。", "target_word": "手工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手工制作", "label": "复合"}, {"form": "手工艺", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠人手而不是机器完成的制作方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机械", "is_correct": false, "explanation": "语义：机械指机器，与后半句“不是机器做的”矛盾。"}, {"text": "手工", "is_correct": true, "explanation": "手工：靠人手而不是机器完成的制作，与“不是机器做的”形成对比。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“手术”是医疗操作，不能用来做衣服。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是器具，不指靠人手完成的制作方式。"}], "explanations": {"机械": "语义：机械指机器，与后半句“不是机器做的”矛盾。", "手工": "手工：靠人手而不是机器完成的制作，与“不是机器做的”形成对比。", "手术": "搭配：“手术”是医疗操作，不能用来做衣服。", "工具": "语义：工具是器具，不指靠人手完成的制作方式。"}, "sentence_index": 0, "correct_answer": "手工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机是手工组装的，每天能卖出十几万台。", "explanation": "这里应该用〈流水线〉。手工指不靠机器，每天卖出十几万台要靠流水线生产，与“手工组装”矛盾。"}, {"text": "这扇门是手工打开的，不用人碰，靠感应开合。", "explanation": "这里应该用〈电动〉。手工指不靠机器，靠感应开合的门要说电动，与“手工”矛盾。"}, {"text": "这个网站的日记都是手工一键生成的，几秒就能完成。", "explanation": "这里应该用〈自动〉。手工指不靠机器，一键几秒生成的要说自动生成，与“手工”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流水线", "is_correct": false, "explanation": "语义：流水线是机器批量生产，与“有温度”相矛盾。"}, {"text": "手工", "is_correct": true, "explanation": "手工：靠人手做的东西，与“有温度”搭配。"}, {"text": "机床", "is_correct": false, "explanation": "搭配：“机床”是加工设备，一般不说人们喜欢机床做的东西。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，不像手工做的东西那样“有温度”。"}], "explanations": {"流水线": "语义：流水线是机器批量生产，与“有温度”相矛盾。", "手工": "手工：靠人手做的东西，与“有温度”搭配。", "机床": "搭配：“机床”是加工设备，一般不说人们喜欢机床做的东西。", "电脑": "语义：电脑是电子设备，不像手工做的东西那样“有温度”。"}, "sentence_index": 6, "correct_answer": "手工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷用手工复印了一千张椅子的图纸。", "explanation": "这里应该用〈复印机〉。手工指不靠机器，一千张复印要靠复印机完成，与“手工”矛盾。"}, {"text": "这个工地靠手工推土机修路，已经修了三年。", "explanation": "这里应该用〈机械〉。手工指不靠机器，推土机修路属于机械作业，要说机械。"}, {"text": "他用手工和朋友聊天，比画得很快。", "explanation": "这里应该用〈手语〉。手工指做东西，用手比画交流要说手语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子被手工做的，不是机器做的。", "corrected_sentence": "这把椅子是手工做的，不是机器做的。", "error_description": "“被”字句需要一个能施动的人或物，“手工”不是施事者，不能说“被手工做的”。应把“被”改为“是”，说“是手工做的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张木桌要用手工做来，机器做不好。", "corrected_sentence": "这张木桌要用手工来做，机器做不好。", "error_description": "“来”应放在“用手工”后面，说“用手工来做”，不能放在动词“做”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
