INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手枪是一只手就能拿的小枪。", "primary_collocate": null, "pronunciation": "shǒu qiāng", "ipa": "ʂou˨˩˦ tɕʰiɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "警察腰上有一把手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把手枪很小，一只手就能拿。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的警察手里拿着手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在柜子里找到了一把手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一把黑色的手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手枪放进了包里。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支手枪不重，女孩也拿得动。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给我们看他以前的手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手枪比步枪小得多。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出一把小手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "玩具手枪", "label": "复合"}, {"form": "手槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体积小、一只手就能拿着的枪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手枪", "is_correct": true, "explanation": "正确：“手枪”是一只手就能拿的小枪，可以别在腰上。"}, {"text": "步枪", "is_correct": false, "explanation": "语义：步枪体积大，不能别在腰上。"}, {"text": "伞", "is_correct": false, "explanation": "语义：伞不是武器，不会别在警察的腰上。"}, {"text": "手表", "is_correct": false, "explanation": "搭配：手表的量词常用“块”或“只”，不说“一把手表”。"}], "explanations": {"手枪": "正确：“手枪”是一只手就能拿的小枪，可以别在腰上。", "步枪": "语义：步枪体积大，不能别在腰上。", "伞": "语义：伞不是武器，不会别在警察的腰上。", "手表": "搭配：手表的量词常用“块”或“只”，不说“一把手表”。"}, "sentence_index": 0, "correct_answer": "手枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一根手枪，放在桌子上。", "explanation": "这里的量词错误：手枪应该用“把”或“支”，不能用“根”。"}, {"text": "这把手枪很大，两个人才抬得动。", "explanation": "这里和定义矛盾。“手枪”是一只手就能拿的小枪，不能说“很大，两个人才抬得动”，这里应该是〈步枪〉或〈机枪〉。"}, {"text": "他扛着手枪走进了树林。", "explanation": "这里应该用〈步枪〉。手枪枪身短，要单手握着，不能扛在肩上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手枪", "is_correct": true, "explanation": "正确：“手枪”很轻，女孩也拿得动。"}, {"text": "大炮", "is_correct": false, "explanation": "语义：大炮很重，与“不重，女孩也拿得动”矛盾。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴很重，一个女孩不可能拿得动，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头的量词是“块”或“个”，不说“这支石头”。"}], "explanations": {"手枪": "正确：“手枪”很轻，女孩也拿得动。", "大炮": "语义：大炮很重，与“不重，女孩也拿得动”矛盾。", "钢琴": "语义：钢琴很重，一个女孩不可能拿得动，与句意矛盾。", "石头": "搭配：石头的量词是“块”或“个”，不说“这支石头”。"}, "sentence_index": 6, "correct_answer": "手枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从口袋里拿出一条手枪。", "explanation": "这里的量词错误：手枪应该用“把”或“支”，“条”用于长条形的东西。"}, {"text": "夜里他用手枪照路。", "explanation": "这里应该用〈手电筒〉。“手枪”是武器，不能用来照路。"}, {"text": "他用手枪点烟。", "explanation": "这里应该用〈打火机〉。“手枪”不能用来点烟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家里有一只旧手枪。", "corrected_sentence": "他家里有一把旧手枪。", "error_description": "量词错误：“只”不用于手枪，应改为“把”。正确说法是“一把旧手枪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把手枪放了进抽屉。", "corrected_sentence": "他把手枪放进了抽屉。", "error_description": "补语与体标位置错误：“进”是趋向补语，“了”应放在“放进”之后，说“放进了抽屉”，不能说“放了进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
