INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以单手持握射击的短枪。", "primary_collocate": null, "pronunciation": "shǒu qiāng", "ipa": "ʂou˨˩˦ tɕʰiɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这位运动员练习的是手枪射击。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用手枪对着天空开了一枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手枪的子弹比步枪的子弹小。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学会了怎么用手枪射击。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手枪可以单手拿着射击。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，选手要用手枪打远处的靶子。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一把一百年前的手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察检查了他的手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手枪里没有子弹。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们每天都练习用手枪。", "target_word": "手枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "玩具手枪", "label": "复合"}, {"form": "手槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "枪身短、可以单手握着射击的枪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手枪", "is_correct": true, "explanation": "正确：“手枪射击”是一种体育项目。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是球类运动，与“射击”不相干。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不涉及射击，与句意不合。"}, {"text": "冰球", "is_correct": false, "explanation": "搭配：“冰球”的动作是“射门”，不说“冰球射击”。"}], "explanations": {"手枪": "正确：“手枪射击”是一种体育项目。", "足球": "语义：足球是球类运动，与“射击”不相干。", "游泳": "语义：游泳不涉及射击，与句意不合。", "冰球": "搭配：“冰球”的动作是“射门”，不说“冰球射击”。"}, "sentence_index": 0, "correct_answer": "手枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他扛着手枪走进了树林。", "explanation": "这里应该用〈步枪〉。手枪枪身短，要单手握着，不能说“扛着”。"}, {"text": "这种手枪有两米长，要用双手才能端起来射击。", "explanation": "这里和定义矛盾。“手枪”枪身短，可以单手握着射击，“两米长”“双手端起来”的应该是〈步枪〉。"}, {"text": "他的桌上放着一台手枪。", "explanation": "这里的量词错误：手枪应该用“把”或“支”，“台”用于机器或电器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手枪", "is_correct": true, "explanation": "正确：“一把一百年前的手枪”可以作为博物馆里的展品。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：河流的量词是“条”，不说“一把河流”。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：夜空不能作为展品放在博物馆里，与句意矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不能放在博物馆里作为一件展品，与句意矛盾。"}], "explanations": {"手枪": "正确：“一把一百年前的手枪”可以作为博物馆里的展品。", "河流": "搭配：河流的量词是“条”，不说“一把河流”。", "夜空": "语义：夜空不能作为展品放在博物馆里，与句意矛盾。", "城市": "语义：城市不能放在博物馆里作为一件展品，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "手枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "战士们每天都练习用手枪炸碉堡。", "explanation": "这里应该用〈手榴弹〉。手枪是用来射击的，不能用来炸碉堡。"}, {"text": "战士们每天都练习用一块手枪。", "explanation": "这里的量词错误：手枪应该用“把”或“支”，不能用“块”。"}, {"text": "战士们每天都练习用手枪击毁坦克。", "explanation": "这里应该用〈反坦克炮〉。手枪威力和射程都有限，不能用来击毁坦克，与“手枪”的用途不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经学会用手枪射击着了。", "corrected_sentence": "他已经学会用手枪射击了。", "error_description": "体标错误：“射击”后不能再加“着”表示完成，这里只用“了”。正确说法是“学会用手枪射击了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只手枪，子弹却不够。", "corrected_sentence": "他有一把手枪，子弹却不够。", "error_description": "量词错误：“只”不用于手枪，应改为“把”。正确说法是“一把手枪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
