INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98373, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打工是替别人做事，挣一些钱。", "primary_collocate": null, "pronunciation": "dǎ gōng", "ipa": "ta˨˩˦ kʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "我周末去饭店打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放假的时候在超市打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在咖啡店打工，每月挣一点钱。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生常常利用假期去打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想打工挣点零花钱。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他白天上课，晚上打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在商店打工，帮老板卖东西。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪儿打工？", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我在朋友的店里打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打工挣的钱，买了一台电脑。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打过工", "label": "体标"}, {"form": "打工族", "label": "复合"}, {"form": "打工仔", "label": "复合"}], "register": "口语", "sense_fingerprint": "利用课余或假期时间替别人做事，挣一点零用钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98373, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打工", "is_correct": true, "explanation": "打工：替别人做事、挣报酬，是本词。"}, {"text": "大功", "is_correct": false, "explanation": "大功 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是大功劳。"}, {"text": "大公", "is_correct": false, "explanation": "大公 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声），意思是公正无私。"}, {"text": "大工", "is_correct": false, "explanation": "大工 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是有技术的工人（与“小工”相对）。"}], "explanations": {"打工": "打工：替别人做事、挣报酬，是本词。", "大功": "大功 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是大功劳。", "大公": "大公 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声），意思是公正无私。", "大工": "大工 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是有技术的工人（与“小工”相对）。"}, "sentence_index": null, "correct_answer": "打工"}, "level_3": {"options": [{"text": "打工", "is_correct": true, "explanation": "打工指替饭店做事挣钱，与“去饭店”的语境吻合。"}, {"text": "上课", "is_correct": false, "explanation": "语义：饭店不是上课的地方，与“去饭店”的场所不相容。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：饭店里一般不能游泳，与“去饭店”的场所不相容。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“去饭店考试”的场所与事件不相容，句子不成立。"}], "explanations": {"打工": "打工指替饭店做事挣钱，与“去饭店”的语境吻合。", "上课": "语义：饭店不是上课的地方，与“去饭店”的场所不相容。", "游泳": "语义：饭店里一般不能游泳，与“去饭店”的场所不相容。", "考试": "语义：“去饭店考试”的场所与事件不相容，句子不成立。"}, "sentence_index": 0, "correct_answer": "打工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末他去寺庙打工，只是来参观游览。", "explanation": "这里应该用〈参观〉。打工指替别人做事挣报酬，来寺庙参观游览不属于这种情况。"}, {"text": "他毕业后去部队打工，每月领工资。", "explanation": "这里应该用〈当兵〉。打工指在企业或商店替人做事挣钱，服兵役不说打工。"}, {"text": "周末他在家里打工，帮妈妈洗碗、拖地。", "explanation": "这里应该用〈做家务〉。打工指替别人做事、拿报酬，在家帮妈妈做家务不拿钱，不能说打工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打工", "is_correct": true, "explanation": "打工与“帮老板卖东西”的语境一致，指在商店替老板干活。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“在商店睡觉”与后半句“帮老板卖东西”矛盾，无法成立。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：商店里不能游泳，与“在商店”的场所不相容，也与后半句矛盾。"}, {"text": "出席", "is_correct": false, "explanation": "语域：“出席”是书面语，用在口语叙述中不自然，也与“卖东西”的语境不符。"}], "explanations": {"打工": "打工与“帮老板卖东西”的语境一致，指在商店替老板干活。", "睡觉": "语义：“在商店睡觉”与后半句“帮老板卖东西”矛盾，无法成立。", "游泳": "语义：商店里不能游泳，与“在商店”的场所不相容，也与后半句矛盾。", "出席": "语域：“出席”是书面语，用在口语叙述中不自然，也与“卖东西”的语境不符。"}, "sentence_index": 6, "correct_answer": "打工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去海边打工，玩得很开心。", "explanation": "这里应该用〈旅游〉。打工指替别人做事挣报酬，去海边玩不能说打工。"}, {"text": "他在银行门口打工，排了一个小时。", "explanation": "这里应该用〈排队〉。打工指替别人做事挣钱，在银行门口等候不属于这种情况。"}, {"text": "他每天去医院打工，其实只是去看望朋友。", "explanation": "这里应该用〈看望〉。打工指替别人做事挣钱，去医院探望朋友不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晚上超市打工。", "corrected_sentence": "他晚上在超市打工。", "error_description": "错误在“在”：“在超市”表示动作发生的地点，“在”不能省，应说“在超市打工”，不能说“超市打工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他大学时打工过，挣了不少钱。", "corrected_sentence": "他大学时打过工，挣了不少钱。", "error_description": "错误在“过”的位置：“打工”是离合词，动态助词“过”要插在“打”和“工”之间，应说“打过工”，不能说“打工过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
