INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受雇于人做工，换取报酬。", "primary_collocate": null, "pronunciation": "dǎ gōng", "ipa": "ta˨˩˦ kʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "他从农村来城里打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在工厂打工已经十年了。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人去大城市打工。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给一家公司打工，每月拿工资。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想给别人打工，想自己开店。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在外地打工，过年才回家。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打工的人每个月都有工资。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打工养活一家人。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在建筑工地打工，非常辛苦。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去他在北京打工，现在回老家了。", "target_word": "打工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打过工", "label": "体标"}, {"form": "打工族", "label": "复合"}, {"form": "打工仔", "label": "复合"}], "register": "口语", "sense_fingerprint": "被雇用做工，靠劳动换取工资，常指外出谋生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打工", "is_correct": true, "explanation": "打工：受雇于人做工，换取报酬，是本词。"}, {"text": "大功", "is_correct": false, "explanation": "大功 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是大功劳。"}, {"text": "大公", "is_correct": false, "explanation": "大公 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声），意思是公正无私。"}, {"text": "大工", "is_correct": false, "explanation": "大工 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是有技术的工人（与“小工”相对）。"}], "explanations": {"打工": "打工：受雇于人做工，换取报酬，是本词。", "大功": "大功 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是大功劳。", "大公": "大公 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声），意思是公正无私。", "大工": "大工 dàgōng 与 dǎgōng 第一个音节声调不同（dà 第四声，dǎ 第三声），意思是有技术的工人（与“小工”相对）。"}, "sentence_index": null, "correct_answer": "打工"}, "level_3": {"options": [{"text": "打工", "is_correct": true, "explanation": "打工指外出替别人做事挣钱，与“从农村来城里”的语境吻合。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“城里”指国内的城市，与“出国”的意思矛盾，句子不成立。"}, {"text": "放羊", "is_correct": false, "explanation": "语义：放羊要在草原或农村进行，与“来城里”的场景不相容。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“从农村来城里”的语境不相容，句子不成立。"}], "explanations": {"打工": "打工指外出替别人做事挣钱，与“从农村来城里”的语境吻合。", "出国": "语义：“城里”指国内的城市，与“出国”的意思矛盾，句子不成立。", "放羊": "语义：放羊要在草原或农村进行，与“来城里”的场景不相容。", "睡觉": "语义：“睡觉”与“从农村来城里”的语境不相容，句子不成立。"}, "sentence_index": 0, "correct_answer": "打工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在家里打工，每天给自己做饭，不拿钱。", "explanation": "这里不能用〈打工〉。打工指有报酬的劳动，在自己家里做事不拿钱，应说〈做家务〉。"}, {"text": "周末我去爷爷家打工，只是陪爷爷下棋。", "explanation": "这里不能用〈打工〉。打工指替别人做事挣报酬，陪爷爷下棋是家人之间的陪伴，不属于这种情况，应说〈陪伴〉。"}, {"text": "暑假我们去北京打工，玩得很开心。", "explanation": "这里应该用〈旅游〉。打工指替别人做事挣报酬，去北京玩要说旅游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打工", "is_correct": true, "explanation": "“打工的人”指替别人做事挣工资的人，与“每个月都有工资”一致。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉的人一般不领工资，与后半句“每个月都有工资”矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“发呆”与“工资”不搭配，“发呆的人每个月都有工资”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是休闲活动，与“每个月都有工资”的劳动报酬语境不符。"}], "explanations": {"打工": "“打工的人”指替别人做事挣工资的人，与“每个月都有工资”一致。", "睡觉": "语义：睡觉的人一般不领工资，与后半句“每个月都有工资”矛盾。", "发呆": "搭配：“发呆”与“工资”不搭配，“发呆的人每个月都有工资”说不通。", "散步": "语义：散步是休闲活动，与“每个月都有工资”的劳动报酬语境不符。"}, "sentence_index": 6, "correct_answer": "打工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子昨天发烧了，在家打工了一天。", "explanation": "这里应该用〈休息〉。打工指受雇于人做工挣工资，孩子发烧在家休息不属于这种情况。"}, {"text": "他毕业后去部队打工，每月领工资。", "explanation": "这里应该用〈当兵〉。打工指在企业或商店替人做事挣钱，服兵役不说打工。"}, {"text": "他每天去公园打工，只是跑步锻炼身体。", "explanation": "这里应该用〈锻炼〉。打工指替别人做事挣钱，跑步锻炼身体不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年城里打工，很辛苦。", "corrected_sentence": "他去年在城里打工，很辛苦。", "error_description": "错误在“在”：“在城里”表示动作发生的地点，“在”不能省，应说“在城里打工”，不能说“城里打工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对一家餐厅打工，每天工作八小时。", "corrected_sentence": "他给一家餐厅打工，每天工作八小时。", "error_description": "错误在介词：“对”不能表示替某个单位做事，应说“给一家餐厅打工”（口语常用“给”，书面可用“为”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
