INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把式是很会做某件事的人，做得又快又好。", "primary_collocate": null, "pronunciation": "bǎ shi", "ipa": "pa˨˩ ʂʅ", "syllable_count": 2, "sentences": [{"text": "他种菜种得又快又好，是村里的把式。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张是修车的把式，什么车都能修好。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干农活他是把式，一天能割两亩麦子。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拜这位把式为师，学做木工。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是做饭的把式，十分钟就做好四个菜。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都说，她是织布的把式。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别看他年轻，修电视可是把式。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个把式修了一辈子鞋，又快又结实。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是剪头发的把式，一会儿就剪好了。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要盖房子，就得请个有经验的把式来。", "target_word": "把式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个把式", "label": "量词"}, {"form": "老把式", "label": "复合"}, {"form": "庄稼把式", "label": "复合"}], "register": "口语", "sense_fingerprint": "很会做某件事、做得又快又好的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "司机", "is_correct": false, "explanation": "语义：「司机」指驾驶车辆的人，与「种菜种得又快又好」的技能无关，句意不合。"}, {"text": "把式", "is_correct": true, "explanation": "把式指擅长某种劳动或技艺的人，与“种菜种得又快又好”的意思相符。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”形容体型，与“种菜种得又快又好”的能力无关。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：「裁缝」指做衣服的人，与「种菜种得又快又好」的技能无关，句意不合。"}], "explanations": {"司机": "语义：「司机」指驾驶车辆的人，与「种菜种得又快又好」的技能无关，句意不合。", "把式": "把式指擅长某种劳动或技艺的人，与“种菜种得又快又好”的意思相符。", "胖子": "体貌：“胖子”形容体型，与“种菜种得又快又好”的能力无关。", "裁缝": "语义：「裁缝」指做衣服的人，与「种菜种得又快又好」的技能无关，句意不合。"}, "sentence_index": 0, "correct_answer": "把式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做的木工活又慢又粗糙，是有名的把式。", "explanation": "这里应该用〈生手〉。把式指做得又快又好的能手，木工活又慢又粗糙的只能算〈生手〉。"}, {"text": "他耕地一天只能翻一小块，是村里的把式。", "explanation": "这里应该用〈生手〉。把式指做得又快又好的能手，耕地一天只能翻一小块的只能算〈生手〉。"}, {"text": "他修的收音机三天两头坏，是修收音机的把式。", "explanation": "这里应该用〈生手〉。把式指做得又快又好的能手，修出的收音机三天两头坏只能算〈生手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老人", "is_correct": false, "explanation": "语义：“老人”与前句“别看他年轻”的语意相反，逻辑不通。"}, {"text": "把式", "is_correct": true, "explanation": "把式指擅长修理等技艺的人，与“修电视可是把式”的意思相符。"}, {"text": "教授", "is_correct": false, "explanation": "语义：“教授”是学术职称，与修电视的技能无关。"}, {"text": "学者", "is_correct": false, "explanation": "语域：“学者”是书面语，与口语化的“修电视可是把式”不合。"}], "explanations": {"老人": "语义：“老人”与前句“别看他年轻”的语意相反，逻辑不通。", "把式": "把式指擅长修理等技艺的人，与“修电视可是把式”的意思相符。", "教授": "语义：“教授”是学术职称，与修电视的技能无关。", "学者": "语域：“学者”是书面语，与口语化的“修电视可是把式”不合。"}, "sentence_index": 6, "correct_answer": "把式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他修一台电视要磨蹭一下午，是修电视的把式。", "explanation": "这里应该用〈生手〉。把式指做得又快又好的能手，修一台电视要磨蹭一下午的只能算〈生手〉。"}, {"text": "他修鞋总要拖上两三天，是修鞋的把式。", "explanation": "这里应该用〈慢性子〉。把式指做得又快又好的能手，修鞋要拖两三天的人不能称把式。"}, {"text": "他做一张板凳要花整整一个月，是做木工的把式。", "explanation": "这里应该用〈生手〉。把式指做得又快又好的能手，做一张板凳要花一个月的只能算〈生手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只把式，干活又快又好。", "corrected_sentence": "他是一个把式，干活又快又好。", "error_description": "量词错误：把式指人，应用“个”，不能用“只”（“只”多用于动物）。应改为“一个把式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里修电视把式就是他。", "corrected_sentence": "村里修电视的把式就是他。", "error_description": "漏了“的”：修饰名词的动词短语后面要加“的”，应说“修电视的把式”，不说“修电视把式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
