INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98389, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拉新是想办法让新的人来用某个东西。", "primary_collocate": null, "pronunciation": "lā xīn", "ipa": "la˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这个软件最近在拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友为了拉新，送我一个红包。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏公司常用红包来拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用靠送礼物拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在朋友圈发链接拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了拉新，这个软件免费送会员。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的任务是拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款游戏想拉新，所以改了画面。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老用户带朋友来玩，就是拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学校门口发传单拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "想办法让新的人来用软件、游戏等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拉新", "is_correct": true, "explanation": "正确。“拉新”指想办法让新用户来用软件，与“软件最近在做推广”的语境相符。"}, {"text": "骑马", "is_correct": false, "explanation": "语义：软件不会骑马，“骑马”的主语须是人或动物。"}, {"text": "种树", "is_correct": false, "explanation": "语义：软件不会种树，“种树”的主语须是人。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：软件不吃饭，与“软件”作主语不搭。"}], "explanations": {"拉新": "正确。“拉新”指想办法让新用户来用软件，与“软件最近在做推广”的语境相符。", "骑马": "语义：软件不会骑马，“骑马”的主语须是人或动物。", "种树": "语义：软件不会种树，“种树”的主语须是人。", "吃饭": "语义：软件不吃饭，与“软件”作主语不搭。"}, "sentence_index": 0, "correct_answer": "拉新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司今年拉新了三名程序员。", "explanation": "这里应该用〈招聘〉。“拉新”指吸引新用户、新客户加入，招人要用“招聘”，不能用“拉新”。"}, {"text": "我们要拉新老用户，防止他们离开。", "explanation": "这里应该用〈挽留〉。“拉新”指吸引新用户加入，留住已有的老用户要用“挽留”，两者语义相反。"}, {"text": "出租车司机在车站拉新。", "explanation": "这里应该用〈拉客〉。“拉新”用于吸引新用户加入产品或服务，司机在车站招揽乘客要说“拉客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拉新", "is_correct": true, "explanation": "正确。“拉新”指吸引新用户，与“小组的任务”相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“任务”指要完成的事，不能说“任务是咳嗽”。"}, {"text": "生孩子", "is_correct": false, "explanation": "语义：小组的任务不能是生孩子。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：任务不指洗澡这类个人活动。"}], "explanations": {"拉新": "正确。“拉新”指吸引新用户，与“小组的任务”相符。", "咳嗽": "搭配：“任务”指要完成的事，不能说“任务是咳嗽”。", "生孩子": "语义：小组的任务不能是生孩子。", "洗澡": "语义：任务不指洗澡这类个人活动。"}, "sentence_index": 6, "correct_answer": "拉新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司去年拉新了一座写字楼。", "explanation": "这里应该用〈购置〉。“拉新”指吸引新用户、新客户加入，写字楼不是用户，买下它要说“购置”。"}, {"text": "他们拉新了一个孩子。", "explanation": "这里应该用〈收养〉。“拉新”指让新用户、新客户加入产品或服务，收养孩子要说“收养”。"}, {"text": "他把旧衣服拉新了。", "explanation": "这里应该用〈翻新〉。“拉新”指吸引新用户加入，把旧东西弄得像新的一样要说“翻新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件去年拉新了了一批用户。", "corrected_sentence": "这个软件去年拉新了一批用户。", "error_description": "错误：“拉新了了一批用户”。正确：“拉新了一批用户”。“了”重复出现，同一个动词后只用一个“了”，应去掉一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店这几周一直在拉新着。", "corrected_sentence": "这家店这几周一直在拉新。", "error_description": "错误：“一直在拉新着”。正确：“一直在拉新”。“着”表示持续状态，不能直接加在“拉新”这种动宾词后面，去掉“着”句子才自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
