INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吸引新用户、新客户加入。", "primary_collocate": null, "pronunciation": "lā xīn", "ipa": "la˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "公司今年的重点是拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行靠高利息来拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家健身房做活动拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台推出新人礼包来拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个月必须拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拉新比留住老客户更花钱。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电商平台的拉新成本越来越高。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责市场部的拉新工作。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保险公司用低价产品来拉新。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次拉新活动吸引了很多新客户。", "target_word": "拉新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "企业、平台吸引新用户或新客户加入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拉新", "is_correct": true, "explanation": "正确。“拉新”指吸引新用户、新客户加入，适合作为公司的重点工作。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：公司不会失眠，“失眠”不能作为公司的重点。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不是公司可以确定的重点。"}, {"text": "扔掉", "is_correct": false, "explanation": "配价：“扔掉”是及物动词，必须带受事宾语，“是”后没有宾语，句子不完整。"}], "explanations": {"拉新": "正确。“拉新”指吸引新用户、新客户加入，适合作为公司的重点工作。", "失眠": "语义：公司不会失眠，“失眠”不能作为公司的重点。", "下雨": "语义：下雨是天气现象，不是公司可以确定的重点。", "扔掉": "配价：“扔掉”是及物动词，必须带受事宾语，“是”后没有宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "拉新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司今年拉新了海外市场。", "explanation": "这里应该用〈开拓〉。“拉新”指吸引新用户、新客户加入，开辟新的市场要说“开拓”。"}, {"text": "这家店想拉新老会员。", "explanation": "这里应该用〈挽留〉。“拉新”指吸引新会员，留住老会员要用“挽留”，两者方向相反。"}, {"text": "公司今年要拉新十名工程师。", "explanation": "这里应该用〈招聘〉。“拉新”针对的是新用户、新客户，招工程师要用“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拉新", "is_correct": true, "explanation": "正确。“拉新成本”指吸引新用户所花的费用，与“电商平台”的语境相符。"}, {"text": "养老", "is_correct": false, "explanation": "语义：电商平台不能养老，“养老”的对象是老年人。"}, {"text": "生病", "is_correct": false, "explanation": "语义：平台不会生病，“生病”的主语须是人或动物。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”指人的身体变胖，不能用于描述平台的成本。"}], "explanations": {"拉新": "正确。“拉新成本”指吸引新用户所花的费用，与“电商平台”的语境相符。", "养老": "语义：电商平台不能养老，“养老”的对象是老年人。", "生病": "语义：平台不会生病，“生病”的主语须是人或动物。", "发胖": "体貌：“发胖”指人的身体变胖，不能用于描述平台的成本。"}, "sentence_index": 6, "correct_answer": "拉新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校拉新了一位院长。", "explanation": "这里应该用〈聘请〉。“拉新”指吸引新用户、新客户加入，请人担任职务要说“聘请”。"}, {"text": "工人把老房子拉新了。", "explanation": "这里应该用〈翻新〉。“拉新”指吸引新用户、新客户加入，把旧房子修得像新的要说“翻新”。"}, {"text": "老板拉新了十件优质商品。", "explanation": "这里应该用〈挑选〉。“拉新”指吸引新用户、新客户加入，从众多商品中选出好的要说“挑选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "平台今年一直在拉新着用户。", "corrected_sentence": "平台今年一直在拉新用户。", "error_description": "错误：“拉新着用户”。正确：“一直在拉新用户”。“着”不能插在“拉新”和宾语“用户”之间，持续态的“着”不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平台去年拉新了了一百万名用户。", "corrected_sentence": "平台去年拉新了一百万名用户。", "error_description": "错误：“拉新了了一百万名用户”。正确：“拉新了一百万名用户”。“了”重复出现，同一个动词后只用一个“了”，应去掉一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
