INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招标是想要做事的人先告诉大家，请别人来说自己愿意花多少钱做。", "primary_collocate": null, "pronunciation": "zhāo biāo", "ipa": "ʈʂaʊ˥ piaʊ˥", "syllable_count": 2, "sentences": [{"text": "学校打算给新楼招标。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府要为新桥招标。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经招标了，下周看结果。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院想盖一座新楼，所以先招标。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路要先招标，再选公司。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里想修路，明天开始招标。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们计划在网上招标。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为新地铁招标，很多公司都来报价。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司去年招标过一个大工程。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校招标装修食堂，价格最低的公司得到了机会。", "target_word": "招标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招标了", "label": "完成体（了）"}, {"form": "招标过", "label": "经历体（过）"}, {"form": "招标会", "label": "复合词"}, {"form": "招标书", "label": "复合词"}], "register": "正式", "sense_fingerprint": "公开征求报价以承包工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点名", "is_correct": false, "explanation": "语义：“点名”是核对人员，不能用来指给新楼做事。"}, {"text": "招标", "is_correct": true, "explanation": "正确：先公开发布条件、请别人报价，与“打算给新楼”的做法相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是生病，“给新楼感冒”说不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，“给新楼毕业”说不通。"}], "explanations": {"点名": "语义：“点名”是核对人员，不能用来指给新楼做事。", "招标": "正确：先公开发布条件、请别人报价，与“打算给新楼”的做法相符。", "感冒": "语义：“感冒”是生病，“给新楼感冒”说不通。", "毕业": "语义：“毕业”指学生完成学业，“给新楼毕业”说不通。"}, "sentence_index": 0, "correct_answer": "招标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几家公司都想招标，竞争很激烈。", "explanation": "这里应该用〈投标〉。“招标”是发包方发布条件，想报价的公司应“投标”。"}, {"text": "公司很缺人，就去网上招标一下。", "explanation": "这里应该用〈招聘〉。“招标”是挑选承办者，不能用来招人。"}, {"text": "他们为了拿到合同，纷纷招标。", "explanation": "这里应该用〈报价〉。为了拿合同而竞争报价的是承包方，“招标”是发包方发起的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：“散步”是走路，不能在网上进行。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”要在浴室等地方进行，不能和“在网上”搭配。"}, {"text": "种树", "is_correct": false, "explanation": "语义：“种树”指栽种植物，不能在网上进行。"}, {"text": "招标", "is_correct": true, "explanation": "正确：指在网上公开发布条件、征集报价，与“计划”相符。"}], "explanations": {"散步": "语义：“散步”是走路，不能在网上进行。", "洗澡": "搭配：“洗澡”要在浴室等地方进行，不能和“在网上”搭配。", "种树": "语义：“种树”指栽种植物，不能在网上进行。", "招标": "正确：指在网上公开发布条件、征集报价，与“计划”相符。"}, "sentence_index": 6, "correct_answer": "招标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司想招标，希望拿到这个工程。", "explanation": "这里应该用〈投标〉。想拿到工程的公司是去“投标”；“招标”是发包方请别人报价。"}, {"text": "饭店缺服务员，老板在门口招标。", "explanation": "这里应该用〈招聘〉。招人工作是“招聘”；“招标”是请别人报价做工程。"}, {"text": "他把家里的旧画拿去招标，卖了很多钱。", "explanation": "这里应该用〈拍卖〉。出价高的人买走东西是“拍卖”；“招标”是请人报价来做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校决定新楼的工程招标。", "corrected_sentence": "学校决定为新楼的工程招标。", "error_description": "错误：缺少介词“为”。“招标”的对象要用“为……”引出，放在“招标”前面。正确：“学校决定为新楼的工程招标”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司去年招标着，效果很好。", "corrected_sentence": "我们公司去年招标了，效果很好。", "error_description": "错误：“着”表示动作的持续，不能与“去年”这种已完成的时间搭配。正确：“招标了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
