INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拜访是去别人家里看望他。", "primary_collocate": null, "pronunciation": "bài fǎng", "ipa": "pai˥˩ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "周末我想去拜访王老师。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着水果去拜访朋友。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天拜访了一位老同学。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们要拜访亲戚。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想什么时候来拜访我们？", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有拜访过他家。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都去拜访邻居。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去拜访别人以前，最好先打电话。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生下午要来家里拜访爷爷。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拜访了住在乡下的奶奶。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜访了", "label": "体标"}, {"form": "拜访过", "label": "体标"}, {"form": "拜访者", "label": "复合"}], "register": "正式", "sense_fingerprint": "去别人家里看望某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拜访", "is_correct": true, "explanation": "拜访：去别人家里看望、拜见，与“周末我想去”和“王老师”（人）相合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“参观王老师”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或话题，不能说“讨论王老师”。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：“瞻仰”是书面庄重用语，多用于遗迹、伟人，用来指普通老师不合语境。"}], "explanations": {"拜访": "拜访：去别人家里看望、拜见，与“周末我想去”和“王老师”（人）相合。", "参观": "搭配：“参观”的对象是场所或展览，不能说“参观王老师”。", "讨论": "搭配：“讨论”的对象是问题或话题，不能说“讨论王老师”。", "瞻仰": "语域：“瞻仰”是书面庄重用语，多用于遗迹、伟人，用来指普通老师不合语境。"}, "sentence_index": 0, "correct_answer": "拜访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个暑假我们拜访了故宫。", "explanation": "这里应该用〈参观〉。拜访的对象是人，故宫是名胜，应说参观。"}, {"text": "周末我拜访了那部电影。", "explanation": "这里应该用〈看〉。拜访的对象是人，电影要用看。"}, {"text": "我每周末都打电话拜访奶奶。", "explanation": "这里应该用〈问候〉。拜访要求亲自上门或到场，不能靠打电话进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拜访", "is_correct": true, "explanation": "拜访：去邻居家上门见面，与“每个月都去”相合。"}, {"text": "浏览", "is_correct": false, "explanation": "搭配：“浏览”的对象是网页、书刊，不能说“浏览邻居”。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”是为离去的人送行，是一次性的，与“每个月都去”不合。"}, {"text": "接见", "is_correct": false, "explanation": "语义：“接见”是接待来访者的一方所为，此处说“去”不合。"}], "explanations": {"拜访": "拜访：去邻居家上门见面，与“每个月都去”相合。", "浏览": "搭配：“浏览”的对象是网页、书刊，不能说“浏览邻居”。", "欢送": "语义：“欢送”是为离去的人送行，是一次性的，与“每个月都去”不合。", "接见": "语义：“接见”是接待来访者的一方所为，此处说“去”不合。"}, "sentence_index": 6, "correct_answer": "拜访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去陵园拜访了烈士。", "explanation": "这里应该用〈拜谒〉。拜访的对象是在世的人，烈士已故，去陵园要用拜谒。"}, {"text": "他拜访了很多国家。", "explanation": "这里应该用〈访问〉。拜访指到某人或某单位去见面，国家之间的正式访问不用拜访。"}, {"text": "我常去拜访那家超市。", "explanation": "这里应该用〈光顾〉。拜访的对象是人，超市这类商店要用光顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从来没有拜访了那位老校长。", "corrected_sentence": "我们从来没有拜访过那位老校长。", "error_description": "错误在于“没有”与“了”的搭配：否定已发生的经历要用“拜访过”，不能说“没有拜访了”。应改为“没有拜访过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天拜访了同事。", "corrected_sentence": "他明天拜访同事。", "error_description": "错误在于“了”：“拜访了”表示已完成，与“明天”的将来时间矛盾。应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
