INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98394, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "访问；前去看望别人。", "primary_collocate": null, "pronunciation": "bài fǎng", "ipa": "pai˥˩ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "王经理明天要去拜访一位客户。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长拜访了几位老教授。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司派人拜访了新的客户。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他特意去北京拜访那位作家。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者拜访了这位有名的医生。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很高兴能拜访您。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备拜访几家公司，了解情况。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拜访过很多国家的朋友。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生经常拜访老师。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先打电话，再去拜访张老师。", "target_word": "拜访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜访了", "label": "体标"}, {"form": "拜访过", "label": "体标"}, {"form": "拜访者", "label": "复合"}], "register": "正式", "sense_fingerprint": "正式地前去访问、看望他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拜访", "is_correct": true, "explanation": "拜访：去客户单位见面，与“王经理明天要去”和“一位客户”相合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“参观一位客户”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或话题，不能说“讨论一位客户”。"}, {"text": "拜谒", "is_correct": false, "explanation": "语域：“拜谒”是书面敬语，指拜见尊长或瞻仰陵墓，用于商务客户不合。"}], "explanations": {"拜访": "拜访：去客户单位见面，与“王经理明天要去”和“一位客户”相合。", "参观": "搭配：“参观”的对象是场所或展览，不能说“参观一位客户”。", "讨论": "搭配：“讨论”的对象是问题或话题，不能说“讨论一位客户”。", "拜谒": "语域：“拜谒”是书面敬语，指拜见尊长或瞻仰陵墓，用于商务客户不合。"}, "sentence_index": 0, "correct_answer": "拜访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他特意去北京拜访故宫。", "explanation": "这里应该用〈参观〉。拜访的对象是人，故宫是名胜，应说参观。"}, {"text": "我每天都发消息拜访老师。", "explanation": "这里应该用〈问候〉。拜访要求亲自到场，发消息只能问候，不能用拜访。"}, {"text": "他去墓地拜访了祖先。", "explanation": "这里应该用〈拜谒〉。拜访的对象是在世的人，向已故的祖先致敬要用拜谒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拜访", "is_correct": true, "explanation": "拜访：上门见面了解情况，与“准备”和“几家公司”相合。"}, {"text": "浏览", "is_correct": false, "explanation": "搭配：“浏览”的对象是网页、资料，不能说“浏览几家公司”。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：“欢送”的对象是离开的人，不能说“欢送几家公司”。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：“瞻仰”是书面庄重用语，多用于遗迹、伟人，与商务考察的语境不合。"}], "explanations": {"拜访": "拜访：上门见面了解情况，与“准备”和“几家公司”相合。", "浏览": "搭配：“浏览”的对象是网页、资料，不能说“浏览几家公司”。", "欢送": "搭配：“欢送”的对象是离开的人，不能说“欢送几家公司”。", "瞻仰": "语域：“瞻仰”是书面庄重用语，多用于遗迹、伟人，与商务考察的语境不合。"}, "sentence_index": 6, "correct_answer": "拜访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常去拜访那家饭馆。", "explanation": "这里应该用〈光顾〉。拜访的对象是人，饭馆这类商店要用光顾。"}, {"text": "周末我拜访了那本小说。", "explanation": "这里应该用〈读〉。拜访的对象是人，看书要用读，不能拜访书。"}, {"text": "我拜访了这个问题。", "explanation": "这里应该用〈研究〉。拜访的对象是人，问题要用研究，不能拜访问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周要去拜访了一位老客户。", "corrected_sentence": "我下周要去拜访一位老客户。", "error_description": "错误在于“了”：“下周”指将来，句中用“了”表示已完成，与时间矛盾。应删去“了”，说“要去拜访一位老客户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她明天拜访了几位老教授。", "corrected_sentence": "她明天拜访几位老教授。", "error_description": "错误在于“了”：“拜访了”表示已完成，与“明天”的将来时间矛盾。应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
