INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98395, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挂牌是把牌子挂起来，告诉大家这里开始做事了。", "primary_collocate": null, "pronunciation": "guà pái", "ipa": "kua˥˩ pʰai˧˥", "syllable_count": 2, "sentences": [{"text": "新开的小店明天上午挂牌。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家楼下的诊所昨天挂牌了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的律师事务所下个月就要挂牌了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一挂牌，朋友们都来送花。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的咖啡店终于挂牌了，门口有很多花。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学校挂牌那天，校长讲了几句话。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的饭馆今天挂牌，我去帮忙。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作室挂牌以后，每天都有客人来。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院什么时候挂牌？", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租了一间房，准备下周挂牌营业。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挂了牌", "label": "体标（了）"}, {"form": "挂过牌", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把牌子挂在门口，表示店铺、诊所等开始做事、开业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挂牌", "is_correct": true, "explanation": "正确：挂牌表示小店挂出牌子、开始营业，与“新开的小店”相符。"}, {"text": "搬走", "is_correct": false, "explanation": "语义：“新开的”小店刚开业就“搬走”，与“新开”矛盾。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校、班级，不能说小店开学。"}, {"text": "退房", "is_correct": false, "explanation": "搭配：“退房”只用于住宿场所，小店不能退房。"}], "explanations": {"挂牌": "正确：挂牌表示小店挂出牌子、开始营业，与“新开的小店”相符。", "搬走": "语义：“新开的”小店刚开业就“搬走”，与“新开”矛盾。", "开学": "搭配：“开学”只用于学校、班级，不能说小店开学。", "退房": "搭配：“退房”只用于住宿场所，小店不能退房。"}, "sentence_index": 0, "correct_answer": "挂牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天去医院挂牌看病。", "explanation": "这里应该用〈挂号〉。挂牌指悬挂牌子表示开业，在医院登记看病要说挂号。"}, {"text": "墙上挂牌了一张照片。", "explanation": "这里应该用〈挂〉。挂牌特指把牌子挂出来表示开业，挂照片只用“挂”。"}, {"text": "他的生日聚会下周挂牌。", "explanation": "这里应该用〈举行〉。挂牌指店铺、机构挂出牌子开始营业，聚会要说“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挂牌", "is_correct": true, "explanation": "正确：挂牌即开始营业，符合“今天”与“我去帮忙”的语境。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，饭馆不能毕业。"}, {"text": "出院", "is_correct": false, "explanation": "搭配：“出院”只用于病人离开医院，不能用于饭馆。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”只用于人，不能说饭馆退休。"}], "explanations": {"挂牌": "正确：挂牌即开始营业，符合“今天”与“我去帮忙”的语境。", "毕业": "语义：“毕业”指学生完成学业，饭馆不能毕业。", "出院": "搭配：“出院”只用于病人离开医院，不能用于饭馆。", "退休": "搭配：“退休”只用于人，不能说饭馆退休。"}, "sentence_index": 6, "correct_answer": "挂牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场展览下周挂牌。", "explanation": "这里应该用〈开幕〉。挂牌用于店铺、机构开始营业，展览开始要说“开幕”。"}, {"text": "这条新地铁线路下周挂牌。", "explanation": "这里应该用〈开通〉。挂牌指机构、店铺开业，线路开始运行要说“开通”。"}, {"text": "这档节目下周挂牌。", "explanation": "这里应该用〈开播〉。挂牌指店铺、机构开始营业，节目开始播出要说“开播”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家新店明天挂过牌。", "corrected_sentence": "这家新店明天挂牌。", "error_description": "体标错误：“挂过牌”表示过去的经历，与表示将来的“明天”矛盾。应说“明天挂牌”，不加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭馆下周挂过牌营业。", "corrected_sentence": "这家饭馆下周挂牌营业。", "error_description": "体标错误：“挂过牌”表示过去曾经有过的经历，与表示将来的“下周”矛盾。应说“挂牌营业”，不加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
