INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "悬挂牌子，表示机构正式成立或开始营业。", "primary_collocate": null, "pronunciation": "guà pái", "ipa": "kua˥˩ pʰai˧˥", "syllable_count": 2, "sentences": [{"text": "市里的新图书馆今天正式挂牌。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究中心上个月挂牌成立了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司合并后，新公司明天挂牌。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校挂牌那天，很多家长都来了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新医院挂牌后，看病的人越来越多。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区里的社区中心终于挂牌了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站在门口，看工人给新单位挂牌。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行下周一正式挂牌营业。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的文化站什么时候挂牌？", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司挂牌以后，我们就有自己的办公室了。", "target_word": "挂牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挂了牌", "label": "体标（了）"}, {"form": "挂过牌", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "机构、单位悬挂牌子，表示正式成立或开始营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挂牌", "is_correct": true, "explanation": "正确：挂牌表示图书馆正式成立，与“正式”相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，图书馆不能毕业。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校、班级，不说图书馆开学。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”只用于人，不能说图书馆退休。"}], "explanations": {"挂牌": "正确：挂牌表示图书馆正式成立，与“正式”相符。", "毕业": "语义：“毕业”指学生完成学业，图书馆不能毕业。", "开学": "搭配：“开学”只用于学校、班级，不说图书馆开学。", "退休": "搭配：“退休”只用于人，不能说图书馆退休。"}, "sentence_index": 0, "correct_answer": "挂牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去医院挂牌看医生。", "explanation": "这里应该用〈挂号〉。挂牌指悬挂牌子表示机构成立，在医院登记看病要说挂号。"}, {"text": "市政府今天挂牌了新的政策。", "explanation": "这里应该用〈发布〉。挂牌指机构正式成立或开始营业，宣布政策要说“发布”。"}, {"text": "我们的婚礼下周挂牌。", "explanation": "这里应该用〈举行〉。挂牌指机构正式成立或开始营业，婚礼要说“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挂牌", "is_correct": true, "explanation": "正确：挂牌表示单位正式成立或开始营业，与“新单位”相符。"}, {"text": "退房", "is_correct": false, "explanation": "搭配：“退房”指离开酒店，不能对单位使用。"}, {"text": "出院", "is_correct": false, "explanation": "搭配：“出院”只用于病人离开医院，不能用于单位。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指学生去学校，单位不能上学。"}], "explanations": {"挂牌": "正确：挂牌表示单位正式成立或开始营业，与“新单位”相符。", "退房": "搭配：“退房”指离开酒店，不能对单位使用。", "出院": "搭配：“出院”只用于病人离开医院，不能用于单位。", "上学": "语义：“上学”指学生去学校，单位不能上学。"}, "sentence_index": 6, "correct_answer": "挂牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新节目下周挂牌。", "explanation": "这里应该用〈开播〉。挂牌用于机构正式成立或开始营业，节目开始播出要说“开播”。"}, {"text": "这条新地铁线下周挂牌。", "explanation": "这里应该用〈开通〉。挂牌指机构、店铺开业，线路开始运行要说“开通”。"}, {"text": "比赛下周挂牌。", "explanation": "这里应该用〈开赛〉。挂牌指机构、店铺正式开业，比赛开始要说“开赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校下个月挂过牌。", "corrected_sentence": "这所学校下个月挂牌。", "error_description": "体标错误：“挂过牌”表示过去的经历，与表示将来的“下个月”矛盾。应说“下个月挂牌”，不加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新公司下周挂过牌。", "corrected_sentence": "新公司下周挂牌。", "error_description": "体标错误：“挂过牌”表示曾经有过的经历，与表示将来的“下周”矛盾。应说“下周挂牌”，不加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
