INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98397, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拦截是把过来的东西挡住，不让它过去。", "primary_collocate": null, "pronunciation": "lán jié", "ipa": "lan˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "守门员拦截了对方的射门。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防守队员在空中拦截了传球。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防空系统成功拦截了那枚导弹。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会自动拦截垃圾短信。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳起来想拦截那个球，可是没有够到。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能拦截广告。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门将扑出去，拦截了那个远射。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防火墙拦截了可疑的网络访问。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把飞来的球拦截下来了。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会拦截对方的传球。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拦截了", "label": "体标（了）"}, {"form": "拦截过", "label": "体标（过）"}, {"form": "拦截器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "拦截：把飞来的球、导弹、信息等挡住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拦截", "is_correct": true, "explanation": "拦截：把飞来的射门挡住，使其不能进门，符合守门员扑救的情境。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：欢迎的对象是人或到来的客人，不能说欢迎射门。"}, {"text": "打听", "is_correct": false, "explanation": "语义：打听要获取消息，射门是动作，不能被打听。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销是把开支报给单位核销，与射门无关。"}], "explanations": {"拦截": "拦截：把飞来的射门挡住，使其不能进门，符合守门员扑救的情境。", "欢迎": "搭配：欢迎的对象是人或到来的客人，不能说欢迎射门。", "打听": "语义：打听要获取消息，射门是动作，不能被打听。", "报销": "语义：报销是把开支报给单位核销，与射门无关。"}, "sentence_index": 0, "correct_answer": "拦截"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把掉在地上的球拦截起来了。", "explanation": "这里应该用〈捡起〉。拦截指挡住飞来或经过的东西，地上的球没有在移动，不能用拦截。"}, {"text": "他拦截了对方的时间。", "explanation": "这里应该用〈浪费〉。拦截指挡住飞来或经过的东西，时间是抽象概念，不能被拦截。"}, {"text": "妈妈把睡着的婴儿拦截了。", "explanation": "这里应该用〈抱起〉。拦截指挡住正在过来或经过的东西，睡着的婴儿没有移动，不能说拦截。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拦截", "is_correct": true, "explanation": "拦截：挡住飞来的远射，使其不能进门，符合门将扑出去的动作。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭的对象是火或灯光，不能用于球。"}, {"text": "修建", "is_correct": false, "explanation": "语义：修建的对象是房屋、道路等建筑，远射不能被修建。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：拜访的对象是人，远射是球的动作，不能被拜访。"}], "explanations": {"拦截": "拦截：挡住飞来的远射，使其不能进门，符合门将扑出去的动作。", "熄灭": "搭配：熄灭的对象是火或灯光，不能用于球。", "修建": "语义：修建的对象是房屋、道路等建筑，远射不能被修建。", "拜访": "语义：拜访的对象是人，远射是球的动作，不能被拜访。"}, "sentence_index": 6, "correct_answer": "拦截"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很会拦截对方的感情。", "explanation": "这里应该用〈理解〉。拦截指挡住飞来或经过的具体事物，感情是抽象的心理状态，不能被拦截。"}, {"text": "他很会拦截对方的梦想。", "explanation": "这里应该用〈实现〉。拦截指挡住飞来或经过的具体事物，梦想是抽象目标，不能被拦截。"}, {"text": "他把对方的快乐拦截了。", "explanation": "这里应该用〈破坏〉。拦截指挡住飞来或经过的具体事物，快乐是抽象的感受，不能被拦截。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "守门员把那个传中的球拦截上来了。", "corrected_sentence": "守门员把那个传中的球拦截下来了。", "error_description": "「拦截上来」方向错误。拦截是把来的球挡住使其停下，应说「拦截下来」；「上来」表示向上移动，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在比赛中把那个球拦截了了。", "corrected_sentence": "他在比赛中把那个球拦截了。", "error_description": "体标重复：“了”只能用一个，“拦截了了”错误，应说“把那个球拦截了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放行", "is_correct": true, "explanation": "放行：允许通过，与拦截（半路阻拦使其不能通过）构成反义。"}, {"text": "放松", "is_correct": false, "explanation": "与拦截无反义关系：放松指使紧张的状态缓和，与阻拦无关。"}, {"text": "帮助", "is_correct": false, "explanation": "与拦截无反义关系：帮助是给予支援，与阻拦动作不构成对立。"}, {"text": "打扫", "is_correct": false, "explanation": "与拦截无反义关系：打扫是清除脏物，与阻拦无关。"}], "correct_answer": "放行", "explanations": {"放行": "放行：允许通过，与拦截（半路阻拦使其不能通过）构成反义。", "放松": "与拦截无反义关系：放松指使紧张的状态缓和，与阻拦无关。", "帮助": "与拦截无反义关系：帮助是给予支援，与阻拦动作不构成对立。", "打扫": "与拦截无反义关系：打扫是清除脏物，与阻拦无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放行", "is_correct": true, "explanation": "放行：允许通过，与拦截（半路阻拦使其不能通过）构成反义。"}, {"text": "清洗", "is_correct": false, "explanation": "与拦截无反义关系：清洗是把脏物弄干净，与阻拦无关。"}, {"text": "表扬", "is_correct": false, "explanation": "与拦截无反义关系：表扬是肯定和称赞，与阻拦不构成对立。"}, {"text": "翻译", "is_correct": false, "explanation": "与拦截无反义关系：翻译是转换语言，与阻拦无关。"}], "correct_answer": "放行", "explanations": {"放行": "放行：允许通过，与拦截（半路阻拦使其不能通过）构成反义。", "清洗": "与拦截无反义关系：清洗是把脏物弄干净，与阻拦无关。", "表扬": "与拦截无反义关系：表扬是肯定和称赞，与阻拦不构成对立。", "翻译": "与拦截无反义关系：翻译是转换语言，与阻拦无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "中途阻拦，使不能通过。", "primary_collocate": null, "pronunciation": "lán jié", "ipa": "lan˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "警察在路口拦截了那辆可疑的车。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安在门口拦截了陌生人。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关拦截了一批走私的货物。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷想逃跑，路人拦截了他。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在路上拦截那位明星，想问几个问题。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边防人员拦截了几个偷渡的人。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在楼梯口拦截了迟到的学生。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在半路拦截了送信的人。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交警正在拦截超速的汽车。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察拦截过这辆车。", "target_word": "拦截", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拦截了", "label": "体标（了）"}, {"form": "拦截过", "label": "体标（过）"}, {"form": "拦截器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "拦截：在半路拦住人或车辆，不让通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拦截", "is_correct": true, "explanation": "拦截：在半路拦住车辆，使其不能通过，符合警察在路口执法的情境。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：欢迎的对象是人或客人，不能说欢迎一辆车。"}, {"text": "编织", "is_correct": false, "explanation": "语义：编织的是布、网等材料，车辆不能被编织。"}, {"text": "探望", "is_correct": false, "explanation": "搭配：探望的对象是人，不能用于车辆。"}], "explanations": {"拦截": "拦截：在半路拦住车辆，使其不能通过，符合警察在路口执法的情境。", "欢迎": "搭配：欢迎的对象是人或客人，不能说欢迎一辆车。", "编织": "语义：编织的是布、网等材料，车辆不能被编织。", "探望": "搭配：探望的对象是人，不能用于车辆。"}, "sentence_index": 0, "correct_answer": "拦截"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人拦截了那座桥。", "explanation": "这里应该用〈修好〉。拦截是中途阻拦正在经过的人或车，使其不能通过，桥是固定的建筑，不能被拦截。"}, {"text": "他拦截了一棵树。", "explanation": "这里应该用〈种〉。拦截是中途阻拦正在经过的人或车，使其不能通过，树是固定不动的，不能拦截。"}, {"text": "他很快拦截了这个道理。", "explanation": "这里应该用〈理解〉。拦截是中途阻拦正在经过的人或车，使其不能通过，道理是抽象的，不能被拦截。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拦截", "is_correct": true, "explanation": "拦截：在楼梯口拦住迟到的学生，使其不能继续往前走，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植的对象是植物，学生不能被种植。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：颁布的宾语是法令、规章，不能用于学生。"}, {"text": "修复", "is_correct": false, "explanation": "语义：修复的对象是物品或机能，学生不能被修复。"}], "explanations": {"拦截": "拦截：在楼梯口拦住迟到的学生，使其不能继续往前走，符合句意。", "种植": "语义：种植的对象是植物，学生不能被种植。", "颁布": "搭配：颁布的宾语是法令、规章，不能用于学生。", "修复": "语义：修复的对象是物品或机能，学生不能被修复。"}, "sentence_index": 6, "correct_answer": "拦截"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她拦截了一锅饭。", "explanation": "这里应该用〈煮〉。拦截是中途阻拦正在经过的人或车，使其不能通过，锅里的饭是静止的，不能被拦截。"}, {"text": "工人拦截过这座房子。", "explanation": "这里应该用〈粉刷〉。拦截是阻止人或车通过，房子不能被拦截；给房子刷漆应说“粉刷”。"}, {"text": "他拦截过这扇窗。", "explanation": "这里应该用〈擦〉。拦截是阻挡人或车通过，擦窗户时不能用拦截。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交警在高速路口把那辆超速的卡车拦截上来了。", "corrected_sentence": "交警在高速路口把那辆超速的卡车拦截下来了。", "error_description": "「拦截上来」方向错误。拦截是把车拦住使其停下，应说「拦截下来」；「上来」表示向上移动，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交警在高速路口把那辆超速的卡车拦截了了。", "corrected_sentence": "交警在高速路口把那辆超速的卡车拦截了。", "error_description": "体标重复：“了”只能用一个，“拦截了了”错误，应说“把那辆超速的卡车拦截了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱与攻没有反义关系，不是这个义项的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "跳与攻没有反义关系，不是这个义项的反义词。"}, {"text": "写", "is_correct": false, "explanation": "写与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "唱": "唱与攻没有反义关系，不是这个义项的反义词。", "跳": "跳与攻没有反义关系，不是这个义项的反义词。", "写": "写与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗与攻没有反义关系，不是这个义项的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃与攻没有反义关系，不是这个义项的反义词。"}, {"text": "画", "is_correct": false, "explanation": "画与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "洗": "洗与攻没有反义关系，不是这个义项的反义词。", "吃": "吃与攻没有反义关系，不是这个义项的反义词。", "画": "画与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "攻是冲过去打对方，想打赢。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "我们攻，你们守。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红队从左边攻，蓝队在右边守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上半场我们一直在攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别只会守，也要会攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们攻得很快，我们守不住。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队一拿到球，就马上攻对方的球门。", "target_word": "攻", "complexity_tier": "T3", "furigana": "wǒ men duì yī ná dào qiú jiù mǎ shàng gōng duì fāng de qiú mén", "sentence_source": "generated"}, {"text": "球队一直攻，可是没有进球。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方攻过来，我们马上往后退。", "target_word": "攻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，比赛时先守后攻最好。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里，我这一队从山上往下攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻了", "label": "体标"}, {"form": "攻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "比赛、游戏或战斗中主动冲向对方，想要取胜（与守相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指主动冲向对方进攻。"}, {"text": "刚", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献、进贡。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}], "explanations": {"攻": "攻 gōng，正确答案，指主动冲向对方进攻。", "刚": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。", "空": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献、进贡。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻是主动冲向对方，与「守」相对，句意通顺。"}, {"text": "写", "is_correct": false, "explanation": "语义：写不是比赛或战斗中的动作，「我们写，你们守」与攻守对立的句意不合。"}, {"text": "赢", "is_correct": false, "explanation": "语义：赢是结果，不是与守相对的主动进攻动作，不符合攻守对立的句意。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻是主动冲向对方，与「守」相对，句意通顺。", "写": "语义：写不是比赛或战斗中的动作，「我们写，你们守」与攻守对立的句意不合。", "赢": "语义：赢是结果，不是与守相对的主动进攻动作，不符合攻守对立的句意。", "送": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在下半场攻了两个球。", "explanation": "这里应该用〈进〉。得分要说「进球」，攻表示主动冲向对方的动作，不能表示得分。"}, {"text": "汽车攻上了电线杆，车头坏了。", "explanation": "这里应该用〈撞〉。撞表示物体相互碰撞，攻表示主动冲向对方的进攻，不能形容汽车撞上电线杆。"}, {"text": "他把钥匙攻进了锁眼。", "explanation": "这里应该用〈插〉。钥匙插入锁眼要用「插」，攻表示主动冲向对方，不能形容钥匙进入锁眼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指主动冲向对方进攻。"}, {"text": "供", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是供应、供给。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。"}, {"text": "钢", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}], "explanations": {"攻": "攻 gōng，正确答案，指主动冲向对方进攻。", "供": "gòng（第四声）与 gōng（第一声）声调不同，意思是供应、供给。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。", "钢": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻是主动进攻，句中球队一直进攻却没有进球，句意通顺。"}, {"text": "哭", "is_correct": false, "explanation": "语义：比赛语境中「一直哭」与「没有进球」的句意不合，不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡不是比赛动作，球队不会「一直睡」，句意荒谬。"}, {"text": "修", "is_correct": false, "explanation": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻是主动进攻，句中球队一直进攻却没有进球，句意通顺。", "哭": "语义：比赛语境中「一直哭」与「没有进球」的句意不合，不成立。", "睡": "语义：睡不是比赛动作，球队不会「一直睡」，句意荒谬。", "修": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们队终于攻得了冠军。", "explanation": "这里应该用〈夺〉。争得冠军要说「夺得」或「夺冠」，攻不能与「冠军」搭配。"}, {"text": "妈妈把碗攻在地上了，碎了一地。", "explanation": "这里应该用〈摔〉。摔表示物体掉落碰撞，攻表示主动进攻，不能形容碗掉在地上。"}, {"text": "他在中场攻到了球，马上传给队友。", "explanation": "这里应该用〈抢〉。拿到球要说「抢到」，攻表示主动进攻的动作，不说「攻到球」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们攻地很猛，我们只好往后退。", "corrected_sentence": "他们攻得很猛，我们只好往后退。", "error_description": "「攻」后面引出补语要用「得」，不能用「地」（「地」用在动词前）。应说「攻得很猛」，不能说「攻地很猛」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队攻着一次，没有成功。", "corrected_sentence": "我们队攻过一次，没有成功。", "error_description": "表示经历过某次动作要用「过」，「着」表示动作正在进行或持续，不能说「攻着一次」。应说「攻过一次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
