INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进攻；向对方发起进击。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "他们先守后攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我方队员一起往前攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "敌人从北边攻，我们在南边守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下半场红队开始攻，蓝队只能守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，他们从三个方向一起攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你攻左边，我攻右边。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对手一攻，我们就退。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个队很会守，也很会攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把球传到前面，大家一起往前攻。", "target_word": "攻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，主队就大胆地攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻了", "label": "体标"}, {"form": "攻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向对方发起进击，进攻（与守相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指向对方发起进击。"}, {"text": "刚", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}], "explanations": {"攻": "攻 gōng，正确答案，指向对方发起进击。", "刚": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻指向对方进击，与前面的「守」相对，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「先守后吃」不构成比赛或战斗的动作，句意荒谬。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与守、攻的语境不合，「先守后唱」句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻指向对方进击，与前面的「守」相对，句意通顺。", "吃": "语义：「先守后吃」不构成比赛或战斗的动作，句意荒谬。", "唱": "语义：唱与守、攻的语境不合，「先守后唱」句意不通。", "送": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把信攻到了桌子底下。", "explanation": "这里应该用〈塞〉。把东西塞到某处要用「塞」，攻表示向对方发起进击，不能形容把信放到桌子底下。"}, {"text": "他把石头攻进了河里。", "explanation": "这里应该用〈扔〉。扔是把东西抛出去的动作，攻表示进攻，不能形容把石头扔进河里。"}, {"text": "我们的队员一脚攻中了门框。", "explanation": "这里应该用〈射中〉。射门击中门框要用「射」，攻不表示射门的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指向对方发起进击。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。"}, {"text": "钢", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}], "explanations": {"攻": "攻 gōng，正确答案，指向对方发起进击。", "空": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。", "钢": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻指向对方进击，与「退」相对应，句意通顺。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡不是进攻的动作，「对手一睡，我们就退」句意不成立。"}, {"text": "修", "is_correct": false, "explanation": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗与比赛或战斗的语境不合，「对手一洗」句意荒谬。"}], "explanations": {"攻": "攻指向对方进击，与「退」相对应，句意通顺。", "睡": "语义：睡不是进攻的动作，「对手一睡，我们就退」句意不成立。", "修": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。", "洗": "语义：洗与比赛或战斗的语境不合，「对手一洗」句意荒谬。"}, "sentence_index": 6, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛一开始，主队就攻到了球。", "explanation": "这里应该用〈抢〉。拿到球要说「抢到」，攻表示主动进攻，不说「攻到球」。"}, {"text": "工人在地上攻了一个坑。", "explanation": "这里应该用〈挖〉。挖是用工具掘开土地的动作，攻表示进攻，不能形容挖坑。"}, {"text": "主队终于攻得了金牌。", "explanation": "这里应该用〈夺〉。争得金牌要说「夺得」，攻不能与「金牌」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们攻了三个，都没有成功。", "corrected_sentence": "我们攻了三次，都没有成功。", "error_description": "量词错误：表示「攻」这个动作的次数要用动量词「次」，应说「攻了三次」，不能用名量词「个」说「攻了三个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对手曾经攻着我们的城。", "corrected_sentence": "对手曾经攻过我们的城。", "error_description": "「曾经」表示经历过的事，要用体标「过」，「着」表示进行或持续，与「曾经」不搭配。应说「曾经攻过我们的城」，不能说「攻着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
