INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府管理国家或地方的各项事务。", "primary_collocate": null, "pronunciation": "zhèng wù", "ipa": "ʈʂɤŋ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "现在很多政务都可以在网上办理。", "target_word": "政务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府在网站上介绍了政务的办理方法。", "target_word": "政务", "complexity_tier": "T3", "furigana": "shì zhèng fǔ zài wǎng zhàn shàng jiè shào le zhèng wù de bàn lǐ fāng fǎ.", "sentence_source": "generated"}, {"text": "我们可以在市政府的窗口办理政务。", "target_word": "政务", "complexity_tier": "T3", "furigana": "wǒ men kě yǐ zài shì zhèng fǔ de chuāng kǒu bàn lǐ zhèng wù.", "sentence_source": "generated"}, {"text": "这个城市的政务由市政府统一管理。", "target_word": "政务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府应该把政务向市民公开。", "target_word": "政务", "complexity_tier": "T3", "furigana": "zhèng fǔ yīng gāi bǎ zhèng wù xiàng shì mín gōng kāi.", "sentence_source": "generated"}, {"text": "他在政府里负责地方政务。", "target_word": "政务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政务越透明，市民就越信任政府。", "target_word": "政务", "complexity_tier": "T3", "furigana": "zhèng wù yuè tòu míng, shì mín jiù yuè xìn rèn zhèng fǔ.", "sentence_source": "generated"}, {"text": "她去办政务，结果在窗口排了很久的队。", "target_word": "政务", "complexity_tier": "T3", "furigana": "tā qù bàn zhèng wù, jié guǒ zài chuāng kǒu pái le hěn jiǔ de duì.", "sentence_source": "generated"}, {"text": "新的办法让政务处理得更快。", "target_word": "政务", "complexity_tier": "T3", "furigana": "xīn de bàn fǎ ràng zhèng wù chǔ lǐ de gèng kuài.", "sentence_source": "generated"}, {"text": "这些政务都要依法管理。", "target_word": "政务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "政務", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政府管理国家或地方的各项事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政务", "is_correct": true, "explanation": "正确：政务指政府管理的事务，这些可以在网上办理的正是政务。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不是需要“办理”的事项，这句话说的是办事情。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能在网上“办理”。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：“办理”后面不能接“作文”，应说“写作文”。"}], "explanations": {"政务": "正确：政务指政府管理的事务，这些可以在网上办理的正是政务。", "游戏": "语义：游戏不是需要“办理”的事项，这句话说的是办事情。", "蔬菜": "语义：蔬菜是食物，不能在网上“办理”。", "作文": "搭配：“办理”后面不能接“作文”，应说“写作文”。"}, "sentence_index": 0, "correct_answer": "政务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府推出了一项新政务，鼓励创业。", "explanation": "这里应该用〈政策〉。政务指政府管理的各项事务，鼓励创业的方针要说政策。"}, {"text": "这次志愿活动，他负责的政务是打扫卫生。", "explanation": "这里应该用〈任务〉。政务指政府管理的事务，志愿活动中分派的工作要说任务。"}, {"text": "孩子每天要写很多政务。", "explanation": "这里应该用〈作业〉。政务是政府的事务，学生的功课要说作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政务", "is_correct": true, "explanation": "正确：政务越透明，市民才会越信任政府，这里的主语是政务。"}, {"text": "水", "is_correct": false, "explanation": "语义：水的透明度与市民信任政府无关，这句话说不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃的透明与市民信任政府没有关系，这里说不通。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“透明”一般不用来形容阳光，这里不搭配。"}], "explanations": {"政务": "正确：政务越透明，市民才会越信任政府，这里的主语是政务。", "水": "语义：水的透明度与市民信任政府无关，这句话说不通。", "玻璃": "语义：玻璃的透明与市民信任政府没有关系，这里说不通。", "阳光": "搭配：“透明”一般不用来形容阳光，这里不搭配。"}, "sentence_index": 6, "correct_answer": "政务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的政务由班长负责。", "explanation": "这里应该用〈事务〉。政务专指政府管理的事务，班里的事情不能说政务。"}, {"text": "会计每天要核对很多政务。", "explanation": "这里应该用〈账目〉。政务指政府管理的事务，公司的收支记录要说账目。"}, {"text": "运动员每天要参加很多政务。", "explanation": "这里应该用〈比赛〉。政务指政府的事务，体育比赛不能说政务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在窗口办理了三个政务。", "corrected_sentence": "他在窗口办理了三项政务。", "error_description": "量词错误：“政务”应使用量词“项”，不能用“个”。“三个政务”不自然，应说“三项政务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把这个政务办完了。", "corrected_sentence": "我们已经把这项政务办完了。", "error_description": "量词错误：“政务”应使用量词“项”，不能用“个”。“这个政务”不自然，应说“这项政务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胜", "is_correct": true, "explanation": "“胜”与“败”是反义词，都指比赛或打仗的输赢。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“败”没有反义关系，指快速移动。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“败”没有反义关系，指进食。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“败”没有反义关系，指书写。"}], "correct_answer": "胜", "explanations": {"胜": "“胜”与“败”是反义词，都指比赛或打仗的输赢。", "跑": "“跑”与“败”没有反义关系，指快速移动。", "吃": "“吃”与“败”没有反义关系，指进食。", "写": "“写”与“败”没有反义关系，指书写。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胜", "is_correct": true, "explanation": "“胜”与“败”是反义词，都指比赛或打仗的输赢。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“败”没有反义关系，指发出乐声。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“败”没有反义关系，指移动。"}, {"text": "读", "is_correct": false, "explanation": "“读”与“败”没有反义关系，指看着文字发出声音。"}], "correct_answer": "胜", "explanations": {"胜": "“胜”与“败”是反义词，都指比赛或打仗的输赢。", "唱": "“唱”与“败”没有反义关系，指发出乐声。", "走": "“走”与“败”没有反义关系，指移动。", "读": "“读”与“败”没有反义关系，指看着文字发出声音。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "败是比赛或打仗时输了。", "primary_collocate": null, "pronunciation": "bài", "ipa": "pai˥˩", "syllable_count": 1, "sentences": [{"text": "网球比赛中，他先败了一局。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红队以二比三败给了蓝队。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场仗打了三天，对方终于败了。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的篮球赛，我们队败了。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在决赛中败给了老朋友。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手太强，我们败得很快。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位拳击手败过一次，以后再没输过。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两军打了一整天，南军先败了。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队去年败给了我们，今年想赢回来。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛还没结束，他就知道自己要败了。", "target_word": "败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "败了", "label": "体标（了）"}, {"form": "败过", "label": "体标（过）"}, {"form": "敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛或打仗时输了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "败", "is_correct": true, "explanation": "败 bài（第四声）是比赛或打仗时输了，即目标词本身。"}, {"text": "摆", "is_correct": false, "explanation": "摆 bǎi（第三声）与 bài（第四声）声调不同，意思是摆放。"}, {"text": "白", "is_correct": false, "explanation": "白 bái（第二声）与 bài（第四声）声调不同，意思是白色。"}, {"text": "办", "is_correct": false, "explanation": "办 bàn 与 bài 韵母不同（-an 与 -ai），意思是办理。"}, {"text": "派", "is_correct": false, "explanation": "派 pài 与 bài 声母不同（p 与 b），意思是派遣、派出。"}], "explanations": {"败": "败 bài（第四声）是比赛或打仗时输了，即目标词本身。", "摆": "摆 bǎi（第三声）与 bài（第四声）声调不同，意思是摆放。", "白": "白 bái（第二声）与 bài（第四声）声调不同，意思是白色。", "办": "办 bàn 与 bài 韵母不同（-an 与 -ai），意思是办理。", "派": "派 pài 与 bài 声母不同（p 与 b），意思是派遣、派出。"}, "sentence_index": null, "correct_answer": "败"}, "level_3": {"options": [{"text": "败", "is_correct": true, "explanation": "“败”指比赛中输了，“先败了一局”表示先输了一局，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与网球比赛无关，“写了一局”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与网球比赛无关，“唱了一局”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“局”搭配表示比赛的结果。"}], "explanations": {"败": "“败”指比赛中输了，“先败了一局”表示先输了一局，符合句意。", "写": "语义：“写”与网球比赛无关，“写了一局”说不通。", "唱": "语义：“唱”与网球比赛无关，“唱了一局”说不通。", "吃": "搭配：“吃”不能与“局”搭配表示比赛的结果。"}, "sentence_index": 0, "correct_answer": "败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案败了，需要重新设计。", "explanation": "这里应该用〈失败〉。“败”多指比赛或打仗时输了，方案没成功要说“失败”。"}, {"text": "这辆车败了，只好打车。", "explanation": "这里应该用〈坏〉。车坏了用“坏”，“败”只用于比赛或打仗时输了。"}, {"text": "这块手表败了，我得拿去修。", "explanation": "这里应该用〈坏〉。手表坏了用“坏”，“败”不用于机器或物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "败", "is_correct": true, "explanation": "败 bài（第四声）是比赛或打仗时输了，即目标词本身。"}, {"text": "菜", "is_correct": false, "explanation": "菜 cài 与 bài 声母不同（c 与 b），意思是蔬菜。"}, {"text": "再", "is_correct": false, "explanation": "再 zài 与 bài 声母不同（z 与 b），意思是再次、又。"}, {"text": "带", "is_correct": false, "explanation": "带 dài 与 bài 声母不同（d 与 b），意思是携带。"}, {"text": "盖", "is_correct": false, "explanation": "盖 gài 与 bài 声母不同（g 与 b），意思是覆盖。"}], "explanations": {"败": "败 bài（第四声）是比赛或打仗时输了，即目标词本身。", "菜": "菜 cài 与 bài 声母不同（c 与 b），意思是蔬菜。", "再": "再 zài 与 bài 声母不同（z 与 b），意思是再次、又。", "带": "带 dài 与 bài 声母不同（d 与 b），意思是携带。", "盖": "盖 gài 与 bài 声母不同（g 与 b），意思是覆盖。"}, "sentence_index": null, "correct_answer": "败"}, "level_3": {"options": [{"text": "败", "is_correct": true, "explanation": "“败过一次”指比赛中输过，与后半句“以后再没输过”前后照应。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指做饭，与拳击比赛无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不接比赛的结果，“洗过一次”与拳击无关。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是针线活，与拳击比赛无关。"}], "explanations": {"败": "“败过一次”指比赛中输过，与后半句“以后再没输过”前后照应。", "煮": "语义：“煮”指做饭，与拳击比赛无关。", "洗": "搭配：“洗”不接比赛的结果，“洗过一次”与拳击无关。", "缝": "语义：“缝”是针线活，与拳击比赛无关。"}, "sentence_index": 6, "correct_answer": "败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次体育测验他败了，只得了三分。", "explanation": "这里应该用〈失败〉。体育测验没考好不用“败”，“败”多指比赛或打仗时输了。"}, {"text": "这台电脑用了五年，终于败了。", "explanation": "这里应该用〈坏〉。电脑等机器不能用了要说“坏”，“败”只用于比赛或打仗时输了。"}, {"text": "这个项目败了，大家都很失望。", "explanation": "这里应该用〈失败〉。项目没成功要说“失败”，“败”多指比赛或打仗时输了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场排球赛，我们队先败了给对手一局，后来逆转赢了。", "corrected_sentence": "这场排球赛，我们队先败给对手一局，后来逆转赢了。", "error_description": "错误：“了”不能放在“败”和“给”中间。正确：应说“败给对手一局”或“败给了对手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开始就败很快，观众都没反应过来。", "corrected_sentence": "他一开始就败得很快，观众都没反应过来。", "error_description": "错误：“败”后的补语漏掉了“得”。正确：补语前要用“得”，应说“败得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
