INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有勇气去做某事。", "primary_collocate": null, "pronunciation": "gǎn yú", "ipa": "kan˨˩˦ y˧˥", "syllable_count": 2, "sentences": [{"text": "面对错误，你敢于承认吗？", "target_word": "敢于", "complexity_tier": "T3", "furigana": "Miàn duì cuò wù，nǐ gǎn yú chéng rèn ma？", "sentence_source": "generated"}, {"text": "他从小就敢于挑战自己。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很佩服敢于改变生活的人。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她敢于拒绝不合理的要求。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟现在敢于在全班面前讲话了。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好学生敢于向老师提问。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敢于站出来保护同学。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要敢于说“不”。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她敢于跟经理说出不同意见。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有敢于尝试，才会有机会。", "target_word": "敢于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有勇气去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敢于", "is_correct": true, "explanation": "敢于：有勇气去做，与“承认”搭配，表示不回避地承认错误。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用于“承认”。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指保存物品，不能用于“承认”这种行为。"}, {"text": "缴纳", "is_correct": false, "explanation": "搭配：“缴纳”的对象是费用或税款，不能用于“承认”。"}], "explanations": {"敢于": "敢于：有勇气去做，与“承认”搭配，表示不回避地承认错误。", "驾驶": "搭配：“驾驶”的对象是车辆，不能用于“承认”。", "收藏": "语义：“收藏”指保存物品，不能用于“承认”这种行为。", "缴纳": "搭配：“缴纳”的对象是费用或税款，不能用于“承认”。"}, "sentence_index": 0, "correct_answer": "敢于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我敢于每天扫地。", "explanation": "这里应该用〈经常〉。敢于强调有勇气去做，扫地是日常家务，不需要勇气，应说“经常”。"}, {"text": "我弟弟敢于每天洗澡。", "explanation": "这里应该用〈坚持〉。敢于强调克服困难的勇气，洗澡是日常习惯，应说“坚持”。"}, {"text": "他敢于每天七点起床。", "explanation": "这里应该用〈按时〉。敢于强调有勇气去做有风险的事，每天七点起床是作息安排，应说“按时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敢于", "is_correct": true, "explanation": "敢于：有勇气去做，表示他不怕困难，站出来保护同学。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，与“保护同学”不相关。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能用于“保护同学”。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是产品或技术，不能用于“保护同学”。"}], "explanations": {"敢于": "敢于：有勇气去做，表示他不怕困难，站出来保护同学。", "种植": "语义：“种植”指栽培植物，与“保护同学”不相关。", "购买": "搭配：“购买”的对象是商品，不能用于“保护同学”。", "发明": "搭配：“发明”的对象是产品或技术，不能用于“保护同学”。"}, "sentence_index": 6, "correct_answer": "敢于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他敢于每天吃早饭。", "explanation": "这里应该用〈习惯〉。敢于表示有勇气去做有风险的事，每天吃早饭是习惯，应说“习惯”。"}, {"text": "她敢于喝茶。", "explanation": "这里应该用〈喜欢〉。敢于表示克服困难，喝茶不需要勇气，应说“喜欢”。"}, {"text": "我敢于周末洗衣服。", "explanation": "这里应该用〈打算〉。敢于表示不怕困难，周末洗衣服不需要勇气，应说“打算”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学敢于敢于在课堂上发言。", "corrected_sentence": "我们班的同学敢于在课堂上发言。", "error_description": "“敢于”只能出现一次，不能重复。错误形式是“敢于敢于在课堂上发言”，正确形式是“敢于在课堂上发言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王敢于了承认失败。", "corrected_sentence": "小王敢于承认失败。", "error_description": "“敢于”后面不能直接加“了”，它不表示完成动作，句子不通。正确形式是“敢于承认失败”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
