INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98411, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "早在是说很久以前就已经有了。", "primary_collocate": null, "pronunciation": "zǎo zài", "ipa": "tsɑʊ̯˨˩˦ tsaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "早在两千年前，中国就有了纸。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在古代，人们就知道月亮会影响海水。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在我出生以前，这座桥就有了。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在唐朝，这里就已经很热闹了。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在小学的时候，他就有了自己的电脑。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在一百年前，这个城市就有地铁了。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在几千年前，人们就会用火做饭。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在三岁时，她就有了自己的小书包。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在孩子出生前，他们就买好了房子。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早在古时候，人们就喝茶了。", "target_word": "早在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "早在+时间，表示很久以前就已经有了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早在", "is_correct": true, "explanation": "早在表示很久以前就已经有了，与“两千年前”的时间一致。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“两千年前”的久远时间矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“两千年前”这种久远的时间不相符。"}, {"text": "业已", "is_correct": false, "explanation": "语法：“业已”意思是“已经”，只能修饰动词，不能直接带“两千年前”这样的时间词。"}], "explanations": {"早在": "早在表示很久以前就已经有了，与“两千年前”的时间一致。", "立刻": "语义：“立刻”表示马上，与“两千年前”的久远时间矛盾。", "忽然": "语义：“忽然”表示突然发生，与“两千年前”这种久远的时间不相符。", "业已": "语法：“业已”意思是“已经”，只能修饰动词，不能直接带“两千年前”这样的时间词。"}, "sentence_index": 0, "correct_answer": "早在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早在明年，这里就会很热闹。", "explanation": "这里不能用〈早在〉。早在表示很久以前已经发生，不能用于将来的时间。"}, {"text": "早在他的房间里，我们就找到了钥匙。", "explanation": "这里不能用〈早在〉。早在后面接的是时间，不能接地点。"}, {"text": "早在大家都回家以后，他才来。", "explanation": "这里不能用〈早在〉。早在表示很久以前就已经发生，这里说的是较晚的时间，与早在的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早在", "is_correct": true, "explanation": "早在与“几千年前”搭配，表示很久以前就已经发生，语义通顺。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，不能修饰“几千年前”这样确定的久远时间。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化，不能修饰一个久远的时间点。"}, {"text": "随即", "is_correct": false, "explanation": "语义：“随即”表示紧接着马上发生，不能带“几千年前”这样久远的时间。"}], "explanations": {"早在": "早在与“几千年前”搭配，表示很久以前就已经发生，语义通顺。", "偶尔": "语义：“偶尔”表示不时发生，不能修饰“几千年前”这样确定的久远时间。", "渐渐": "语义：“渐渐”表示逐步变化，不能修饰一个久远的时间点。", "随即": "语义：“随即”表示紧接着马上发生，不能带“几千年前”这样久远的时间。"}, "sentence_index": 6, "correct_answer": "早在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早在现在，人们都用手机上网。", "explanation": "这里不能用〈早在〉。早在指过去很早的时间，不能用于现在。"}, {"text": "早在刚刚，他就走了。", "explanation": "这里不能用〈早在〉。早在表示很久以前就已经发生，刚刚发生的事不能用早在。"}, {"text": "早在明天的会议，我们就准备好了。", "explanation": "这里不能用〈早在〉。早在表示很久以前，不能用于将来的会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早在三十年前了，这里就有了学校。", "corrected_sentence": "早在三十年前，这里就有了学校。", "error_description": "错误在“了”的位置：“早在三十年前”是时间状语，后面不能加“了”，应说“早在三十年前，这里就有了学校。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们早在今天就用石头做工具。", "corrected_sentence": "人们早在古代就用石头做工具。", "error_description": "错误在时间词：“早在”表示很久以前，后面要接过去的时间，“今天”是现在，不能说“早在今天”，应说“早在古代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
