INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宇宙中的天体，如地球、火星。", "primary_collocate": null, "pronunciation": "xīng qiú", "ipa": "ɕiŋ˥˥ tɕʰjoʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "地球是一颗蓝色的星球。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火星是离地球很近的星球。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙中有很多我们不知道的星球。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在远处发现了一颗新星球。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗星球上没有水，也没有空气。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们想在别的星球上生活。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳系里有很多星球。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星球离我们很远，坐飞船要三年。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想坐飞船去另一个星球看看。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想知道这个星球上有没有生命。", "target_word": "星球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "外星球", "label": "复合"}], "register": "中性", "sense_fingerprint": "宇宙中的天体，如地球、火星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星球", "is_correct": true, "explanation": "正确：星球指宇宙中的天体，地球就是一颗蓝色的星球。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：地球不是椅子，句子说的是天体。"}, {"text": "雨滴", "is_correct": false, "explanation": "语义：地球不是雨滴，句子说的是一个天体。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“蓝色的”不能修饰“声音”，“一颗蓝色的声音”不通。"}], "explanations": {"星球": "正确：星球指宇宙中的天体，地球就是一颗蓝色的星球。", "椅子": "语义：地球不是椅子，句子说的是天体。", "雨滴": "语义：地球不是雨滴，句子说的是一个天体。", "声音": "搭配：“蓝色的”不能修饰“声音”，“一颗蓝色的声音”不通。"}, "sentence_index": 0, "correct_answer": "星球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在窗外看到一只星球。", "explanation": "量词用错。〈只〉用于动物，星球应使用〈颗〉或〈个〉。"}, {"text": "我花钱买了一把星球。", "explanation": "量词用错。〈把〉用于有柄的器具，星球应使用〈颗〉或〈个〉。"}, {"text": "他在球场上踢进了一个星球。", "explanation": "这里应该用〈足球〉。星球指宇宙中的天体，踢进球门的是足球，不能说星球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星球", "is_correct": true, "explanation": "正确：星球指太阳系里的天体，如地球、火星。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳系里只有一个太阳，不能说“很多太阳”。"}, {"text": "地球", "is_correct": false, "explanation": "语义：太阳系里只有一个地球，不能说“很多地球”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不在太阳系里运行，句子说的是天体。"}], "explanations": {"星球": "正确：星球指太阳系里的天体，如地球、火星。", "太阳": "语义：太阳系里只有一个太阳，不能说“很多太阳”。", "地球": "语义：太阳系里只有一个地球，不能说“很多地球”。", "铅笔": "语义：铅笔是文具，不在太阳系里运行，句子说的是天体。"}, "sentence_index": 6, "correct_answer": "星球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在河边捡到一块星球。", "explanation": "量词用错。〈块〉用于块状的东西，星球应使用〈颗〉或〈个〉。"}, {"text": "这个西瓜是一个大星球。", "explanation": "这里应该用〈球体〉。西瓜形状像球体，但它不是天体，不能说星球。"}, {"text": "妈妈帮我剥了一个白星球。", "explanation": "这里应该用〈鸡蛋〉。星球是天体，剥壳的白色圆形食物是鸡蛋，不能说星球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "望远镜里看到了一只暗淡的星球。", "corrected_sentence": "望远镜里看到了一颗暗淡的星球。", "error_description": "量词错误：星球应用“颗”或“个”，“只”多用于动物。应说“一颗暗淡的星球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天文台的书架上有许多关于星球们的书。", "corrected_sentence": "天文台的书架上有许多关于星球的书。", "error_description": "“们”只用于人或拟人化的人群，不能加在“星球”后面。应说“关于星球的书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
