INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法中表示动作发生时间的形式，即时态。", "primary_collocate": null, "pronunciation": "shí shì", "ipa": "ʂɻ̩˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个句子用的是哪种时式？", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语法书里有一章专门讲时式。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要先学会英语的时式。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日语的时式变化比英语的复杂。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了动词的各种时式。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动词变了，时式也跟着变。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把时式的用法讲得很清楚。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时式不同，动词的样子也不同。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译时要注意原文的时式。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作业里时式错了好几处。", "target_word": "时式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "语法中表示动作发生时间的形式，即时态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32f05aeb-564f-4b8c-a84f-e4cd4c804739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时式", "is_correct": true, "explanation": "正确：时式 shí shì，指语法中表示动作发生时间的形式，即时态。"}, {"text": "十四", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是数字十四。"}, {"text": "石狮", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是石头做的狮子。"}, {"text": "事事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是每件事。"}], "explanations": {"时式": "正确：时式 shí shì，指语法中表示动作发生时间的形式，即时态。", "十四": "sì 与 shì 声母不同（s 与 sh），意思是数字十四。", "石狮": "shī（第一声）与 shì（第四声）声调不同，意思是石头做的狮子。", "事事": "shì（第四声）与 shí（第二声）声调不同，意思是每件事。"}, "sentence_index": null, "correct_answer": "时式"}, "level_3": {"options": [{"text": "时式", "is_correct": true, "explanation": "正确：时式在这里指动作时间的语法形式，即时态。"}, {"text": "天气", "is_correct": false, "explanation": "语义：句子没有天气，问“哪种天气”不符合语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：句子没有味道，问句子的“哪种味道”不通。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”不能用来描述句子的语法形式。"}], "explanations": {"时式": "正确：时式在这里指动作时间的语法形式，即时态。", "天气": "语义：句子没有天气，问“哪种天气”不符合语境。", "味道": "语义：句子没有味道，问句子的“哪种味道”不通。", "力气": "搭配：“力气”不能用来描述句子的语法形式。"}, "sentence_index": 0, "correct_answer": "时式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章用的时式是宋体。", "explanation": "这里应该用〈字体〉。时式是动词的时间形式，宋体是字体，不能说“时式是宋体”。"}, {"text": "老师教了我们一条时式。", "explanation": "量词用错。〈条〉用于细长的东西，时式应使用〈种〉。"}, {"text": "他在那个时式学习很努力。", "explanation": "这里应该用〈时期〉。时式是语法形式，不指一段时期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98418, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时式", "is_correct": true, "explanation": "正确：时式 shí shì，指语法中表示动作发生时间的形式，即时态。"}, {"text": "实施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是实行、施行。"}, {"text": "史事", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史上的事件。"}, {"text": "时时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）第二个音节声调不同，意思是常常。"}], "explanations": {"时式": "正确：时式 shí shì，指语法中表示动作发生时间的形式，即时态。", "实施": "shī（第一声）与 shì（第四声）声调不同，意思是实行、施行。", "史事": "shǐ（第三声）与 shí（第二声）声调不同，意思是历史上的事件。", "时时": "shí（第二声）与 shì（第四声）第二个音节声调不同，意思是常常。"}, "sentence_index": null, "correct_answer": "时式"}, "level_3": {"options": [{"text": "时式", "is_correct": true, "explanation": "正确：这本书讲的是语法中时式的用法。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空没有用法，“把天空的用法讲得很清楚”不符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不是需要讲用法的对象，“空气的用法”不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日没有用法，句子讲的是语法知识。"}], "explanations": {"时式": "正确：这本书讲的是语法中时式的用法。", "天空": "语义：天空没有用法，“把天空的用法讲得很清楚”不符合语境。", "空气": "搭配：空气不是需要讲用法的对象，“空气的用法”不通。", "生日": "语义：生日没有用法，句子讲的是语法知识。"}, "sentence_index": 6, "correct_answer": "时式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个时式的人工作很努力。", "explanation": "这里应该用〈时代〉。时式是语法形式，不指一个年代。"}, {"text": "他刚买了一台时式。", "explanation": "量词用错。〈台〉用于机器，时式应使用〈种〉。"}, {"text": "我们一起度过了美好的时式。", "explanation": "这里应该用〈时光〉。时式是语法形式，不能说“度过时式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英语有好几条时式需要学习。", "corrected_sentence": "英语有好几种时式需要学习。", "error_description": "量词错误：时式应用“种”，“条”用于细长的东西。应说“好几种时式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们学了一只英语的时式。", "corrected_sentence": "同学们学了一种英语的时式。", "error_description": "量词错误：时式应用“种”，“只”多用于动物。应说“一种英语的时式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c5e01a-7d0b-4cbf-bd3c-c80ae71b9dc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
