INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时间线是一条线，把事情按先后顺序排在上面。", "primary_collocate": null, "pronunciation": "shí jiān xiàn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "老师在黑板上画了一条时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些事情放在时间线上。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用一张纸做了一条时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间线的左边是过去，右边是现在。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在时间线上写下了每一年的大事。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条时间线从1900年开始。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间线上有五件事，请按顺序读。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用红笔在时间线上画了圈。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上贴着一条很长的时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们把照片按先后排在时间线上。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条时间线", "label": "量词"}, {"form": "時間線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "画出来的一条线，事情按先后顺序排在上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间线", "is_correct": true, "explanation": "正确：“画了一条时间线”指在黑板上画出的线，与“画了一条”搭配自然。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻是消息，不能画在黑板上，句子不通。"}, {"text": "法律", "is_correct": false, "explanation": "搭配：“画”不能与“法律”搭配，法律不能被画在黑板上。"}, {"text": "短信", "is_correct": false, "explanation": "语义：短信是手机上的文字，无法画在黑板上。"}], "explanations": {"时间线": "正确：“画了一条时间线”指在黑板上画出的线，与“画了一条”搭配自然。", "新闻": "语义：新闻是消息，不能画在黑板上，句子不通。", "法律": "搭配：“画”不能与“法律”搭配，法律不能被画在黑板上。", "短信": "语义：短信是手机上的文字，无法画在黑板上。"}, "sentence_index": 0, "correct_answer": "时间线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一条时间线把箱子捆了起来。", "explanation": "这里的〈时间线〉被当成了绳子，应该用〈绳子〉。时间线是画在纸上、按先后排列事件的线，不能用来捆东西。"}, {"text": "这条时间线经过公园，很好走。", "explanation": "这里应该用〈路线〉。路线指走的路径，可以经过公园、好走；时间线不指路径。"}, {"text": "屋顶上的时间线被大风吹断了，我们家停了电。", "explanation": "这里的〈时间线〉被当成了电线，应该用〈电线〉。时间线是画在纸上、排列事件的线，不能用来输电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间线", "is_correct": true, "explanation": "正确：“时间线上有五件事”指画出的线上排着事件，可以按顺序读。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不能按顺序读五件事，与“请按顺序读”冲突。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“上”不与“空气”搭配，应说“空气中”。"}, {"text": "水面", "is_correct": false, "explanation": "语义：水面上的东西不能按顺序读，句意不通。"}], "explanations": {"时间线": "正确：“时间线上有五件事”指画出的线上排着事件，可以按顺序读。", "天空": "语义：天空上不能按顺序读五件事，与“请按顺序读”冲突。", "空气": "搭配：“上”不与“空气”搭配，应说“空气中”。", "水面": "语义：水面上的东西不能按顺序读，句意不通。"}, "sentence_index": 6, "correct_answer": "时间线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上贴着一颗很长的时间线。", "explanation": "这里应该用〈条〉。时间线是长条形的线，“颗”用于圆形的小东西。"}, {"text": "他在纸上写了一扇时间线。", "explanation": "这里应该用〈条〉。“扇”用于门窗，时间线应该用“条”。"}, {"text": "我们做了一把时间线。", "explanation": "这里应该用〈条〉。“把”用于有柄的物件，时间线不能用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们在纸上画了一朵时间线。", "corrected_sentence": "同学们在纸上画了一条时间线。", "error_description": "量词错误：“时间线”是线，应该用“条”；“朵”用于花，不能用来计量时间线。正确的说法是“一条时间线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室后面的墙上挂着一条很长时间线。", "corrected_sentence": "教室后面的墙上挂着一条很长的时间线。", "error_description": "修饰语漏了“的”：“很长”是“很”加形容词“长”，修饰名词时中间要加“的”，应说“很长的时间线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
