INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按时间先后排列事件的线索。", "primary_collocate": null, "pronunciation": "shí jiān xiàn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "警察正在整理案子的时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的时间线很乱，我看不懂。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说有两条时间线，一条写过去，一条写现在。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说一下这件事的时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者查清了这件事的时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我生病的时间线，我想了很久。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的时间线从古代到未来。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这本书，我才弄清楚故事的时间线。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把项目的时间线发给了每个人。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的和证人说的时间线不一样。", "target_word": "时间线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条时间线", "label": "量词"}, {"form": "時間線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事件发展按先后顺序形成的线索", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间线", "is_correct": true, "explanation": "正确：警察整理的是案件中事件发生的先后线索，“整理案子的时间线”合理。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子与案子无关，不能用来整理案子。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“整理”不能搭配“脾气”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是案件材料，不能用“整理”来处理。"}], "explanations": {"时间线": "正确：警察整理的是案件中事件发生的先后线索，“整理案子的时间线”合理。", "鞋子": "语义：鞋子与案子无关，不能用来整理案子。", "脾气": "搭配：“整理”不能搭配“脾气”。", "天气": "语义：天气不是案件材料，不能用“整理”来处理。"}, "sentence_index": 0, "correct_answer": "时间线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在阳台上拉了一条时间线晾衣服。", "explanation": "这里的〈时间线〉被当成了晾衣绳，应该用〈晾衣绳〉。时间线指按时间先后排列事件的线索，不是绳子。"}, {"text": "我今天没有时间线去看电影。", "explanation": "这里应该用〈时间〉。时间线指按先后排列事件的线索，不表示可以用来做事的时间。"}, {"text": "这条时间线经过公园，很好走。", "explanation": "这里应该用〈路线〉。路线指走的路径，时间线不指路径。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间线", "is_correct": true, "explanation": "正确：“游戏的时间线”指游戏故事的先后顺序，与“从古代到未来”搭配。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不能从古代延伸到未来，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：游戏没有体重，不能说从古代到未来的体重。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“从…到…”只用于时间或空间的跨度，不与“味道”搭配。"}], "explanations": {"时间线": "正确：“游戏的时间线”指游戏故事的先后顺序，与“从古代到未来”搭配。", "脚步": "语义：脚步不能从古代延伸到未来，句意不通。", "体重": "语义：游戏没有体重，不能说从古代到未来的体重。", "味道": "搭配：“从…到…”只用于时间或空间的跨度，不与“味道”搭配。"}, "sentence_index": 6, "correct_answer": "时间线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在会议室里贴了一扇很长的时间线。", "explanation": "这里应该用〈条〉。“扇”用于门窗，时间线应该用“条”。"}, {"text": "这件事有一颗很清楚的时间线。", "explanation": "这里应该用〈条〉。“颗”用于圆形的小东西，时间线应该用“条”。"}, {"text": "我给他看了一朵时间线。", "explanation": "这里应该用〈条〉。“朵”用于花，时间线应该用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说有两张时间线。", "corrected_sentence": "这部小说有两条时间线。", "error_description": "量词错误：“时间线”应该用“条”；“张”用于纸、桌子等平面的东西，不能用来计量时间线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告里有一朵清楚的时间线。", "corrected_sentence": "这份报告里有一条清楚的时间线。", "error_description": "量词错误：“时间线”应该用“条”；“朵”用于花，不能用来计量时间线。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
