INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98423, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "泛指地认为某种做法是最合适的选择，不针对具体的听话人。", "primary_collocate": null, "pronunciation": "zuì hǎo shì", "ipa": "tsueɪ˥˩ xɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "去机场最好是坐地铁。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买水果最好是早上去。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语最好是每天听一点。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定最好是先问问家人。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末出门最好是带上伞。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药最好是饭后。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想睡得好，最好是晚上不喝咖啡。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请客最好是在家里做饭。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复习最好是考试前一周开始。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家最好是找朋友帮忙。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "指出某种做法是最合适的选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最好是", "is_correct": true, "explanation": "正确：“最好是”引出建议，“去机场最好是坐地铁”表示认为坐地铁最合适。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已完成，与“去机场”的将来打算矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“去机场”的计划不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能用来引出“去机场”该怎么做的建议。"}], "explanations": {"最好是": "正确：“最好是”引出建议，“去机场最好是坐地铁”表示认为坐地铁最合适。", "已经": "语义：“已经”表示动作已完成，与“去机场”的将来打算矛盾。", "正在": "体貌：“正在”表示动作进行中，与“去机场”的计划不合。", "忽然": "语义：“忽然”表示突然发生，不能用来引出“去机场”该怎么做的建议。"}, "sentence_index": 0, "correct_answer": "最好是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我们最好是去了公园。", "explanation": "误用：“最好是”只用于提出将来或眼前的建议，不能用于已经发生的事；这里应直接说“我们去了公园”。"}, {"text": "水最好是由两个氢原子和一个氧原子组成的。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述客观事实；水的组成是事实，这里应直接说“水是由两个氢原子和一个氧原子组成的”。"}, {"text": "地球最好是绕着太阳转。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述天文事实；地球绕太阳转是事实，这里应直接说“地球绕着太阳转”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最好是", "is_correct": true, "explanation": "正确：“最好是”引出对睡眠的建议，“要想睡得好，最好是晚上不喝咖啡”表示建议。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与要求或常理相反，与“要想睡得好”的目标冲突。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示险些发生，与给出建议的语境不合。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不能用在“要想睡得好”这类条件分句之后引出建议。"}], "explanations": {"最好是": "正确：“最好是”引出对睡眠的建议，“要想睡得好，最好是晚上不喝咖啡”表示建议。", "偏偏": "语义：“偏偏”表示与要求或常理相反，与“要想睡得好”的目标冲突。", "差点": "语义：“差点”表示险些发生，与给出建议的语境不合。", "忽然": "搭配：“忽然”表示突然发生，不能用在“要想睡得好”这类条件分句之后引出建议。"}, "sentence_index": 6, "correct_answer": "最好是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车最好是昨天就修好了。", "explanation": "误用：“最好是”只用于提出建议，不用来陈述已经完成的事；这里应直接说“这辆车昨天就修好了”。"}, {"text": "一加一最好是二。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述数学事实；一加一等于二是事实，这里应直接说“一加一等于二”。"}, {"text": "三角形最好是有三条边。", "explanation": "误用：“最好是”不用来陈述几何事实；三角形有三条边是定义，这里应直接说“三角形有三条边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去机场最好是是坐公交车。", "corrected_sentence": "去机场最好是坐公交车。", "error_description": "重复错误：“最好是”中的“是”只能出现一次，应说“去机场最好是坐公交车”，不能多写一个“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "要想睡得好，晚上最好是是不喝咖啡。", "corrected_sentence": "要想睡得好，晚上最好是不喝咖啡。", "error_description": "重复错误：“最好是”中的“是”只能出现一次，应说“晚上最好是不喝咖啡”，不能多写一个“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
