INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98424, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示建议，认为这样做最合适。", "primary_collocate": null, "pronunciation": "zuì hǎo shì", "ipa": "tsueɪ˥˩ xɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你最好是现在就告诉他。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，你最好是在家休息。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气了，你最好是别说话。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最好是先打个电话。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，我们最好是打车回去。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最好是多穿一件衣服。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最好是你来给老师解释一下。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最好是别把这件事告诉妈妈。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，你最好是明天再走。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们最好是早点儿到。", "target_word": "最好是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "向对方提出建议，认为这样做最合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最好是", "is_correct": true, "explanation": "正确：“最好是”引出建议，“你最好是现在就告诉他”表示建议对方这样做。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“现在就”的建议语境矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“现在就”的建议不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能和“现在就”一起用来提出建议。"}], "explanations": {"最好是": "正确：“最好是”引出建议，“你最好是现在就告诉他”表示建议对方这样做。", "已经": "语义：“已经”表示已完成，与“现在就”的建议语境矛盾。", "正在": "体貌：“正在”表示动作进行中，与“现在就”的建议不合。", "忽然": "语义：“忽然”表示突然发生，不能和“现在就”一起用来提出建议。"}, "sentence_index": 0, "correct_answer": "最好是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天最好是先打了个电话。", "explanation": "误用：“最好是”只用于提出将来或眼前的建议，不能用于已经发生的事；这里应直接说“我昨天先打了个电话”。"}, {"text": "地球最好是绕着太阳转。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述天文事实；地球绕太阳转是事实，这里应直接说“地球绕着太阳转”。"}, {"text": "三角形最好是有三条边。", "explanation": "误用：“最好是”不用来陈述几何事实；三角形有三条边是定义，这里应直接说“三角形有三条边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最好是", "is_correct": true, "explanation": "正确：“最好是”引出建议，“最好是你来给老师解释一下”表示建议由对方来做。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能用在句首引出建议。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生，与建议的语境不合。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：“差点”表示险些发生，不能用于句首引出建议。"}], "explanations": {"最好是": "正确：“最好是”引出建议，“最好是你来给老师解释一下”表示建议由对方来做。", "忽然": "语义：“忽然”表示突然发生，不能用在句首引出建议。", "刚刚": "语义：“刚刚”表示刚发生，与建议的语境不合。", "差点": "搭配：“差点”表示险些发生，不能用于句首引出建议。"}, "sentence_index": 6, "correct_answer": "最好是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一加一最好是二。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述数学事实；一加一等于二是事实，这里应直接说“一加一等于二”。"}, {"text": "这辆车最好是昨天就修好了。", "explanation": "误用：“最好是”只用于提出建议，不用来陈述已经完成的事；这里应直接说“这辆车昨天就修好了”。"}, {"text": "水最好是由两个氢原子和一个氧原子组成的。", "explanation": "误用：“最好是”表示建议或希望，不用来陈述客观事实；水的组成是事实，这里应直接说“水是由两个氢原子和一个氧原子组成的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你最好是是今天就告诉他。", "corrected_sentence": "你最好是今天就告诉他。", "error_description": "重复错误：“最好是”中的“是”只能出现一次，应说“你最好是今天就告诉他”，不能多写一个“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你最好是是别跟妈妈说这件事。", "corrected_sentence": "你最好是别跟妈妈说这件事。", "error_description": "重复错误：“最好是”中的“是”只能出现一次，应说“你最好是别跟妈妈说这件事”，不能多写一个“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
