INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本台是说话的这个电视台或广播台。", "primary_collocate": null, "pronunciation": "běn tái", "ipa": "pən˨˩ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "观众朋友们，欢迎收看本台的新闻节目。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台记者刚刚从现场发来了报道。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台今天晚上八点播出新电视剧。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台提醒大家，明天有大雨。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台将继续关注这件事。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢您一直收看本台的节目。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据本台消息，比赛已经结束了。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台欢迎观众打电话来提意见。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台刚收到一条重要的消息。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台的天气预报每天早上七点播出。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本台记者", "label": "复合"}, {"form": "本臺", "label": "繁体"}], "register": "书面", "sense_fingerprint": "播音员或记者称自己所在的电视台或广播台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本台", "is_correct": true, "explanation": "正确：“本台”指说话者所在的电视台，可以作“收看……的新闻节目”的定语。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不会播出新闻节目，句子不通。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书籍，不是播出新闻节目的机构。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“收看”的对象是节目或频道，不能与“书店”搭配。"}], "explanations": {"本台": "正确：“本台”指说话者所在的电视台，可以作“收看……的新闻节目”的定语。", "厨房": "语义：厨房不会播出新闻节目，句子不通。", "小说": "语义：小说是书籍，不是播出新闻节目的机构。", "书店": "搭配：“收看”的对象是节目或频道，不能与“书店”搭配。"}, "sentence_index": 0, "correct_answer": "本台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本台的学生都很努力。", "explanation": "这里应该用〈本校〉。本台是电视台或广播台，不是学校，不能说“本台的学生”。"}, {"text": "本台今年的人口增加了不少。", "explanation": "这里应该用〈本市〉。本台指电视台或广播台，不指城市，不能说人口。"}, {"text": "本台的医生都很努力。", "explanation": "这里应该用〈本院〉。医生属于医院，电视台或广播台没有医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本台", "is_correct": true, "explanation": "正确：“据本台消息”指根据本台的报道，本台是消息来源。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不会报道比赛结束的消息。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“据…消息”要求有信息来源的人或机构，“天空”不能发布消息。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林不是消息来源，不能报道比赛。"}], "explanations": {"本台": "正确：“据本台消息”指根据本台的报道，本台是消息来源。", "图书馆": "语义：图书馆不会报道比赛结束的消息。", "天空": "搭配：“据…消息”要求有信息来源的人或机构，“天空”不能发布消息。", "树林": "语义：树林不是消息来源，不能报道比赛。"}, "sentence_index": 6, "correct_answer": "本台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本台的病人今天特别多。", "explanation": "这里应该用〈本院〉。病人在医院，本台是电视台或广播台。"}, {"text": "本台的老师明天下午开会。", "explanation": "这里应该用〈本校〉。老师属于学校，本台指电视台或广播台。"}, {"text": "本台的面包又香又便宜。", "explanation": "这里应该用〈本店〉。卖面包的是商店，本台指电视台或广播台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本台们的记者正在现场采访。", "corrected_sentence": "本台的记者正在现场采访。", "error_description": "“本台”是机构，不能加“们”表示复数；应说“本台的记者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们本台工作。", "corrected_sentence": "我们在本台工作。", "error_description": "漏了“在”：表示地点的“在本台”不能省略“在”，应说“我们在本台工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
