INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指说话者所属的电视台或广播电台。", "primary_collocate": null, "pronunciation": "běn tái", "ipa": "pən˨˩ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "听众朋友们，这里是本台的音乐节目。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台今晚十点播放晚安故事。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台的主持人正在直播间里和听众聊天。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台昨天收到了很多听众来信。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台将为您直播明天的足球比赛。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以上是本台的全部节目，再见。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台新来的记者在报道一场大火。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台的广播每天从早上六点开始。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本台邀请了一位医生来讲健康知识。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，本台刚才的声音出了问题。", "target_word": "本台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本台记者", "label": "复合"}, {"form": "本臺", "label": "繁体"}], "register": "书面", "sense_fingerprint": "说话者指自己所属的电视台或广播电台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本台", "is_correct": true, "explanation": "正确：“本台的音乐节目”指说话者所在电台的节目，句子通顺。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场不播出音乐节目，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“音乐节目”是电台或电视台播出的，不说“厨房的音乐节目”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不播音乐节目，与“这里是……”的说明不符。"}], "explanations": {"本台": "正确：“本台的音乐节目”指说话者所在电台的节目，句子通顺。", "菜市场": "语义：菜市场不播出音乐节目，句子不通。", "厨房": "搭配：“音乐节目”是电台或电视台播出的，不说“厨房的音乐节目”。", "图书馆": "语义：图书馆不播音乐节目，与“这里是……”的说明不符。"}, "sentence_index": 0, "correct_answer": "本台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本台今年的产量提高了百分之十。", "explanation": "这里应该用〈本厂〉。本台指电视台或广播台，不生产产品，不能说产量。"}, {"text": "本台今天打折，欢迎大家来买。", "explanation": "这里应该用〈本店〉。本台不卖东西，不能打折促销。"}, {"text": "本台的同学都很努力。", "explanation": "这里应该用〈本班〉。本台是机构，不是班级，不能说“本台的同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本台", "is_correct": true, "explanation": "正确：“本台新来的记者”指本台的记者，作主语通顺。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不会派记者报道大火。"}, {"text": "洗衣店", "is_correct": false, "explanation": "搭配：“记者”属于新闻机构，不与“洗衣店”搭配。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园与报道大火无关，句意不通。"}], "explanations": {"本台": "正确：“本台新来的记者”指本台的记者，作主语通顺。", "理发店": "语义：理发店不会派记者报道大火。", "洗衣店": "搭配：“记者”属于新闻机构，不与“洗衣店”搭配。", "动物园": "语义：动物园与报道大火无关，句意不通。"}, "sentence_index": 6, "correct_answer": "本台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本台今天的菜都很新鲜，欢迎来吃。", "explanation": "这里应该用〈本店〉。本台指电视台或广播台，不卖饭菜。"}, {"text": "本台的病人今天都出院了。", "explanation": "这里应该用〈本院〉。本台是电台或电视台，没有病人。"}, {"text": "本台的学生明天放假。", "explanation": "这里应该用〈本校〉。本台是电台或电视台，不是学校，没有学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个本台的记者正在采访市长。", "corrected_sentence": "本台的记者正在采访市长。", "error_description": "“本台”已经指说话者所在的电台，前面不能再加“一个”这样的数量词，应去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本台们的主持人很有名。", "corrected_sentence": "本台的主持人很有名。", "error_description": "“本台”是机构，不能加“们”表示复数；应说“本台的主持人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
