INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼下是在楼房的下面几层。", "primary_collocate": null, "pronunciation": "lóu xià", "ipa": "lou˧˥ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "我在楼下等你。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼下有一家小饭店。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住在楼下，我住在楼上。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在楼下买菜。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你到楼下来一下。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们去楼下的公园走走吧。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼下的小狗叫了一晚上。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在楼下玩儿。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的车停在楼下。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外面下雨了，你别在楼下站着。", "target_word": "楼下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "樓下", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在楼房下面几层的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楼下", "is_correct": true, "explanation": "正确：“楼下”指楼房下面的几层，可以用来说在那里等人。"}, {"text": "碗里", "is_correct": false, "explanation": "语义：人不能待在碗里等人，句意不通。"}, {"text": "水里", "is_correct": false, "explanation": "搭配：“等你”一般不说在水里，地点与动作不搭配。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：人不能待在书包里等人，与常识冲突。"}], "explanations": {"楼下": "正确：“楼下”指楼房下面的几层，可以用来说在那里等人。", "碗里": "语义：人不能待在碗里等人，句意不通。", "水里": "搭配：“等你”一般不说在水里，地点与动作不搭配。", "书包里": "语义：人不能待在书包里等人，与常识冲突。"}, "sentence_index": 0, "correct_answer": "楼下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河的楼下钓鱼。", "explanation": "“楼下”指楼房下面的几层，河边没有楼层，这里应该用〈河边〉。"}, {"text": "他的成绩排在楼下。", "explanation": "“楼下”指楼房下面的几层，不能用来表示名次靠后，这里应该用〈下面〉。"}, {"text": "这个小院没有楼，楼下很安静。", "explanation": "小院是平房，没有楼层，不能说楼下，这里应该用〈院子里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楼下", "is_correct": true, "explanation": "正确：“楼下”指楼房下面的几层，小狗可以在楼下叫。"}, {"text": "早上", "is_correct": false, "explanation": "语义：“早上”与“叫了一晚上”的时间相互矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "搭配：“中午”与“叫了一晚上”的时间范围不搭配。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底不会有小狗在叫，句意不通。"}], "explanations": {"楼下": "正确：“楼下”指楼房下面的几层，小狗可以在楼下叫。", "早上": "语义：“早上”与“叫了一晚上”的时间相互矛盾。", "中午": "搭配：“中午”与“叫了一晚上”的时间范围不搭配。", "海底": "语义：海底不会有小狗在叫，句意不通。"}, "sentence_index": 6, "correct_answer": "楼下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书包放在桌子的楼下。", "explanation": "“楼下”指楼房下面的几层，桌子不是楼房，这里应该用〈桌子下面〉。"}, {"text": "我们在大树的楼下乘凉。", "explanation": "大树没有楼层，不能用“楼下”，这里应该用〈树下〉。"}, {"text": "车子停在草地的楼下。", "explanation": "草地上没有楼房，不能说楼下，这里应该用〈草地上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹看书在楼下。", "corrected_sentence": "妹妹在楼下看书。", "error_description": "错误：表示动作地点的「在楼下」放在了动词后面。正确：「在楼下」要放在动词「看书」前面，应说「妹妹在楼下看书」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们踢球在楼下。", "corrected_sentence": "孩子们在楼下踢球。", "error_description": "错误：表示动作地点的「在楼下」放在了动词后面。正确：「在楼下」要放在「踢球」前面，应说「孩子们在楼下踢球」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
