INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼房下面的一层或几层。", "primary_collocate": null, "pronunciation": "lóu xià", "ipa": "lou˧˥ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "这座楼的楼下是商店。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼下是饭店，楼上是旅馆。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼下很大，楼上比较小。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院的楼下是药房。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在三楼，楼下是邻居。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼下两层都是办公室。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼下几层都是停车的地方。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼下人很多，楼上很安静。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店在这座楼的楼下。", "target_word": "楼下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "楼下已经租给一家银行了。", "target_word": "楼下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "樓下", "label": "繁体"}], "register": "口语", "sense_fingerprint": "楼房下面的一层或几层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楼下", "is_correct": true, "explanation": "正确：“楼下”指这座楼下面的楼层，可以放商店。"}, {"text": "碗里", "is_correct": false, "explanation": "语义：碗里不能是商店，句意不通。"}, {"text": "水里", "is_correct": false, "explanation": "搭配：“水里”与“商店”的地点关系不搭配。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：商店不能放在书包里，与常识冲突。"}], "explanations": {"楼下": "正确：“楼下”指这座楼下面的楼层，可以放商店。", "碗里": "语义：碗里不能是商店，句意不通。", "水里": "搭配：“水里”与“商店”的地点关系不搭配。", "书包里": "语义：商店不能放在书包里，与常识冲突。"}, "sentence_index": 0, "correct_answer": "楼下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在湖的楼下划船。", "explanation": "“楼下”指楼房下面的几层，湖上没有楼房，这里应该用〈湖面上〉。"}, {"text": "我们队这次比赛排在楼下。", "explanation": "“楼下”指楼房下面的几层，不能用来表示名次，这里应该用〈下面〉。"}, {"text": "这个平房没有楼，楼下很安静。", "explanation": "平房没有楼层，不能说楼下，这里应该用〈屋里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楼下", "is_correct": true, "explanation": "正确：“楼下”指楼房下面的几层，可以用来说停车的地方。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底没有楼层，也不能停车，句意不通。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天空中没有几层可以停车，句意不通。"}, {"text": "床底下", "is_correct": false, "explanation": "搭配：“停车的地方”与“床底下”不搭配，床底下不能停车。"}], "explanations": {"楼下": "正确：“楼下”指楼房下面的几层，可以用来说停车的地方。", "海底": "语义：海底没有楼层，也不能停车，句意不通。", "天上": "语义：天空中没有几层可以停车，句意不通。", "床底下": "搭配：“停车的地方”与“床底下”不搭配，床底下不能停车。"}, "sentence_index": 6, "correct_answer": "楼下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙丢在马路的楼下。", "explanation": "“楼下”指楼房下面的几层，马路上没有楼房，这里应该用〈马路上〉。"}, {"text": "这间木屋没有楼，楼下放着床。", "explanation": "木屋没有楼层，不能说楼下，这里应该用〈屋里〉。"}, {"text": "学生们在操场的楼下上体育课。", "explanation": "操场上没有楼房，不能说楼下，这里应该用〈操场上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店这座楼的楼下。", "corrected_sentence": "书店在这座楼的楼下。", "error_description": "错误：地点「这座楼的楼下」前面缺少动词「在」。正确：说某物的位置要用「在＋楼下」，应说「书店在这座楼的楼下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室楼下两层。", "corrected_sentence": "教室在楼下两层。", "error_description": "错误：地点「楼下两层」前面缺少动词「在」。正确：应说「教室在楼下两层」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "样本是从很多东西里拿出来的几个，让人看看是什么样子。", "primary_collocate": null, "pronunciation": "yàng běn", "ipa": "jɑŋ˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "店员给了我一份布料样本。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看一下这本样本，再决定买哪种。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要一份地砖的样本。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把样本寄给了客人。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个样本的颜色很好看。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙纸样本放在桌子上。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先拿一个样本回家看看。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了样本，很满意。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们免费送了我们几个样本。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些样本是新做的，请你试一试。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "樣本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "样本：拿出来给人看的样品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "样本", "is_correct": true, "explanation": "正确：样本指拿出来给人看的样品，这里是店员给的布料样品。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜用的说明，与布料无关，句子里说的是布料样品。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人的医疗记录，与布料样品无关。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“份”通常量具体的样品或资料，“一份尺寸”这种说法不自然，与“一份布料”的量词搭配不通。"}], "explanations": {"样本": "正确：样本指拿出来给人看的样品，这里是店员给的布料样品。", "食谱": "语义：食谱是做菜用的说明，与布料无关，句子里说的是布料样品。", "病历": "语义：病历是病人的医疗记录，与布料样品无关。", "尺寸": "搭配：“份”通常量具体的样品或资料，“一份尺寸”这种说法不自然，与“一份布料”的量词搭配不通。"}, "sentence_index": 0, "correct_answer": "样本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的样本很精神。", "explanation": "这里应该用〈样子〉。样本指拿出来给人看的样品，形容人的模样要用“样子”。"}, {"text": "这位老人的样本很健康。", "explanation": "这里应该用〈身体〉。样本指拿出来给人看的样品，人的身体状况要说“身体”。"}, {"text": "我买了一只样本。", "explanation": "量词用错。“只”用于动物或成对的东西，样品应该用“份”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "样本", "is_correct": true, "explanation": "正确：样本指拿来给人看的样品，可以拿一个回家看看。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是人，不能被“拿”回家看看。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“拿”的对象要是实物，“感冒”是病，不能说“拿感冒”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“拿”的对象要是具体的东西，“天气”是抽象概念，不能拿回家。"}], "explanations": {"样本": "正确：样本指拿来给人看的样品，可以拿一个回家看看。", "病人": "语义：病人是人，不能被“拿”回家看看。", "感冒": "搭配：“拿”的对象要是实物，“感冒”是病，不能说“拿感冒”。", "天气": "搭配：“拿”的对象要是具体的东西，“天气”是抽象概念，不能拿回家。"}, "sentence_index": 6, "correct_answer": "样本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的样本很可爱。", "explanation": "这里应该用〈样子〉。样本指拿出来给人看的样品，形容人的外貌要用“样子”。"}, {"text": "这台电脑的样本很快。", "explanation": "这里应该用〈速度〉。样本指拿出来给人看的样品，电脑运行快慢要说“速度”。"}, {"text": "他拿了一把样本。", "explanation": "量词用错。“把”用于有柄的器具，样品应该用“份”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店员拿了三只样本给我看。", "corrected_sentence": "店员拿了三份样本给我看。", "error_description": "量词错误：样本是可以拿给人看的样品，量词应用“份”。说“三只样本”错误，正确是“三份样本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板看了几样本，很满意。", "corrected_sentence": "老板看了几份样本，很满意。", "error_description": "量词缺失：“几”后面要加量词，应说“几份样本”，不能说“几样本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
