INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从总体中抽取出来用来代表整体的一部分。", "primary_collocate": null, "pronunciation": "yàng běn", "ipa": "jɑŋ˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次调查的样本有一千人。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "样本太少，结果不一定准。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从全校学生中选了一个样本。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个样本不能代表所有人。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者增加了样本的数量。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "样本要选得随机一些。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的样本来自三个城市。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "样本越大，结论越可靠。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用这个样本做了分析。", "target_word": "样本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员从这座城市随机抽取了一千人作为样本。", "target_word": "样本", "complexity_tier": "T3", "furigana": "yán jiū rén yuán cóng zhè zuò chéng shì suí jī chōu qǔ le yī qiān rén zuò wéi yàng běn", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "樣本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "样本：调查研究中代表整体的一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "样本", "is_correct": true, "explanation": "正确：样本指从总体中抽出、代表整体的一部分，这里指被调查的人。"}, {"text": "问卷", "is_correct": false, "explanation": "语义：问卷是一份表格，不是人，不能说“有一千人”。"}, {"text": "预算", "is_correct": false, "explanation": "搭配：预算是用钱计算的数额，计量用“元”，不用“人”，与“有一千人”不搭。"}, {"text": "题目", "is_correct": false, "explanation": "语义：题目是试题的内容，不是人，不能说“有一千人”。"}], "explanations": {"样本": "正确：样本指从总体中抽出、代表整体的一部分，这里指被调查的人。", "问卷": "语义：问卷是一份表格，不是人，不能说“有一千人”。", "预算": "搭配：预算是用钱计算的数额，计量用“元”，不用“人”，与“有一千人”不搭。", "题目": "语义：题目是试题的内容，不是人，不能说“有一千人”。"}, "sentence_index": 0, "correct_answer": "样本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次调查用了随机样本的方法。", "explanation": "这里应该用〈抽样〉。样本指被抽出的那部分对象，不能指抽取的方法，“……的方法”要用“抽样”。"}, {"text": "这项研究的样本是三个月。", "explanation": "这里应该用〈时间〉。样本指被抽出来代表整体的对象，不能指研究持续的时间长短。"}, {"text": "研究者选了一只样本。", "explanation": "量词用错。“只”不用来量抽取的调查对象，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "样本", "is_correct": true, "explanation": "正确：样本指被抽出、代表整体的对象，这里是来自三个城市的被调查对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会“来自”某个城市，与句子所指的对象不符。"}, {"text": "标题", "is_correct": false, "explanation": "语义：标题是文字，不能“来自三个城市”，与被调查的对象不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“来自”多用于人或物的来源，“价格”一般不说“来自某城市”。"}], "explanations": {"样本": "正确：样本指被抽出、代表整体的对象，这里是来自三个城市的被调查对象。", "天气": "语义：天气不会“来自”某个城市，与句子所指的对象不符。", "标题": "语义：标题是文字，不能“来自三个城市”，与被调查的对象不合。", "价格": "搭配：“来自”多用于人或物的来源，“价格”一般不说“来自某城市”。"}, "sentence_index": 6, "correct_answer": "样本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们做了一次样本，结果很准确。", "explanation": "这里应该用〈统计〉。样本是抽出的对象，不是行为，“做了一次”后要接动作。"}, {"text": "他们调查了一条样本。", "explanation": "量词用错。“条”用于细长的东西，抽取的调查对象应用〈个〉。"}, {"text": "我们进行了一次大规模的样本。", "explanation": "这里应该用〈调研〉。“进行一次大规模的……”要接行为，样本是名词，不能当行为来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只样本是随机抽取的。", "corrected_sentence": "这个样本是随机抽取的。", "error_description": "量词错误：这里的样本是被抽出的对象，应用量词“个”。说“这只样本”不对，正确是“这个样本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者选取了一样本。", "corrected_sentence": "研究者选取了一个样本。", "error_description": "量词缺失：“一”后面要加量词，应说“一个样本”，不能说“一样本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
