INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98435, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "次经是一些没有放进主要经书里的古书。", "primary_collocate": null, "pronunciation": "cì jīng", "ipa": "tsʰɨ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "次经是一些没有放进经书的古书。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有几篇次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有一本讲次经的书。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对次经很感兴趣。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天给我们讲次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很少有人知道次经的故事。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些古书后来叫次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店买了一本次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次经不在主要的经书里。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究次经需要读很多古书。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "没有收进主要经书的古书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次经", "is_correct": true, "explanation": "正确。“次经”指没有收进主要经书的古书，作句子主语，与定义相符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与书面的定义句不搭，而且意思也不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是古书，不能说“石头是一些古书”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是书，不能说“老师是一些古书”。"}], "explanations": {"次经": "正确。“次经”指没有收进主要经书的古书，作句子主语，与定义相符。", "玩意儿": "语域：“玩意儿”是口语词，与书面的定义句不搭，而且意思也不通。", "石头": "语义：石头不是古书，不能说“石头是一些古书”。", "老师": "语义：老师是人，不是书，不能说“老师是一些古书”。"}, "sentence_index": 0, "correct_answer": "次经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上吃了一碗次经。", "explanation": "这里应该用〈面条〉。“次经”是古书，不能吃，吃的是面条。"}, {"text": "我们学校新来了一位次经。", "explanation": "这里应该用〈老师〉。“次经”是古书，不是人，不能说“来了一位次经”。"}, {"text": "我每次遇到生词都查次经。", "explanation": "这里应该用〈字典〉。“次经”是没有收进主要经书的古书，不是工具书，不能用来查生词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次经", "is_correct": true, "explanation": "正确。“那些古书后来叫次经”，“次经”是这类古书的名称，与句意相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：古书不会被叫作咖啡，“咖啡”是饮品。"}, {"text": "地图", "is_correct": false, "explanation": "语义：古书不会被叫作地图，“地图”是另一类东西。"}, {"text": "张三", "is_correct": false, "explanation": "语义：“张三”是人名，不是一类古书的名称，句意不通。"}], "explanations": {"次经": "正确。“那些古书后来叫次经”，“次经”是这类古书的名称，与句意相符。", "咖啡": "语义：古书不会被叫作咖啡，“咖啡”是饮品。", "地图": "语义：古书不会被叫作地图，“地图”是另一类东西。", "张三": "语义：“张三”是人名，不是一类古书的名称，句意不通。"}, "sentence_index": 6, "correct_answer": "次经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写了一篇关于唐朝历史的次经。", "explanation": "这里应该用〈论文〉。“次经”是古书的一类，不是学术文章，不能说“写一篇次经”。"}, {"text": "报纸上登了一则次经。", "explanation": "这里应该用〈新闻〉。“次经”是古书，不是报道，报纸上登的是新闻。"}, {"text": "这本次经教我们做菜。", "explanation": "这里应该用〈食谱〉。“次经”是没有收进主要经书的古书，不教做菜，教做菜的是食谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我借了一张次经。", "corrected_sentence": "我借了一本次经。", "error_description": "错误：“一张次经”。正确：“一本次经”。“次经”是书，量词应用“本”，“张”多用于纸张、桌子等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他次经放进了书架。", "corrected_sentence": "他把次经放进了书架。", "error_description": "错误：“他次经放进了书架”。正确：“他把次经放进了书架”。“把”字句要用“把”引出被处置的“次经”，漏掉“把”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
