INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基督教中未被列入正典的圣经书卷。", "primary_collocate": null, "pronunciation": "cì jīng", "ipa": "tsʰɨ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "基督教的次经不在正典里。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天主教的圣经里有次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些教会不承认次经是正典。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过圣经，也读过次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次经没有列入基督教的正典。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本圣经后面附有次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师今天讲了次经里的故事。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新教的圣经通常没有次经。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次经是圣经里不算正典的书卷。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在教会学习次经的历史。", "target_word": "次经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "基督教里没有列入正典的圣经书卷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次经", "is_correct": true, "explanation": "正确。“基督教的次经不在正典里”，“次经”指未列入正典的圣经书卷，与句意相符。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不是圣经书卷，不能说“基督教的饺子不在正典里”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是书卷，与“正典”无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与书面的宗教表述不搭，而且意思不通。"}], "explanations": {"次经": "正确。“基督教的次经不在正典里”，“次经”指未列入正典的圣经书卷，与句意相符。", "饺子": "语义：饺子不是圣经书卷，不能说“基督教的饺子不在正典里”。", "冰箱": "语义：冰箱不是书卷，与“正典”无关。", "玩意儿": "语域：“玩意儿”是口语词，与书面的宗教表述不搭，而且意思不通。"}, "sentence_index": 0, "correct_answer": "次经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在教堂领受了次经。", "explanation": "这里应该用〈圣餐〉。“次经”是圣经书卷，不能被领受，领受的是圣餐。"}, {"text": "教会新来了一位次经。", "explanation": "这里应该用〈牧师〉。“次经”是书卷，不指人，新来的是牧师。"}, {"text": "教堂里大家一起唱次经。", "explanation": "这里应该用〈赞美诗〉。“次经”是书卷，不能用来唱，大家一起唱的是赞美诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次经", "is_correct": true, "explanation": "正确。“牧师今天讲了次经里的故事”，“次经”是书，“里的故事”与之搭配。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是书，“咳嗽里的故事”不成立。"}, {"text": "萝卜", "is_correct": false, "explanation": "搭配：“……里的故事”要求“里”前是书籍或作品，不能说萝卜里的故事。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机不是书，不能讲故事。"}], "explanations": {"次经": "正确。“牧师今天讲了次经里的故事”，“次经”是书，“里的故事”与之搭配。", "咳嗽": "语义：咳嗽不是书，“咳嗽里的故事”不成立。", "萝卜": "搭配：“……里的故事”要求“里”前是书籍或作品，不能说萝卜里的故事。", "洗衣机": "语义：洗衣机不是书，不能讲故事。"}, "sentence_index": 6, "correct_answer": "次经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在教会过次经。", "explanation": "这里应该用〈圣诞节〉。“过”后接节日，“次经”不是节日，应说“过圣诞节”。"}, {"text": "他在教会的院子里种了次经。", "explanation": "这里应该用〈树苗〉。“次经”是书卷，不能种，种的是树苗。"}, {"text": "他在教堂喝了一杯次经。", "explanation": "这里应该用〈葡萄酒〉。“次经”是书卷，不能喝，圣餐中喝的是葡萄酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们教会的图书馆有几张次经。", "corrected_sentence": "我们教会的图书馆有几本次经。", "error_description": "错误：“几张次经”。正确：“几本次经”。“次经”是书，应用量词“本”，“张”不用于书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "牧师次经放在圣经后面。", "corrected_sentence": "牧师把次经放在圣经后面。", "error_description": "错误：“牧师次经放在圣经后面”。正确：“牧师把次经放在圣经后面”。处置式要用“把”引出被处置的“次经”，漏掉“把”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
