INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98439, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "歌唱是用好听的声音把歌唱出来。", "primary_collocate": null, "pronunciation": "gē chàng", "ipa": "kɤ˥ ʈʂʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她用好听的声音歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，她在湖边轻轻地歌唱。", "target_word": "歌唱", "complexity_tier": "T3", "furigana": "yè lǐ tā zài hú biān qīng qīng de gē chàng", "sentence_source": "generated"}, {"text": "我不好意思在大家面前歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们围着火堆跳舞，也歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的鸟儿整天歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈一边做饭一边轻轻地歌唱。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在舞台上自由地歌唱着。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来没有在这么多人面前歌唱过。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站起来，开心地歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都希望你为我们歌唱。", "target_word": "歌唱", "complexity_tier": "T3", "furigana": "dà jiā dōu xī wàng nǐ wèi wǒ men gē chàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "歌唱着", "label": "体标"}, {"form": "歌唱了", "label": "体标"}, {"form": "歌唱过", "label": "体标"}, {"form": "歌唱家", "label": "复合"}], "register": "书面", "sense_fingerprint": "用好听的声音把歌唱出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌唱", "is_correct": true, "explanation": "“歌唱”是用声音唱歌，与“用好听的声音”相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭是伤心时发出的声音，与“好听的声音”相反。"}, {"text": "吼", "is_correct": false, "explanation": "搭配：“吼”是粗声大喊，不能与“好听的声音”搭配。"}, {"text": "尖叫", "is_correct": false, "explanation": "语义：尖叫声刺耳，与“好听的声音”的意思相反。"}], "explanations": {"歌唱": "“歌唱”是用声音唱歌，与“用好听的声音”相符。", "哭": "语义：哭是伤心时发出的声音，与“好听的声音”相反。", "吼": "搭配：“吼”是粗声大喊，不能与“好听的声音”搭配。", "尖叫": "语义：尖叫声刺耳，与“好听的声音”的意思相反。"}, "sentence_index": 0, "correct_answer": "歌唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在班会上歌唱了一份计划书。", "explanation": "这里应该用〈宣读〉。读计划书要念出来，“歌唱”只指用好听的声音唱，不能用于念文件。"}, {"text": "他在台上歌唱了一篇演讲稿。", "explanation": "这里应该用〈朗诵〉。演讲稿要念出来，不能用“歌唱”。"}, {"text": "同学们在晚会上歌唱了一把吉他。", "explanation": "这里应该用〈弹〉。吉他要弹奏，“歌唱”只用于人或鸟发出的声音，不能用于乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌唱", "is_correct": true, "explanation": "“歌唱”是用声音唱歌，在舞台上自由地唱，符合句意。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是做针线活，通常要带对象（如缝衣服），不用来描述舞台上的表演。"}, {"text": "打", "is_correct": false, "explanation": "配价：“打”要有受事宾语（如打球、打拳），句中没有，单独用“打着”不完整。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”一般接土、洞等对象，不用来描述舞台上的表演。"}], "explanations": {"歌唱": "“歌唱”是用声音唱歌，在舞台上自由地唱，符合句意。", "缝": "语义：“缝”是做针线活，通常要带对象（如缝衣服），不用来描述舞台上的表演。", "打": "配价：“打”要有受事宾语（如打球、打拳），句中没有，单独用“打着”不完整。", "挖": "搭配：“挖”一般接土、洞等对象，不用来描述舞台上的表演。"}, "sentence_index": 6, "correct_answer": "歌唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会议上歌唱了一份报告。", "explanation": "这里应该用〈做〉。做报告是用语言讲述，“歌唱”只指用好听的声音唱，不能用于报告。"}, {"text": "他每天都在书房里歌唱一本书。", "explanation": "这里应该用〈读〉。书要读，不用“歌唱”。"}, {"text": "他在教室里歌唱了一道数学题。", "explanation": "这里应该用〈解〉。解数学题要算出答案，“歌唱”只指用好听的声音唱，不能用于解题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位歌手好听的声音歌唱，很多人都爱听。", "corrected_sentence": "这位歌手用好听的声音歌唱，很多人都爱听。", "error_description": "缺失：方式状语前缺少介词“用”，应说“用好听的声音歌唱”，不能省去“用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天晚上都在家里轻轻地歌唱了。", "corrected_sentence": "他每天晚上都在家里轻轻地歌唱。", "error_description": "错误：“每天晚上”表示经常性的动作，不能用“了”表示完成。正确：应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
