INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发出有节奏、有旋律的声音唱歌。", "primary_collocate": null, "pronunciation": "gē chàng", "ipa": "kɤ˥ ʈʂʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们在教室里快乐地歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在树上歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在台上，大声歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一边走路一边歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢在河边歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上，同学们一起歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她歌唱了一个晚上，声音有点哑。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，鸟儿又开始歌唱了。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱在山上歌唱。", "target_word": "歌唱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐着歌唱，大家静静地听。", "target_word": "歌唱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歌唱着", "label": "体标"}, {"form": "歌唱了", "label": "体标"}, {"form": "歌唱过", "label": "体标"}, {"form": "歌唱家", "label": "复合"}], "register": "书面", "sense_fingerprint": "用有节奏有旋律的声音唱歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4524131-87bb-4ddd-a1bb-d43eeffdbef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌唱", "is_correct": true, "explanation": "“歌唱”是用有节奏的声音唱，与“快乐地”相符，描述孩子们在教室里高兴地唱歌。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣表示伤心，与“快乐地”的情绪相反。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”需要有参观的对象（如展馆），句中没有交代，单独用在这里不完整。"}, {"text": "发抖", "is_correct": false, "explanation": "语义：发抖多因寒冷或害怕，与“快乐地”的情绪不符。"}], "explanations": {"歌唱": "“歌唱”是用有节奏的声音唱，与“快乐地”相符，描述孩子们在教室里高兴地唱歌。", "哭泣": "语义：哭泣表示伤心，与“快乐地”的情绪相反。", "参观": "配价：“参观”需要有参观的对象（如展馆），句中没有交代，单独用在这里不完整。", "发抖": "语义：发抖多因寒冷或害怕，与“快乐地”的情绪不符。"}, "sentence_index": 0, "correct_answer": "歌唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板前歌唱这道数学题。", "explanation": "这里应该用〈讲解〉。讲解题目是用语言说明，“歌唱”只指用有节奏的声音唱，不能用于讲题。"}, {"text": "他在舞台上歌唱了一篇散文。", "explanation": "这里应该用〈朗诵〉。散文要念出来，不能用“歌唱”。"}, {"text": "她在班里歌唱了这件事的经过。", "explanation": "这里应该用〈叙述〉。讲述事情的经过要用“叙述”，“歌唱”只指用有节奏的声音唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌唱", "is_correct": true, "explanation": "“歌唱”是用声音唱，唱了很久，与“声音有点哑”的结果相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与声音沙哑没有因果关系，句意说不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：写字用的是手，与声音沙哑没有关系，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗东西不用嗓子，与“声音有点哑”没有因果关系，句意不通。"}], "explanations": {"歌唱": "“歌唱”是用声音唱，唱了很久，与“声音有点哑”的结果相符。", "游泳": "语义：游泳与声音沙哑没有因果关系，句意说不通。", "写": "语义：写字用的是手，与声音沙哑没有关系，句意不通。", "洗": "语义：洗东西不用嗓子，与“声音有点哑”没有因果关系，句意不通。"}, "sentence_index": 6, "correct_answer": "歌唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们歌唱课文。", "explanation": "这里应该用〈朗读〉。课文要朗读，不用“歌唱”。"}, {"text": "他在店里歌唱了新产品的功能。", "explanation": "这里应该用〈介绍〉。介绍产品功能是用语言说明，“歌唱”只指用有节奏的声音唱。"}, {"text": "他在操场上歌唱了一套体操动作。", "explanation": "这里应该用〈做〉。体操动作是用身体完成的，“歌唱”只指用有节奏的声音唱，不能用于动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟窗外歌唱，把我吵醒了。", "corrected_sentence": "小鸟在窗外歌唱，把我吵醒了。", "error_description": "缺失：地点状语“在窗外”前缺少介词“在”，应说“小鸟在窗外歌唱”，不能说“小鸟窗外歌唱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在湖边轻轻地歌唱了着，我们都听得很入迷。", "corrected_sentence": "他在湖边轻轻地歌唱着，我们都听得很入迷。", "error_description": "错误：“了”与“着”同时用在“歌唱”后。正确：表示动作正在进行只用“着”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d7b560-c8bd-48b0-bdf4-58b3e930c4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
