INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一件接一件地经过，经历了很多次或很长的时间。", "primary_collocate": null, "pronunciation": "lì jīng", "ipa": "li˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这座老桥历经三百年，还是很结实。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他历经几次失败，终于成功了。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家老店历经三代人，一直开到现在。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市历经多次战争，慢慢重新发展起来。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她历经了很多次考试，才找到这份工作。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书历经十年修改，才出版。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个家庭历经四次搬家，最后留在了上海。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路历经多次修理，今天还很好走。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家历经几次改革，变得越来越强。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇历经一次又一次的大水，还在这里。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "历经了", "label": "体标"}, {"form": "歷經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一件接一件、多次地经过，强调次数多、时间长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历经", "is_correct": true, "explanation": "正确：历经三百年，表示经过了漫长的岁月，句意通顺。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”后接舒适或快乐的事物，不能接“三百年”这样的时长。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”接责任或任务，不能接时间，句子不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得美好而观看，用在这里与老桥的结实无关，句意不合。"}], "explanations": {"历经": "正确：历经三百年，表示经过了漫长的岁月，句意通顺。", "享受": "搭配：“享受”后接舒适或快乐的事物，不能接“三百年”这样的时长。", "承担": "搭配：“承担”接责任或任务，不能接时间，句子不通。", "欣赏": "语义：“欣赏”指觉得美好而观看，用在这里与老桥的结实无关，句意不合。"}, "sentence_index": 0, "correct_answer": "历经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车历经了这座小城。", "explanation": "这里应该用〈经过〉。历经强调多次或长时间的艰难过程，火车路过一次不用历经。"}, {"text": "他昨天历经了一次面试。", "explanation": "这里应该用〈参加〉。历经用于多次或长时间的过程，一次面试只用参加。"}, {"text": "这家店历经了一次装修。", "explanation": "这里应该用〈进行〉。历经强调经受漫长或艰难的过程，一次装修要用进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历经", "is_correct": true, "explanation": "正确：历经四次搬家，表示经过了多次搬迁，句意通顺。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：“缺乏”表示没有某种东西，不能用来说明经历了搬家。"}, {"text": "吸引", "is_correct": false, "explanation": "搭配：“吸引”接人或注意力，不能接“四次搬家”，句子不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物品，与“四次搬家”的经历无关，句意不合。"}], "explanations": {"历经": "正确：历经四次搬家，表示经过了多次搬迁，句意通顺。", "缺乏": "语义：“缺乏”表示没有某种东西，不能用来说明经历了搬家。", "吸引": "搭配：“吸引”接人或注意力，不能接“四次搬家”，句子不通。", "装饰": "语义：“装饰”指美化物品，与“四次搬家”的经历无关，句意不合。"}, "sentence_index": 6, "correct_answer": "历经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他历经了一次愉快的旅行。", "explanation": "这里应该用〈享受〉。历经用于艰难的遭遇，愉快的旅行要用享受。"}, {"text": "我历经了一顿晚饭。", "explanation": "这里应该用〈吃〉。历经不能接“一顿晚饭”这类日常小事，应说吃了一顿晚饭。"}, {"text": "他历经了一件小礼物。", "explanation": "这里应该用〈收到〉。历经接的是艰难的经历，收到礼物要用收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年，她历经着多次手术，身体终于好转。", "corrected_sentence": "去年，她历经了多次手术，身体终于好转。", "error_description": "“着”用错：“去年”指已经过去的时间，“历经”表示已经经历，应用“了”，说“历经了”，不说“历经着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很历经许多困难，终于成功了。", "corrected_sentence": "他历经许多困难，终于成功了。", "error_description": "副词位置错误：“很”不能放在“历经”前，应直接说“历经许多困难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
