INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经历；亲身经过。", "primary_collocate": null, "pronunciation": "lì jīng", "ipa": "li˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "爷爷历经战争，一直不愿多说。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她历经苦难，却一直很乐观。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人历经风雨，什么都不怕。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他历经许多困难，还是笑着面对生活。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶历经那场大病，身体慢慢好了。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们历经风雨，才走到今天。", "target_word": "历经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他历经了人生的起起落落，变得很平静。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些历经灾难的人，都特别珍惜现在。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生历经多年辛苦，终于有了自己的医院。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师历经艰苦的岁月，所以特别爱帮助别人。", "target_word": "历经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "历经了", "label": "体标"}, {"form": "歷經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "亲身经历艰难的事，多接风雨、苦难、灾难等宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历经", "is_correct": true, "explanation": "正确：历经战争，表示亲身经过战乱，与“一直不愿多说”的语境相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得美好而观看，与战争的经历相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指以愉快的心情接受，与“不愿多说”的语境相矛盾。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”接责任或任务，不能接“战争”作宾语表示经历。"}], "explanations": {"历经": "正确：历经战争，表示亲身经过战乱，与“一直不愿多说”的语境相合。", "欣赏": "语义：“欣赏”指觉得美好而观看，与战争的经历相矛盾。", "享受": "语义：“享受”指以愉快的心情接受，与“不愿多说”的语境相矛盾。", "承担": "搭配：“承担”接责任或任务，不能接“战争”作宾语表示经历。"}, "sentence_index": 0, "correct_answer": "历经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车历经了那个路口。", "explanation": "这里应该用〈经过〉。历经强调亲身经受艰难的过程，公交车路过路口不用历经。"}, {"text": "他历经了一个好主意。", "explanation": "这里应该用〈想出〉。历经指亲身经过某件事，构思主意要用想出。"}, {"text": "我历经了一道新菜。", "explanation": "这里应该用〈尝到〉。历经指亲身经过某件事，品尝菜肴要用尝到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历经", "is_correct": true, "explanation": "正确：历经人生的起起落落，表示亲身经过各种波折，句意通顺。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”接物品或人，不能接“人生的起起落落”，句子不通。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”接建筑、设施等有形之物，不能接“人生的起起落落”，句子不通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”接货物等有形之物，不能接“人生的起起落落”，句子不通。"}], "explanations": {"历经": "正确：历经人生的起起落落，表示亲身经过各种波折，句意通顺。", "挑选": "搭配：“挑选”接物品或人，不能接“人生的起起落落”，句子不通。", "拆除": "搭配：“拆除”接建筑、设施等有形之物，不能接“人生的起起落落”，句子不通。", "搬运": "搭配：“搬运”接货物等有形之物，不能接“人生的起起落落”，句子不通。"}, "sentence_index": 6, "correct_answer": "历经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师历经了一封信。", "explanation": "这里应该用〈收到〉。历经指亲身经受艰难的事，收到信件要用收到。"}, {"text": "我们历经了一个谜语。", "explanation": "这里应该用〈猜出〉。历经指亲身经过某件事，解开谜语要用猜出。"}, {"text": "爱迪生历经了那盏电灯。", "explanation": "这里应该用〈发明〉。历经指亲身经过某件事，创造电灯要用发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年轻时，爷爷历经着许多战争，后来一直不愿多说。", "corrected_sentence": "年轻时，爷爷历经了许多战争，后来一直不愿多说。", "error_description": "“着”用错：“年轻时”指已经过去的时间，“历经”表示已经经历，应用“了”，说“历经了”，不说“历经着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老人很历经风雨，身体依然硬朗。", "corrected_sentence": "那位老人历经风雨，身体依然硬朗。", "error_description": "副词位置错误：“很”不能放在“历经”前，应直接说“历经风雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98445, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国营", "is_correct": true, "explanation": "反义：“民营”指普通人自己开办，“国营”指国家经营，二者相对。"}, {"text": "整洁", "is_correct": false, "explanation": "无关：“整洁”形容环境干净，与“民营”没有反义关系。"}, {"text": "孤独", "is_correct": false, "explanation": "无关：“孤独”形容人的心理状态，与“民营”不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度，与“民营”没有对应关系。"}], "correct_answer": "国营", "explanations": {"国营": "反义：“民营”指普通人自己开办，“国营”指国家经营，二者相对。", "整洁": "无关：“整洁”形容环境干净，与“民营”没有反义关系。", "孤独": "无关：“孤独”形容人的心理状态，与“民营”不构成反义。", "迅速": "无关：“迅速”形容速度，与“民营”没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
