INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98445, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "民营是由普通人自己开、自己管的，不是国家开的。", "primary_collocate": null, "pronunciation": "mín yíng", "ipa": "min˧˥ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家书店是民营的，不是国家开的。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸开了一家民营饭馆。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营商店的东西比较便宜。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一家民营医院，不是公立的。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营公司的人不太多。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去民营公司工作。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所学校是民营的。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营医院的病房很干净。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在民营工厂上班。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民营电影院很小。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民营企业", "label": "复合"}, {"form": "民营经济", "label": "复合"}, {"form": "民營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "民营：普通人自己开办、不是国家开的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民营", "is_correct": true, "explanation": "正确：民营指普通人自己开办、不是国家开的，与后半句的意思一致。"}, {"text": "公立", "is_correct": false, "explanation": "语义：公立指政府或国家办的，与“不是国家开的”矛盾。"}, {"text": "国营", "is_correct": false, "explanation": "语义：国营指国家经营，与“不是国家开的”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”多形容人的说话或性格，一般不说“书店是幽默的”。"}], "explanations": {"民营": "正确：民营指普通人自己开办、不是国家开的，与后半句的意思一致。", "公立": "语义：公立指政府或国家办的，与“不是国家开的”矛盾。", "国营": "语义：国营指国家经营，与“不是国家开的”矛盾。", "幽默": "搭配：“幽默”多形容人的说话或性格，一般不说“书店是幽默的”。"}, "sentence_index": 0, "correct_answer": "民营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的民营房间。", "explanation": "这里应该用〈私人〉。民营指普通人自己开办的经营，房间不是经营对象，应说“私人房间”。"}, {"text": "这是民营电话。", "explanation": "这里应该用〈公用〉。“公用电话”是公共设施，不是普通人开办的，不能说“民营电话”。"}, {"text": "这是民营的菜园。", "explanation": "这里应该用〈自家〉。菜园是自家的，不是开办经营的，不能用“民营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民营", "is_correct": true, "explanation": "正确：民营指普通人自己开办的，这里说这所学校是民间开办的。"}, {"text": "农用", "is_correct": false, "explanation": "语义：“农用”指用于农业，学校不能是农用的。"}, {"text": "矮胖", "is_correct": false, "explanation": "体貌：“矮胖”形容人或动物的体型，不能用于学校。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”形容人的态度，不能修饰学校。"}], "explanations": {"民营": "正确：民营指普通人自己开办的，这里说这所学校是民间开办的。", "农用": "语义：“农用”指用于农业，学校不能是农用的。", "矮胖": "体貌：“矮胖”形容人或动物的体型，不能用于学校。", "凶狠": "语义：“凶狠”形容人的态度，不能修饰学校。"}, "sentence_index": 6, "correct_answer": "民营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我的民营自行车。", "explanation": "这里应该用〈自己的〉。民营指普通人开办经营的店、公司等，个人的东西不是经营对象，不能说“民营”。"}, {"text": "这是一台民营电脑。", "explanation": "这里应该用〈家用〉。“家用”指供家里使用，民营指经营主体，电脑的用途要说“家用”。"}, {"text": "这首歌是民营的。", "explanation": "这里应该用〈民间〉。“民间歌曲”指流传在民间的歌，民营只修饰企业、机构，不能用来说歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐的小店很民营的。", "corrected_sentence": "我姐姐的小店是民营的。", "error_description": "“民营”是分类属性词，不能用“很”修饰，应说“我姐姐的小店是民营的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
