INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98446, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由民间个人或集体出资经营的。", "primary_collocate": null, "pronunciation": "mín yíng", "ipa": "min˧˥ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家民营医院的服务很好。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家民营企业工作。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营公司的老板是一位女士。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路是民营公司修的。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营企业为城市提供了很多工作。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所民营学校有两百名学生。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想开一家民营银行。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民营经济发展得很快。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多民营企业都在招人。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家民营工厂生产电子零件。", "target_word": "民营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民营企业", "label": "复合"}, {"form": "民营经济", "label": "复合"}, {"form": "民營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "民营：民间出资经营的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民营", "is_correct": true, "explanation": "正确：民营指民间出资经营，这里说这家医院是民间经营的。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能修饰医院。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”形容人的懒散状态，与医院的服务质量不搭。"}, {"text": "贵重", "is_correct": false, "explanation": "搭配：“贵重”多修饰物品，一般不说“贵重医院”。"}], "explanations": {"民营": "正确：民营指民间出资经营，这里说这家医院是民间经营的。", "聪明": "语义：“聪明”形容人的智力，不能修饰医院。", "慵懒": "语义：“慵懒”形容人的懒散状态，与医院的服务质量不搭。", "贵重": "搭配：“贵重”多修饰物品，一般不说“贵重医院”。"}, "sentence_index": 0, "correct_answer": "民营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的民营物品。", "explanation": "这里应该用〈私人〉。民营指企业、机构由民间出资经营，个人用品只能说“私人”。"}, {"text": "这是一种民营的艺术形式。", "explanation": "这里应该用〈民间〉。民营专指由民间出资经营的企业或机构，艺术形式不能说民营。"}, {"text": "我的民营作业做完了。", "explanation": "这里应该用〈课后〉。民营指企业、机构由民间出资经营，作业不能用民营修饰，应说“课后作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民营", "is_correct": true, "explanation": "正确：民营银行指民间出资经营的银行，这里是她想开的民间银行。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：“调皮”形容人或动物的淘气，不能修饰银行。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用于机构。"}, {"text": "含蓄", "is_correct": false, "explanation": "语义：“含蓄”形容说话或表达方式，不能修饰银行。"}], "explanations": {"民营": "正确：民营银行指民间出资经营的银行，这里是她想开的民间银行。", "调皮": "语义：“调皮”形容人或动物的淘气，不能修饰银行。", "高挑": "体貌：“高挑”形容人的身材，不能用于机构。", "含蓄": "语义：“含蓄”形容说话或表达方式，不能修饰银行。"}, "sentence_index": 6, "correct_answer": "民营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次民营聚会很热闹。", "explanation": "这里应该用〈家庭〉。民营专指企业、机构由民间出资经营，聚会不能说民营，应说“家庭聚会”。"}, {"text": "这笔钱来自民营财政。", "explanation": "这里应该用〈国家〉。财政归国家，不能说“民营财政”，民营指民间出资经营。"}, {"text": "这是他的民营爱好。", "explanation": "这里应该用〈个人〉。爱好属于个人，“民营”指企业或机构的出资经营，不能修饰爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司很民营的，规模很大。", "corrected_sentence": "这家公司是民营的，规模很大。", "error_description": "“民营”是分类属性词，不能用“很”修饰，应说“这家公司是民营的，规模很大。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家很民营医院的费用很低。", "corrected_sentence": "这家民营医院的费用很低。", "error_description": "“民营”是分类属性词，不能用“很”修饰，应去掉“很”，说“这家民营医院的费用很低。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
