INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汗是人热了或者跑了以后，从身体上流出来的水。", "primary_collocate": null, "pronunciation": "hàn", "ipa": "xan˥˩", "syllable_count": 1, "sentences": [{"text": "天太热了，他头上全是汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我出了一身汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用毛巾擦了擦脸上的汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天打球，汗一直往下流。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我擦汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗流进了我的眼睛。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在太阳底下干活，身上全是汗。", "target_word": "汗", "complexity_tier": "T3", "furigana": "tā zài tài yang dǐ xià gàn huó, shēn shàng quán shì hàn.", "sentence_source": "generated"}, {"text": "我的衣服上都是汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，他的汗滴在地上了。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑得很快，可是一点汗也没有。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一身汗", "label": "量词"}, {"form": "汗水", "label": "复合"}, {"form": "出汗", "label": "复合"}], "register": "中性", "sense_fingerprint": "人热或运动后从身上流出的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗（hàn）：人热或运动后从身上流出的水，即本义。"}, {"text": "寒", "is_correct": false, "explanation": "hán（第二声）与 hàn（第四声）声调不同，意思是寒冷，与出汗无关。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（第三声）与 hàn（第四声）声调不同，意思是大声叫。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 hàn 声母不同（f／h），意思是米饭、饭食。"}, {"text": "害", "is_correct": false, "explanation": "hài 与 hàn 韵母不同（ai／an），意思是伤害、害怕。"}], "explanations": {"汗": "汗（hàn）：人热或运动后从身上流出的水，即本义。", "寒": "hán（第二声）与 hàn（第四声）声调不同，意思是寒冷，与出汗无关。", "喊": "hǎn（第三声）与 hàn（第四声）声调不同，意思是大声叫。", "饭": "fàn 与 hàn 声母不同（f／h），意思是米饭、饭食。", "害": "hài 与 hàn 韵母不同（ai／an），意思是伤害、害怕。"}, "sentence_index": null, "correct_answer": "汗"}, "level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗：天热时头上出的汗水，与“天太热了”的原因相合。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪多在寒冷时下，与“天太热了”矛盾，不会“全是”在头上。"}, {"text": "血", "is_correct": false, "explanation": "语义：血不会因天热流出，与“天太热了”的原因不合。"}, {"text": "泪", "is_correct": false, "explanation": "搭配：泪流在脸颊上，不说“头上全是泪”。"}], "explanations": {"汗": "汗：天热时头上出的汗水，与“天太热了”的原因相合。", "雪": "语义：雪多在寒冷时下，与“天太热了”矛盾，不会“全是”在头上。", "血": "语义：血不会因天热流出，与“天太热了”的原因不合。", "泪": "搭配：泪流在脸颊上，不说“头上全是泪”。"}, "sentence_index": 0, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑完步，他喝了很多汗。", "explanation": "这里应该用〈水〉。汗是从皮肤排出的，不能喝，渴了要喝水。"}, {"text": "他哭得很伤心，汗一直往下流。", "explanation": "这里应该用〈眼泪〉。哭时流的是眼泪，汗是出汗时排出的。"}, {"text": "他打开水龙头，水管里流出了很多汗。", "explanation": "这里应该用〈水〉。汗是人身上排出的，水管里流出的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98449, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗（hàn）：人热或运动后从身上流出的水，即本义。"}, {"text": "含", "is_correct": false, "explanation": "hán（第二声）与 hàn（第四声）声调不同，意思是包含。"}, {"text": "办", "is_correct": false, "explanation": "bàn 与 hàn 声母不同（b／h），意思是办理、办事。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 hàn 声母不同（k／h），意思是观看。"}], "explanations": {"汗": "汗（hàn）：人热或运动后从身上流出的水，即本义。", "含": "hán（第二声）与 hàn（第四声）声调不同，意思是包含。", "办": "bàn 与 hàn 声母不同（b／h），意思是办理、办事。", "看": "kàn 与 hàn 声母不同（k／h），意思是观看。"}, "sentence_index": null, "correct_answer": "汗"}, "level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗：在太阳底下干活出的汗，与“太阳底下干活”相合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：太阳底下通常是晴天，雨与“太阳底下干活”的语境矛盾。"}, {"text": "霜", "is_correct": false, "explanation": "语义：霜在寒冷的清晨形成，与太阳底下干活的语境矛盾。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：脚印印在地面上，不说“身上全是脚印”。"}], "explanations": {"汗": "汗：在太阳底下干活出的汗，与“太阳底下干活”相合。", "雨": "语义：太阳底下通常是晴天，雨与“太阳底下干活”的语境矛盾。", "霜": "语义：霜在寒冷的清晨形成，与太阳底下干活的语境矛盾。", "脚印": "搭配：脚印印在地面上，不说“身上全是脚印”。"}, "sentence_index": 6, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上草地上有很多汗。", "explanation": "这里应该用〈露水〉。汗是人体皮肤排出的，草地上的水珠是露水。"}, {"text": "屋檐上的汗一滴一滴落下来。", "explanation": "这里应该用〈雨水〉。汗来自人体，不会从屋檐滴下，屋檐上落的是雨水。"}, {"text": "他的膝盖磕破了，流出了汗。", "explanation": "这里应该用〈血〉。汗是皮肤排出的液体，伤口流出的是血。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他干活以后出了一个汗。", "corrected_sentence": "他干活以后出了一身汗。", "error_description": "错误在于量词：“汗”要用“身”计量，说“一身汗”，不说“一个汗”。应改为“出了一身汗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爬完山，出得一身汗。", "corrected_sentence": "他爬完山，出了一身汗。", "error_description": "「出」与「一身汗」连用表示结果时要用「了」，此处用「得」不通。应说「出了一身汗」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
