INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体皮肤排出的液体。", "primary_collocate": null, "pronunciation": "hàn", "ipa": "xan˥˩", "syllable_count": 1, "sentences": [{"text": "汗是从皮肤里出来的。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在热的时候会出汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗有一点咸味。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤会排出汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我晚上睡觉出不出汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说汗能让身体凉下来。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手心里都是汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天出汗少，夏天出汗多。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡觉时头上有很多汗。", "target_word": "汗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后，他的皮肤上渗出了很多汗。", "target_word": "汗", "complexity_tier": "T3", "furigana": "yùn dòng hòu, tā de pí fū shàng shèn chū le hěn duō hàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "一身汗", "label": "量词"}, {"form": "汗水", "label": "复合"}, {"form": "冷汗", "label": "复合"}], "register": "中性", "sense_fingerprint": "人体皮肤排出的液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac4e9f2-af27-4930-b8ea-043df36a41fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗（hàn）：人体皮肤排出的液体，即本义。"}, {"text": "寒", "is_correct": false, "explanation": "hán（第二声）与 hàn（第四声）声调不同，意思是寒冷。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（第三声）与 hàn（第四声）声调不同，意思是大声叫。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 hàn 声母不同（f／h），意思是米饭。"}, {"text": "害", "is_correct": false, "explanation": "hài 与 hàn 韵母不同（ai／an），意思是伤害。"}], "explanations": {"汗": "汗（hàn）：人体皮肤排出的液体，即本义。", "寒": "hán（第二声）与 hàn（第四声）声调不同，意思是寒冷。", "喊": "hǎn（第三声）与 hàn（第四声）声调不同，意思是大声叫。", "饭": "fàn 与 hàn 声母不同（f／h），意思是米饭。", "害": "hài 与 hàn 韵母不同（ai／an），意思是伤害。"}, "sentence_index": null, "correct_answer": "汗"}, "level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗：皮肤汗腺排出的液体，与“从皮肤里出来”相合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨从天上落下，不从皮肤里出来，与句意矛盾。"}, {"text": "光", "is_correct": false, "explanation": "语义：光是发出来的，不会从皮肤里出来，与句意矛盾。"}, {"text": "泪", "is_correct": false, "explanation": "语义：泪是从眼睛里流出的，不是从皮肤里出来，与句意矛盾。"}], "explanations": {"汗": "汗：皮肤汗腺排出的液体，与“从皮肤里出来”相合。", "雨": "语义：雨从天上落下，不从皮肤里出来，与句意矛盾。", "光": "语义：光是发出来的，不会从皮肤里出来，与句意矛盾。", "泪": "语义：泪是从眼睛里流出的，不是从皮肤里出来，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哭的时候，他眼睛会流出汗。", "explanation": "这里应该用〈眼泪〉。汗来自皮肤的汗腺，眼睛里流出的是眼泪。"}, {"text": "我渴了，喝了一杯汗。", "explanation": "这里应该用〈水〉。汗是皮肤排出的液体，不能用来喝，渴了要喝水。"}, {"text": "他的伤口流出了汗。", "explanation": "这里应该用〈血〉。伤口流出的是血，汗是皮肤汗腺排出的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98450, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗（hàn）：人体皮肤排出的液体，即本义。"}, {"text": "含", "is_correct": false, "explanation": "hán（第二声）与 hàn（第四声）声调不同，意思是包含。"}, {"text": "办", "is_correct": false, "explanation": "bàn 与 hàn 声母不同（b／h），意思是办理。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 hàn 声母不同（k／h），意思是观看。"}], "explanations": {"汗": "汗（hàn）：人体皮肤排出的液体，即本义。", "含": "hán（第二声）与 hàn（第四声）声调不同，意思是包含。", "办": "bàn 与 hàn 声母不同（b／h），意思是办理。", "看": "kàn 与 hàn 声母不同（k／h），意思是观看。"}, "sentence_index": null, "correct_answer": "汗"}, "level_3": {"options": [{"text": "汗", "is_correct": true, "explanation": "汗：紧张时手心出的汗，与“紧张得”相合。"}, {"text": "血", "is_correct": false, "explanation": "语义：血不会因紧张而出现在手心，句意会变成受伤，与语境不合。"}, {"text": "灰", "is_correct": false, "explanation": "语义：灰尘不会因紧张出现在手心，与“紧张得”的原因矛盾。"}, {"text": "泪", "is_correct": false, "explanation": "搭配：泪流在脸上，不说“手心里都是泪”。"}], "explanations": {"汗": "汗：紧张时手心出的汗，与“紧张得”相合。", "血": "语义：血不会因紧张而出现在手心，句意会变成受伤，与语境不合。", "灰": "语义：灰尘不会因紧张出现在手心，与“紧张得”的原因矛盾。", "泪": "搭配：泪流在脸上，不说“手心里都是泪”。"}, "sentence_index": 6, "correct_answer": "汗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "清晨草地上挂着很多汗。", "explanation": "这里应该用〈露水〉。汗是人体皮肤排出的，草地上清晨挂的水珠是露水。"}, {"text": "下雨后，树叶上的汗一滴一滴落下来。", "explanation": "这里应该用〈雨水〉。汗来自人体，不会从树叶上滴下，树叶上落的是雨水。"}, {"text": "他说话的时候，嘴里流出了很多汗。", "explanation": "这里应该用〈口水〉。汗来自皮肤的汗腺，嘴里流出的是口水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天一直没有出了汗。", "corrected_sentence": "我今天一直没有出汗。", "error_description": "错误在于“没有”与“了”的搭配：否定未发生的动作时，“出汗”后不能加“了”。错误形式“没有出了汗”，正确形式“没有出汗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走了很久，出了一只汗。", "corrected_sentence": "他走了很久，出了一身汗。", "error_description": "错误在于量词：汗用“身”计量，说“一身汗”，不说“一只汗”。错误形式“出了一只汗”，正确形式“出了一身汗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f15b34-ab7e-4c19-b235-6f115843099d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "液体是可以流动的东西，比如水和牛奶。", "primary_collocate": null, "pronunciation": "yè tǐ", "ipa": "i̯e˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "牛奶和果汁都是液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤也是一种液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，不要让液体洒在书上。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "液体可以从高处流到低处。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里的液体是醋。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种液体很黏，像蜂蜜一样。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子破了，里面的液体流了出来。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子能装三百毫升液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用管子把液体吸了上来。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把液体打翻了。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "液体燃料", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以流动的东西，如水、牛奶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "液体：牛奶和果汁都是可以流动的液态物质，符合句意。"}, {"text": "固体", "is_correct": false, "explanation": "体貌：固体有固定的形状，与会流动的牛奶、果汁不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：牛奶和果汁不是石头，“石头”与句子的所指完全不同。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：牛奶和果汁是饮品，不是颜料，句子说它们“都是颜料”不成立。"}], "explanations": {"液体": "液体：牛奶和果汁都是可以流动的液态物质，符合句意。", "固体": "体貌：固体有固定的形状，与会流动的牛奶、果汁不符。", "石头": "语义：牛奶和果汁不是石头，“石头”与句子的所指完全不同。", "颜料": "语义：牛奶和果汁是饮品，不是颜料，句子说它们“都是颜料”不成立。"}, "sentence_index": 0, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用液体盖了一座房子。", "explanation": "这里应该用〈砖〉。盖房子要用砖这类有固定形状的材料，液体没有固定形状，不能用来盖房子。"}, {"text": "他用刀把液体切开了。", "explanation": "这里应该用〈固体〉。能用刀切开的是有固定形状的固体；液体没有固定形状，不能切。"}, {"text": "这扇窗户是用液体做的。", "explanation": "这里应该用〈玻璃〉。窗户要用玻璃这类固体材料做，液体没有固定形状，不能用来做窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "液体：杯子里的东西可以流出来，说明是液态物质，符合句意。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是固体，不会像液体那样流出来。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“流出来”说有形的物质，不说“声音流了出来”。"}, {"text": "硬币", "is_correct": false, "explanation": "体貌：硬币有固定的形状，不会流动。"}], "explanations": {"液体": "液体：杯子里的东西可以流出来，说明是液态物质，符合句意。", "木头": "语义：木头是固体，不会像液体那样流出来。", "声音": "搭配：“流出来”说有形的物质，不说“声音流了出来”。", "硬币": "体貌：硬币有固定的形状，不会流动。"}, "sentence_index": 6, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天读液体。", "explanation": "这里应该用〈书〉。读的是书、报纸这类文字材料，液体没有文字，不能读。"}, {"text": "他用液体把钉子敲进了木板。", "explanation": "这里应该用〈锤子〉。敲钉子要用锤子，液体不能用来敲打东西。"}, {"text": "妈妈不小心把液体摔碎了。", "explanation": "这里应该用〈碗〉。碗可以摔碎，液体没有固定形状，不能说“摔碎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上洒了一块液体。", "corrected_sentence": "桌上洒了一滩液体。", "error_description": "“一块液体”错误：“块”用于有固定形状的块状物，液体应用“滩”“滴”“瓶”等量词。应改为“一滩液体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一杯透明地液体倒进了碗里。", "corrected_sentence": "他把一杯透明的液体倒进了碗里。", "error_description": "“透明地液体”错误：修饰名词应用结构助词“的”，“地”用于修饰动词，应说“透明的液体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
