INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有一定体积但没有固定形状、可以流动的物质。", "primary_collocate": null, "pronunciation": "yè tǐ", "ipa": "i̯e˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "水是一种没有颜色的液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "液体会流动，没有固定的形状。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶液体是什么？", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把液体倒进了杯子里。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一些红色的液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰受热以后会变成液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种液体闻起来很香。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上不能带太多液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把液体放进瓶子，它就有了瓶子的形状。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有三瓶不同的液体。", "target_word": "液体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "液体燃料", "label": "复合"}], "register": "中性", "sense_fingerprint": "有体积、无固定形状、能流动的物质状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "液体：水是有一定体积、能流动的液态物质，符合“没有颜色的液体”。"}, {"text": "固体", "is_correct": false, "explanation": "语义：水是液体，不是固体，“固体”与句子所说的水的状态相矛盾。"}, {"text": "气体", "is_correct": false, "explanation": "语义：常温下的水是液态，“气体”说的是另一种物质状态，与“水”不符。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“颜料”本身带有颜色，不能说“没有颜色的颜料”。"}], "explanations": {"液体": "液体：水是有一定体积、能流动的液态物质，符合“没有颜色的液体”。", "固体": "语义：水是液体，不是固体，“固体”与句子所说的水的状态相矛盾。", "气体": "语义：常温下的水是液态，“气体”说的是另一种物质状态，与“水”不符。", "颜料": "搭配：“颜料”本身带有颜色，不能说“没有颜色的颜料”。"}, "sentence_index": 0, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空气是一种液体。", "explanation": "这里应该用〈流体〉。流体包括液体和气体；“液体”只指液态物质，空气是气体，不能称为液体。"}, {"text": "他把液体切成了小块。", "explanation": "这里应该用〈固体〉。能切成小块的是有固定形状的固体；液体没有固定形状，不能切。"}, {"text": "这把椅子是用液体做的。", "explanation": "这里应该用〈木头〉。椅子要用木头这类有固定形状的固体材料做，液体没有固定形状，不能用来做椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "液体：指有香味、可以闻的液态物质，符合“闻起来很香”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“闻起来”要求有气味的事物，不能说“声音闻起来很香”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”没有气味，不能用“闻起来很香”来形容。"}, {"text": "石头", "is_correct": false, "explanation": "语义：一般的石头没有香味，与“闻起来很香”相矛盾。"}], "explanations": {"液体": "液体：指有香味、可以闻的液态物质，符合“闻起来很香”。", "声音": "搭配：“闻起来”要求有气味的事物，不能说“声音闻起来很香”。", "颜色": "搭配：“颜色”没有气味，不能用“闻起来很香”来形容。", "石头": "语义：一般的石头没有香味，与“闻起来很香”相矛盾。"}, "sentence_index": 6, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上读液体。", "explanation": "这里应该用〈报纸〉。读的是报纸、书这类文字材料，液体没有文字，不能读。"}, {"text": "他用液体把木板钉在墙上。", "explanation": "这里应该用〈钉子〉。钉木板要用钉子这类工具，液体不能用来钉东西。"}, {"text": "他不小心把液体打碎了。", "explanation": "这里应该用〈杯子〉。杯子等有固定形状的器皿可以打碎，液体没有固定形状，不能说“打碎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只液体落在了纸上。", "corrected_sentence": "一滴液体落在了纸上。", "error_description": "“一只液体”错误：“只”用于动物或单个物件，液体的量词应用“滴”（或“瓶”“杯”）。应改为“一滴液体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一种很稠地液体。", "corrected_sentence": "这是一种很稠的液体。", "error_description": "“很稠地液体”错误：修饰名词应用“的”，“地”用于修饰动词，应说“很稠的液体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
