INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98453, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "湿地是有很多水、土很湿的地方，常常有鸟和小鱼。", "primary_collocate": null, "pronunciation": "shī dì", "ipa": "ʂʅ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "城外有一片大湿地，春天有很多鸟。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去湿地看鸟。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地里的水很浅，小鱼在草中游。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块湿地冬天也有水。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们穿着雨鞋走进湿地。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地的土很软，走路要小心。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的湿地里住着很多白鸟。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去湿地拍照片。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湿地离城市不远，常有人来看鸟。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地的草很高，鸟藏在里面。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "湿地公园", "label": "复合"}, {"form": "濕地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水多、土湿、有鸟和小鱼的自然地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地指水多、土地潮湿的自然地方。"}, {"text": "史地", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是历史和地理。"}, {"text": "石堤", "is_correct": false, "explanation": "shí dī 与 shī dì 两个音节声调都不同，意思是石头砌成的堤。"}, {"text": "实地", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是实际的地方。"}], "explanations": {"湿地": "正确：湿地指水多、土地潮湿的自然地方。", "史地": "shǐ（第三声）与 shī（第一声）声调不同，意思是历史和地理。", "石堤": "shí dī 与 shī dì 两个音节声调都不同，意思是石头砌成的堤。", "实地": "shí（第二声）与 shī（第一声）声调不同，意思是实际的地方。"}, "sentence_index": null, "correct_answer": "湿地"}, "level_3": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地是水多、有鸟栖息的自然地方，与“春天有很多鸟”相符。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场没有水，春天也不会有很多鸟，与后一分句矛盾。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川是冰雪覆盖的地方，不会是“春天有很多鸟”的景象。"}, {"text": "教室", "is_correct": false, "explanation": "量词与语义：“教室”是房间，不能用“一片”计量，也不是自然地带，与“有很多鸟”不合。"}], "explanations": {"湿地": "正确：湿地是水多、有鸟栖息的自然地方，与“春天有很多鸟”相符。", "停车场": "语义：停车场没有水，春天也不会有很多鸟，与后一分句矛盾。", "冰川": "语义：冰川是冰雪覆盖的地方，不会是“春天有很多鸟”的景象。", "教室": "量词与语义：“教室”是房间，不能用“一片”计量，也不是自然地带，与“有很多鸟”不合。"}, "sentence_index": 0, "correct_answer": "湿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间湿地冬天也有水。", "explanation": "量词错误：“间”用于房屋，湿地是大片土地，应说“片”或“块”。"}, {"text": "湿地里有很多人在等车。", "explanation": "这里应该用〈车站〉。湿地是含水多的自然地方，人们等车的地方要说“车站”。"}, {"text": "这片湿地今年没下雨，庄稼都干死了。", "explanation": "这里应该用〈旱地〉。湿地指含水多的土地，没有雨、庄稼干死说的是旱地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地是白鸟栖息的水边地带，与“住着很多白鸟”相符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是鸟的栖息地，与“住着很多白鸟”不合。"}, {"text": "海岸", "is_correct": false, "explanation": "搭配：“河边的海岸”不通，海岸指海洋的边缘。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库里不住鸟，与“住着很多白鸟”矛盾。"}], "explanations": {"湿地": "正确：湿地是白鸟栖息的水边地带，与“住着很多白鸟”相符。", "工厂": "语义：工厂不是鸟的栖息地，与“住着很多白鸟”不合。", "海岸": "搭配：“河边的海岸”不通，海岸指海洋的边缘。", "仓库": "语义：仓库里不住鸟，与“住着很多白鸟”矛盾。"}, "sentence_index": 6, "correct_answer": "湿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湿地里的麦子很高，鸟藏在里面。", "explanation": "这里应该用〈麦田〉。湿地是含水多的自然地方，种麦子的地要说“麦田”。"}, {"text": "那颗湿地的草很高，鸟藏在里面。", "explanation": "量词错误：“颗”用于粒状的小东西，湿地应说“片”或“块”。"}, {"text": "湿地里的果树很高，鸟藏在里面。", "explanation": "这里应该用〈果园〉。种果树的地方要说“果园”，湿地不是果园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只湿地边上长着很多芦苇。", "corrected_sentence": "这片湿地边上长着很多芦苇。", "error_description": "量词错误：“只”用于动物或单个物体，湿地是大片土地，应说“这片湿地”，不能说“这只湿地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了一条很美的湿地。", "corrected_sentence": "我们去了一片很美的湿地。", "error_description": "量词错误：“条”用于细长的东西，湿地是大片土地，应说“一片湿地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
