INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "常年积水或含水很多的土地。", "primary_collocate": null, "pronunciation": "shī dì", "ipa": "ʂʅ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这片湿地常年有水，不能盖房子。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定保护城东的湿地。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地能留住雨水，也能让空气更干净。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多地方的湿地越来越少了。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块湿地的面积有五百公顷。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护湿地，工厂搬到了别的地方。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地对城市的水很重要。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水把附近的土地变成了湿地。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在湿地旁边建了一个观鸟站。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨多，湿地里的水会变深。", "target_word": "湿地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "湿地公园", "label": "复合"}, {"form": "濕地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "常年积水或含水量很大的土地，需要保护", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61055a68-0e57-44de-a57b-c0b45d7280bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地指常年积水或含水很多的土地。"}, {"text": "实地", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是实际的地方。"}, {"text": "史地", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是历史和地理。"}, {"text": "石堤", "is_correct": false, "explanation": "shí dī 与 shī dì 两个音节声调都不同，意思是石头砌成的堤。"}], "explanations": {"湿地": "正确：湿地指常年积水或含水很多的土地。", "实地": "shí（第二声）与 shī（第一声）声调不同，意思是实际的地方。", "史地": "shǐ（第三声）与 shī（第一声）声调不同，意思是历史和地理。", "石堤": "shí dī 与 shī dì 两个音节声调都不同，意思是石头砌成的堤。"}, "sentence_index": null, "correct_answer": "湿地"}, "level_3": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地常年有水，因此不能盖房子，与后一分句相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干燥少水，不可能“常年有水”，与前一分句矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "量词与语义：“教室”是房间，不能用“片”计量，也不是常年积水的地方。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场不是常年积水的地方，与“常年有水”矛盾。"}], "explanations": {"湿地": "正确：湿地常年有水，因此不能盖房子，与后一分句相符。", "沙漠": "语义：沙漠干燥少水，不可能“常年有水”，与前一分句矛盾。", "教室": "量词与语义：“教室”是房间，不能用“片”计量，也不是常年积水的地方。", "操场": "语义：操场不是常年积水的地方，与“常年有水”矛盾。"}, "sentence_index": 0, "correct_answer": "湿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所湿地今年开放了。", "explanation": "量词错误：“所”用于学校、医院等机构，湿地是自然地域，应说“片”或“块”。"}, {"text": "这片湿地常年干燥，风很大。", "explanation": "这里应该用〈沙丘〉。湿地常年积水，不会常年干燥，“干燥、风很大”说的是沙丘。"}, {"text": "雨停后，路上全是湿地。", "explanation": "这里应该用〈泥水〉。湿地指常年积水的自然土地，雨后路上的积水和泥要说“泥水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿地", "is_correct": true, "explanation": "正确：湿地能储存雨水，对城市的水很重要。"}, {"text": "马路", "is_correct": false, "explanation": "语义：马路不储水，与“对城市的水很重要”不符。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室与城市的水关系不大，放在此处语境不合。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是供人游泳的人工设施，不能为城市储存、净化雨水。"}], "explanations": {"湿地": "正确：湿地能储存雨水，对城市的水很重要。", "马路": "语义：马路不储水，与“对城市的水很重要”不符。", "办公室": "语义：办公室与城市的水关系不大，放在此处语境不合。", "游泳池": "语义：游泳池是供人游泳的人工设施，不能为城市储存、净化雨水。"}, "sentence_index": 6, "correct_answer": "湿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天雨多，湿地里的庄稼长得更高了。", "explanation": "这里应该用〈田地〉。湿地是常年积水的自然地方，种庄稼的地要说“田地”。"}, {"text": "夏天雨多，这颗湿地里的水会变深。", "explanation": "量词错误：“颗”用于粒状的小东西，湿地应说“片”或“块”。"}, {"text": "夏天雨多，湿地里的电脑会变慢。", "explanation": "这里应该用〈办公室〉。湿地是自然的含水地域，放电脑的地方是办公室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有一座很大的湿地。", "corrected_sentence": "这里有一片很大的湿地。", "error_description": "量词错误：“座”多用于山、楼房等，不能用于湿地，湿地应说“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去过一所湿地。", "corrected_sentence": "我去过一片湿地。", "error_description": "量词错误：“一所湿地”应为“一片湿地”。“所”用于学校、医院等机构，湿地是自然地域，应用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5c5fa7-ed67-4d24-8873-971cab016d0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
