INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父亲。", "primary_collocate": null, "pronunciation": "bà", "ipa": "pa˥˩", "syllable_count": 1, "sentences": [{"text": "我爸是医生，我妈是老师。", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸，你今天几点回家？", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸每天早上跑步。", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爸在银行工作。", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你爸今天下班早吗？", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我妈做饭，我爸洗碗。", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明的爸来学校开会了。", "target_word": "爸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸是我最好的朋友。", "target_word": "爸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸，这个周末我们去公园吧。", "target_word": "爸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸给我买过一辆自行车。", "target_word": "爸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爸爸", "label": "重叠"}, {"form": "老爸", "label": "复合"}], "register": "口语", "sense_fingerprint": "爸：父亲的口语称呼，用来称呼或指自己和他人的父亲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爸", "is_correct": true, "explanation": "正确答案：爸（bà，第四声），指父亲的口语称呼。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 bà（第四声）声调不同，意思是数字八。"}, {"text": "把", "is_correct": false, "explanation": "bǎ（第三声）与 bà（第四声）声调不同，意思是介词“把”。"}, {"text": "拔", "is_correct": false, "explanation": "bá（第二声）与 bà（第四声）声调不同，意思是拔出。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 bà 声母不同（p 与 b），声调相同，意思是害怕。"}, {"text": "办", "is_correct": false, "explanation": "bàn 比 bà 多一个韵尾 n，声调相同，意思是办理。"}], "explanations": {"爸": "正确答案：爸（bà，第四声），指父亲的口语称呼。", "八": "bā（第一声）与 bà（第四声）声调不同，意思是数字八。", "把": "bǎ（第三声）与 bà（第四声）声调不同，意思是介词“把”。", "拔": "bá（第二声）与 bà（第四声）声调不同，意思是拔出。", "怕": "pà 与 bà 声母不同（p 与 b），声调相同，意思是害怕。", "办": "bàn 比 bà 多一个韵尾 n，声调相同，意思是办理。"}, "sentence_index": null, "correct_answer": "爸"}, "level_3": {"options": [{"text": "爸", "is_correct": true, "explanation": "正确：“我爸”指自己的父亲，与后句“我妈”并列。"}, {"text": "令尊", "is_correct": false, "explanation": "语域：“令尊”是敬称别人父亲的书面语，不能用来称呼自己的父亲。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生年纪还小，当不了医生。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不能工作，不可能是医生。"}], "explanations": {"爸": "正确：“我爸”指自己的父亲，与后句“我妈”并列。", "令尊": "语域：“令尊”是敬称别人父亲的书面语，不能用来称呼自己的父亲。", "小学生": "语义：小学生年纪还小，当不了医生。", "婴儿": "语义：婴儿还不能工作，不可能是医生。"}, "sentence_index": 0, "correct_answer": "爸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一只爸，他每天早上跑步。", "explanation": "量词错误：“爸”指人，量词要用“个”或“位”，“只”用于动物，这里不能说“一只爸”。"}, {"text": "王老师，爸，请您再讲一遍这道题。", "explanation": "称呼错误：“爸”只用于称呼自己的父亲，不能用来称呼老师。这里已经说了“王老师”，应删去“爸”。"}, {"text": "我爸正在坐月子，每天吃很多鸡蛋。", "explanation": "搭配错误：“坐月子”只用于产后的女性，“爸”不能作主语，这里应该用〈产妇〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98462, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爸", "is_correct": true, "explanation": "正确答案：爸（bà，第四声），指父亲的口语称呼。"}, {"text": "巴", "is_correct": false, "explanation": "bā（第一声）与 bà（第四声）声调不同，意思是巴（如巴士）。"}, {"text": "靶", "is_correct": false, "explanation": "bǎ（第三声）与 bà（第四声）声调不同，意思是靶子。"}, {"text": "半", "is_correct": false, "explanation": "bàn 比 bà 多一个韵尾 n，声调相同，意思是一半。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 比 bà 多一个韵尾 ng，声调相同，意思是厉害或棍棒。"}], "explanations": {"爸": "正确答案：爸（bà，第四声），指父亲的口语称呼。", "巴": "bā（第一声）与 bà（第四声）声调不同，意思是巴（如巴士）。", "靶": "bǎ（第三声）与 bà（第四声）声调不同，意思是靶子。", "半": "bàn 比 bà 多一个韵尾 n，声调相同，意思是一半。", "棒": "bàng 比 bà 多一个韵尾 ng，声调相同，意思是厉害或棍棒。"}, "sentence_index": null, "correct_answer": "爸"}, "level_3": {"options": [{"text": "爸", "is_correct": true, "explanation": "正确：“小明的爸”指小明的父亲，可以来学校开会。"}, {"text": "家父", "is_correct": false, "explanation": "语域：“家父”是对外人谦称自己的父亲，不能用来指小明的父亲。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会来学校开会。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会来学校开会，与“开会”不搭。"}], "explanations": {"爸": "正确：“小明的爸”指小明的父亲，可以来学校开会。", "家父": "语域：“家父”是对外人谦称自己的父亲，不能用来指小明的父亲。", "猫": "语义：猫不会来学校开会。", "汽车": "语义：汽车不会来学校开会，与“开会”不搭。"}, "sentence_index": 6, "correct_answer": "爸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸比我大两岁，我们经常一起打篮球。", "explanation": "词义错误：“爸”只指父亲，不能指比自己大的同辈。这里应该用〈哥哥〉。"}, {"text": "我爸今年五岁，正在上幼儿园。", "explanation": "词义错误：五岁的孩子不可能是父亲，这里应该用〈弟弟〉。"}, {"text": "我爸是班上最高的同学，他坐在我后面。", "explanation": "词义错误：“爸”只指父亲，不能指班上的其他人，这里应该用〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸我正在厨房做饭。", "corrected_sentence": "我爸正在厨房做饭。", "error_description": "语序错误：“我”修饰“爸”，应说“我爸”，不能颠倒成“爸我”。正确说法是“我爸正在厨房做饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸们在公园散步。", "corrected_sentence": "我爸在公园散步。", "error_description": "错误形式：“我爸们”；正确形式：“我爸”。“我爸”只指一个人（自己的父亲），不能加“们”。正确说法是“我爸在公园散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
