INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牛肉是牛身上的肉，可以做成菜来吃。", "primary_collocate": null, "pronunciation": "niú ròu", "ipa": "niou˧˥ ʐou˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶把牛肉放进锅里煮着。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把牛肉煮了一个小时。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘牛肉煮得很软，孩子们都爱吃。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有一块牛肉。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从来没吃过生牛肉。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉要先洗干净，再下锅。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用牛肉和土豆做了晚饭。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛肉煮着吃最香。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥最喜欢吃烤牛肉。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把牛肉分给了大家。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "斤", "label": "量词"}], "register": "中性", "sense_fingerprint": "牛身上的肉，常用来煮着吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牛肉", "is_correct": true, "explanation": "牛肉：牛身上的肉，可以放进锅里煮，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能放进锅里煮着吃。"}, {"text": "牛仔裤", "is_correct": false, "explanation": "搭配：放进锅里煮的应是食材，“牛仔裤”不能煮着吃。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能煮来吃，与“煮着”的语境不符。"}], "explanations": {"牛肉": "牛肉：牛身上的肉，可以放进锅里煮，符合句意。", "书": "语义：书不能放进锅里煮着吃。", "牛仔裤": "搭配：放进锅里煮的应是食材，“牛仔裤”不能煮着吃。", "石头": "语义：石头不能煮来吃，与“煮着”的语境不符。"}, "sentence_index": 0, "correct_answer": "牛肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套是用牛肉做的。", "explanation": "这里应该用〈牛皮〉。外套是用牛皮做的，牛肉是食物，不能用来做衣服。"}, {"text": "草地上有一群牛肉。", "explanation": "这里应该用〈牛〉。“牛”指活的动物，“牛肉”只指肉，草地上不会有牛肉在活动。"}, {"text": "工厂用牛肉发电。", "explanation": "这里应该用〈煤〉。发电常用煤、水等燃料，牛肉是食物，不能用来发电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛肉", "is_correct": true, "explanation": "牛肉：是可以用来做菜的食材，符合句意。"}, {"text": "牛皮", "is_correct": false, "explanation": "语义：牛皮不是食材，不能用来做晚饭。"}, {"text": "牛棚", "is_correct": false, "explanation": "语义：牛棚是建筑，不是食材，不能用来做饭。"}, {"text": "白纸", "is_correct": false, "explanation": "搭配：做饭用的是食材，“白纸”与“做晚饭”不搭配。"}], "explanations": {"牛肉": "牛肉：是可以用来做菜的食材，符合句意。", "牛皮": "语义：牛皮不是食材，不能用来做晚饭。", "牛棚": "语义：牛棚是建筑，不是食材，不能用来做饭。", "白纸": "搭配：做饭用的是食材，“白纸”与“做晚饭”不搭配。"}, "sentence_index": 6, "correct_answer": "牛肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明把牛肉读给了大家听。", "explanation": "这里应该用〈书〉。读给别人听的是书、故事这类文字内容，牛肉不能读。"}, {"text": "他用牛肉把木板钉在墙上。", "explanation": "这里应该用〈钉子〉。钉木板要用钉子这类工具，牛肉是食物，不能用来钉东西。"}, {"text": "宝宝每天都喝牛肉。", "explanation": "这里应该用〈牛奶〉。牛奶是可以喝的液体，牛肉是固体，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只牛肉煮烂了才好吃。", "corrected_sentence": "这块牛肉煮烂了才好吃。", "error_description": "“这只牛肉”错误：“只”用于动物或单个物件，牛肉的量词应用“块”。应改为“这块牛肉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用新鲜地牛肉做了晚饭。", "corrected_sentence": "她用新鲜的牛肉做了晚饭。", "error_description": "“新鲜地牛肉”错误：修饰名词时应用结构助词“的”，“地”用于修饰动词，应说“新鲜的牛肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
