INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牛的肉，可食用。", "primary_collocate": null, "pronunciation": "niú ròu", "ipa": "niou˧˥ ʐou˥˩", "syllable_count": 2, "sentences": [{"text": "我今天在市场买了两斤牛肉。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的牛肉很新鲜。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不吃猪肉，只吃牛肉和鱼。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用牛肉做了一碗汤。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉切成小块再放进锅里。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块牛肉太硬了，我咬不动。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉比鸡肉贵一些。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点了一份牛肉和一杯茶。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的牛肉今天打八折。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们晚饭想吃牛肉，不想吃鱼。", "target_word": "牛肉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "斤", "label": "量词"}], "register": "中性", "sense_fingerprint": "牛身上可以食用的肉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牛肉", "is_correct": true, "explanation": "牛肉：可食用的牛肉，市场上可以按斤买，符合句意。"}, {"text": "牛仔裤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，裤子应按“条”计，不能说“两斤牛仔裤”。"}, {"text": "牛车", "is_correct": false, "explanation": "语义：牛车是交通工具，不是可以在市场按斤买的东西。"}, {"text": "牛棚", "is_correct": false, "explanation": "语义：牛棚是牛住的地方，是建筑，不能在市场按斤买。"}], "explanations": {"牛肉": "牛肉：可食用的牛肉，市场上可以按斤买，符合句意。", "牛仔裤": "搭配：“斤”是重量单位，裤子应按“条”计，不能说“两斤牛仔裤”。", "牛车": "语义：牛车是交通工具，不是可以在市场按斤买的东西。", "牛棚": "语义：牛棚是牛住的地方，是建筑，不能在市场按斤买。"}, "sentence_index": 0, "correct_answer": "牛肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们农场养了十头牛肉。", "explanation": "这里应该用〈牛〉。“牛”指活的动物，“牛肉”只指肉，不能用来说养的动物。"}, {"text": "工厂用牛肉发电。", "explanation": "这里应该用〈煤〉。发电常用煤、水等燃料，牛肉是食物，不能用来发电。"}, {"text": "他每天早上喝牛肉。", "explanation": "这里应该用〈牛奶〉。牛奶是可以喝的液体，牛肉是固体，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛肉", "is_correct": true, "explanation": "牛肉：是可以买卖的食品，可以和鸡肉比较价格，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是商品，不能用来与鸡肉比较价格。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是商品，不能与鸡肉比价。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“比……贵”比较的是可以买卖的物品，“颜色”不能这样比较。"}], "explanations": {"牛肉": "牛肉：是可以买卖的食品，可以和鸡肉比较价格，符合句意。", "空气": "语义：空气不是商品，不能用来与鸡肉比较价格。", "声音": "语义：声音不是商品，不能与鸡肉比价。", "颜色": "搭配：“比……贵”比较的是可以买卖的物品，“颜色”不能这样比较。"}, "sentence_index": 6, "correct_answer": "牛肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋是用牛肉做的。", "explanation": "这里应该用〈牛皮〉。鞋子是用牛皮做的，牛肉是食物，不能用来做鞋。"}, {"text": "果农在树上摘牛肉。", "explanation": "这里应该用〈苹果〉。摘的是树上的果实，牛肉是肉，不能从树上摘。"}, {"text": "做蛋糕时要放一些牛肉。", "explanation": "这里应该用〈黄油〉。做蛋糕常用黄油这类油脂，牛肉是肉，不用于蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只牛肉。", "corrected_sentence": "我买了一块牛肉。", "error_description": "“一只牛肉”错误：“只”用于动物或单个物件，牛肉的量词应用“块”（或“斤”）。应说“一块牛肉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他切了一块很厚地牛肉。", "corrected_sentence": "他切了一块很厚的牛肉。", "error_description": "“很厚地牛肉”错误：修饰名词应用结构助词“的”，“地”用于修饰动词，应说“很厚的牛肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
