INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "狗年是十二生肖里属狗的那一年。", "primary_collocate": null, "pronunciation": "gǒu nián", "ipa": "kou˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年是狗年。", "target_word": "狗年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我是狗年出生的。", "target_word": "狗年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年是狗年，明年是猪年。", "target_word": "狗年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "2018年是狗年。", "target_word": "狗年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我奶奶生在狗年，她属狗。", "target_word": "狗年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗年的春节，我们全家去旅行。", "target_word": "狗年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十二生肖里，狗年在鸡年后面。", "target_word": "狗年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥是狗年生的，我是猪年生的。", "target_word": "狗年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下一个狗年是2030年。", "target_word": "狗年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "狗年出生的孩子都属狗。", "target_word": "狗年", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "狗年：十二生肖中轮到属狗的那一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狗年", "is_correct": true, "explanation": "正确：“今年是狗年”，狗年指十二生肖中属狗的那一年。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”与“今年”矛盾，今年不能是去年。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是日子，不是年份，与“今年”矛盾。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“是”后面接年份时要用生肖年的名称，春节是节日，不说“今年是春节”。"}], "explanations": {"狗年": "正确：“今年是狗年”，狗年指十二生肖中属狗的那一年。", "去年": "语义：“去年”与“今年”矛盾，今年不能是去年。", "明天": "语义：“明天”是日子，不是年份，与“今年”矛盾。", "春节": "搭配：“是”后面接年份时要用生肖年的名称，春节是节日，不说“今年是春节”。"}, "sentence_index": 0, "correct_answer": "狗年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "狗年在门口摇着尾巴。", "explanation": "词义错误：“狗年”指年份，不是动物，不会摇尾巴；这里应该用〈小狗〉。"}, {"text": "我家来了一只狗年。", "explanation": "词义错误：“狗年”是时间，不是动物，不能说“来了一只狗年”；这里应该用〈小狗〉。"}, {"text": "我家的狗年很可爱，每天陪我散步。", "explanation": "词义错误：“狗年”指年份，不是动物，不会陪人散步；这里应该用〈小狗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狗年", "is_correct": true, "explanation": "正确：十二生肖的顺序中，狗排在鸡之后。"}, {"text": "猴年", "is_correct": false, "explanation": "语义：十二生肖中猴排在鸡之前，猴年不在鸡年后面。"}, {"text": "马年", "is_correct": false, "explanation": "语义：十二生肖中马排在鸡之前，马年不在鸡年后面。"}, {"text": "鸡年", "is_correct": false, "explanation": "搭配：“在……后面”要求两个不同的生肖，“鸡年”不能排在自己后面。"}], "explanations": {"狗年": "正确：十二生肖的顺序中，狗排在鸡之后。", "猴年": "语义：十二生肖中猴排在鸡之前，猴年不在鸡年后面。", "马年": "语义：十二生肖中马排在鸡之前，马年不在鸡年后面。", "鸡年": "搭配：“在……后面”要求两个不同的生肖，“鸡年”不能排在自己后面。"}, "sentence_index": 6, "correct_answer": "狗年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去狗年旅行。", "explanation": "搭配错误：“去”后面要接地点，“狗年”是年份，不能作目的地。"}, {"text": "我把狗年送给了朋友。", "explanation": "搭配错误：“狗年”是时间，不能像物品一样送人。"}, {"text": "我和狗年一起吃了晚饭。", "explanation": "搭配错误：“一起吃饭”的对象要是人，“狗年”是时间，不能作同伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "狗年了来，大家都很高兴。", "corrected_sentence": "狗年来了，大家都很高兴。", "error_description": "语序错误：“了”应紧跟在动词“来”之后，正确说法是“狗年来了”，不能说“狗年了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个狗年们我都过得很开心。", "corrected_sentence": "这几个狗年我都过得很开心。", "error_description": "多余的“们”：“们”只加在指人的名词后面，“狗年”是时间词，不能说“狗年们”。正确说法是“这几个狗年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
