INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98473, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生死是活着和死去。", "primary_collocate": null, "pronunciation": "shēng sǐ", "ipa": "ʂɤŋ˥ sɹ̩˨˩", "syllable_count": 2, "sentences": [{"text": "生死是每个人都会想到的问题。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在乎自己的生死，只想救别人。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是爱情和生死。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震中，很多人在生死之间做了选择。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把生死看得很平静。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术决定了病人的生死。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生死的话题让孩子有点害怕。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员常常在生死边缘工作。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了很多人的生死故事。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在战争中一起经历了生死。", "target_word": "生死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生死线", "label": "复合"}, {"form": "生死之交", "label": "复合"}], "register": "通用", "sense_fingerprint": "活着和死去这一对人生的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生死", "is_correct": true, "explanation": "正确答案：生死（shēng sǐ），指活着和死去这一对人生状态。"}, {"text": "声势", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同（sh 与 s），声调也不同，意思是声势、气势。"}, {"text": "生子", "is_correct": false, "explanation": "zǐ（第三声）与 sǐ（第三声）声调相同，声母 z 与 s 不同，意思是生育子女。"}, {"text": "胜似", "is_correct": false, "explanation": "shèng（第四声）与 shēng 只差声调，sì（第四声）与 sǐ（第三声）只差声调，意思是胜过。"}, {"text": "生食", "is_correct": false, "explanation": "shí 与 sǐ 声母和声调都不同，意思是生的食物，不是生死。"}], "explanations": {"生死": "正确答案：生死（shēng sǐ），指活着和死去这一对人生状态。", "声势": "shì（第四声）与 sǐ（第三声）声母不同（sh 与 s），声调也不同，意思是声势、气势。", "生子": "zǐ（第三声）与 sǐ（第三声）声调相同，声母 z 与 s 不同，意思是生育子女。", "胜似": "shèng（第四声）与 shēng 只差声调，sì（第四声）与 sǐ（第三声）只差声调，意思是胜过。", "生食": "shí 与 sǐ 声母和声调都不同，意思是生的食物，不是生死。"}, "sentence_index": null, "correct_answer": "生死"}, "level_3": {"options": [{"text": "生死", "is_correct": true, "explanation": "“生死”指活着与死去，能作主语，符合“是每个人都会想到的问题”的句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观特征，不是人人都会深入思考的根本问题。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的组成部分，与“每个人都会想到的问题”的含义不相符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西、小物件，不是每个人都会思考的人生问题。"}], "explanations": {"生死": "“生死”指活着与死去，能作主语，符合“是每个人都会想到的问题”的句意。", "颜色": "语义：颜色是事物的外观特征，不是人人都会深入思考的根本问题。", "窗户": "语义：窗户是建筑的组成部分，与“每个人都会想到的问题”的含义不相符。", "玩意儿": "语义：“玩意儿”指东西、小物件，不是每个人都会思考的人生问题。"}, "sentence_index": 0, "correct_answer": "生死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震让很多人失去了生死。", "explanation": "这里应该用〈性命〉。“生死”指活着和死去的状况，不指人的性命；说“失去性命”才符合习惯。"}, {"text": "他的生死很健康。", "explanation": "这里应该用〈身体〉。“生死”指活着与死去，不指身体状况；形容身体好坏要说“身体”。"}, {"text": "这次事故的生死很严重。", "explanation": "这里应该用〈后果〉。“生死”不表示事情造成的结果；说事故的后果严重要用“后果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98473, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生死", "is_correct": true, "explanation": "正确答案：生死（shēng sǐ），指活着和死去这一对人生状态。"}, {"text": "生字", "is_correct": false, "explanation": "zì（第四声）与 sǐ（第三声）声母不同，声调也不同，意思是生字（新学的汉字）。"}, {"text": "盛世", "is_correct": false, "explanation": "shèng 与 shēng 声调不同，shì 与 sǐ 声母和声调都不同，意思是繁荣的时代。"}, {"text": "省市", "is_correct": false, "explanation": "shěng 与 shēng 声调不同，shì 与 sǐ 声母和声调都不同，意思是省和市。"}, {"text": "生事", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同，声调也不同，意思是惹事、找麻烦。"}, {"text": "生丝", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）只差声调，意思是没有加工过的蚕丝。"}], "explanations": {"生死": "正确答案：生死（shēng sǐ），指活着和死去这一对人生状态。", "生字": "zì（第四声）与 sǐ（第三声）声母不同，声调也不同，意思是生字（新学的汉字）。", "盛世": "shèng 与 shēng 声调不同，shì 与 sǐ 声母和声调都不同，意思是繁荣的时代。", "省市": "shěng 与 shēng 声调不同，shì 与 sǐ 声母和声调都不同，意思是省和市。", "生事": "shì（第四声）与 sǐ（第三声）声母不同，声调也不同，意思是惹事、找麻烦。", "生丝": "sī（第一声）与 sǐ（第三声）只差声调，意思是没有加工过的蚕丝。"}, "sentence_index": null, "correct_answer": "生死"}, "level_3": {"options": [{"text": "生死", "is_correct": true, "explanation": "“生死”是人生大事，能与“的话题”构成名词短语作主语，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会让孩子害怕，“颜色的话题让孩子害怕”句意荒谬。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一日三餐之一，“早餐的话题”不会让孩子有这样的感受。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“乐谱”是音乐用的记录，不能说“乐谱的话题让孩子害怕”，搭配不当。"}], "explanations": {"生死": "“生死”是人生大事，能与“的话题”构成名词短语作主语，符合句意。", "颜色": "语义：颜色不会让孩子害怕，“颜色的话题让孩子害怕”句意荒谬。", "早餐": "语义：早餐是一日三餐之一，“早餐的话题”不会让孩子有这样的感受。", "乐谱": "搭配：“乐谱”是音乐用的记录，不能说“乐谱的话题让孩子害怕”，搭配不当。"}, "sentence_index": 6, "correct_answer": "生死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在战争中的生死很艰苦。", "explanation": "这里应该用〈生活〉。“生死”指活着与死去，不指生活的艰苦程度；描述生活条件要用“生活”。"}, {"text": "这台机器的生死很长。", "explanation": "这里应该用〈寿命〉。“生死”指活着和死去，不用来说物体的使用年限；机器能用多久要用“寿命”。"}, {"text": "他们在战争中一起躲开了生死。", "explanation": "这里应该用〈死亡〉。“生死”是生存与死亡的合称，不能作“躲开”的对象；躲开危险要说“躲开死亡”或“避开危险”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在生死关键救了战友。", "corrected_sentence": "他在生死关头救了战友。", "error_description": "用词错误：“生死关头”是固定说法，“关头”不能换成“关键”，应写“他在生死关头救了战友。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在战争中经历过一把生死。", "corrected_sentence": "他们在战争中经历过一次生死。", "error_description": "错误：量词“把”只用于有柄的器具，不能修饰“生死”。应改为“一次”：“经历过一次生死”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胖", "is_correct": true, "explanation": "胖与瘦是反义词，《现代汉语词典》有此对应，指身体肉多。"}, {"text": "高", "is_correct": false, "explanation": "高说身材或位置的高低，与瘦不构成反义关系。"}, {"text": "硬", "is_correct": false, "explanation": "硬说质地坚实，与瘦没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快与慢相对，与瘦无关。"}], "correct_answer": "胖", "explanations": {"胖": "胖与瘦是反义词，《现代汉语词典》有此对应，指身体肉多。", "高": "高说身材或位置的高低，与瘦不构成反义关系。", "硬": "硬说质地坚实，与瘦没有反义关系。", "快": "快与慢相对，与瘦无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "胖", "is_correct": true, "explanation": "胖与瘦是反义词，《现代汉语词典》有此对应，指身体肉多。"}, {"text": "忙", "is_correct": false, "explanation": "忙说没有空闲，与瘦没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮说光线或颜色，与瘦无关。"}, {"text": "长", "is_correct": false, "explanation": "长说长度，与瘦不构成反义关系。"}], "correct_answer": "胖", "explanations": {"胖": "胖与瘦是反义词，《现代汉语词典》有此对应，指身体肉多。", "忙": "忙说没有空闲，与瘦没有反义关系。", "亮": "亮说光线或颜色，与瘦无关。", "长": "长说长度，与瘦不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "瘦是身上的肉很少，不胖。", "primary_collocate": null, "pronunciation": "shòu", "ipa": "ʂoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他最近很瘦，大家都很担心他。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前很胖，现在变瘦了。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小猫又瘦又小。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子很高，也很瘦。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹太瘦了，应该多吃一点。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病以后，爷爷瘦了很多。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看起来比去年瘦。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马又老又瘦，走得很慢。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他瘦得像一根竹子。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃得很少，人有点瘦。", "target_word": "瘦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瘦瘦", "label": "重叠"}, {"form": "瘦了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或动物身上肉少、不胖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瘦", "is_correct": true, "explanation": "瘦（shòu）：身上肉少、不胖，是本词的读音与意思。"}, {"text": "手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，意思是收起、收到。"}, {"text": "树", "is_correct": false, "explanation": "shù 与 shòu 韵母不同（u 与 ou），声调都是第四声，意思是树。"}, {"text": "首", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是首，如“一首歌”。"}], "explanations": {"瘦": "瘦（shòu）：身上肉少、不胖，是本词的读音与意思。", "手": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手。", "收": "shōu（第一声）与 shòu（第四声）声调不同，意思是收起、收到。", "树": "shù 与 shòu 韵母不同（u 与 ou），声调都是第四声，意思是树。", "首": "shǒu（第三声）与 shòu（第四声）声调不同，意思是首，如“一首歌”。"}, "sentence_index": null, "correct_answer": "瘦"}, "level_3": {"options": [{"text": "瘦", "is_correct": true, "explanation": "瘦：身上肉少、不胖，与“大家都很担心他”的语境相合。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”与“大家都很担心他”矛盾，身体健康一般不会让人担心。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“最近”后面不接“年轻”这类长期状态，说“最近很年轻”不通。"}, {"text": "强壮", "is_correct": false, "explanation": "语义：“强壮”说身体有力，与“大家都很担心他”的语境正相反。"}], "explanations": {"瘦": "瘦：身上肉少、不胖，与“大家都很担心他”的语境相合。", "健康": "语义：“健康”与“大家都很担心他”矛盾，身体健康一般不会让人担心。", "年轻": "搭配：“最近”后面不接“年轻”这类长期状态，说“最近很年轻”不通。", "强壮": "语义：“强壮”说身体有力，与“大家都很担心他”的语境正相反。"}, "sentence_index": 0, "correct_answer": "瘦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子很瘦，一拉就断了。", "explanation": "这里应该用〈细〉。瘦只用于人或动物身上肉少，形容细长的绳子要用细。"}, {"text": "这个箱子很瘦，装不下几件衣服。", "explanation": "这里应该用〈小〉。瘦形容人或动物身上肉少，箱子的大小要用小。"}, {"text": "这张纸很瘦，一碰就破了。", "explanation": "这里应该用〈薄〉。瘦形容人或动物身上肉少，纸张的厚薄要用薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瘦", "is_correct": true, "explanation": "瘦（shòu）：身上肉少、不胖，是本词的读音与意思。"}, {"text": "肉", "is_correct": false, "explanation": "ròu 与 shòu 声母不同（r 与 sh），声调相同，意思是肉。"}, {"text": "臭", "is_correct": false, "explanation": "chòu 与 shòu 声母不同（ch 与 sh），声调相同，意思是难闻的气味。"}, {"text": "守", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是守护。"}, {"text": "数", "is_correct": false, "explanation": "shù 与 shòu 韵母不同（u 与 ou），声调相同，意思是数字、数一数。"}, {"text": "奏", "is_correct": false, "explanation": "zòu 与 shòu 声母不同（z 与 sh），声调相同，意思是演奏。"}], "explanations": {"瘦": "瘦（shòu）：身上肉少、不胖，是本词的读音与意思。", "肉": "ròu 与 shòu 声母不同（r 与 sh），声调相同，意思是肉。", "臭": "chòu 与 shòu 声母不同（ch 与 sh），声调相同，意思是难闻的气味。", "守": "shǒu（第三声）与 shòu（第四声）声调不同，意思是守护。", "数": "shù 与 shòu 韵母不同（u 与 ou），声调相同，意思是数字、数一数。", "奏": "zòu 与 shòu 声母不同（z 与 sh），声调相同，意思是演奏。"}, "sentence_index": null, "correct_answer": "瘦"}, "level_3": {"options": [{"text": "瘦", "is_correct": true, "explanation": "瘦：身上肉少、不胖，与“比去年”的外貌比较相合。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，不能拿来比较一个人看起来的样子。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”形容说话或语言，不用来形容外貌。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」说味道，不能用来比较一个人看起来的样子。"}], "explanations": {"瘦": "瘦：身上肉少、不胖，与“比去年”的外貌比较相合。", "冷": "语义：“冷”说温度，不能拿来比较一个人看起来的样子。", "流利": "搭配：“流利”形容说话或语言，不用来形容外貌。", "甜": "语义：「甜」说味道，不能用来比较一个人看起来的样子。"}, "sentence_index": 6, "correct_answer": "瘦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很瘦，两辆车过不去。", "explanation": "这里应该用〈窄〉。瘦形容人或动物身上肉少，道路的宽窄要用窄。"}, {"text": "这个杯子很瘦，装不了多少水。", "explanation": "这里应该用〈小〉。瘦形容人或动物身上肉少，杯子的大小要用小。"}, {"text": "这座山很瘦，爬起来一点也不累。", "explanation": "这里应该用〈矮〉。瘦不用于山这类物体，说高度低要用矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这几个月瘦很厉害。", "corrected_sentence": "他这几个月瘦得很厉害。", "error_description": "错在“瘦”后面漏了程度补语的结构助词“得”。程度补语要说“瘦得很厉害”，不能直接说“瘦很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猫瘦瘦地，很可爱。", "corrected_sentence": "那只猫瘦瘦的，很可爱。", "error_description": "错在“瘦瘦”后面用了“地”。描写人或动物的样子要用“的”，“地”用来修饰动词。应说“瘦瘦的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
