INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发作是藏着的病或脾气一下子出来了。", "primary_collocate": null, "pronunciation": "fā zuò", "ipa": "fa˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这个老毛病藏了多年，今天一下子发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直不说话，突然发作，推倒了桌子。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里的火压了很久，终于发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的旧病在雨天发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲平时很温和，今天却发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胃病半夜突然发作，疼得睡不着。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这几句话，小李的脾气马上发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药一停，她的病就发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这病平时没事，累了才会发作。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子饿了，脾气一下子发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发作了", "label": "了体标"}, {"form": "发作过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "原来藏着的病或脾气一下子表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发作", "is_correct": true, "explanation": "正确：“发作”指原来藏着的病一下子表现出来，与“藏了多年”和“一下子”相符。"}, {"text": "放晴", "is_correct": false, "explanation": "语义：“放晴”指天气转好，老毛病不会放晴。"}, {"text": "退烧", "is_correct": false, "explanation": "搭配：“退烧”指发热的体温下降，老毛病不能说退烧。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”指患上感冒，老毛病是旧病，不能说感冒了。"}], "explanations": {"发作": "正确：“发作”指原来藏着的病一下子表现出来，与“藏了多年”和“一下子”相符。", "放晴": "语义：“放晴”指天气转好，老毛病不会放晴。", "退烧": "搭配：“退烧”指发热的体温下降，老毛病不能说退烧。", "感冒": "搭配：“感冒”指患上感冒，老毛病是旧病，不能说感冒了。"}, "sentence_index": 0, "correct_answer": "发作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座沉睡多年的火山今天终于发作了。", "explanation": "这里应该用〈爆发〉。发作指藏着的病或脾气突然表现出来，火山喷发要用爆发。"}, {"text": "这次地震昨天在山区发作了。", "explanation": "这里应该用〈发生〉。发作只用于病症或脾气，地震这类自然事件要说发生。"}, {"text": "这场瘟疫去年在村里发作了。", "explanation": "这里应该用〈暴发〉。发作说的是个人的病或情绪，瘟疫大范围蔓延要说暴发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发作", "is_correct": true, "explanation": "正确：“发作”指情绪突然表现出来，与“听了这几句话”的诱因和“马上”相符。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开花或比喻事物兴盛，脾气不能开花。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”指体温升高，脾气不能说发烧。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”指天气，与小李的脾气无关。"}], "explanations": {"发作": "正确：“发作”指情绪突然表现出来，与“听了这几句话”的诱因和“马上”相符。", "开花": "语义：“开花”指植物开花或比喻事物兴盛，脾气不能开花。", "发烧": "搭配：“发烧”指体温升高，脾气不能说发烧。", "下雨": "语义：“下雨”指天气，与小李的脾气无关。"}, "sentence_index": 6, "correct_answer": "发作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水质这个月突然发作了。", "explanation": "这里应该用〈恶化〉。发作只用于病症或脾气，水质变差要说恶化。"}, {"text": "这只股票今天突然发作，一天就涨了两成。", "explanation": "这里应该用〈飙升〉。发作只指病症或脾气，股价猛涨要说飙升。"}, {"text": "这个城市的气温上周突然发作了。", "explanation": "这里应该用〈骤降〉。发作只指病症或脾气，气温急剧下降要说骤降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她憋了很久的气，昨天终于发作了气。", "corrected_sentence": "她憋了很久的气，昨天终于发作了。", "error_description": "错误：“发作了气”，“发作”是不及物动词，后面不能带宾语“气”。正确：“终于发作了”，“发作”后面直接结束，不加宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老张的脾气马上发作着，把大家都吓坏了。", "corrected_sentence": "老张的脾气马上发作了，把大家都吓坏了。", "error_description": "错误：“发作着”用“着”表示持续状态，但“马上”说的是突然发生并已完成的动作，应用“了”。正确：“发作了”，表示动作完成的“了”放在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
