INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "病症或情绪突然表现出来。", "primary_collocate": null, "pronunciation": "fā zuò", "ipa": "fa˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他的哮喘又发作了，要马上吃药。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的心脏病昨晚发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的脾气突然发作，大家都不敢说话。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病一旦发作，就会很痛苦。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头疼病每到冬天就发作。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忍了一整天，晚上终于发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人的癫痫可能随时发作。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的过敏在春天发作得很厉害。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒喝多了，他的胃病又发作了。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕他的坏脾气在会上发作。", "target_word": "发作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发作了", "label": "了体标"}, {"form": "发作过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "病症或脾气突然表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发作", "is_correct": true, "explanation": "正确：“发作”指病症突然表现出来，与“又……了”和后句“要马上吃药”相符。"}, {"text": "好转", "is_correct": false, "explanation": "语义：“好转”指病情变好，与后句“要马上吃药”所说的病情加重相矛盾。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”的主体是人的体温，哮喘不能说发烧。"}, {"text": "痊愈", "is_correct": false, "explanation": "语义：“痊愈”指病已彻底好了，与“又”和“要马上吃药”矛盾。"}], "explanations": {"发作": "正确：“发作”指病症突然表现出来，与“又……了”和后句“要马上吃药”相符。", "好转": "语义：“好转”指病情变好，与后句“要马上吃药”所说的病情加重相矛盾。", "发烧": "搭配：“发烧”的主体是人的体温，哮喘不能说发烧。", "痊愈": "语义：“痊愈”指病已彻底好了，与“又”和“要马上吃药”矛盾。"}, "sentence_index": 0, "correct_answer": "发作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座火山昨天发作了。", "explanation": "这里应该用〈爆发〉。发作多指病症或情绪突然表现出来，火山喷发要用爆发。"}, {"text": "这次交通事故昨天在路口发作了。", "explanation": "这里应该用〈发生〉。发作只用于病症或情绪，事故这类事件要说发生。"}, {"text": "这场疫情去年在这座城市发作了。", "explanation": "这里应该用〈暴发〉。发作说的是个人的病症或情绪，疫情大范围出现要说暴发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发作", "is_correct": true, "explanation": "正确：“发作”指病症突然出现，与“可能随时”的预测语境相符。"}, {"text": "退烧", "is_correct": false, "explanation": "搭配：“退烧”指发热的体温下降，癫痫不会退烧。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”指天气，与病人的癫痫无关，句子说的是病情。"}, {"text": "入睡", "is_correct": false, "explanation": "搭配：“入睡”的主语是人，“癫痫”是病症，不能说癫痫入睡。"}], "explanations": {"发作": "正确：“发作”指病症突然出现，与“可能随时”的预测语境相符。", "退烧": "搭配：“退烧”指发热的体温下降，癫痫不会退烧。", "下雨": "语义：“下雨”指天气，与病人的癫痫无关，句子说的是病情。", "入睡": "搭配：“入睡”的主语是人，“癫痫”是病症，不能说癫痫入睡。"}, "sentence_index": 6, "correct_answer": "发作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的空气质量昨天突然发作了。", "explanation": "这里应该用〈恶化〉。发作只用于病症或脾气，空气质量变差要说恶化。"}, {"text": "这家公司的利润今年一下子发作了。", "explanation": "这里应该用〈增长〉。发作只指病症或脾气突然表现，利润上升要说增长。"}, {"text": "这套房子的价格上个月突然发作了。", "explanation": "这里应该用〈上涨〉。发作只指病症或脾气，价格上升要说上涨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的哮喘昨晚又发作了着，要马上吃药。", "corrected_sentence": "他的哮喘昨晚又发作了，要马上吃药。", "error_description": "体标错误：“了”与“着”不能连用，“发作了”之后不能再接“着”。正确说法是“他的哮喘昨晚又发作了，要马上吃药。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小李的脾气突然发作着，大家都吓了一跳。", "corrected_sentence": "小李的脾气突然发作了，大家都吓了一跳。", "error_description": "体貌错误：“突然”表示瞬间发生的事，应与完成的“了”搭配，说“突然发作了”，不能用表示持续的“着”说“突然发作着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
