INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98483, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "直属是直接归某一个地方管。", "primary_collocate": null, "pronunciation": "zhí shǔ", "ipa": "ʈʂɻ̩˧˥ ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "这所大学直属教育部。", "target_word": "直属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司直属总公司。", "target_word": "直属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所学校直属市教育局。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院直属省政府。", "target_word": "直属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们部门直属总经理，不归别的部门管。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "该研究所直属中国科学院。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家报社直属市政府。", "target_word": "直属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个公司直属于集团总部。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家博物馆直属文化和旅游部。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海关直属中央，不归地方管。", "target_word": "直属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "直屬", "label": "繁体"}], "register": "书面", "sense_fingerprint": "直属：直接归某个地方或部门管，中间没有别的层级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a70e542a-3e78-41c2-b2e4-2d7a51a2477b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直属", "is_correct": true, "explanation": "正确：直属 zhí shǔ，表示直接归某个地方管。"}, {"text": "植树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是植树。"}, {"text": "质数", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）、shù（第四声）与 shǔ（第三声）声调都不同，意思是质数。"}, {"text": "指数", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）、shù（第四声）与 shǔ（第三声）声调都不同，意思是指数。"}], "explanations": {"直属": "正确：直属 zhí shǔ，表示直接归某个地方管。", "植树": "shù（第四声）与 shǔ（第三声）声调不同，意思是植树。", "质数": "zhì（第四声）与 zhí（第二声）、shù（第四声）与 shǔ（第三声）声调都不同，意思是质数。", "指数": "zhǐ（第三声）与 zhí（第二声）、shù（第四声）与 shǔ（第三声）声调都不同，意思是指数。"}, "sentence_index": null, "correct_answer": "直属"}, "level_3": {"options": [{"text": "直属", "is_correct": true, "explanation": "正确：直属表示直接归某个单位管，符合“大学直接归教育部管”的关系。"}, {"text": "管理", "is_correct": false, "explanation": "语义：管理是上级管下级，大学不能管理教育部这样的上级机关。"}, {"text": "领导", "is_correct": false, "explanation": "语义：领导是上级带领下级，句中的上下级关系被说反了。"}, {"text": "建议", "is_correct": false, "explanation": "配价：建议后面接的是建议的内容，不能直接以机构名词作宾语。"}], "explanations": {"直属": "正确：直属表示直接归某个单位管，符合“大学直接归教育部管”的关系。", "管理": "语义：管理是上级管下级，大学不能管理教育部这样的上级机关。", "领导": "语义：领导是上级带领下级，句中的上下级关系被说反了。", "建议": "配价：建议后面接的是建议的内容，不能直接以机构名词作宾语。"}, "sentence_index": 0, "correct_answer": "直属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "省政府直属这家医院。", "explanation": "这里应该用〈管辖〉。直属的主语是下级，表示直接隶属于上级；省政府是上级，不能说直属医院，应说管辖。"}, {"text": "这条路直属大门。", "explanation": "这里应该用〈直通〉。直属指机构之间的直接隶属关系，道路通往某处不说直属，应说直通。"}, {"text": "我的直属朋友是小王。", "explanation": "这里应该用〈好〉。直属只用于上下级或机构之间的隶属关系，朋友之间没有隶属关系，应说“好朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直属", "is_correct": true, "explanation": "正确：直属表示直接归某个政府管，与“报社归市政府管”的关系一致。"}, {"text": "批准", "is_correct": false, "explanation": "语义：批准是上级对下级的事项作决定，报社不能批准市政府。"}, {"text": "经营", "is_correct": false, "explanation": "搭配：经营用于企业或业务，不能用于政府机构。"}, {"text": "雇用", "is_correct": false, "explanation": "搭配：雇用的对象是人员，报社不能把市政府当作雇员。"}], "explanations": {"直属": "正确：直属表示直接归某个政府管，与“报社归市政府管”的关系一致。", "批准": "语义：批准是上级对下级的事项作决定，报社不能批准市政府。", "经营": "搭配：经营用于企业或业务，不能用于政府机构。", "雇用": "搭配：雇用的对象是人员，报社不能把市政府当作雇员。"}, "sentence_index": 6, "correct_answer": "直属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔钱直属我。", "explanation": "这里应该用〈属于〉。直属只用于机构之间直接管辖的关系，个人的钱不说直属，应说属于。"}, {"text": "这批货物直属仓库。", "explanation": "这里应该用〈归属〉。直属指机构之间的直接隶属，货物不是机构，应说归属。"}, {"text": "这个部门间接直属校长。", "explanation": "这里应该用〈隶属〉。直属已表示不经中间层级的直接隶属，与“间接”矛盾；间接隶属应说隶属于某个机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所中学直属给区教育局。", "corrected_sentence": "这所中学直属区教育局。", "error_description": "错误形式：「直属给」；正确形式：「直属」或「直属于」。直属后直接接机构名词，不用「给」引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个研究所很直属国务院。", "corrected_sentence": "这个研究所直属国务院。", "error_description": "程度副词错误：「直属」表示客观的隶属关系，不能用「很」修饰，应删去「很」。正确说法是「这个研究所直属国务院」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b51fa9ff-6b5a-45c9-905d-19eaa2acef61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
