INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "睡眠是闭上眼睛睡觉，让身体休息。", "primary_collocate": null, "pronunciation": "shuì mián", "ipa": "ʂweɪ̯˥˩ mjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我昨晚的睡眠很好。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠对身体很重要。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天的睡眠只有五个小时。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上喝咖啡会影响睡眠。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到好的睡眠，我早点关灯。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要足够的睡眠。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不好的人白天会很累。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我要多注意睡眠。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的房间有助于睡眠。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她睡眠不足，所以脸色不好。", "target_word": "睡眠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡眠时间", "label": "复合词"}, {"form": "睡眠质量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "日常生活中睡觉休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "搭配：“噪音”说大或小，不说“很好”。"}, {"text": "睡眠", "is_correct": true, "explanation": "正确：“睡眠”指睡觉休息的状态，与“很好”搭配，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说轻或重，不说“很好”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不是我昨晚的状态。"}], "explanations": {"噪音": "搭配：“噪音”说大或小，不说“很好”。", "睡眠": "正确：“睡眠”指睡觉休息的状态，与“很好”搭配，符合句意。", "体重": "搭配：“体重”说轻或重，不说“很好”。", "地铁": "语义：“地铁”是交通工具，不是我昨晚的状态。"}, "sentence_index": 0, "correct_answer": "睡眠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨晚做了一个好睡眠。", "explanation": "这里应该用〈梦〉。“做”搭配的是梦，不搭配“睡眠”；“睡眠”指睡觉时身体休息的状态。"}, {"text": "我突然感到一阵睡眠。", "explanation": "这里应该用〈睡意〉。“一阵”用于感觉，感到的是睡意，不说“一阵睡眠”。"}, {"text": "他把睡眠装进了行李箱，准备出差。", "explanation": "这里应该用〈睡袋〉。睡眠是身体的状态，不是物体，不能装进行李箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是可以“好”或“不好”的状态，句子说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能用来形容人的睡眠状态。"}, {"text": "睡眠", "is_correct": true, "explanation": "正确：“睡眠不好”指睡得不好，人会因此白天很累，符合句意。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通讯工具，“电话不好的人”说不通。"}], "explanations": {"书包": "语义：“书包”不是可以“好”或“不好”的状态，句子说不通。", "地铁": "语义：“地铁”是交通工具，不能用来形容人的睡眠状态。", "睡眠": "正确：“睡眠不好”指睡得不好，人会因此白天很累，符合句意。", "电话": "语义：“电话”是通讯工具，“电话不好的人”说不通。"}, "sentence_index": 6, "correct_answer": "睡眠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她昨晚睡了一个睡眠。", "explanation": "这里应该用〈一觉〉。睡一次用“一觉”，不说“一个睡眠”。"}, {"text": "她患上了睡眠，所以脸色不好。", "explanation": "这里应该用〈失眠〉。睡眠是正常的生理状态，不是病症，不能说“患上睡眠”。"}, {"text": "她被睡眠吓醒了，所以脸色不好。", "explanation": "这里应该用〈噩梦〉。被吓醒的是噩梦，睡眠本身不能吓人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每晚有一条完整的睡眠。", "corrected_sentence": "我每晚有一段完整的睡眠。", "error_description": "量词错误：指一段睡眠应用量词“段”，说“一段完整的睡眠”，不说“一条完整的睡眠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我最近把睡眠调整好着。", "corrected_sentence": "我最近把睡眠调整好了。", "error_description": "体标错误：“把”字句表示动作已完成，要用“了”，说“调整好了”，不说“调整好着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
