INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种马是专门用来生小马的公马。", "primary_collocate": null, "pronunciation": "zhǒng mǎ", "ipa": "tʂʊŋ˨˩ ma˨˩", "syllable_count": 2, "sentences": [{"text": "老张养了一匹种马，专门用来配种。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹种马很强壮，它的小马都很健康。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母马要生小马，得先找一匹好种马。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种马一天要吃很多东西，所以养它很贵。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马场新来了一匹种马，大家都去看。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那匹黑色的种马是马场的宝贝。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的种马今年有二十匹小马。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买种马，让自己的母马生小马。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种马的价钱很高，一匹要几十万元。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在马场里看见了一匹大种马。", "target_word": "种马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "匹", "label": "量词"}, {"form": "種馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来让母马生小马的公马", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种马", "is_correct": true, "explanation": "“种马”指专门配种的公马，与“专门用来配种”一致。"}, {"text": "小马", "is_correct": false, "explanation": "语义：小马是幼马，不能用来配种，句意不通。"}, {"text": "赛马", "is_correct": false, "explanation": "语义：赛马用于比赛，并不是专门用来配种的马。"}, {"text": "奶牛", "is_correct": false, "explanation": "语义：奶牛用来产奶，不是用来配种的马，而且“匹”不能修饰牛。"}], "explanations": {"种马": "“种马”指专门配种的公马，与“专门用来配种”一致。", "小马": "语义：小马是幼马，不能用来配种，句意不通。", "赛马": "语义：赛马用于比赛，并不是专门用来配种的马。", "奶牛": "语义：奶牛用来产奶，不是用来配种的马，而且“匹”不能修饰牛。"}, "sentence_index": 0, "correct_answer": "种马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这匹种马怀孕了，下个月就要生小马。", "explanation": "这里应该用〈母马〉。“种马”是公马，不会怀孕；怀孕的是母马。"}, {"text": "刚出生的种马每天都要喝奶。", "explanation": "这里应该用〈小马〉。“种马”指成年后专门配种的公马，刚出生的马应说“小马”。"}, {"text": "这批种马前天就发芽了。", "explanation": "这里应该用〈种子〉。“种马”是专门生小马的公马，不会发芽；能发芽的是种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种马", "is_correct": true, "explanation": "“种马”能够让母马生小马，与“今年有二十匹小马”的句意相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学生用的东西，不会生小马，句意荒谬。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会生小马，句子完全不通。"}, {"text": "母鸡", "is_correct": false, "explanation": "搭配：母鸡不会生小马，而且“匹”用于马，与“母鸡”不搭配。"}], "explanations": {"种马": "“种马”能够让母马生小马，与“今年有二十匹小马”的句意相符。", "书包": "语义：书包是学生用的东西，不会生小马，句意荒谬。", "电脑": "语义：电脑不会生小马，句子完全不通。", "母鸡": "搭配：母鸡不会生小马，而且“匹”用于马，与“母鸡”不搭配。"}, "sentence_index": 6, "correct_answer": "种马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这匹种马每天能挤出一桶奶。", "explanation": "这里应该用〈奶牛〉。“种马”是公马，不产奶；能产奶的是母畜，如奶牛。"}, {"text": "这匹种马去年已经阉割了，现在不能再生小马。", "explanation": "这里应该用〈骟马〉。“种马”指专门生小马的公马，阉割后的马不能生小马，应称“骟马”。"}, {"text": "这匹种马专门用来拉车，从不生小马。", "explanation": "这里应该用〈挽马〉。“种马”是专门生小马的公马，不负责拉车；专门拉车的马要用“挽马”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场今年新买了三匹马种。", "corrected_sentence": "农场今年新买了三匹种马。", "error_description": "错误：“马种”，应为“种马”。“马种”指马的品种，这里数的是马，应说“种马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王有一匹很强种马。", "corrected_sentence": "老王有一匹很强的种马。", "error_description": "错误：“很强种马”，应为“很强的种马”。形容词“很强”修饰名词“种马”时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟粕", "is_correct": true, "explanation": "糟粕指事物中粗劣、无用的部分，与“精华”构成反义词。"}, {"text": "框架", "is_correct": false, "explanation": "框架指事物的基本结构，与“精华”没有反义关系。"}, {"text": "路线", "is_correct": false, "explanation": "路线指行进的方向和道路，与“精华”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与“精华”没有反义关系。"}], "correct_answer": "糟粕", "explanations": {"糟粕": "糟粕指事物中粗劣、无用的部分，与“精华”构成反义词。", "框架": "框架指事物的基本结构，与“精华”没有反义关系。", "路线": "路线指行进的方向和道路，与“精华”没有反义关系。", "桌子": "桌子是家具，与“精华”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟粕", "is_correct": true, "explanation": "糟粕指事物中粗劣、无用的部分，与“精华”构成反义词。"}, {"text": "地毯", "is_correct": false, "explanation": "地毯是铺在地上的织物，与“精华”没有反义关系。"}, {"text": "季节", "is_correct": false, "explanation": "季节指一年中的时段，与“精华”没有反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "课本指学习用的书，与“精华”没有反义关系。"}], "correct_answer": "糟粕", "explanations": {"糟粕": "糟粕指事物中粗劣、无用的部分，与“精华”构成反义词。", "地毯": "地毯是铺在地上的织物，与“精华”没有反义关系。", "季节": "季节指一年中的时段，与“精华”没有反义关系。", "课本": "课本指学习用的书，与“精华”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精华是一样东西里最好、最重要的那一部分。", "primary_collocate": null, "pronunciation": "jīng huá", "ipa": "tɕiŋ˥ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "这道汤用了好几种肉，精华都在汤里。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太厚了，我只读了它的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京故宫是中国建筑的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这门课的精华总结成了一页纸。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆里的国宝，都是历史的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一章是全书的精华，不要跳过。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把一辈子的精华教给了年轻人。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从大量资料中选出了精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议的精华是下午的讨论。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只看这一页，就能知道报告的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精華", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一样东西里最好最重要的那部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精华", "is_correct": true, "explanation": "精华指汤里最好、最重要的部分，“都在汤里”的语境正好符合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是汤里的东西，“桌子都在汤里”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能说“在汤里”，只能说在菜单上。"}, {"text": "厚度", "is_correct": false, "explanation": "体貌：厚度说的是物体的厚薄，不能说分布在汤里。"}], "explanations": {"精华": "精华指汤里最好、最重要的部分，“都在汤里”的语境正好符合。", "桌子": "语义：桌子不是汤里的东西，“桌子都在汤里”说不通。", "价格": "搭配：“价格”不能说“在汤里”，只能说在菜单上。", "厚度": "体貌：厚度说的是物体的厚薄，不能说分布在汤里。"}, "sentence_index": 0, "correct_answer": "精华"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晚上精华很足，还能学习两个小时。", "explanation": "这里应该用〈精力〉。精华指事物中最好、最重要的部分，说人能用于做事的活力要用精力。"}, {"text": "这位工人的精华很大，搬得动这箱书。", "explanation": "这里应该用〈体力〉。精华指事物中最好、最重要的部分，说人身体的力气要用体力。"}, {"text": "他今天精华很好，跑了十公里。", "explanation": "这里应该用〈精神〉。精华指事物中最好的部分，说人的状态要用精神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精华", "is_correct": true, "explanation": "精华指一辈子积累下来最好、最重要的部分，可以教给年轻人。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的用品，不是可以教给别人的东西。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能教给别人。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“教给”的对象是知识或经验，工资不能教。"}], "explanations": {"精华": "精华指一辈子积累下来最好、最重要的部分，可以教给年轻人。", "钱包": "语义：钱包是装钱的用品，不是可以教给别人的东西。", "身高": "体貌：身高是外形特征，不能教给别人。", "工资": "搭配：“教给”的对象是知识或经验，工资不能教。"}, "sentence_index": 6, "correct_answer": "精华"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这个月的精华都花完了。", "explanation": "这里应该用〈工资〉。精华指事物中最好、最重要的部分，不能花掉；花掉的是工资。"}, {"text": "这件衣服的精华是红色。", "explanation": "这里应该用〈颜色〉。精华指最好、最重要的部分，说衣服是什么色要用颜色。"}, {"text": "他的精华不高，只有一米六。", "explanation": "这里应该用〈身高〉。精华指事物中最好的部分，说人有多高要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书里地精华抄在了笔记本上。", "corrected_sentence": "他把书里的精华抄在了笔记本上。", "error_description": "结构助词错误：修饰名词“精华”要用“的”，不能用“地”（“地”用于修饰动词）。应写“他把书里的精华抄在了笔记本上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书里的一只精华值得我们记住。", "corrected_sentence": "书里的一部分精华值得我们记住。", "error_description": "量词错误：“精华”应说“一部分精华”。“只”用于动物或成对物件中的一个，写成“一只精华”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
