INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物中最重要、最好的部分。", "primary_collocate": null, "pronunciation": "jīng huá", "ipa": "tɕiŋ˥ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "这本书的精华都在最后一章。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说一说这篇文章的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生的精华都写进了这本书里。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览集中了中国文化的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话是整个演讲的精华，大家要记住。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了课文的精华，我们听得很认真。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医是中国传统文化的精华之一。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜集中了本地菜的精华。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的精华是最后十分钟。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书时要抓住内容的精华，不用记每个字。", "target_word": "精华", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精華", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物中最重要、最好的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精华", "is_correct": true, "explanation": "精华指这本书里最重要、最好的部分，放在“都在最后一章”的语境里意思通顺。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面位于书的最前面，不会分布在最后一章。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“在某一章”只用于内容，不能说价格在哪一章。"}, {"text": "厚度", "is_correct": false, "explanation": "体貌：厚度是书的外形特征，不会分布在某一章里。"}], "explanations": {"精华": "精华指这本书里最重要、最好的部分，放在“都在最后一章”的语境里意思通顺。", "封面": "语义：封面位于书的最前面，不会分布在最后一章。", "价格": "搭配：“在某一章”只用于内容，不能说价格在哪一章。", "厚度": "体貌：厚度是书的外形特征，不会分布在某一章里。"}, "sentence_index": 0, "correct_answer": "精华"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的精华很足，一口气爬了五层楼。", "explanation": "这里应该用〈体力〉。精华指事物中最好、最重要的部分，说人身体的力气要用体力。"}, {"text": "这位老人的精华很好，每天早起散步。", "explanation": "这里应该用〈精神〉。精华指事物中最好、最重要的部分，说人的精神面貌要用精神。"}, {"text": "他今天精华很充沛，跑了十公里。", "explanation": "这里应该用〈精力〉。精华指事物中最好、最重要的部分，说人的活力和干劲要用精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精华", "is_correct": true, "explanation": "精华指中医是中国文化里最好、最重要的部分之一，符合“之一”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能说中医是“桌子之一”。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外观特征，不能当作文化的组成部分。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“之一”后接的是可以列举的文化组成部分，工资不属于文化。"}], "explanations": {"精华": "精华指中医是中国文化里最好、最重要的部分之一，符合“之一”的语境。", "桌子": "语义：桌子是家具，不能说中医是“桌子之一”。", "颜色": "体貌：颜色是外观特征，不能当作文化的组成部分。", "工资": "搭配：“之一”后接的是可以列举的文化组成部分，工资不属于文化。"}, "sentence_index": 6, "correct_answer": "精华"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的精华是二十平方米。", "explanation": "这里应该用〈面积〉。精华指最好、最重要的部分，说房间多大要用面积。"}, {"text": "他的精华很差，总是忘事。", "explanation": "这里应该用〈记性〉。精华指事物中最好的部分，说人记东西的能力要用记性。"}, {"text": "今天的精华很冷，要多穿衣服。", "explanation": "这里应该用〈天气〉。精华指事物中最好的部分，说冷热要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把整个会议地精华写进了报告里。", "corrected_sentence": "他把整个会议的精华写进了报告里。", "error_description": "结构助词错误：修饰名词“精华”要用“的”，不能用“地”（“地”用于修饰动词）。应写“他把整个会议的精华写进了报告里。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章的一块精华值得细读。", "corrected_sentence": "这篇文章的一部分精华值得细读。", "error_description": "量词错误：“精华”是抽象的内容，应说“一部分精华”。“块”用于块状的实物，写成“一块精华”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
