INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家、地区或个人在经济方面的实力。", "primary_collocate": null, "pronunciation": "jīng jì lì liàng", "ipa": "tɕiŋ˥ tɕi˥˩ li˥˩ liaŋ˥˩", "syllable_count": 4, "sentences": [{"text": "中国的经济力量排在世界前面。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的经济力量比以前强多了。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的经济力量差得很远。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的经济力量主要来自工业。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用经济力量帮助了很多小国家。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省经济力量不强，年轻人都去外地工作。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济力量弱的地方，学校也比较少。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个地区的经济力量差不多。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发新市场以后，这个国家的经济力量更强了。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的经济力量还不能和大公司比。", "target_word": "经济力量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国家、地区或个人在经济方面的实力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49f408f-adef-4962-af02-3ece88a3a05a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济力量", "is_correct": true, "explanation": "“经济力量”指国家的经济实力，可以“排在世界前面”，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气候状况，不能按名次“排在世界前面”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的练习，国家不能“排在世界前面”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，国家不能用它来排名。"}], "explanations": {"经济力量": "“经济力量”指国家的经济实力，可以“排在世界前面”，符合句意。", "天气": "语义：“天气”是气候状况，不能按名次“排在世界前面”。", "作业": "语义：“作业”是学生的练习，国家不能“排在世界前面”。", "身材": "体貌：“身材”指人的体形，国家不能用它来排名。"}, "sentence_index": 0, "correct_answer": "经济力量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种炸弹的经济力量很大，一下子就炸平了一座楼。", "explanation": "这里应该用〈威力〉。经济力量指经济方面的实力，形容炸弹的破坏力要用〈威力〉。"}, {"text": "他很有经济力量，一口气能举起两百斤。", "explanation": "这里说的是身体的力气，属于“力量”的体力意思。经济力量只指经济方面的实力，不能用来形容举重的力气。"}, {"text": "这台发动机的经济力量很大，能拉动两节车厢。", "explanation": "这里应该用〈动力〉。经济力量指经济方面的实力，形容发动机的推动能力要用〈动力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济力量", "is_correct": true, "explanation": "“经济力量弱”指地方的经济实力弱，与“学校也比较少”的因果关系相符。"}, {"text": "免疫力", "is_correct": false, "explanation": "语义：“免疫力”是人体的抵抗能力，不能说“免疫力弱的地方”。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”是人发出的声音，不能用来形容地方。"}, {"text": "体力", "is_correct": false, "explanation": "语义：“体力”指人身体的力气，不能用来形容地方的强弱。"}], "explanations": {"经济力量": "“经济力量弱”指地方的经济实力弱，与“学校也比较少”的因果关系相符。", "免疫力": "语义：“免疫力”是人体的抵抗能力，不能说“免疫力弱的地方”。", "嗓音": "语义：“嗓音”是人发出的声音，不能用来形容地方。", "体力": "语义：“体力”指人身体的力气，不能用来形容地方的强弱。"}, "sentence_index": 6, "correct_answer": "经济力量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的经济力量很高，每天来的人特别多。", "explanation": "这里应该用〈人气〉。经济力量指经济实力，店铺受欢迎要用〈人气〉。"}, {"text": "这句口号很有经济力量，大家都记住了。", "explanation": "这里应该用〈号召力〉。经济力量指经济方面的实力，形容口号能让人响应、记住要用〈号召力〉。"}, {"text": "这条河的经济力量很大，一夜之间冲走了好几棵树。", "explanation": "这里应该用〈冲击力〉。经济力量指经济方面的实力，形容河水的冲力要用〈冲击力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的经济力量很高。", "corrected_sentence": "这个地区的经济力量很强。", "error_description": "搭配错误：“经济力量”说“强”“大”或“弱”，不说“很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的经济力量越来越高。", "corrected_sentence": "这个城市的经济力量越来越强。", "error_description": "搭配错误：“经济力量”说“强”“弱”或“大”，不说“越来越高”，应说“越来越强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eefb572-4ef1-4179-84dd-e0259d070744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
