INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "台上是在高高的台子上面。", "primary_collocate": null, "pronunciation": "tái shàng", "ipa": "tʰaɪ̯˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "台上放着一盆红花。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上有很多书。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳到台上，看着窗外。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的灯很亮。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子放在台上。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上站着一个小孩。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台子很高，台上的东西我拿不到。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬到台上，看得更远。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上有水，小心一点。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上没有人，只有一把椅子。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "高台子的上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上（tái shàng）：高台子的上面，是本词的读音与意思。"}, {"text": "头上", "is_correct": false, "explanation": "tóu shàng 与台上第一个音节韵母不同（ou 与 ai），意思是头的上方。"}, {"text": "台账", "is_correct": false, "explanation": "tái zhàng 与台上第二个音节声母不同（zh 与 sh），意思是记录账目的本子。"}, {"text": "台商", "is_correct": false, "explanation": "tái shāng 与台上第二个音节声调不同（阴平与去声），意思是台湾的商人。"}], "explanations": {"台上": "台上（tái shàng）：高台子的上面，是本词的读音与意思。", "头上": "tóu shàng 与台上第一个音节韵母不同（ou 与 ai），意思是头的上方。", "台账": "tái zhàng 与台上第二个音节声母不同（zh 与 sh），意思是记录账目的本子。", "台商": "tái shāng 与台上第二个音节声调不同（阴平与去声），意思是台湾的商人。"}, "sentence_index": null, "correct_answer": "台上"}, "level_3": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上：高台子的上面，与“放着一盆红花”的语境相合。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上是天空，花盆不会放在天空中。"}, {"text": "水底", "is_correct": false, "explanation": "搭配：“水底”一般指水下的东西，不说“水底放着一盆花”。"}, {"text": "冰箱里", "is_correct": false, "explanation": "语义：冰箱里放的是食物，花盆不会放进冰箱，与“放着一盆红花”的语境不合。"}], "explanations": {"台上": "台上：高台子的上面，与“放着一盆红花”的语境相合。", "天上": "语义：天上是天空，花盆不会放在天空中。", "水底": "搭配：“水底”一般指水下的东西，不说“水底放着一盆花”。", "冰箱里": "语义：冰箱里放的是食物，花盆不会放进冰箱，与“放着一盆红花”的语境不合。"}, "sentence_index": 0, "correct_answer": "台上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把相框挂在台上。", "explanation": "这里误把“台上”当成了竖直的表面。台上指台子的平面，只能放置东西，不能用于悬挂，应说〈挂在墙上〉。"}, {"text": "我把书放进台上。", "explanation": "这里误把“台上”当作可以装入东西的空间。台上只表示台子表面的位置，不能用于装入的动作，应说〈放在台上〉。"}, {"text": "台上下面藏着一只小猫。", "explanation": "这里的“台上”指台子的上面，和“下面”矛盾。台子底下应说〈台子下面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上：指台子的上面，与“台子很高”和“拿不到”的语境相合。"}, {"text": "地上", "is_correct": false, "explanation": "语义：地上在低处，伸手就能拿到，与“台子很高”“拿不到”的语境矛盾。"}, {"text": "脚下", "is_correct": false, "explanation": "语义：脚下离人最近，东西在脚下不会拿不到，句意矛盾。"}, {"text": "身上", "is_correct": false, "explanation": "搭配：“身上”指人自己的身体上，“身上的东西拿不到”不合常理。"}], "explanations": {"台上": "台上：指台子的上面，与“台子很高”和“拿不到”的语境相合。", "地上": "语义：地上在低处，伸手就能拿到，与“台子很高”“拿不到”的语境矛盾。", "脚下": "语义：脚下离人最近，东西在脚下不会拿不到，句意矛盾。", "身上": "搭配：“身上”指人自己的身体上，“身上的东西拿不到”不合常理。"}, "sentence_index": 6, "correct_answer": "台上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫跳进台上睡觉。", "explanation": "这里的“台上”指台子的表面，不能当作可以进入的空间，应说〈跳上〉。"}, {"text": "这个台上很高，我够不着。", "explanation": "这里应该说〈台子〉。台上只表示位置，不能指台子这个物体。"}, {"text": "他一直站进台上，挡住了大家的视线。", "explanation": "这里应该用〈站上〉。站在台上不用“进”，“进”表示进入某个空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台上里摆着一盆红花，很好看。", "corrected_sentence": "台上摆着一盆红花，很好看。", "error_description": "错在“台上”后面多加了“里”。“台上”已经表示位置，后面不能再加方位词“里”。应说“台上摆着一盆红花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台上花很美，大家都在拍照。", "corrected_sentence": "台上的花很美，大家都在拍照。", "error_description": "错在“台上”后面漏了结构助词“的”。“台上”修饰名词“花”时要加“的”，应说“台上的花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "台子的上面，多指舞台上。", "primary_collocate": null, "pronunciation": "tái shàng", "ipa": "tʰaɪ̯˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "台上的歌手唱得很好听。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上正在演一个老故事。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次站在台上，有点紧张。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的演员穿着红衣服。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上灯光很亮，台下很暗。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上有人跳舞，台下的人都在看。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在台上唱了一首歌。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的主持人笑着说话。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在台上说了几句话，大家都鼓掌。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的人很多，我找不到他。", "target_word": "台上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "舞台的上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00032f7-208c-448d-9c5f-b377604ba846') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上（tái shàng）：舞台上，是本词的读音与意思。"}, {"text": "头上", "is_correct": false, "explanation": "tóu shàng 与台上第一个音节韵母不同（ou 与 ai），意思是头的上方。"}, {"text": "台账", "is_correct": false, "explanation": "tái zhàng 与台上第二个音节声母不同（zh 与 sh），意思是记录账目的本子。"}, {"text": "台商", "is_correct": false, "explanation": "tái shāng 与台上第二个音节声调不同（阴平与去声），意思是台湾的商人。"}], "explanations": {"台上": "台上（tái shàng）：舞台上，是本词的读音与意思。", "头上": "tóu shàng 与台上第一个音节韵母不同（ou 与 ai），意思是头的上方。", "台账": "tái zhàng 与台上第二个音节声母不同（zh 与 sh），意思是记录账目的本子。", "台商": "tái shāng 与台上第二个音节声调不同（阴平与去声），意思是台湾的商人。"}, "sentence_index": null, "correct_answer": "台上"}, "level_3": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上：舞台上，与“歌手唱得很好听”的语境相合。"}, {"text": "水底", "is_correct": false, "explanation": "语义：歌手不会在水底唱歌，与“唱得很好听”的语境不合。"}, {"text": "云里", "is_correct": false, "explanation": "语义：云里是天空中，歌手不会在云里唱歌。"}, {"text": "冰箱里", "is_correct": false, "explanation": "语义：冰箱里放的是食物，歌手不会在冰箱里唱歌。"}], "explanations": {"台上": "台上：舞台上，与“歌手唱得很好听”的语境相合。", "水底": "语义：歌手不会在水底唱歌，与“唱得很好听”的语境不合。", "云里": "语义：云里是天空中，歌手不会在云里唱歌。", "冰箱里": "语义：冰箱里放的是食物，歌手不会在冰箱里唱歌。"}, "sentence_index": 0, "correct_answer": "台上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台上下面放着一箱书，没人发现。", "explanation": "这里的“台上”指台子的上面，和“下面”矛盾。台子底下应说〈台子下面〉。"}, {"text": "台上的观众都在鼓掌，很热闹。", "explanation": "这里应该用〈台下〉。观众在台下，台上是表演者站的地方。"}, {"text": "他走上台上，对着观众鞠了一躬。", "explanation": "这里应该说〈走上台〉。“上”已表示走到台子上，后面不能再接“台上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台上", "is_correct": true, "explanation": "台上：在舞台上，与“唱了一首歌”的语境相合。"}, {"text": "地图上", "is_correct": false, "explanation": "语义：地图上是画着地形的平面，不是唱歌的地方。"}, {"text": "书上", "is_correct": false, "explanation": "搭配：“书上”常与“写”“印”搭配，不与“唱”搭配。"}, {"text": "月球上", "is_correct": false, "explanation": "语义：月球上没有空气，人无法在那里唱歌。"}], "explanations": {"台上": "台上：在舞台上，与“唱了一首歌”的语境相合。", "地图上": "语义：地图上是画着地形的平面，不是唱歌的地方。", "书上": "搭配：“书上”常与“写”“印”搭配，不与“唱”搭配。", "月球上": "语义：月球上没有空气，人无法在那里唱歌。"}, "sentence_index": 6, "correct_answer": "台上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "化妆间在台上，演员们都在那里化妆。", "explanation": "这里应该用〈后台〉。化妆间在舞台后面，不在台面上，“台上”不能指化妆间。"}, {"text": "这个台上是新搭的，很结实。", "explanation": "这里应该说〈舞台〉。台上只表示舞台上面的位置，不能指舞台这个东西本身。"}, {"text": "这个台上很重，搬不动。", "explanation": "这里应该说〈台子〉。台上只表示位置，不能指台子这个物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他台上说得很流利。", "corrected_sentence": "他在台上说得很流利。", "error_description": "错在“台上”前漏了介词“在”。表示在台上做某事要说“在台上说”，不能直接说“台上说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台上老师很幽默，同学们都笑了。", "corrected_sentence": "台上的老师很幽默，同学们都笑了。", "error_description": "错在“台上”后面漏了结构助词“的”。“台上”修饰名词“老师”时要加“的”，应说“台上的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbec9055-fda2-4155-9721-6bad08d2852a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
