INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "台本是演戏时，写着每个人该说什么话的本子。", "primary_collocate": null, "pronunciation": "tái běn", "ipa": "tʰaɪ˧˥ pən˨˩", "syllable_count": 2, "sentences": [{"text": "演员们每天拿着台本练习说话。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个台本很长，我背了三天才背完。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演在台本上写了很多字。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带台本，上台前非常着急。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的台本里，他要说五句话。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一本台本。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台本上写着每个人该说的话。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家先读一遍台本，再上台演戏。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的台本丢了，你能借我看看吗？", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们照着台本演了一个小故事。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}], "register": "中性", "sense_fingerprint": "演戏时写着每个人台词的本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98511, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本（tái běn）指演戏时写着每个人台词的本子，与听到的读音一致。"}, {"text": "太笨", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，bèn 与 běn 声调也不同，意思是太笨。"}, {"text": "台版", "is_correct": false, "explanation": "bǎn（第三声）与 běn（第三声）的韵母不同：an 与 en 不同，意思是台湾出版的版本。"}, {"text": "台盆", "is_correct": false, "explanation": "pén（第二声）与 běn（第三声）声母不同（p 与 b），意思是洗手用的台盆。"}], "explanations": {"台本": "台本（tái běn）指演戏时写着每个人台词的本子，与听到的读音一致。", "太笨": "tài（第四声）与 tái（第二声）声调不同，bèn 与 běn 声调也不同，意思是太笨。", "台版": "bǎn（第三声）与 běn（第三声）的韵母不同：an 与 en 不同，意思是台湾出版的版本。", "台盆": "pén（第二声）与 běn（第三声）声母不同（p 与 b），意思是洗手用的台盆。"}, "sentence_index": null, "correct_answer": "台本"}, "level_3": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本指演员练习用的、写着台词的本子，拿着它练习说话很自然。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是吃饭用的器具，与练习说话无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“拿着”后接可以拿的物品，体重不能拿。"}, {"text": "扫把", "is_correct": false, "explanation": "语义：扫把是打扫用具，与练习说话无关。"}], "explanations": {"台本": "台本指演员练习用的、写着台词的本子，拿着它练习说话很自然。", "饭碗": "语义：饭碗是吃饭用的器具，与练习说话无关。", "体重": "搭配：“拿着”后接可以拿的物品，体重不能拿。", "扫把": "语义：扫把是打扫用具，与练习说话无关。"}, "sentence_index": 0, "correct_answer": "台本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们每天背台本，准备考试。", "explanation": "这里应该用〈课本〉。台本是演戏时写台词的本子，学生学习要用课本。"}, {"text": "妈妈照着台本做了一桌菜。", "explanation": "这里应该用〈菜谱〉。台本是演戏用的本子，做菜要照着菜谱。"}, {"text": "我去图书馆借了一本台本，想学数学。", "explanation": "这里应该用〈课本〉。台本是演戏用的、写着台词的本子，学数学要用课本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本是写着每个人该说的话的本子，写在上面符合语境。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶上不会写台词，与“写着该说的话”无关。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤上不能写字，“汤上写着台词”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“上写着”的承载物应能写字，身高不能写字。"}], "explanations": {"台本": "台本是写着每个人该说的话的本子，写在上面符合语境。", "树叶": "语义：树叶上不会写台词，与“写着该说的话”无关。", "汤": "语义：汤上不能写字，“汤上写着台词”说不通。", "身高": "搭配：“上写着”的承载物应能写字，身高不能写字。"}, "sentence_index": 6, "correct_answer": "台本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上在台本上写今天发生的事。", "explanation": "这里应该用〈日记本〉。台本是演戏时写台词的本子，记录每天的事要用日记本。"}, {"text": "去国外旅游一定要带好台本。", "explanation": "这里应该用〈护照〉。台本是演戏用的本子，出国要带护照。"}, {"text": "银行给了我一本台本，上面写着我存了多少钱。", "explanation": "这里应该用〈存折〉。台本是演戏时写台词的本子，记录存款的是存折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演员们每天拿着一把台本练习说话。", "corrected_sentence": "演员们每天拿着一本台本练习说话。", "error_description": "量词错误：“台本”应用量词“本”，“把”用于有柄的器具，不能修饰台本。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只台本很长，我背了三天。", "corrected_sentence": "这本台本很长，我背了三天。", "error_description": "量词错误：“台本”应用量词“本”，写成“这只台本”不对，“只”用于动物或成对物件中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
