INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戏剧、电影等演出所依据的剧本。", "primary_collocate": null, "pronunciation": "tái běn", "ipa": "tʰaɪ˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这部电影的台本是一位有名作家写的。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演改了几次台本，终于拍好了这部戏。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部话剧的台本很有意思。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买下了这部小说的电影台本。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出前，剧团又修改了一遍台本。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写一个电视剧台本。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个台本讲的是一家人的故事。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍电影要先有好台本。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读完台本，决定接下这个角色。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部戏的台本写得又短又好。", "target_word": "台本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}], "register": "中性", "sense_fingerprint": "戏剧、电影等演出所依据的剧本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '389b43bd-a0c5-4cce-afd4-0cb183a97713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98512, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本（tái běn）指戏剧、电影演出所依据的剧本，与听到的读音一致。"}, {"text": "太笨", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，bèn 与 běn 声调也不同，意思是太笨。"}, {"text": "台版", "is_correct": false, "explanation": "bǎn（第三声）与 běn（第三声）的韵母不同：an 与 en 不同，意思是台湾出版的版本。"}, {"text": "台盆", "is_correct": false, "explanation": "pén（第二声）与 běn（第三声）声母不同（p 与 b），意思是洗手用的台盆。"}], "explanations": {"台本": "台本（tái běn）指戏剧、电影演出所依据的剧本，与听到的读音一致。", "太笨": "tài（第四声）与 tái（第二声）声调不同，bèn 与 běn 声调也不同，意思是太笨。", "台版": "bǎn（第三声）与 běn（第三声）的韵母不同：an 与 en 不同，意思是台湾出版的版本。", "台盆": "pén（第二声）与 běn（第三声）声母不同（p 与 b），意思是洗手用的台盆。"}, "sentence_index": null, "correct_answer": "台本"}, "level_3": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本是电影所依据的剧本，“这部电影的台本是作家写的”符合语境。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是表演的人，不是由作家写出来的东西。"}, {"text": "票房", "is_correct": false, "explanation": "搭配：票房是数字，不能说由作家写。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观特征，不能说是作家写的。"}], "explanations": {"台本": "台本是电影所依据的剧本，“这部电影的台本是作家写的”符合语境。", "演员": "语义：演员是表演的人，不是由作家写出来的东西。", "票房": "搭配：票房是数字，不能说由作家写。", "颜色": "语义：颜色是外观特征，不能说是作家写的。"}, "sentence_index": 0, "correct_answer": "台本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个软件的台本写得很复杂。", "explanation": "这里应该用〈脚本〉。台本是演出用的剧本，计算机程序的指令要说脚本。"}, {"text": "这首歌的台本很难弹。", "explanation": "这里应该用〈乐谱〉。台本是演出用的剧本，弹奏乐曲要看乐谱。"}, {"text": "妈妈照着台本做饭。", "explanation": "这里应该用〈食谱〉。台本是演出用的剧本，做饭要照着食谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台本", "is_correct": true, "explanation": "台本是演出所依据的剧本，可以讲一家人的故事。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅是吃饭的场所，不能讲故事。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币是钱币，不能讲一家人的故事。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“讲的是故事”的主语应是作品，体重是数值，不能讲故事。"}], "explanations": {"台本": "台本是演出所依据的剧本，可以讲一家人的故事。", "餐厅": "语义：餐厅是吃饭的场所，不能讲故事。", "硬币": "语义：硬币是钱币，不能讲一家人的故事。", "体重": "搭配：“讲的是故事”的主语应是作品，体重是数值，不能讲故事。"}, "sentence_index": 6, "correct_answer": "台本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上看台本，了解今天的新闻。", "explanation": "这里应该用〈报纸〉。台本是演出所依据的剧本，了解新闻要看报纸。"}, {"text": "请把这份工作台本发给每个员工，告诉他们公司的规定。", "explanation": "这里应该用〈手册〉。台本是演出用的剧本，公司规定写在员工手册里。"}, {"text": "医生在台本上写了要吃的药。", "explanation": "这里应该用〈病历〉。台本是演出用的剧本，医生记录用药写在病历上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "导演把台本改着三遍。", "corrected_sentence": "导演把台本改了三遍。", "error_description": "体标错误：表示已经完成的次数要用“了”，不能用“着”；“着”表示动作的持续或状态，应说“导演把台本改了三遍”，不能说“改着三遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只台本的故事很感人。", "corrected_sentence": "这本台本的故事很感人。", "error_description": "量词错误：“台本”应用量词“本”，写成“这只台本”不对，“只”用于动物或成对物件中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e533fe3-b9e4-4731-9909-51b1f981ef48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
