INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "舌头是在嘴巴里面软软的，用来尝味道和说话。", "primary_collocate": null, "pronunciation": "shé tou", "ipa": "ʂɤ˧˥ tʰou", "syllable_count": 2, "sentences": [{"text": "吃了很辣的东西以后，我的舌头很麻。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗热的时候会把舌头伸得很长。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一紧张，舌头就不听话，话说不清楚。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩对着镜子做鬼脸，还吐出舌头。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种糖很甜，舌头一碰就能尝出来。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把舌头咬破了。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇的舌头细细的，还分成两条。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了太烫的茶，我的舌头现在还疼。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语时，舌头要放在正确的位置。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子伸着舌头，在舔手里的冰淇淋。", "target_word": "舌头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "大舌头", "label": "复合"}], "register": "中性", "sense_fingerprint": "嘴里柔软、用来尝味和说话的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3810a26-ecf2-428b-beee-e994530c768a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舌头", "is_correct": true, "explanation": "正确：“舌头”是嘴里柔软、能尝味道的部分，吃辣后会发麻。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有感觉，不会因吃辣而发麻。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“很麻”要求身体部位作主语，“书包”不能作主语。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是电子设备，不会因吃辣而发麻。"}], "explanations": {"舌头": "正确：“舌头”是嘴里柔软、能尝味道的部分，吃辣后会发麻。", "桌子": "语义：“桌子”没有感觉，不会因吃辣而发麻。", "书包": "配价：“很麻”要求身体部位作主语，“书包”不能作主语。", "手机": "语义：“手机”是电子设备，不会因吃辣而发麻。"}, "sentence_index": 0, "correct_answer": "舌头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的舌头很亮，看起来很精神。", "explanation": "这里应该用〈眼睛〉。能发亮、显得精神的是眼睛；舌头长在口腔里，不能用“亮”来形容。"}, {"text": "他用舌头拿起了勺子。", "explanation": "这里应该用〈手〉。拿起勺子要靠手，舌头不能用来拿东西。"}, {"text": "妈妈用舌头切菜，动作很快。", "explanation": "这里应该用〈刀〉。切菜要用刀，舌头不能用来切东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舌头", "is_correct": true, "explanation": "正确：“舌头”细长，蛇的舌头分成两条，句子指的正是它。"}, {"text": "皮", "is_correct": false, "explanation": "语义：蛇的皮不会分成两条，句子说不通。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：蛇没有翅膀，“分成两条”不能用来指翅膀。"}, {"text": "绳子", "is_correct": false, "explanation": "配价：修饰“蛇的”的应是身体部位，“绳子”不符。"}], "explanations": {"舌头": "正确：“舌头”细长，蛇的舌头分成两条，句子指的正是它。", "皮": "语义：蛇的皮不会分成两条，句子说不通。", "翅膀": "语义：蛇没有翅膀，“分成两条”不能用来指翅膀。", "绳子": "配价：修饰“蛇的”的应是身体部位，“绳子”不符。"}, "sentence_index": 6, "correct_answer": "舌头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子用舌头听声音，老师很惊讶。", "explanation": "这里应该用〈耳朵〉。听声音靠耳朵，舌头负责尝味，不能用来听。"}, {"text": "孩子用舌头看黑板，老师很惊讶。", "explanation": "这里应该用〈眼睛〉。看东西靠眼睛，舌头不能用来看。"}, {"text": "孩子用舌头咬苹果，老师很惊讶。", "explanation": "这里应该用〈牙齿〉。咬碎食物要靠牙齿，舌头不能咬东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子伸出了舌头们。", "corrected_sentence": "孩子伸出了舌头。", "error_description": "错误：“舌头们”。“们”只用于指人的名词，“舌头”后不能加“们”，正确为“伸出了舌头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蛇有很细舌头，还分成两条。", "corrected_sentence": "蛇有很细的舌头，还分成两条。", "error_description": "错误：“很细舌头”。定语与中心词之间要加“的”，正确为“很细的舌头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'facb088e-822e-4b9a-85e2-6c9f4cc48419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
