INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "芯片是电脑和手机里很小很小的零件，像它们的小脑袋。", "primary_collocate": null, "pronunciation": "xīn piàn", "ipa": "ɕin˥ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "手机里有一块很小的芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的芯片坏了，不能开机。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个芯片比指甲还小。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的芯片更快。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅在换电脑里的芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有芯片，手机就不会工作。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表里也有芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡里有一个芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小芯片能做大事情。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的芯片出问题了。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "手机芯片", "label": "复合"}], "register": "口语", "sense_fingerprint": "芯片：电脑手机里很小的重要零件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98519, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "芯片", "is_correct": true, "explanation": "正确答案。芯片 xīnpiàn 指电脑和手机里的小零件。"}, {"text": "新建", "is_correct": false, "explanation": "jiàn 与 piàn 声母不同（j 与 p），意思是新建、新修建，不是芯片。"}, {"text": "新线", "is_correct": false, "explanation": "xiàn 与 piàn 声母不同（x 与 p），意思是新的线路，不是芯片。"}, {"text": "新篇", "is_correct": false, "explanation": "piān 与 piàn 声调不同（第一声与第四声），意思是新的篇章，不是芯片。"}], "explanations": {"芯片": "正确答案。芯片 xīnpiàn 指电脑和手机里的小零件。", "新建": "jiàn 与 piàn 声母不同（j 与 p），意思是新建、新修建，不是芯片。", "新线": "xiàn 与 piàn 声母不同（x 与 p），意思是新的线路，不是芯片。", "新篇": "piān 与 piàn 声调不同（第一声与第四声），意思是新的篇章，不是芯片。"}, "sentence_index": null, "correct_answer": "芯片"}, "level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，手机里不会有一块蛋糕。"}, {"text": "芯片", "is_correct": true, "explanation": "正确：手机里的小零件就是芯片，与“一块很小的”相合。"}, {"text": "方法", "is_correct": false, "explanation": "搭配：“块”不能用来计量“方法”这样的抽象名词。"}, {"text": "木头", "is_correct": false, "explanation": "语义：手机里不会有一块木头。"}], "explanations": {"蛋糕": "语义：蛋糕是食物，手机里不会有一块蛋糕。", "芯片": "正确：手机里的小零件就是芯片，与“一块很小的”相合。", "方法": "搭配：“块”不能用来计量“方法”这样的抽象名词。", "木头": "语义：手机里不会有一块木头。"}, "sentence_index": 0, "correct_answer": "芯片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机里有一条很小的芯片。", "explanation": "这里应该用〈块〉。“条”用于细长的东西，芯片不能用“条”来计量。"}, {"text": "弟弟抱着一袋芯片看电视。", "explanation": "这里的“芯片”被当成了零食，但它只指电子元件，不指吃的东西。"}, {"text": "他用芯片在纸上写字。", "explanation": "这里把“芯片”当成了笔，但芯片是电子元件，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "语义：报纸是纸质读物，手表里不可能有报纸。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军是比赛的胜者，不会在手表里。"}, {"text": "情愫", "is_correct": false, "explanation": "语域：“情愫”偏书面、文学化，口语句子中不合适；语义：手表里也不会有情愫。"}, {"text": "芯片", "is_correct": true, "explanation": "正确：手表里有芯片，与“我的手表里也有”相合。"}], "explanations": {"报纸": "语义：报纸是纸质读物，手表里不可能有报纸。", "冠军": "语义：冠军是比赛的胜者，不会在手表里。", "情愫": "语域：“情愫”偏书面、文学化，口语句子中不合适；语义：手表里也不会有情愫。", "芯片": "正确：手表里有芯片，与“我的手表里也有”相合。"}, "sentence_index": 6, "correct_answer": "芯片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "修理工在电视店买了一根芯片。", "explanation": "这里应该用〈块〉。“根”用于细长的东西，芯片不能用“根”来计量。"}, {"text": "他喝了一口芯片。", "explanation": "这里把“芯片”当成了可以喝的饮料，但芯片是电子元件，不能喝。"}, {"text": "他在牌桌上用芯片押注。", "explanation": "这里的“芯片”被当成了牌桌上的筹码，但“芯片”只指电子元件，没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电脑里装了两根芯片。", "corrected_sentence": "电脑里装了两块芯片。", "error_description": "量词错误：“根”用于细长的东西，芯片应该用“块”来计量。正确说法是“电脑里装了两块芯片。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器里有一根旧芯片。", "corrected_sentence": "这台机器里有一块旧芯片。", "error_description": "量词错误：“根”用于细长的东西，芯片应该用“块”来计量。正确说法是“这台机器里有一块旧芯片。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
