INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集成电路的载体，由半导体材料制成的微小元件。", "primary_collocate": null, "pronunciation": "xīn piàn", "ipa": "ɕin˥ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这块芯片是用硅做的。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门生产芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芯片的体积很小，却很重要。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在设计新的芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近全世界都缺芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车里也要用很多芯片。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把芯片装进了机器里。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种芯片的速度非常快。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家支持芯片的研究。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芯片需要在干净的房间里制造。", "target_word": "芯片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "手机芯片", "label": "复合"}], "register": "中性", "sense_fingerprint": "芯片：半导体材料制成的集成电路载体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98520, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "芯片", "is_correct": true, "explanation": "正确答案。芯片 xīnpiàn 指集成电路的载体，由半导体材料制成。"}, {"text": "新建", "is_correct": false, "explanation": "jiàn 与 piàn 声母不同（j 与 p），意思是新建、新修建，不是芯片。"}, {"text": "新线", "is_correct": false, "explanation": "xiàn 与 piàn 声母不同（x 与 p），意思是新的线路，不是芯片。"}, {"text": "新篇", "is_correct": false, "explanation": "piān 与 piàn 声调不同（第一声与第四声），意思是新的篇章，不是芯片。"}], "explanations": {"芯片": "正确答案。芯片 xīnpiàn 指集成电路的载体，由半导体材料制成。", "新建": "jiàn 与 piàn 声母不同（j 与 p），意思是新建、新修建，不是芯片。", "新线": "xiàn 与 piàn 声母不同（x 与 p），意思是新的线路，不是芯片。", "新篇": "piān 与 piàn 声调不同（第一声与第四声），意思是新的篇章，不是芯片。"}, "sentence_index": null, "correct_answer": "芯片"}, "level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能用硅做成。"}, {"text": "芯片", "is_correct": true, "explanation": "正确：芯片是用硅做的半导体元件，与“这块”和“用硅做的”都吻合。"}, {"text": "方法", "is_correct": false, "explanation": "搭配：“块”不能用来计量“方法”这样的抽象名词；语义：方法不能用硅做。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是木材，不是用硅做的。"}], "explanations": {"蛋糕": "语义：蛋糕是食物，不能用硅做成。", "芯片": "正确：芯片是用硅做的半导体元件，与“这块”和“用硅做的”都吻合。", "方法": "搭配：“块”不能用来计量“方法”这样的抽象名词；语义：方法不能用硅做。", "木头": "语义：木头是木材，不是用硅做的。"}, "sentence_index": 0, "correct_answer": "芯片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "芯片是一种很重要的半导体材料。", "explanation": "这里应该用〈硅〉。硅才是半导体材料，芯片是用硅等材料做成的元件，不能说它本身是材料。"}, {"text": "他在电脑店买了一条芯片。", "explanation": "这里应该用〈块〉。“条”用于细长的东西，芯片不能用“条”来计量。"}, {"text": "妈妈买了一袋芯片，我们一起吃。", "explanation": "这里的“芯片”被当成了零食，但它只指电子元件，不指吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：大海无法装进机器里。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被装进机器，句子说不通。"}, {"text": "恐惧", "is_correct": false, "explanation": "搭配：“装进”接的是具体的东西，“恐惧”是抽象的情绪，不能装进机器。"}, {"text": "芯片", "is_correct": true, "explanation": "正确：芯片可以装进机器里，符合“把……装进了机器里”。"}], "explanations": {"大海": "语义：大海无法装进机器里。", "天空": "语义：天空不能被装进机器，句子说不通。", "恐惧": "搭配：“装进”接的是具体的东西，“恐惧”是抽象的情绪，不能装进机器。", "芯片": "正确：芯片可以装进机器里，符合“把……装进了机器里”。"}, "sentence_index": 6, "correct_answer": "芯片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用芯片捏了一只小猴子。", "explanation": "这里应该用〈面团〉。面团可以揉捏成各种形状，芯片是电子元件，不能这样捏。"}, {"text": "他把芯片穿在身上，就出门了。", "explanation": "这里把“芯片”当成了可以穿戴的衣服，但芯片是电子元件，不能穿在身上。应该说〈衣服〉之类可以穿的东西。"}, {"text": "他在赌场里用芯片下注。", "explanation": "这里的“芯片”被当成了赌场里的筹码，但“芯片”只指电子元件，没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
